-- 뜻·예시·기존 퀴즈만 수정. 예상 원본과 다르면 전체 묶음을 취소합니다.
-- 재실행 시 동일한 수정은 중복 적용하지 않습니다.
BEGIN;
DO $apply$
DECLARE p record; current_row jsonb; changed integer := 0; skipped integer := 0;
BEGIN
  FOR p IN SELECT * FROM jsonb_to_recordset($content_revision_payload$[{"id":2,"word":"가계순저축률","before_data":{"meaning":"가계가 쓸 수 있는 소득 중 저축으로 남긴 돈의 비율","learning_example":"학습용 가정: 가계의 순저축이 100만 원이고 소득과 현물이전 등을 합친 기준 금액이 400만 원이면 가계순저축률은 25%예요."},"after_data":{"meaning":"가계가 쓸 수 있는 소득에 현물 지원·연금 조정을 반영한 금액 중, 소비하지 않고 순저축으로 남긴 비율","learning_example":"학습용 가정: 가계순처분가능소득이 300만 원, 사회적 현물이전이 80만 원, 연금기금의 가계순지분 증감조정액이 20만 원이고 순저축이 100만 원이면 가계순저축률은 100 ÷ (300 + 80 + 20) × 100 = 25%예요."},"guard_data":{"meaning":"가계가 쓸 수 있는 소득 중 저축으로 남긴 돈의 비율","detailed_meaning":"일반적으로 저축률은 저축액을 처분가능소득으로 나눈 비율을 말한다. 마찬가지로 가계순저축률은 가계부문의 순저축액을 가계순처분가능소득과 정부로부터 받은 사회적 현물이전 금액, 연금기금의 가계순지분 증감조정액을 합계한 금액으로 나눈 비율이다. 여기서 사회적 현물이전(Social Transfer in Kind)이란 정부 등이 가계에 현물이전의 형태로 제공하는 재화 및 서비스로서 무상교육, 보건소의 무상진료 등이 해당된다. 또한 연금기금의 가계순지분 증감조정액을 분모에 더하는 이유는 퇴직연금 등과 같이 가계가 납부한 연금부담금과 연금수취액의 차액을 반영해야 가계부문의 저축액을 정확히 구할수 있기 때문이다. 가계순저축률은 가계부문의 저축성향을 가장 잘 나타내주는 지표라고 할 수 있다. 가계순저축률(%) = {가계부문 순저축 / (가계순처분가능소득 + 사회적현물이전수취 + 연금기금의 가계순지분 증감조정)} × 100","learning_example":"학습용 가정: 가계의 순저축이 100만 원이고 소득과 현물이전 등을 합친 기준 금액이 400만 원이면 가계순저축률은 25%예요.","news_example":"소득이 늘었지만 소비가 더 크게 늘어 가계순저축률이 떨어지면서 저축 여력이 약해졌다.","visuals":null}},{"id":9,"word":"간접금융","before_data":{"meaning":"은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식","type":"quiz","answer":0,"options":["간접금융","대출채권 분할매각","예금취급기관","금융지주회사"],"explanation":"간접금융은/는 은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"은행 등 금융기관이 예금 등으로 모은 돈을 자기 책임으로 대출해 자금 공급자와 수요자를 연결하는 방식","visuals":[{"q":"은행이 가계의 예금을 받아 자기 책임으로 기업에 대출해 주었어요. 자금 조달 방식은?","type":"quiz","answer":0,"options":["간접금융","기업의 주식 발행을 통한 직접금융","기업의 회사채 발행을 통한 직접금융","기업의 유보이익을 이용한 내부자금 조달"],"explanation":"가계는 기업이 아니라 은행에 돈을 맡기고, 은행이 기업에 대출하므로 간접금융이에요. 기업이 주식·회사채를 발행하면 직접금융이고, 유보이익 사용은 내부자금 조달이에요.","lessonCheck":true}]},"guard_data":{"meaning":"은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식","detailed_meaning":"자금 잉여주체와 자금 부족주체 사이에 은행이나 저축은행 신용협동기구 등 금융기관이 개입하여 자금을 중개하는 방식을 간접금융(Indirect Financing)이라고 한다. 즉 금융기관이 일반 대중으로부터 예금을 받아 기업 등 다른 경제주체에게 대출해 주는 방식이다. 한편 주식, 채권 발행의 경우와 같이 자금수요자가 금융기관을 통하지 않고 금융시장에서 직접 필요자금을 조달하는 방식을 직접금융(Direct Financing)이라고 한다. 간접금융에 서는 은행이 중추적인 기능을 하고, 직접금융에서는 주식과 채권이 거래되는 자본시장이 중요한 역할을 수행한다. 직접금융과 간접금융은 상호 경쟁적일 뿐만 아니라 보완적이기도 하므로 균형적으로 발전될 필요가 있다. 직접금융과 간접금융의 상대적 비중이 어느정도이어야 이상적인지는 해당 국가의 경제발전 단계나 경제구조에 따라 달라질 수밖에 없다. 예를 들면 중소기업의 비중이 높은 국가일수록 정보의 비대칭성 문제를 완화하기위해 간접금융이 더 중요하고, 혁신산업에 의해 주도되는 경제일수록 미래의 성장 가능성을 보고 투자하고 그 위험과 이익을 공유하는 주식 등 직접금융의 역할이 더 중요할 것이다. 일반적으로 금융시장이 발달함에 따라 직접금융 비중이 높아진다.","learning_example":"사람들이 은행에 맡긴 예금이 은행 대출을 거쳐 기업의 사업 자금으로 이어져요.","news_example":"중소기업은 주식이나 회사채 발행이 어려워 은행 대출 같은 간접금융에 크게 의존하는 것으로 나타났다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식","type":"quiz","answer":0,"options":["간접금융","대출채권 분할매각","예금취급기관","금융지주회사"],"explanation":"간접금융은/는 은행 같은 금융회사를 거쳐 돈을 빌리고 빌려주는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":10,"word":"간접세","before_data":{"meaning":"물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세)","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세)","type":"quiz","answer":0,"options":["간접세","죄악세","추가경정예산","균형재정승수"],"explanation":"간접세은/는 물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세) 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"세금을 납부할 의무가 있는 사람과 실제로 그 부담을 지는 사람이 다르도록 설계된 세금","visuals":[{"q":"사업자가 납부할 의무를 지지만 상품 가격을 통해 소비자가 부담하도록 설계된 부가가치세는 어떤 분류에 속할까요?","type":"quiz","answer":0,"options":["간접세","직접세","사회보험료","행정서비스 수수료"],"explanation":"부가가치세는 납세의무자인 사업자와 부담자인 소비자가 구분되는 간접세예요. 직접세는 납세의무자와 부담자가 일치하는 분류이고, 보험료와 수수료는 이 세금 분류가 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세)","detailed_meaning":"조세는 납세의무자와 실제로 세금을 부담하게 되는 조세부담자가 일치하는지 여부에 따라 간접세(Indirect Tax)와 직접세(Direct Tax)로 구분된다. 납세의무자와 조세부담자가 일치하여 조세부담이 전가(轉嫁)되지 않는 조세를 직접세라고 하며, 대표적인 예로는 소득세, 법인세, 상속세, 증여세, 종합부동산세 등이 있다. 이와 달리 납세의무자와 조세부담자가 일치하지 않고 조세의 부담이 타인에게 전가되는 세금을 간접세라고 하며, 대표적인 예로는 부가가치세, 개별소비세, 주세, 인지세, 증권거래세 등이 있다. 간접세는 조세에 대한 저항이 적고 징수가 간편하여 조세수입의 확보가 용이하다는 장점이 있다. 반면, 개인의 사정을 고려할 수 없으므로 누진세율(累進稅率)을 적용하지 못하고 비례세율이 적용됨으로써 소득이 적은 자에게 상대적으로 높은 조세부담률이 적용되는 역진성(逆進性) 을 띠게 되어 공평부담의 원칙에 어긋난다는 단점이 있다. 한편, 국민계정체계에서는 조세의 실질적인 부담주체를 결정하기가 쉽지 않은 점 등을 감안하여 간접세와 직접세 대신생산 및 수입세, 소득 및 부 등에 대한 경상세, 자본세란 용어를 사용하고 있다.","learning_example":"가게가 물건을 팔 때 부가가치세를 납부하지만, 물건값을 내는 소비자가 그 세금을 부담해요.","news_example":"부가가치세처럼 물건값에 포함돼 소비자가 부담하는 간접세는 소득이 낮을수록 부담이 크다는 지적이 나왔다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세)","type":"quiz","answer":0,"options":["간접세","죄악세","추가경정예산","균형재정승수"],"explanation":"간접세은/는 물건값에 숨어 있어 내는 사람과 부담하는 사람이 다른 세금(부가가치세) 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":16,"word":"거액익스포저 규제","before_data":{"meaning":"한 거래처에 대출이 너무 몰리지 않도록 한도를 두는 규제"},"after_data":{"meaning":"은행의 대출·보증 등 신용위험이 한 거래상대방이나 서로 연결된 거래상대방 집단에 지나치게 몰리지 않도록 제한하는 규제"},"guard_data":{"meaning":"한 거래처에 대출이 너무 몰리지 않도록 한도를 두는 규제","detailed_meaning":"금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다. 바젤Ⅱ에서는 이러한 편중리스크를 직접 규율하지 않고 각국 감독당국이 편중리스크를 점검·관리하도록 하였다. 우리나라는 은행법 등에서 동일인·동일차주 신용공여 한도 제도를 통해 편중리스크를 관리하고 있다. 한편 금융위기 이후 금융기관간 상호연계성에 의한 시스템 리스크를 억제하고 편중리스크의 근본적인 관리 필요성이 대두됨에 따라 바젤위원회(BCBS)는 거액익스포저 규제를 2019년 1월 도입하였고 우리나라는 2019년 3월시범실시한 이후 2024년 2월부터 시행 중이다. 동 규제는 거액익스포저를 단일 거래상대방 또는 연계된 거래상대방그룹(경제적 상호의존성이 있는 거래상대방들로 구성되어 거래상대방들 중 하나가 파산하면 다른 모든 거래상대방들이 파산할 가능성이 상당히 높은 그룹)에 대한 익스포저의 합계가 은행 기본자본의 10% 이상인 경우로 정의하고, 거액익스포저 현황을 금융당국에 정기적으로 보고하도록 하는 한편, 거액익스포저비율(거액익스포저를 은행 기본자본으로 나눈 값)이 25%를 초과하지 못하도록 하고 있다.","learning_example":"학습용 가정: 한 은행이 A기업에 대출을 지나치게 몰아주려 하면 한도 규제로 추가 대출을 제한해요.","news_example":"은행이 특정 대기업 한 곳에 대출을 지나치게 몰아주지 못하도록 거액익스포저 규제가 적용된다.","visuals":null}},{"id":26,"word":"경상수지","before_data":{"meaning":"외국과 상품·서비스를 사고팔아 번 돈과 쓴 돈의 차이"},"after_data":{"meaning":"외국과의 상품·서비스 거래 및 임금·투자소득·무상 이전에서 받은 금액과 지급한 금액의 차이"},"guard_data":{"meaning":"외국과 상품·서비스를 사고팔아 번 돈과 쓴 돈의 차이","detailed_meaning":"경상수지는 재화나 서비스를 외국과 사고파는 거래 즉 경상거래의 결과로 나타나는 수지를 말한다. 경상수지는 상품수지, 서비스수지, 본원소득수지 및 이전소득수지로 구성된다. 그런데 이 항목들은 금융계정 구성항목과 비교하면 상대적으로 안정적인 성격을 지닌거래들로 이루어져 있기 때문에 경제발전 및 정책변화의 효과를 측정하거나 전망하는 데널리 이용된다.","learning_example":"한 나라가 외국과의 상품·서비스·소득 거래에서 번 돈이 쓴 돈보다 많으면 경상수지가 흑자예요.","news_example":"반도체 수출 호조로 상품과 서비스 거래에서 번 돈이 쓴 돈보다 많아 경상수지 흑자가 이어졌다.","visuals":[{"item":"000000","stat":"301Y013","type":"ecos","unit":"억 달러","cycle":"M","scale":0.01,"title":"경상수지 최근 5년 (월별)","months":60,"caption":"0보다 위면 흑자, 아래면 적자예요. 수출이 잘되면 흑자가 커져요."}]}},{"id":33,"word":"경제활동인구","before_data":{"meaning":"15세 이상 중 일할 능력과 의사가 있는 사람(취업자+실업자)"},"after_data":{"meaning":"15세 이상 인구 중 취업자와, 적극적으로 구직하며 바로 일할 수 있는 실업자를 합한 인구"},"guard_data":{"meaning":"15세 이상 중 일할 능력과 의사가 있는 사람(취업자+실업자)","detailed_meaning":"만15세 이상 인구 중 일할 수 있는 능력과 취업의사를 동시에 갖춘 사람을 경제활동인구라 한다. 경제활동인구는 현재 취업상태에 있는지에 따라 취업자와 실업자로 구분된다. 취업자란 매월 15일이 포함된 1주일 동안에 수입을 목적으로 1시간 이상 일한 사람과 본인 또는 가족이 운영하는 농장이나 사업체에서 주당 18시간 이상 일한 무급가족종사자를 가리킨다. 그밖에 일정한 직장이나 사업장은 가지고 있으나 일시적인 질병, 일기불순, 휴가, 노동쟁의 등의 사유로 조사기간에 일을 하지 않은 사람도 취업자로 분류된다. 실업자란 적극적으로 일자리를 구해보았으나 일을 하지 못한 사람으로서 즉시 취업이 가능한 사람을 말한다. 한편 15세 이상 인구 중 경제활동인구에 포함되지 않은 사람, 즉 조사대상기간에 취업도 실업도 아닌 상태에 있는 사람은 비경제활동인구로 분류된다. 비경제활동인구에는 집안에서 가사와 육아를 도맡아 하는 전업주부, 학교에 다니는 학생, 일을 할 수없는 연로자와 심신장애자, 구직단념자 등이 포함된다. 경제활동참가율은 15세 이상 인구에 대한 경제활동인구의 비율을 말한다. 경제활동인구(취업자 + 실업자) 경제활동참가율 = ×100 15세 이상 인구","learning_example":"학습용 가정: 15세 이상 취업자 90명과 적극적으로 일자리를 찾는 실업자 10명은 모두 경제활동인구예요.","news_example":"일할 의사와 능력이 있는 15세 이상 인구인 경제활동인구는 취업자와 실업자를 합한 개념이다.","visuals":null}},{"id":47,"word":"골디락스경제","before_data":{"meaning":"인플레이션도 실업도 걱정 없는, 뜨겁지도 차갑지도 않은 이상적 경제"},"after_data":{"meaning":"경기가 지나치게 과열되거나 침체되지 않아 물가와 고용이 비교적 안정된 상태로 성장하는 경제"},"guard_data":{"meaning":"인플레이션도 실업도 걱정 없는, 뜨겁지도 차갑지도 않은 이상적 경제","detailed_meaning":"골디락스경제(Goldilocks Economy)는 경기과열에 따른 인플레이션과 경기침체에 따른 실업을 염려할 필요가 없는 최적 상태에 있는 건실한 경제를 가리킨다. 이는 영국의 전래동화인 골디락스와 곰 세 마리(Goldilocks and the three bears)에 등장하는 금발머리 소녀의 이름에서 유래하였다. 동화에 따르면 엄마 곰이 끓인 뜨거운 수프를 큰 접시와 중간 접시 그리고 작은 접시에 담은 후 가족이 이를 식히기 위해 산책을 나갔는데, 이 때집에 들어온 골디락스가 아기 곰 접시에 담긴 너무 뜨겁지도 않고 너무 차지도 않은 적당한 온도의 수프를 먹고 기뻐하는 상태를 경제에 비유한 것이라 한다. 즉 경기과열이나 불황으로 인한 높은 수준의 인플레이션이나 실업률을 경험하지 않는 양호한 상태가 지속되는 경제를 지칭한다.","learning_example":"물가는 크게 오르지 않으면서 일자리가 늘고 경제가 안정적으로 성장해요.","news_example":"물가는 안정되고 성장은 견조한 골디락스경제가 이어질 것이라는 기대에 증시가 강세를 보였다.","visuals":null}},{"id":49,"word":"공공재","before_data":{"meaning":"국방·도로처럼 모두가 함께 쓰고 값을 매기기 어려운 재화나 서비스"},"after_data":{"meaning":"여럿이 함께 이용해도 다른 사람의 이용 몫이 줄지 않고, 대가를 내지 않은 사람을 이용에서 배제하기 어려운 재화나 서비스"},"guard_data":{"meaning":"국방·도로처럼 모두가 함께 쓰고 값을 매기기 어려운 재화나 서비스","detailed_meaning":"공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다. 국방·경찰·소방·공원·도로 등과 같이 정부에 의해서만 공급할 수 있는 것이라든가 또는 정부에 의해서 공급되는 것이 바람직하다고 사회적으로 판단되는 재화 또는 서비스가 이에 해당한다. 공공재에는 보통 시장가격은 존재하지 않으며 수익자부담 원칙도 적용되지 않는다. 따라서 공공재 규모의 결정은 정치기구에 맡길 수밖에 없다. 공공재의 성질로는 어떤 사람의 소비가 다른 사람의 소비를 방해하지 않고 여러 사람이 동시에 편익을 받을 수 있는 비경쟁성·비선택성, 대가를 지급하지 않은 특정 개인을 소비에서 제외하지 않는 비배제성등을 들 수 있다.","learning_example":"국방은 한 사람이 혜택을 누린다고 다른 사람이 못 쓰는 게 아니어서 함께 제공돼요.","news_example":"국방이나 가로등처럼 여러 사람이 함께 쓰고 값을 받기 어려운 공공재는 주로 정부가 공급한다.","visuals":[{"body":"국방, 가로등처럼 여럿이 같이 써도 줄지 않고(비경합성), 돈을 안 낸 사람도 못 쓰게 막을 수 없는(비배제성) 재화예요.\n돈을 안 내도 쓸 수 있으니 다들 남이 내주길 기다리는 무임승차가 생기고, 시장에 맡기면 너무 적게 공급돼요.","type":"text","title":"공공재 쉽게 설명"},{"rows":[["배제성 있음","사적재(빵, 옷)","클럽재(유료 케이블 TV, OTT)"],["배제성 없음","공유자원(공동 어장)","공공재(국방, 가로등)"]],"type":"table","title":"재화 4가지 분류","caption":"공공재인지는 누가 만드느냐가 아니라 경합성과 배제성으로 정해요.","columns":["구분","경합성 있음","경합성 없음"]},{"body":"모두가 같은 양을 함께 쓰므로 사람들의 한계편익을 세로로 더해요.\n이 합이 한계비용과 같아지는 양이 사회적으로 알맞아요. 그래서 각자 혼자서는 안 사도 합치면 만들 가치가 있을 수 있어요.","type":"text","title":"공공재의 알맞은 양"},{"q":"가로등을 세우는 데 60만 원이 들고, 주민 세 명이 얻는 편익은 각각 5만, 30만, 50만 원이에요. 옳은 것은?","type":"quiz","answer":0,"options":["편익 합이 비용보다 커서 세우는 게 사회적으로 이득이에요","한 명의 편익도 60만 원이 안 되니 세우면 손해예요","가장 큰 편익 50만 원만 비용과 비교하면 돼요","공공재라서 비용을 따질 필요가 없어요"],"explanation":"공공재는 모두가 함께 쓰므로 편익을 더해 비교해요. 합계 85만 원이 비용 60만 원보다 커요. 하지만 각자 편익을 숨기면 무임승차로 아무도 돈을 안 낼 수 있어요.","lessonCheck":true},{"q":"공공재에서 무임승차가 생기는 직접적인 이유는?","type":"quiz","answer":0,"options":["비배제성(돈을 안 내도 막을 수 없음)","비경합성(같이 써도 줄지 않음)","경합성(쓰면 줄어듦)","배제성(돈을 안 내면 막을 수 있음)"],"explanation":"돈을 안 낸 사람을 막을 수 없으니 남이 내주길 기다리게 돼요. 무임승차는 비배제성 때문이에요."}]}},{"id":58,"word":"구독경제","before_data":{"meaning":"제품을 사지 않고 매달 돈을 내며 빌려 쓰는 소비 방식"},"after_data":{"meaning":"제품이나 서비스를 이용하기 위해 매월·매년 등 정기적으로 요금을 내는 소비·사업 방식"},"guard_data":{"meaning":"제품을 사지 않고 매달 돈을 내며 빌려 쓰는 소비 방식","detailed_meaning":"소비자가 제품이나 서비스를 소유하지 않은 채 일정한 금액을 주기적으로 지불하면서 사용하는 경제 모델을 말한다. 즉, 사는 것이 아니라 빌려 쓰고 구독하는 것에 초점을 둔소비 방식이다. 월간 또는 연간 등 정기 결제로 제품 또는 서비스를 이용하면서 소유 대신사용 권한을 얻게 된다. 소비자의 입장에서는 구독경제가 초기 비용 부담이 적고 다양한 서비스를 체험할 수 있다는 점에서 유리하다. 다만 장기적으로 비용이 누적될 수 있고, 구독 해지를 놓쳐 불필요한 지출이 생기기도 한다. 공급자의 입장에서는 사용자의 취향, 소비 습관에 맞춰 적절한 정보를 제공하여 고객을 꾸준히 유지함으로써 장기 고객을 확보하는 것이 비즈니스의 핵심이 된다.","learning_example":"정수기를 사지 않고 매달 요금을 내며 사용해요.","news_example":"소비자들이 물건을 사는 대신 매달 요금을 내고 이용하는 구독경제 시장이 빠르게 커지고 있다.","visuals":null}},{"id":74,"word":"국민소득","before_data":{"meaning":"한 나라 국민이 노동·자본을 제공하고 벌어들인 순수한 소득의 합계"},"after_data":{"meaning":"한 나라의 거주자가 노동·자본 등을 제공한 대가로 얻은 순소득의 합계"},"guard_data":{"meaning":"한 나라 국민이 노동·자본을 제공하고 벌어들인 순수한 소득의 합계","detailed_meaning":"국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세는 포함되지 않는다. 즉 한 나라 국민이 벌어들인순수한 소득을 나타내는 지표로서 다음과 같이 산출한다. 국민소득(NI) = 국민총소득 - 고정자본소모 - 생산 및 수입세 + 보조금= 국민순소득 - 생산 및 수입세 + 보조금= 국민순소득 - 순생산 및 수입세= 피용자보수 + 영업잉여= 임금 + 지대 + 이자 + 이윤","learning_example":"기업에서 받은 임금과 사업으로 번 소득 등을 합쳐 국민이 벌어들인 소득을 살펴봐요.","news_example":"국민이 노동과 자본을 제공하고 벌어들인 소득을 합친 국민소득이 늘면서 1인당 소득도 증가했다.","visuals":null}},{"id":75,"word":"국민연금","before_data":{"meaning":"일할 때 보험료를 내고 노후에 매달 연금을 받는 공적 연금 제도"},"after_data":{"meaning":"보험료를 바탕으로 수급 요건을 충족하면 노령·장애·사망에 따른 소득 상실에 대비해 연금 등을 지급하는 공적 사회보험 제도"},"guard_data":{"meaning":"일할 때 보험료를 내고 노후에 매달 연금을 받는 공적 연금 제도","detailed_meaning":"일정기간 동안 보험료를 납부하면 노후에 연금을 지급받아 기본적인 생활을 보장받을 수있도록 설계된 공적 연금 제도이다. 현재 우리나라는 국민연금공단이 운영 주체가 되어만 18세 이상 ~ 60세 미만의 대한민국 국민을 대상으로 매달 소득의 일정 비율을 납부받고 있으며, 일정 연령에 도달해야 연금을 수령할 수 있다. 국민연금으로 받을 수 있는 급여로는 노후 생활비로 지급되는 노령연금, 불의의 사고나 질병으로 장애가 생겼을 때지급되는 장애연금, 가입자가 사망할 경우 유족에게 지급되는 유족연금 등이 있다. 국민연금은 고령화 사회에서 은퇴 이후 소득이 줄어드는 사람들을 위한 안정적 소득원으로 개인연금, 퇴직연금과 함께 노후 대비의 핵심축이 된다. 다만 출산율 저하와 고령화로 인해국민연금 기금이 고갈될 수 있다는 우려가 높아지면서 수급 개시 연령 상향, 보험료 인상등의 필요성이 대두되고 있다.","learning_example":"직장인이 일하는 동안 보험료를 내고, 수급 요건을 채우면 노후에 연금을 받아요.","news_example":"국민연금 기금 고갈 우려가 커지면서 보험료율 인상과 수급 연령 조정을 둘러싼 개혁 논의가 이어졌다.","visuals":null}},{"id":77,"word":"국민총소득(GNI)","before_data":{"meaning":"한 나라 국민이 국내외에서 일정 기간 벌어들인 소득의 합계","learning_example":"국내 기업이 해외 지사에서 번 소득도 그 나라 국민이 벌어들인 소득을 셀 때 반영해요."},"after_data":{"meaning":"한 나라의 거주자가 국내외 생산활동에 참여해 일정 기간 벌어들인 임금·이자·배당 등 소득의 합계","learning_example":"학습용 가정: 명목 국내총생산이 100조 원이고 거주자가 국외에서 받은 생산요소소득이 10조 원, 비거주자에게 지급한 생산요소소득이 4조 원이면 명목 국민총소득은 106조 원이에요."},"guard_data":{"meaning":"한 나라 국민이 국내외에서 일정 기간 벌어들인 소득의 합계","detailed_meaning":"국민총소득(GNI; Gross National Income)은 한 나라의 국민이 일정 기간 동안 벌어들인임금, 이자, 배당 등의 소득을 모두 합친 것이다. 국가 간에는 재화와 서비스는 물론 노동이나 자본과 같은 생산요소도 활발하게 거래되고 있다. 한 나라의 기업이 다른 나라 사람을 고용하여 생산을 하기도 하고 반대로 그 나라 국민이 다른 나라에 나가 생산활동에 참여하기도 한다. 여기서 생산요소의 국가 간 이동을 고려하여 거주성 측면, 즉 한 나라의 국민을 기준으로 소득을 측정한 것이 국민총소득이다. 국민총소득(명목기준)은 GDP(명목기준) 에다 한 나라의 국민(거주자)이 다른 나라에서 벌어들인 소득(국외수취요소소득)을 더하고, 다른 나라 국민(비거주자)이 그 나라에서 벌어들인 소득(국외지급요소소득)을 뺀 금액이다. 다시 말해서 국민총소득(명목기준)은 GDP에 국외순수취요소소득을 더하여 산출된다. 다 만 실질기준 국민총소득은 실질구매력을 반영하기 위하여 실질GDP에다 국외순수취요소소득뿐만 아니라 교역조건 변화에 따른 실질무역손익까지 고려하여 산출한다. 국민총소득에서 고정자본소모를 제외하면 국민순소득(NNI; Net National Income)이 된다.","learning_example":"국내 기업이 해외 지사에서 번 소득도 그 나라 국민이 벌어들인 소득을 셀 때 반영해요.","news_example":"해외에서 벌어들인 배당과 이자가 늘면서 국민이 국내외에서 번 소득을 합친 국민총소득(GNI)이 증가했다.","visuals":null}},{"id":84,"word":"국제수지(BOP)","before_data":{"meaning":"일정 기간 한 나라가 외국과 거래하며 받은 돈과 준 돈의 차이","visuals":[{"body":"국제수지는 일정 기간 거주자와 비거주자 사이의 모든 경제적 거래를 기록해요. 우리나라에 사는 외국인도 우리나라 거주자예요.\n한 거래를 두 곳에 같은 크기로 적는 복식부기라 표 전체 합은 늘 0이에요. 그래서 뉴스의 흑자는 대부분 경상수지 흑자를 뜻해요.","type":"text","title":"국적이 아니라 거주지, 합계는 늘 0"},{"rows":[["경상수지","상품수지","자동차·반도체 수출입"],["경상수지","서비스수지","운송·여행·지식재산권 사용료"],["경상수지","본원소득수지","임금·배당·이자"],["경상수지","이전소득수지","대가 없는 송금·원조"],["자본수지","자본이전 등","채무 면제, 특허권 자체 매매"],["금융계정","직접·증권·파생·기타투자, 준비자산","해외 공장 설립, 주식·채권 매매, 외환보유액 증감"]],"type":"table","title":"국제수지표의 구성","caption":"거래 자체는 금융계정, 그 대가로 받는 배당·이자는 경상수지에 적어요.","columns":["계정","세부 항목","예"]},{"q":"한국 투자자가 미국 회사 주식을 사고, 1년 뒤 그 주식에서 배당을 받았어요. 각각 국제수지의 어디에 기록될까요?","type":"quiz","answer":3,"options":["주식 매입은 서비스수지, 배당은 이전소득수지","둘 다 자본수지","둘 다 상품수지","주식 매입은 금융계정, 배당은 본원소득수지"],"explanation":"주식 같은 금융자산을 사고파는 건 금융계정이에요. 그 투자로 받은 배당·이자는 경상수지 안의 본원소득수지에 들어가요.","lessonCheck":true},{"q":"국제수지에서 거주자를 나누는 기준은?","type":"quiz","answer":1,"options":["외화 보유 여부","사는 곳(거주지)","나이","국적"],"explanation":"국제수지는 국적이 아니라 그 나라에 사는지로 거주자를 나눠요. 우리나라에 사는 외국인도 거주자예요."}]},"after_data":{"meaning":"일정 기간 한 나라의 거주자와 비거주자 사이에서 이루어진 상품·서비스·소득·자본·금융 거래의 수입과 지급을 종합한 것","visuals":[{"body":"국제수지는 일정 기간 거주자와 비거주자 사이의 모든 경제적 거래를 기록해요. 우리나라에 사는 외국인도 우리나라 거주자예요.\n한 거래를 두 곳에 같은 크기로 적는 복식부기라 표 전체 합은 늘 0이에요. 그래서 뉴스의 흑자는 대부분 경상수지 흑자를 뜻해요.","type":"text","title":"국적이 아니라 거주지, 합계는 늘 0"},{"rows":[["경상수지","상품수지","자동차·반도체 수출입"],["경상수지","서비스수지","운송·여행·지식재산권 사용료"],["경상수지","본원소득수지","임금·배당·이자"],["경상수지","이전소득수지","대가 없는 송금·원조"],["자본수지","자본이전 등","채무 면제, 특허권 자체 매매"],["금융계정","직접·증권·파생·기타투자, 준비자산","해외 공장 설립, 주식·채권 매매, 외환보유액 증감"]],"type":"table","title":"국제수지표의 구성","caption":"거래 자체는 금융계정, 그 대가로 받는 배당·이자는 경상수지에 적어요.","columns":["계정","세부 항목","예"]},{"q":"한국의 거주자인 투자자가 미국의 비거주자 기업이 발행한 주식을 매입하고, 1년 뒤 그 기업에서 배당을 받았어요. 각각 어디에 기록될까요?","type":"quiz","answer":3,"options":["주식 매입은 금융계정, 배당은 이전소득수지","주식 매입은 자본수지, 배당은 본원소득수지","주식 매입은 상품수지, 배당은 금융계정","주식 매입은 금융계정, 배당은 본원소득수지"],"explanation":"국외 주식의 매입은 금융자산 거래이므로 금융계정에, 그 투자에서 발생한 배당은 본원소득수지에 기록해요. 대가 없이 받는 이전소득과 투자소득은 구별해야 해요.","lessonCheck":true},{"q":"국제수지에서 거주자와 비거주자를 구분할 때 핵심 기준은?","type":"quiz","answer":1,"options":["대금을 원화로 받는지 여부","주된 경제적 이익의 중심이 어느 나라에 있는지","국내 사업자와 거래한 적이 있는지 여부","보유한 여권의 국적"],"explanation":"거주성은 주된 경제적 이익의 중심을 기준으로 판단해요. 국적이나 결제통화가 기준은 아니며, 잠시 그 나라에 머문다는 사실만으로 거주자가 되는 것도 아니에요."}]},"guard_data":{"meaning":"일정 기간 한 나라가 외국과 거래하며 받은 돈과 준 돈의 차이","detailed_meaning":"일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래에 수반되는 수입과 지급의 차이를 의미한다. 국제수지(BOP; Balance Of Payments)는 크게 경상수지, 자본수지, 금융계정, 오차 및 누락 등 4개의 계정으로 구성되어 있다. 경상수지는 ① 상품수출입의 결과인 상품수지, ② 운송, 여행, 건설 등 서비스거래의 결과인 서비스수지, ③ 급료 및 임금, 투자소득 등 본원소득수지, ④ 무상원조, 증여성 송금 등의 결과인 이전소득수지로 구분된다. 자본수지는 자산 소유권의 무상이전, 채권자에 의한 채무면제 등 자본이전과 브랜드네임 등 비생산·비금융자산의 취득 및 처분의 결과로 계상된다. 금융계정은 직접투자, 증권투자, 파생금융상품, 기타투자 및 준비자산으로 구분된다. 오차 및 누락은 경상수지 및 자본수지의 합계와 금융계정 금액이 같지 않을 경우 이를 조정하기 위한 항목으로 국제수지 작성에 이용되는 기초통계간 계상시점, 평가방법상의 차이 등에 기인한다.","learning_example":"한 달 동안 외국에 상품을 팔아 받은 돈과 해외 여행 등에 쓴 돈을 포함해 대외 거래를 집계해요.","news_example":"외국과의 상품·서비스·자본 거래를 모두 기록한 국제수지(BOP)에서 경상수지 흑자가 이어졌다.","visuals":[{"body":"국제수지는 일정 기간 거주자와 비거주자 사이의 모든 경제적 거래를 기록해요. 우리나라에 사는 외국인도 우리나라 거주자예요.\n한 거래를 두 곳에 같은 크기로 적는 복식부기라 표 전체 합은 늘 0이에요. 그래서 뉴스의 흑자는 대부분 경상수지 흑자를 뜻해요.","type":"text","title":"국적이 아니라 거주지, 합계는 늘 0"},{"rows":[["경상수지","상품수지","자동차·반도체 수출입"],["경상수지","서비스수지","운송·여행·지식재산권 사용료"],["경상수지","본원소득수지","임금·배당·이자"],["경상수지","이전소득수지","대가 없는 송금·원조"],["자본수지","자본이전 등","채무 면제, 특허권 자체 매매"],["금융계정","직접·증권·파생·기타투자, 준비자산","해외 공장 설립, 주식·채권 매매, 외환보유액 증감"]],"type":"table","title":"국제수지표의 구성","caption":"거래 자체는 금융계정, 그 대가로 받는 배당·이자는 경상수지에 적어요.","columns":["계정","세부 항목","예"]},{"q":"한국 투자자가 미국 회사 주식을 사고, 1년 뒤 그 주식에서 배당을 받았어요. 각각 국제수지의 어디에 기록될까요?","type":"quiz","answer":3,"options":["주식 매입은 서비스수지, 배당은 이전소득수지","둘 다 자본수지","둘 다 상품수지","주식 매입은 금융계정, 배당은 본원소득수지"],"explanation":"주식 같은 금융자산을 사고파는 건 금융계정이에요. 그 투자로 받은 배당·이자는 경상수지 안의 본원소득수지에 들어가요.","lessonCheck":true},{"q":"국제수지에서 거주자를 나누는 기준은?","type":"quiz","answer":1,"options":["외화 보유 여부","사는 곳(거주지)","나이","국적"],"explanation":"국제수지는 국적이 아니라 그 나라에 사는지로 거주자를 나눠요. 우리나라에 사는 외국인도 거주자예요."}]}},{"id":93,"word":"국채선물","before_data":{"visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 국채를 기초자산으로 미래 가격을 미리 정해 사고파는 선물거래","type":"quiz","answer":0,"options":["국채선물","금리선물","상장지수펀드(ETF)","주택저당증권(MBS)"],"explanation":"국채선물은/는 국채를 기초자산으로 미래 가격을 미리 정해 사고파는 선물거래 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"visuals":[{"q":"국채를 기초자산으로 미래 결제가격을 지금 정하고, 매수·매도 양쪽 모두 계약을 이행할 의무를 지는 표준화된 파생상품은?","type":"quiz","answer":0,"options":["국채선물","국채를 기초자산으로 한 옵션","통화선물","국채 현물거래"],"explanation":"국채선물은 국채를 기초자산으로 정해진 미래 시점의 거래를 약정하며 양쪽 모두 계약 이행 의무를 져요. 옵션은 매수자에게 행사 여부를 선택할 권리를 주므로 달라요.","lessonCheck":true}]},"guard_data":{"meaning":"국채를 기초자산으로 미래 가격을 미리 정해 사고파는 선물거래","detailed_meaning":"국채선물이란 국가가 발행하는 채권을 기초자산으로 하는 선물거래를 의미한다. 국채시장규모가 확대되고 2000년 7월부터 채권시가평가제도가 시행되면서 채권 투자자에게 가격변동 위험을 관리할 수 있는 수단을 제공하면서 국채의 거래를 활성화하기 위해 1999년 9 월에 3년 만기 국채선물시장이 개설되었다. 이후 중기채권 시장 및 장기채권 시장에 대한 위험관리 수단을 제공하기 위해서 2003년 8월에 5년 만기 국채선물이 상장되었고, 2008 년 2월에는 10년 만기 국채선물이 상장되었으며, 2024년 2월에는 초장기 국채 발행량 증가에 따른 헤지 수요 및 시장의 다양한 투자 환경 구축을 위해 30년 국채선물이 상장되었다. 현재 한국거래소에는 3년, 5년, 10년, 30년 만기 국채선물이 거래되고 있다. 국채선물의 주문접수, 거래체결 및 통보과정은 전자거래방식에 의해 자동적으로 수행되고 있다. 미국 시카고상업거래소(CME; Chicago Mercantile Exchange)와 같이 특정 장소(trading pit)에서 거래 참가자들이 모여 육성 또는 수신호로 체결하는 공개호가 방식을 취하는 경우도 있으나 세계적으로 점차 전자거래 방식이 증가하는 추세를 보이고 있다.","learning_example":"투자자가 국채 가격 변동 위험에 대비하려고 국채선물을 거래해요.","news_example":"금리 상승을 예상한 투자자들이 미래 국채 가격을 미리 정해 거래하는 국채선물을 대거 매도했다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 국채를 기초자산으로 미래 가격을 미리 정해 사고파는 선물거래","type":"quiz","answer":0,"options":["국채선물","금리선물","상장지수펀드(ETF)","주택저당증권(MBS)"],"explanation":"국채선물은/는 국채를 기초자산으로 미래 가격을 미리 정해 사고파는 선물거래 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":95,"word":"규제 샌드박스","before_data":{"meaning":"핀테크 기업이 규제를 잠시 면제받고 새 서비스를 시험해 볼 수 있는 제도"},"after_data":{"meaning":"소비자 보호 장치를 두고 새로운 제품·서비스를 시험할 수 있도록 관련 규제를 면제하거나 완화하는 제도"},"guard_data":{"meaning":"핀테크 기업이 규제를 잠시 면제받고 새 서비스를 시험해 볼 수 있는 제도","detailed_meaning":"규제 샌드박스(Regulatory Sandbox)는 핀테크 기업이 현행 규제를 적용받지 않으면서 자신의 혁신적인 금융상품과 비즈니스모델을 시험할 수 있는 공간이나 제도를 뜻한다. 이 용어는 어린이들이 안전하고 자유롭게 놀 수 있는 놀이터의 모래구역 즉 ‘sandbox’를 연상시킨다. 즉 규제 샌드박스에 참여하는 소비자에게는 안전장치를 두고, 혁신적인 기업가 에게는 규제를 면제하거나 완화함으로써, 핀테크 기업의 새로운 도전과 시험을 활성화하려는 규제기관의 정책의지 또는 참여한 기업·소비자의 혁신적인 활동모습을 연상시킨다. 이는 영국의 금융감독기구인 금융행위규제청(FCA)이 핀테크 전담조직(Innovation Hub) 을 설치하고 지속적으로 관련 산업을 지원하기 위해 규제 개선의 필요성을 검토하는 가운데 규제 개선을 위한 여러 방안들 중의 하나로 도입한 것이다. 규제 샌드박스의 장점은 ① 혁신적인 아이디어가 시장(market)에 접근할 수 있는 시간과 비용을 줄이고 ② 혁신기업의 자금조달을 쉽게 해주며 ③ 더 많은 혁신적인 상품이 시험되고 시장에 도입될 수 있을 뿐만 아니라 ④ 규제기관이 미리 새로운 상품 및 서비스에 대한 적절한 소비자보호 안전장치를 확보할 수 있다는 점이다.","learning_example":"새 금융 서비스를 만든 기업이 정해진 시험 기간 동안 일부 규제를 유예받아 실제 이용자와 서비스를 시험해요.","news_example":"핀테크 기업이 규제를 잠시 면제받고 새 서비스를 시험할 수 있는 규제 샌드박스 지정 사례가 늘었다.","visuals":null}},{"id":109,"word":"금산분리","before_data":{"meaning":"산업자본(대기업)이 은행 등 금융회사를 소유하지 못하게 막는 원칙"},"after_data":{"meaning":"산업자본이 금융회사를 지배해 사금고처럼 이용하지 못하도록 산업자본과 금융자본의 결합을 제한하는 원칙"},"guard_data":{"meaning":"산업자본(대기업)이 은행 등 금융회사를 소유하지 못하게 막는 원칙","detailed_meaning":"산업자본과 금융자본이 결합하는 것을 제한하는 원칙을 금산분리라고 한다. 은행업 등 금융산업은 예금이나 채권 등을 통하여 조달된 자금을 재원으로 하여 영업활동을 해서 자기자본비율이 낮은 특징이 있다. 이 때문에 금융산업의 소유구조는 다른 산업에 비해 취약한 편이며 산업자본의 지배하에 놓일 수 있는 위험이 존재한다. 산업자본이 금융자본을 지배하게 되면, 은행이 특정 기업의 사금고처럼 이용될 수 있는 한편, 지배기업이 다른 경쟁 기업보다 유리한 조건으로 자금을 조달할 수 있어 시장의 공정한 경쟁을 저해하고 독과점을 초래할 수 있다. 이러한 이유로 은행법을 통해 산업자본이 보유할 수 있는 은행지분을 원칙적으로 4% 한도로 제한하고 있다.","learning_example":"대기업이 은행 지분을 사서 은행 경영을 지배하려 할 때 소유 제한 규정이 적용돼요.","news_example":"대기업 같은 산업자본이 은행을 소유하지 못하게 막는 금산분리 원칙을 완화할지를 두고 논란이 일었다.","visuals":null}},{"id":145,"word":"기초가격","before_data":{"meaning":"생산자 판매가격에서 세금을 빼고 보조금을 더한, 생산자가 실제로 갖는 몫","learning_example":"학습용 가정: 생산자가 물건을 1만 원에 팔고 제품세 1천 원을 내며 보조금 500원을 받으면 기초가격은 9,500원이에요."},"after_data":{"meaning":"생산자가 생산물 한 단위를 공급하고 받는 금액에서 그 생산물에 붙는 세금을 빼고 생산물 보조금을 더한 가격","learning_example":"학습용 가정: 생산자가 물건 한 개를 공급하고 받는 생산자가격이 1만 원이고, 이 가격에 포함된 생산물세가 1천 원이며 생산물 보조금이 500원이면 기초가격은 1만 원 - 1천 원 + 500원 = 9,500원이에요."},"guard_data":{"meaning":"생산자 판매가격에서 세금을 빼고 보조금을 더한, 생산자가 실제로 갖는 몫","detailed_meaning":"기초가격(Basic Price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부에 서 주는 보조금(subsidy)을 더한 가격을 의미하는 것으로 순수하게 생산자(주로 기업)가 갖게 되는 몫을 말한다. 일반적으로 생산물을 최종 소비하는 소비자가 지불하는 가격 즉, 구매자가격에는 생산물세와 보조금, 운수비용, 거래마진 등이 모두 포함되어 있으며, 생산자가격은 기초가격에다 생산물세를 더하고 보조금을 차감한 가격을 말한다. 예를 들어정부가 국민 건강증진의 일환으로 축산농가를 지원하기 위해 우유 1병에 50원의 보조금을 주며 100원의 생산물세와 200원의 거래마진이 발생한다고 가정하자. 또한 이 우유가 상점에서 1,000원에 판매되고 있다고 하자. 이 경우 구매자가격은 소비자가 지불하는 가 격 1,000원이며, 생산자가격은 구매자가격 1,000원에서 유통업자의 몫인 거래마진 200 원을 뺀 800원이고, 기초가격은 생산자가격 800원에서 정부에 납부하는 세금 100원을 차감하고 정부로부터 받은 보조금 50원을 더한 750원이 된다. GDP를 추계할 때 생산물의 가격평가는 기초가격으로 하는 것을 원칙으로 하는데, 그 이유는 생산성 분석 등에 세금 등으로 인해 초래되는 분석결과의 왜곡을 피하기 위해서다.","learning_example":"학습용 가정: 생산자가 물건을 1만 원에 팔고 제품세 1천 원을 내며 보조금 500원을 받으면 기초가격은 9,500원이에요.","news_example":"생산자가 받은 가격에서 세금을 빼고 보조금을 더한 기초가격은 생산자가 실제로 갖는 몫을 보여준다.","visuals":null}},{"id":149,"word":"기회비용","before_data":{"meaning":"하나를 선택하면서 포기한 다른 선택지의 가치","learning_example":"한 시간 동안 수학 또는 영어를 공부할 수 있다고 해볼게요. 수학을 선택했다면 그 시간에 할 수 있었던 영어 공부의 가치가 기회비용이에요."},"after_data":{"meaning":"하나를 선택하면서 포기한 다른 대안들 가운데 가장 가치가 큰 대안의 가치","learning_example":"학습용 가정: 같은 한 시간에 무료 강의를 듣거나 아르바이트를 하거나 중고품 판매를 할 수 있고, 뒤의 두 활동에서 각각 순수입 1만 원과 7천 원을 얻는다고 해요. 강의를 선택하고 포기한 대안의 가치를 이 순수입으로만 비교하면 기회비용은 합계 1만 7천 원이 아니라 더 큰 1만 원이에요."},"guard_data":{"meaning":"하나를 선택하면서 포기한 다른 선택지의 가치","detailed_meaning":"인간의 욕구에 비해 자원이 부족한 현상을 희소성이라고 한다. 희소한 자원을 가지고 인간의 모든 욕구를 충족시킬 수 없기 때문에 인간은 누구든지 부족한 자원을 어느 곳에 우선으로 활용할 것인가를 결정하는 선택을 해야 한다. 즉 다양한 욕구의 대상들 가운데서 하나를 고를 수밖에 없다. 이때 포기한 선택의 욕구들로부터 예상되는 유·무형의 이익 중최선의 이익을 기회비용(Opportunity Cost)이라고 한다. 자원의 희소성이 존재하는 한 기회비용은 반드시 발생하게 되고 이는 경제문제를 발생시키는 근본요인이 된다. 기업은 투자를 선택할 경우 포기한 나머지 선택의 가치인 투자금액의 은행예금 이자 등이 기회비용이 된다.","learning_example":"한 시간 동안 수학 또는 영어를 공부할 수 있다고 해볼게요. 수학을 선택했다면 그 시간에 할 수 있었던 영어 공부의 가치가 기회비용이에요.","news_example":"대학원 진학을 택하면 그 기간에 직장에서 벌 수 있었던 소득이 기회비용이 된다.","visuals":null}},{"id":161,"word":"노동생산성","before_data":{"meaning":"노동자 한 사람이 일정 기간 동안 만들어 내는 생산량","visuals":[{"q":"같은 근로시간에 생산량이 100개에서 120개로 늘었어요. 노동생산성 변화는?","type":"quiz","answer":0,"options":["20% 상승","20% 하락","변화 없음"],"explanation":"노동 투입이 같을 때 산출량이 20% 늘면 노동생산성도 20% 높아져요.","lessonCheck":true}]},"after_data":{"meaning":"근로자 한 명이나 근로시간 한 시간 등 노동 한 단위당 만들어 낸 생산량","visuals":[{"q":"총근로시간이 100시간으로 같은 두 기간에 같은 제품의 생산량이 100개에서 120개로 늘었어요. 시간당 노동생산성은?","type":"quiz","answer":0,"options":["20% 상승","16.7% 상승","변화 없음"],"explanation":"시간당 생산량은 100개 ÷ 100시간 = 1개에서 120개 ÷ 100시간 = 1.2개로 늘어요. 증가율은 (1.2 - 1) ÷ 1 × 100 = 20%예요.","lessonCheck":true}]},"guard_data":{"meaning":"노동자 한 사람이 일정 기간 동안 만들어 내는 생산량","detailed_meaning":"노동자 1인이 일정 기간 동안 산출해 내는 생산량으로 정의된다. 생산활동이 활발하면 노동생산성 증가율도 높아지는 관계가 있으므로 동 지수의 동향은 생산활동의 흐름을 파악하는 주요 지표로 이용되고 있다. 한편 임금이 노동생산성보다 더 빠르게 상승하면 단위노동비용이 증가하기 때문에 기업은 제품가격의 상승 압력을 받게 되고 그 결과 제품의 가격경쟁력이 떨어질 수 있다. 나라 전체로 확대되면 물가상승 압력이 커지면서 다른 나 라에 비해 수출제품의 가격경쟁력이 낮아지게 된다. 노동생산성지수 = 산출량지수/노동투입량지수×100","learning_example":"학습용 가정: 노동자 한 명이 한 시간에 제품 10개를 만들었다면 시간당 노동생산성은 10개예요.","news_example":"자동화 설비 도입으로 근로자 한 명이 만들어 내는 생산량인 노동생산성이 크게 높아졌다.","visuals":[{"q":"같은 근로시간에 생산량이 100개에서 120개로 늘었어요. 노동생산성 변화는?","type":"quiz","answer":0,"options":["20% 상승","20% 하락","변화 없음"],"explanation":"노동 투입이 같을 때 산출량이 20% 늘면 노동생산성도 20% 높아져요.","lessonCheck":true}]}},{"id":169,"word":"단일금리방식","before_data":{"meaning":"입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식","learning_example":"학습용 가정: 낙찰된 금리 입찰이 2%, 2.5%, 3%라면 세 낙찰자 모두 3% 금리를 적용받아요.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식","type":"quiz","answer":0,"options":["단일금리방식","FTSE 지수","장내시장","스팩(SPAC)"],"explanation":"단일금리방식은/는 입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"채권 발행 입찰에서 낙찰자 모두에게 낙찰된 금리 중 가장 높은 금리를 공통 발행금리로 적용하는 방식","learning_example":"학습용 가정: 채권 발행 입찰을 단일금리방식으로 진행해 연 2%, 2.5%, 3%를 제시한 세 참가자가 낙찰받았다면 세 참가자 모두 연 3%의 발행금리를 적용받아요.","visuals":[{"q":"채권 발행 입찰에서 낙찰자들이 제시한 금리가 연 2%, 2.5%, 3%이고, 단일금리방식으로 발행해요. 적용되는 발행금리는?","type":"quiz","answer":0,"options":["모두 연 3%","각자 제시한 연 2%, 2.5%, 3%","모두 연 2%","모두 단순평균인 연 2.5%"],"explanation":"이 채권 발행의 단일금리방식은 낙찰금리 중 최고인 연 3%를 모두에게 적용해요. 각자 제시한 금리를 적용하는 것은 복수금리방식이며, 최저금리나 단순평균을 적용하는 방식이 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식","detailed_meaning":"경쟁입찰에 따른 발행금리 결정방식에는 복수금리(Conventional)방식과 단일금리 (Dutch)방식이 있다. 복수금리(가격)방식은 각 낙찰자가 입찰시 제시한 금리(가격)를 발행금리(발행가격)로 하는 방식이며, 단일금리(단일가격)방식은 각 낙찰자가 입찰시 제시한 금리(가격) 중 최고금리(최저가격)를 발행금리(발행가격)로 하는 방식이다. 유동성 흡수 시에는 금융기관의 자금운용을 제약한다는 점을 고려하여 금융기관에 유리하게 단일금리방식을 적용하는 반면 유동성 지원 시에는 금융기관의 입찰 독려를 위해 유인을 제공할 필요가 없으므로 복수금리결정방식을 적용하는 경향이 있다. 현재 통화안정증권 발행시 입찰시행 전에 발행금리 결정방식을 공고하고 있으며 입찰참가자에게 더욱 유리한 단일금리방식을 주로 사용한다. 그리고 공개시장운영 수단으로 환매조건부증권(RP) 매매를 경쟁입찰 방식으로 진행할 경우 RP매각 시에는 단일금리방식을, RP매입 시에는 복수금리방식을 주로 사용하고 있다.","learning_example":"학습용 가정: 낙찰된 금리 입찰이 2%, 2.5%, 3%라면 세 낙찰자 모두 3% 금리를 적용받아요.","news_example":"국채 입찰에서 낙찰자 모두에게 같은 금리를 적용하는 단일금리방식은 높은 금리를 써낸 응찰자의 부담을 줄인다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식","type":"quiz","answer":0,"options":["단일금리방식","FTSE 지수","장내시장","스팩(SPAC)"],"explanation":"단일금리방식은/는 입찰에서 낙찰된 가장 높은 금리를 모두에게 똑같이 적용하는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":183,"word":"동남아시아국가연합(ASEAN)","before_data":{"meaning":"동남아 10개국이 경제·사회 협력을 위해 만든 지역협력기구","detailed_meaning":"동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다. 동남아시아 지역협력의 촉진, 외국의 간섭 배제 및 역내 국가의 평화와 안정 수호, 경제·사회·문화·기술 등 각 분야에서의 상호원조를 설립목적으로 하고 있다. 회원국은 1967년 8월 창설 당시 필리핀, 말레이시아, 싱가포르, 인도네시아, 태국 등 5개국이었으나 1984년 브루나이, 1995년 베트남, 1997년 라오스와 미얀 마, 1999년 캄보디아가 차례로 가입하면서 총 10개국으로 늘어났다. 주요 기구로는 정상회의, 외교장관회의, 상임위원회와 함께 상설 사무국을 인도네시아 자카르타에 두고 있다. 1997년 창설 30주년을 맞아 공동의 비전으로 ASEAN Vision 2020을 도입하였고 이 에 따라 아세안정치보안공동체, 아세안경제공동체, 아세안사회문화공동체를 축으로 하는 역내 통합을 추구하고 있으며 2015년 12월 아세안경제공동체를 출범시킴으로써 단일시장 구축을 추진하고 있다. 이와 함께 역외 국가들과도 대화 관계를 수립해 경제·안보·문화 등의 영역에서 협력을 도모하고 있는데 이러한 대화 상대국은 한국을 비롯하여 미국, 일본, 중국, 러시아, 캐나다, 호주, 뉴질랜드, 인도, EU 등이다.","news_example":"동남아 10개국이 모인 동남아시아국가연합(ASEAN)과의 교역이 늘면서 이 지역이 주요 수출시장으로 떠올랐다."},"after_data":{"meaning":"동남아시아 11개국이 평화·안정과 경제·사회·문화 협력을 위해 구성한 지역협력기구","detailed_meaning":"동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다. 동남아시아 지역협력의 촉진, 외국의 간섭 배제 및 역내 국가의 평화와 안정 수호, 경제·사회·문화·기술 등 각 분야에서의 상호원조를 설립목적으로 하고 있다. 회원국은 1967년 8월 창설 당시 필리핀, 말레이시아, 싱가포르, 인도네시아, 태국 등 5개국이었으나 1984년 브루나이, 1995년 베트남, 1997년 라오스와 미얀 마, 1999년 캄보디아가 차례로 가입하면서 총 10개국으로 늘어났으며, 2025년 동티모르의 가입으로 11개국이 되었다. 주요 기구로는 정상회의, 외교장관회의, 상임위원회와 함께 상설 사무국을 인도네시아 자카르타에 두고 있다. 1997년 창설 30주년을 맞아 공동의 비전으로 ASEAN Vision 2020을 도입하였고 이 에 따라 아세안정치보안공동체, 아세안경제공동체, 아세안사회문화공동체를 축으로 하는 역내 통합을 추구하고 있으며 2015년 12월 아세안경제공동체를 출범시킴으로써 단일시장 구축을 추진하고 있다. 이와 함께 역외 국가들과도 대화 관계를 수립해 경제·안보·문화 등의 영역에서 협력을 도모하고 있는데 이러한 대화 상대국은 한국을 비롯하여 미국, 일본, 중국, 러시아, 캐나다, 호주, 뉴질랜드, 인도, EU 등이다.","news_example":"학습용 가정: 한 기업이 동남아시아국가연합(ASEAN)의 11개 회원국을 대상으로 수출 전략을 세웠다."},"guard_data":{"meaning":"동남아 10개국이 경제·사회 협력을 위해 만든 지역협력기구","detailed_meaning":"동남아시아의 지역협력기구로서 아세안(ASEAN; Association of South-East Asian Nations)이라고도 부른다. 동남아시아 지역협력의 촉진, 외국의 간섭 배제 및 역내 국가의 평화와 안정 수호, 경제·사회·문화·기술 등 각 분야에서의 상호원조를 설립목적으로 하고 있다. 회원국은 1967년 8월 창설 당시 필리핀, 말레이시아, 싱가포르, 인도네시아, 태국 등 5개국이었으나 1984년 브루나이, 1995년 베트남, 1997년 라오스와 미얀 마, 1999년 캄보디아가 차례로 가입하면서 총 10개국으로 늘어났다. 주요 기구로는 정상회의, 외교장관회의, 상임위원회와 함께 상설 사무국을 인도네시아 자카르타에 두고 있다. 1997년 창설 30주년을 맞아 공동의 비전으로 ASEAN Vision 2020을 도입하였고 이 에 따라 아세안정치보안공동체, 아세안경제공동체, 아세안사회문화공동체를 축으로 하는 역내 통합을 추구하고 있으며 2015년 12월 아세안경제공동체를 출범시킴으로써 단일시장 구축을 추진하고 있다. 이와 함께 역외 국가들과도 대화 관계를 수립해 경제·안보·문화 등의 영역에서 협력을 도모하고 있는데 이러한 대화 상대국은 한국을 비롯하여 미국, 일본, 중국, 러시아, 캐나다, 호주, 뉴질랜드, 인도, EU 등이다.","learning_example":"동남아시아 나라들이 무역과 사회 문제를 함께 논의하며 지역 협력을 추진해요.","news_example":"동남아 10개국이 모인 동남아시아국가연합(ASEAN)과의 교역이 늘면서 이 지역이 주요 수출시장으로 떠올랐다.","visuals":null}},{"id":186,"word":"듀레이션","before_data":{"meaning":"채권 투자금을 돌려받는 데 걸리는 평균 기간(금리 민감도 지표)","learning_example":"이자와 원금을 여러 번 받는 채권은 각 현금을 받는 시점으로 평균 회수 기간을 계산해요."},"after_data":{"meaning":"채권의 이자·원금을 받는 시점을 각 금액의 현재가치 비중으로 가중평균한 기간으로, 금리 변화에 따른 가격 민감도를 보여 주는 지표","learning_example":"학습용 가정: 1년 뒤 받을 이자의 현재가치가 10만 원이고 2년 뒤 받을 원리금의 현재가치가 90만 원인 채권의 듀레이션은 1년 × 10% + 2년 × 90% = 1.9년이에요."},"guard_data":{"meaning":"채권 투자금을 돌려받는 데 걸리는 평균 기간(금리 민감도 지표)","detailed_meaning":"듀레이션(Duration)이란 채권에서 발생하는 현금흐름의 가중평균만기로 투자자금의 평균회수기간을 의미한다. 듀레이션은 채권의 현금흐름 발생기간(t)에 각 시점 현금흐름의 현재가치가 채권가격에서 차지하는 비중을 가중치로 곱하여 산출한다. 채권의 발행만기는 최종 현금흐름 시점을 나타내는 데 비해 듀레이션은 만기 이전에 발생하는 모든 현금흐름을 감안한 평균회수기간이기 때문에 만기 이전에 현금흐름이 발생하는 이표채권의 듀레이션은 항상 채권의 발행만기보다 짧다. 할인채의 경우 현금흐름이 만기시점에 한번만 존재하므로 듀레이션과 만기가 같다. 듀레이션은 채권의 만기, 표면금리, 만기수익률등에 따라 결정된다. 먼저 듀레이션은 일종의 만기 개념이므로 만기에 비례하여 길어진다. 또한 채권의 표면금리가 높을수록 초기에 많은 금액이 회수되므로 듀레이션은 짧아진다. 마지막으로 현금흐름의 현재가치를 산정하는 할인율로 쓰이는 만기수익률이 높을수록 만기에 가까운 현금흐름의 가중치가 상대적으로 작아져 듀레이션은 짧아진다. 한편 듀레이션은 채권가격의 이자율탄력성을 나타낸다. 즉 듀레이션(D), 채권가격(p), 만기수익률(r) 사이에는 (dp/p) = -〔dr/(1+r)〕× D의 관계가 성립한다. 따라서 듀레이션은 채권투자에 따른 이자율위험(시장이자율 변동에 따른 채권가격의 변동률)을 나타내는 척도이자중요한 리스크 관리수단으로 활용되고 있다.","learning_example":"이자와 원금을 여러 번 받는 채권은 각 현금을 받는 시점으로 평균 회수 기간을 계산해요.","news_example":"만기가 긴 채권일수록 듀레이션이 길어 금리가 오를 때 가격 하락 폭이 커진다.","visuals":[{"type":"flow","steps":["연 3% 이자를 주는 채권을 가지고 있음","시장금리가 5%로 ↑","새로 나오는 채권은 5% 이자를 줌","3% 채권은 덜 매력적이라 싸게 팔아야 함","기존 채권가격 ↓"],"title":"금리가 오르면 채권가격이 내려가는 이유","caption":"금리가 내리면 반대예요. 예전에 산 높은 이자 채권이 귀해져 가격이 올라요."}]}},{"id":195,"word":"레버리지비율","before_data":{"meaning":"위험가중 없이 총자산 대비 기본자본이 얼마인지 보는 은행 건전성 비율"},"after_data":{"meaning":"은행의 기본자본을 보증 등 난외항목까지 포함한 총위험노출액으로 나눈 비율로, 자산별 위험가중치는 적용하지 않는 건전성 지표"},"guard_data":{"meaning":"위험가중 없이 총자산 대비 기본자본이 얼마인지 보는 은행 건전성 비율","detailed_meaning":"레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다. 분자의 자본은 바젤Ⅲ 기준 기본자본(Tier 1)을 사용하며 분모의 총익스포저는 자기자본비율을 산정할 경우에 적용되는 위험가중자산과는 달리 명목가액을 기준으로 하여 산출한다. 자기자본비율 규제 하에서 은행은 호황기에 보유자산의 위험가 중치를 낮게 설정함으로써 외형상 높은 자기자본 수준을 유지하면서 레버리지를 확대할수 있었다. 이 경우 위기 발생시 급격한 디레버리징(자산처분, 부채상환)이 발생하여 위기가 증폭되는 악순환이 발생할 수 있는데, 레버리지비율 규제는 이러한 자기자본비율 규제의 문제점을 보완한다고 할 수 있다. 바젤은행감독위원회(BCBS)는 2015년 1월부터 레버리지비율 공시를 의무화하였으며 은행들은 2018년 1월부터 최저 레버리지비율(3%)도 준수해야 한다. 이 밖에도 글로벌 시스템적 중요 은행(G-SIB)에게는 2022년 1월부터 시스템적중요도에 따라 국별로 추가 레버리지비율이 적용되고 있다. 이는 위험가중자산 기반 자기자본비율 규제에서 G-SIB에 대해 부과하고 있는 추가자본 규제와의 일관성을 갖추기 위한 것으로 G-SIB은 자기자본비율 규제상 부과되는 추가자본의 50%만큼 상향 조정된 레버리지비율을 준수해야 한다. 예를 들어 2%의 추가자본이 부과된 G-SIB이 준수해야 할레버리지비율은 최저 레버리지비율 3%에 추가자본의 50%에 해당하는 1%가 가산된 4% 가 된다. G-SIB이 동 레버리지비율을 준수하지 못할 경우, 추가자본의 미준수시와 동일하게 이익배분이 제한된다. 우리나라는 레버리지비율을 「은행업감독규정」에서 단순기본자본비율로 정의하고 있으며 2015년 1분기부터 보조지표로 공시된 후 2018년부터 동 규제(3% 이상)가 시행되었으며 2020년 1월부터는 인터넷전문은행에도 적용되었다.","learning_example":"학습용 가정: 은행의 기본자본이 5억 원이고 익스포저가 100억 원이면 레버리지비율은 5%예요.","news_example":"위험가중치 없이 총자산 대비 기본자본을 따지는 레버리지비율 규제로 은행의 과도한 자산 확대를 막는다.","visuals":null}},{"id":208,"word":"머니마켓펀드(MMF)","before_data":{"meaning":"여윳돈을 국공채·어음 등 안전한 단기상품에 굴려 수시로 넣고 빼는 펀드","learning_example":"투자자가 잠시 쓸 계획이 없는 돈을 MMF에 넣고 펀드는 만기가 짧은 채권 등에 투자해요."},"after_data":{"meaning":"잠시 맡긴 돈을 국공채·우량 어음 등 단기 금융상품에 투자하는 펀드","learning_example":"학습용 가정: 한 달 뒤 쓸 100만 원을 MMF에 투자했어요. 단기 채권 등에 운용되지만 예금처럼 원금이나 즉시 출금이 보장되는 것은 아니어서 환매 일정을 확인해요."},"guard_data":{"meaning":"여윳돈을 국공채·어음 등 안전한 단기상품에 굴려 수시로 넣고 빼는 펀드","detailed_meaning":"머니마켓펀드(MMF; Money Market Fund)는 고객의 일시적인 여유자금을 금리위험과 신용위험이 적은 국공채, 어음 등에 운용하고 동 운용에서 발생하는 수익을 배당하는 펀드의 일종으로서 대표적인 단기금융상품이다. MMF로 들어온 자금은 주로 부도 위험이 거의 없는 국채, 통화안정증권 등의 채권, 우량 CP, CD 및 예금 등으로 운용하며 운용자산의 가중평균 잔존만기가 60일(시가평가의 경우는 120일) 이내로 제한된다. 편입자산의 신용등급은 취득시점을 기준으로 상위 2개 등급 이내(채권 AA이상, CP A2 이상)여야 하며 주식과 관련이 있는 채권(전환사채 등)이나 사모발행채권 등은 운용대상 자산에서 제외된다. 2022년 4월부터 법인형 MMF에 대해 시가평가제도가 도입되었으나 안정적 자산의 비중이 30%를 초과하는 MMF의 경우 기존과 같이 장부가 평가가 허용된다. 이에 따라현재 대부분의 MMF는 안정성을 추구하는 투자자의 선호를 반영하여 장부가 평가를 적용받기 위한 운용행태를 나타내고 있다. MMF는 유동성 측면에서 익일 설정 및 익일 환매가 이루어짐에 따라 다른 펀드에 비해 유동성이 높은 편이며 자산의 운용은 자산운용사가, 판매는 은행 및 증권사가 하고 있다.","learning_example":"투자자가 잠시 쓸 계획이 없는 돈을 MMF에 넣고 펀드는 만기가 짧은 채권 등에 투자해요.","news_example":"금리가 높은 단기 채권과 어음에 투자하는 머니마켓펀드(MMF)로 수시로 넣고 빼려는 대기 자금이 몰렸다.","visuals":null}},{"id":209,"word":"명목GDP목표제","before_data":{"meaning":"물가 대신 명목 국내총생산 증가율을 목표로 삼는 통화정책 방식","learning_example":"중앙은행이 물가와 실질 생산을 함께 반영하는 명목 GDP의 증가 속도를 정책 목표로 삼아요."},"after_data":{"meaning":"물가와 생산량 변화를 함께 반영하는 명목 국내총생산이 정해 둔 목표 경로를 따르도록 하는 통화정책 방식","learning_example":"학습용 가정: 명목 GDP 목표 경로를 올해 1,000조 원, 내년 1,050조 원으로 정했어요. 중앙은행은 물가와 실질 생산을 함께 살펴 명목 GDP가 이 경로에 가까워지도록 정책을 검토해요."},"guard_data":{"meaning":"물가 대신 명목 국내총생산 증가율을 목표로 삼는 통화정책 방식","detailed_meaning":"명목GDP목표제란 명목GDP가 사전에 정한 목표수준을 따라가는 것을 목표로 하는 통화정책 운영체제이다. 이는 글로벌 금융위기 이후 저인플레이션, 저성장, 저금리 현상이 지속됨에 따라 물가안정목표제의 대안으로 일부 학계를 중심으로 제시된 방안이다. 명목 GDP목표제에서는 물가와 실물경제에 동일한 가중치를 부여하기 때문에 경기부진에 보다 적극적으로 대응하는 것이 가능하다. 또한 유가급등과 같은 공급충격으로 물가상승과 생산감소가 동시에 발생하는 경우 어느 정도의 물가상승을 허용하여 생산감소폭을 축소시키는 유연한 정책대응이 가능하다는 장점도 있다. 그러나 명목GDP목표제의 경우 물가 안정에 대한 중앙은행의 신뢰성을 확보하기 어렵고 현실 적합성이 크게 떨어진다는 단점이 있다. 물가와 경기를 동시에 고려하기 때문에 명목기준지표로서의 명료성이 떨어지고 기대 인플레이션을 안정적으로 관리하기가 어렵다. 또한 목표대상지표의 포괄범위도 넓어중앙은행의 통제가능성도 낮다. 이러한 한계로 현재 명목GDP목표제를 실제로 채택한 사례는 아직 없는 상황이다.","learning_example":"중앙은행이 물가와 실질 생산을 함께 반영하는 명목 GDP의 증가 속도를 정책 목표로 삼아요.","news_example":"물가 대신 명목 국내총생산 증가율을 목표로 하는 명목GDP목표제를 도입하자는 주장이 제기됐다.","visuals":null}},{"id":217,"word":"무위험지표금리(KOFR)","before_data":{"meaning":"국채를 담보로 한 하루짜리 환매조건부매매 금리로 만든 우리나라의 무위험 기준금리","detailed_meaning":"무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리 (RFR; Risk-Free Reference Rate)이다. 이는 투자자가 신용 리스크 없이 얻을 수 있는 이론상의 최소 수익률을 나타내는 금리로서 LIBOR 금리 조작사건 등 기존 금융거래지표의 신뢰도 하락을 계기로 개발된 대체지표금리이다. KOFR는 국채·통안증권을 담보로 하는 초단기 거래이기 때문에 무위험 금리에 가깝고, 실거래에 기반하여 산출되기 때문에 조작 가능성이 없는 것이 특징이다. 우리나라는 2021년 2월 RFR로 RP거래금리를 최종선정했으며, 증권결제 및 장외 RP거래 환매서비스를 제공하는 기관인 한국예탁결제원이 중요지표 산출기관으로 최종 선정되어 KOFR의 산출·공시 업무를 수행하고 있다. 한국무위험지표금리(KOFR)는 2021년 11월 26일부터 「금융거래지표의 관리에 관한 법률」에 따른 중요지표로서 정식 공시를 시작하였으며, KOFR Index는 2018년 1월 2일을 기준시점으로 1,000을 기준지수로 하여 산출된다. KOFR는 신뢰할 수 있는 지표금리 제공을 통해 금융시장의 안정성을 높이며, 국제적인 금리 기준과의 정합성을 높여 국내 금융시장의 국제화를 촉진한다. 또한, 시장에서 실제로 거래된 금리를 기반으로 산출함으로써 금리 산정의 투명성을 높이는 KOFR는 국내 금융시장에서 중요한 역할을 수행하며, 앞으로 더욱 다양한 분야에서 활용될 것으로 기대된다.","learning_example":"국채를 담보로 하루 자금을 빌리는 거래의 금리를 모아 한국의 무위험지표금리를 산출해요."},"after_data":{"meaning":"국채·통화안정증권을 담보로 한 하루짜리 환매조건부매매의 실제 금리로 산출하는 우리나라 무위험지표금리","detailed_meaning":"무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리 (RFR; Risk-Free Reference Rate)이다. 이는 이론상의 무위험 이자율에 가까운 시장금리를 제공하기 위한 지표로서 LIBOR 금리 조작사건 등 기존 금융거래지표의 신뢰도 하락을 계기로 개발된 대체지표금리이다. KOFR는 국채·통안증권을 담보로 하는 초단기 거래이기 때문에 무위험 금리에 가깝고, 실거래에 기반하여 산출되기 때문에 조작 가능성이 매우 낮은 것이 특징이다. 우리나라는 2021년 2월 RFR로 RP거래금리를 최종선정했으며, 증권결제 및 장외 RP거래 환매서비스를 제공하는 기관인 한국예탁결제원이 중요지표 산출기관으로 최종 선정되어 KOFR의 산출·공시 업무를 수행하고 있다. 한국무위험지표금리(KOFR)는 2021년 11월 26일부터 「금융거래지표의 관리에 관한 법률」에 따른 중요지표로서 정식 공시를 시작하였으며, KOFR Index는 2018년 1월 2일을 기준시점으로 1,000을 기준지수로 하여 산출된다. KOFR는 신뢰할 수 있는 지표금리 제공을 통해 금융시장의 안정성을 높이며, 국제적인 금리 기준과의 정합성을 높여 국내 금융시장의 국제화를 촉진한다. 또한, 시장에서 실제로 거래된 금리를 기반으로 산출함으로써 금리 산정의 투명성을 높이는 KOFR는 국내 금융시장에서 중요한 역할을 수행하며, 앞으로 더욱 다양한 분야에서 활용될 것으로 기대된다.","learning_example":"학습용 가정: 금융기관이 국채 또는 통화안정증권을 담보로 오늘 원화를 빌리고 내일 갚는 거래를 해요. 이런 실제 거래의 금리와 금액을 모아 KOFR를 산출해요."},"guard_data":{"meaning":"국채를 담보로 한 하루짜리 환매조건부매매 금리로 만든 우리나라의 무위험 기준금리","detailed_meaning":"무위험지표금리(KOFR)는 Korea Overnight Financing Repo Rate의 약자로서, 국채· 통안증권을 담보로 하는 익일물 RP금리를 사용하여 산출한 우리나라의 무위험지표금리 (RFR; Risk-Free Reference Rate)이다. 이는 투자자가 신용 리스크 없이 얻을 수 있는 이론상의 최소 수익률을 나타내는 금리로서 LIBOR 금리 조작사건 등 기존 금융거래지표의 신뢰도 하락을 계기로 개발된 대체지표금리이다. KOFR는 국채·통안증권을 담보로 하는 초단기 거래이기 때문에 무위험 금리에 가깝고, 실거래에 기반하여 산출되기 때문에 조작 가능성이 없는 것이 특징이다. 우리나라는 2021년 2월 RFR로 RP거래금리를 최종선정했으며, 증권결제 및 장외 RP거래 환매서비스를 제공하는 기관인 한국예탁결제원이 중요지표 산출기관으로 최종 선정되어 KOFR의 산출·공시 업무를 수행하고 있다. 한국무위험지표금리(KOFR)는 2021년 11월 26일부터 「금융거래지표의 관리에 관한 법률」에 따른 중요지표로서 정식 공시를 시작하였으며, KOFR Index는 2018년 1월 2일을 기준시점으로 1,000을 기준지수로 하여 산출된다. KOFR는 신뢰할 수 있는 지표금리 제공을 통해 금융시장의 안정성을 높이며, 국제적인 금리 기준과의 정합성을 높여 국내 금융시장의 국제화를 촉진한다. 또한, 시장에서 실제로 거래된 금리를 기반으로 산출함으로써 금리 산정의 투명성을 높이는 KOFR는 국내 금융시장에서 중요한 역할을 수행하며, 앞으로 더욱 다양한 분야에서 활용될 것으로 기대된다.","learning_example":"국채를 담보로 하루 자금을 빌리는 거래의 금리를 모아 한국의 무위험지표금리를 산출해요.","news_example":"국채 담보 하루짜리 환매조건부매매 금리로 산출되는 무위험지표금리(KOFR)를 기준으로 한 금융상품이 늘고 있다.","visuals":[{"type":"flow","steps":["기준금리 ↑","시장금리 ↑","무위험수익률 ↑","WACC·요구수익률 ↑","미래 현금흐름의 할인율 ↑","DCF 현재가치 ↓","주식의 적정가치 ↓"],"title":"금리가 오르면 주식의 적정가치가 낮아지는 이유","caption":"같은 미래 이익도 할인율이 높을수록 지금 가치로는 작아져요. 금리가 내리면 반대로 적정가치가 높아져요."}]}},{"id":226,"word":"반대매매","before_data":{"meaning":"빚으로 산 주식의 담보가치가 떨어지면 증권사가 강제로 팔아 버리는 것","learning_example":"빚을 내 주식을 산 뒤 주가가 크게 떨어지자 증권사가 담보 부족분을 메우기 위해 주식을 팔아요."},"after_data":{"meaning":"미수금이나 대출금을 제때 갚지 못하거나 담보 부족을 해소하지 못하면 증권사 등이 주식을 강제로 처분하는 것","learning_example":"학습용 가정: 투자자가 미수거래로 산 주식의 결제대금 50만 원을 약정 기한까지 내지 못했어요. 주가가 떨어지지 않았어도 증권사가 약정에 따라 주식을 강제로 팔아 미납금을 회수할 수 있어요."},"guard_data":{"meaning":"빚으로 산 주식의 담보가치가 떨어지면 증권사가 강제로 팔아 버리는 것","detailed_meaning":"반대매매(Reverse Trading)란 만기까지 대출금을 갚지 못하거나 담보가치가 일정 비율이하로 떨어지면 증권사가 주식을 강제로 처분하는 것을 의미한다. 신용매매(보유 주식을 담보로 하여 증권사 자금으로 거래), 스탁론 서비스(외상으로 주식 매수), 미수 거래(담보없는 위탁매매) 계좌를 이용해 주식을 매입했을 경우 주가하락에 따른 담보비율 하락으로 반대매매가 쏟아질 수 있다. 통상 미수거래의 경우에는 3일, 신용거래의 경우에는 1달~3 달이 상환기한이며 이 기간 안에 반대매매를 통해 상환하지 않는 경우나 담보가치가 일정 비율 이하로 하락할 때는 증권사에서 임의적으로 반대매매를 실시한다. 반대매매는 전날 종가 대비 20~30% 낮은 금액으로 주문이 산정되기 때문에 주가에 악영향을 미친다. 특히 개인투자자 지분율이 높은 코스닥시장 종목에 미치는 영향이 크다. 반대매매의 종류에는 크게 세 가지가 있다. 먼저 개장과 동시에 이뤄지는 반대매매다. 증권사로부터 돈을 빌린 신용융자, 예탁증권담보대출의 담보비율이 일정 수준 이하로 내려갔을 때 발생한다. 둘째, 증권사로부터 돈을 빌려 주식을 사고 2거래일 뒤에 상환하는 미수거래도 만기안에 갚지 못할 경우 장 시작 전 동시호가 때 반대매매로 처분된다. 신용융자와 예탁증권담보대출의 담보비율은 증권사와 종목마다 다르지만 통상 140% 안팎 수준이다. 예를 들어 자기자금 1억원과 대출금 1억원을 합친 2억원으로 주식을 매입할 경우 대출금 1억원의 140%인 1억4000만원 상당의 주식을 갖고 있어야 한다. 주식의 가치가 그 밑으로 떨어지면 증권사가 추가 증거금을 요구한다. 담보부족이 발생하면 투자자들은 다음날까지부족 금액을 채워 넣어야 한다. 그렇지 못할 경우 2거래일 뒤 증권사에서 강제로 반대매매에 나선다. 차액결제거래(CFD)는 주식 등 기초자산을 보유하지 않고 가격 변동에 따른차익만 결제하는 파생상품을 말하는데 일반 현물 주식 매매와 달리 거래 과정에 외국계증권사가 포함된다. 국내 투자자가 주문하더라도 실제 사고파는 주체가 외국계 증권사이 기 때문에 투자 주체별 거래 실적에 외국인 수급으로 잡힌다. 오전 10시를 전후로 외국인매도가 쏟아진다면 CFD 반대매매 물량으로 추정할 수 있다. 마지막으로 오후 2시에는 저축은행과 캐피털사로부터 자금을 빌린 주식매입자금대출(스탁론)의 반대매매가 나온다.스탁론의 담보비율은 통상 120% 안팎으로 증권사가 제공하는 신용융자나 예탁증권담보","learning_example":"빚을 내 주식을 산 뒤 주가가 크게 떨어지자 증권사가 담보 부족분을 메우기 위해 주식을 팔아요.","news_example":"주가 급락으로 빚을 내 산 주식의 담보가치가 떨어지자 증권사가 강제로 처분하는 반대매매가 급증했다.","visuals":null}},{"id":234,"word":"범위의 경제","before_data":{"meaning":"한 기업이 여러 제품을 함께 만들 때 평균 비용이 줄어드는 현상","learning_example":"한 회사가 배송망을 함께 써서 음료와 과자를 팔면 각 제품을 따로 운영할 때보다 비용을 줄일 수 있어요."},"after_data":{"meaning":"같은 양의 여러 제품을 각각 따로 생산할 때보다 함께 생산할 때 총비용이 줄어드는 현상","learning_example":"학습용 가정: 음료 1만 개와 과자 1만 개를 따로 생산·배송하면 각각 300만 원과 200만 원이 들어요. 같은 수량을 함께 생산·배송해 450만 원이 든다면 50만 원의 범위의 경제가 있어요."},"guard_data":{"meaning":"한 기업이 여러 제품을 함께 만들 때 평균 비용이 줄어드는 현상","detailed_meaning":"개별 기업이 한 종류의 제품만을 생산하는 경우보다 여러 제품을 같이 생산하면서 평균생산비용이 적게 들 때 범위의 경제(Economies of Scope)가 존재한다고 말한다. 승용차와 트럭을 같이 생산하는 기업의 경우 소재부품이나 조립라인 등의 생산시설을 공동으로 사용할 수 있는 이점을 갖게 된다. 이러한 현상은 동일한 생산요소를 사용하거나 기업운영 및 마케팅 활동을 함께 하거나 생산물이 가진 특성 때문에도 나타날 수 있다. 연구개발·판매·생산은 공동으로 하면서 제품의 종류만 달리할 경우 비용이 절감될 수 있다. 또한 기존 산업과 비슷한 산업에 진출할 경우 시너지효과를 기대할 수 있는데, 구체적인 예로는 은행이 보험 상품을 판매하는 방카슈랑스를 들 수 있다.","learning_example":"한 회사가 배송망을 함께 써서 음료와 과자를 팔면 각 제품을 따로 운영할 때보다 비용을 줄일 수 있어요.","news_example":"한 회사가 여러 금융상품을 함께 팔면 판매망을 공유해 비용이 줄어드는 범위의 경제를 누릴 수 있다.","visuals":null}},{"id":241,"word":"보완재","before_data":{"meaning":"자동차와 휘발유처럼 함께 써야 효용이 생기는 짝꿍 재화","learning_example":"자동차 사용이 늘면 함께 필요한 휘발유 수요도 늘 수 있어요.","visuals":[{"body":"햄버거와 콜라, 짜장면과 단무지처럼 함께 쓸 때 만족이 커지는 상품이에요.\n콜라 값이 오르면 세트로 먹는 부담이 커져 햄버거 수요가 줄어요.\n상대 상품의 값과 내 상품의 수요가 반대 방향으로 움직여요.","type":"text","title":"보완재 쉽게 설명"},{"rows":[["샌드위치(대체재) 값 하락","감소","왼쪽 이동"],["샌드위치(대체재) 값 상승","증가","오른쪽 이동"],["콜라(보완재) 값 하락","증가","오른쪽 이동"],["콜라(보완재) 값 상승","감소","왼쪽 이동"]],"type":"table","title":"햄버거 수요는 어떻게 움직일까","caption":"햄버거 자기 값이 바뀔 때는 곡선은 그대로이고 곡선 위에서 점만 움직여요.","columns":["바뀐 것","햄버거 수요","수요곡선"]},{"q":"프린터 잉크 값이 크게 올랐어요. 프린터 수요는 어떻게 될까요?","type":"quiz","answer":0,"options":["줄어서 수요곡선이 왼쪽으로 이동해요","늘어서 수요곡선이 오른쪽으로 이동해요","프린터 값이 그대로라 전혀 변하지 않아요","수요곡선 위에서 점만 움직여요"],"explanation":"프린터와 잉크는 함께 쓰는 보완재예요. 잉크 값이 오르면 프린터를 쓰는 부담이 커져 같은 가격에서도 덜 사니 수요곡선이 왼쪽으로 움직여요.","lessonCheck":true},{"q":"교차탄력성이 음수(-)인 두 상품의 예로 알맞은 것은?","type":"quiz","answer":0,"options":["자동차와 휘발유","콜라와 사이다","버터와 마가린","버스와 지하철"],"explanation":"한쪽 값이 오를 때 다른 쪽 수요가 줄면 교차탄력성이 음수예요. 함께 쓰는 자동차와 휘발유 같은 보완재가 그래요."},{"rows":[["뜻","함께 쓸 때 만족이 커지는 재화","서로 대신 쓸 수 있는 재화"],["예시","커피와 설탕, 프린터와 잉크","버터와 마가린, 콜라와 사이다"],["한쪽 가격이 오르면","다른 쪽 수요 감소","다른 쪽 수요 증가"]],"type":"table","title":"보완재와 대체재","columns":["구분","보완재","대체재"]}]},"after_data":{"meaning":"함께 사용할 때 효용이 커지고, 다른 조건이 같을 때 한쪽 가격이 오르면 다른 쪽 수요가 줄어드는 관계의 재화","learning_example":"학습용 가정: 프린터 가격과 소득 등은 그대로인데 전용 잉크 가격이 2만 원에서 3만 원으로 올랐어요. 유지비 부담 때문에 같은 가격의 프린터를 사려는 사람이 줄면 프린터와 잉크는 보완재 관계예요.","visuals":[{"body":"햄버거와 콜라, 짜장면과 단무지처럼 함께 쓸 때 만족이 커지는 상품이에요.\n콜라 값이 오르면 세트로 먹는 부담이 커져 햄버거 수요가 줄어요.\n상대 상품의 값과 내 상품의 수요가 반대 방향으로 움직여요.","type":"text","title":"보완재 쉽게 설명"},{"rows":[["샌드위치(대체재) 값 하락","감소","왼쪽 이동"],["샌드위치(대체재) 값 상승","증가","오른쪽 이동"],["콜라(보완재) 값 하락","증가","오른쪽 이동"],["콜라(보완재) 값 상승","감소","왼쪽 이동"]],"type":"table","title":"햄버거 수요는 어떻게 움직일까","caption":"햄버거 자기 값이 바뀔 때는 곡선은 그대로이고 곡선 위에서 점만 움직여요.","columns":["바뀐 것","햄버거 수요","수요곡선"]},{"q":"프린터 가격과 소득 등 다른 조건은 그대로인데 전용 잉크 가격만 크게 올랐어요. 보완재 관계인 프린터의 수요곡선은 어떻게 될까요?","type":"quiz","answer":0,"options":["줄어서 수요곡선이 왼쪽으로 이동해요","늘어서 수요곡선이 오른쪽으로 이동해요","프린터 값이 그대로라 전혀 변하지 않아요","수요곡선 위에서 점만 움직여요"],"explanation":"보완재인 잉크 가격이 올라 사용 비용이 커지면, 각 프린터 가격에서 사려는 양이 줄어 수요곡선이 왼쪽으로 이동해요. 프린터 자체 가격의 변화에 따른 곡선 위 이동과 달라요.","lessonCheck":true},{"q":"다른 조건이 같을 때 A상품 가격이 10% 오르자 B상품 수요량이 5% 줄었어요. 두 상품의 관계와 교차탄력성은?","type":"quiz","answer":0,"options":["보완재이며 교차탄력성은 -0.5","대체재이며 교차탄력성은 +0.5","보완재이며 교차탄력성은 -2","대체재이며 교차탄력성은 +2"],"explanation":"교차탄력성은 B 수요량 변화율 ÷ A 가격 변화율이므로 -5% ÷ 10% = -0.5예요. 음수이므로 보완재 관계예요."},{"rows":[["뜻","함께 쓸 때 만족이 커지는 재화","서로 대신 쓸 수 있는 재화"],["예시","커피와 설탕, 프린터와 잉크","버터와 마가린, 콜라와 사이다"],["한쪽 가격이 오르면","다른 쪽 수요 감소","다른 쪽 수요 증가"]],"type":"table","title":"보완재와 대체재","columns":["구분","보완재","대체재"]}]},"guard_data":{"meaning":"자동차와 휘발유처럼 함께 써야 효용이 생기는 짝꿍 재화","detailed_meaning":"두 가지 이상의 재화가 함께 사용됨으로써 효용을 얻을 수 있는 재화로, 한 재화의 가격이 하락함에 따라 다른 한 재화의 수요가 증가하는 관계에 있는 재화를 말한다. 소비자 효용의 관점에서 볼 때, 소비자는 보완재 관계에 있는 두 재화를 따로 소비할 때의 효용이 함께 소비할 때의 효용보다 줄어든다. 승용차와 휘발유, 컴퓨터와 소프트웨어 등은 보완재의 예이다.","learning_example":"자동차 사용이 늘면 함께 필요한 휘발유 수요도 늘 수 있어요.","news_example":"자동차와 휘발유처럼 함께 쓰는 보완재는 한쪽 가격이 오르면 다른 쪽 수요도 줄어든다.","visuals":[{"body":"햄버거와 콜라, 짜장면과 단무지처럼 함께 쓸 때 만족이 커지는 상품이에요.\n콜라 값이 오르면 세트로 먹는 부담이 커져 햄버거 수요가 줄어요.\n상대 상품의 값과 내 상품의 수요가 반대 방향으로 움직여요.","type":"text","title":"보완재 쉽게 설명"},{"rows":[["샌드위치(대체재) 값 하락","감소","왼쪽 이동"],["샌드위치(대체재) 값 상승","증가","오른쪽 이동"],["콜라(보완재) 값 하락","증가","오른쪽 이동"],["콜라(보완재) 값 상승","감소","왼쪽 이동"]],"type":"table","title":"햄버거 수요는 어떻게 움직일까","caption":"햄버거 자기 값이 바뀔 때는 곡선은 그대로이고 곡선 위에서 점만 움직여요.","columns":["바뀐 것","햄버거 수요","수요곡선"]},{"q":"프린터 잉크 값이 크게 올랐어요. 프린터 수요는 어떻게 될까요?","type":"quiz","answer":0,"options":["줄어서 수요곡선이 왼쪽으로 이동해요","늘어서 수요곡선이 오른쪽으로 이동해요","프린터 값이 그대로라 전혀 변하지 않아요","수요곡선 위에서 점만 움직여요"],"explanation":"프린터와 잉크는 함께 쓰는 보완재예요. 잉크 값이 오르면 프린터를 쓰는 부담이 커져 같은 가격에서도 덜 사니 수요곡선이 왼쪽으로 움직여요.","lessonCheck":true},{"q":"교차탄력성이 음수(-)인 두 상품의 예로 알맞은 것은?","type":"quiz","answer":0,"options":["자동차와 휘발유","콜라와 사이다","버터와 마가린","버스와 지하철"],"explanation":"한쪽 값이 오를 때 다른 쪽 수요가 줄면 교차탄력성이 음수예요. 함께 쓰는 자동차와 휘발유 같은 보완재가 그래요."},{"rows":[["뜻","함께 쓸 때 만족이 커지는 재화","서로 대신 쓸 수 있는 재화"],["예시","커피와 설탕, 프린터와 잉크","버터와 마가린, 콜라와 사이다"],["한쪽 가격이 오르면","다른 쪽 수요 감소","다른 쪽 수요 증가"]],"type":"table","title":"보완재와 대체재","columns":["구분","보완재","대체재"]}]}},{"id":259,"word":"불완전경쟁시장","before_data":{"meaning":"독점·과점처럼 소수 기업이 가격에 영향을 줄 수 있는 시장","learning_example":"한 지역에 통신사가 두 곳뿐이면 각 회사가 요금 결정에 영향을 줄 수 있어요."},"after_data":{"meaning":"독점·과점·독점적 경쟁처럼 기업이 시장가격에 영향을 줄 수 있는 시장","learning_example":"학습용 가정: 한 동네에 빵집이 20곳 있지만 각 가게의 맛과 브랜드가 달라요. 한 가게가 가격을 조금 올려도 일부 단골이 계속 산다면 기업이 많아도 독점적 경쟁이라는 불완전경쟁이 나타날 수 있어요."},"guard_data":{"meaning":"독점·과점처럼 소수 기업이 가격에 영향을 줄 수 있는 시장","detailed_meaning":"시장에 의한 가격결정에 어떠한 영향도 미칠 수 없는 상태를 완전경쟁이라 한다. 이는 경제주체의 자유로운 시장 진입과 퇴출, 다수의 공급자와 수요자 존재, 거래되는 재화 및 서비스의 동질성, 정보의 완전성이 충족되는 경우에만 존재 가능하다. 현실에서는 이러한 요건이 충족되기 어려워 독점시장, 과점시장과 독점적 경쟁시장과 같은 형태의 불완전경쟁시장이 나타나게 된다. 하나의 공급자가 존재하여 재화 및 서비스의 가격을 결정하는 시장을 독점시장이라고 한다. 두 개 이상의 소수 공급자만이 서로 경쟁하는 시장을 과점시장이라고 하는데, 이러한 예로는 국내의 이동통신서비스, 자동차 시장 등을 들 수 있다. 마지막으로 독점적 경쟁시장에서는 다수의 공급자가 각기 특화된 재화 및 서비스를 생산함으로써 독자적으로 가격을 결정할 수 있는 시장지배력을 행사할 수 있다.","learning_example":"한 지역에 통신사가 두 곳뿐이면 각 회사가 요금 결정에 영향을 줄 수 있어요.","news_example":"소수 기업이 가격에 영향력을 행사하는 불완전경쟁시장에서는 완전경쟁보다 가격이 높게 형성되기 쉽다.","visuals":null}},{"id":265,"word":"비관측경제(NOE)","before_data":{"meaning":"지하경제처럼 통계 자료에 잡히지 않아 국내총생산 계산에서 빠지는 경제활동","learning_example":"현금으로만 거래하고 신고하지 않은 경제활동은 공식 통계에서 파악하기 어려워요."},"after_data":{"meaning":"국내총생산 추계에 쓰는 기초자료나 행정자료에서 직접 포착되지 않는 경제활동","learning_example":"학습용 가정: 수리업자가 현금으로 받은 수리비 30만 원을 신고하지 않아 기초자료에 빠졌어요. 이 활동은 비관측경제에 해당하지만, 자료에서 안 보인다는 이유만으로 GDP에서 반드시 제외되는 것은 아니에요."},"guard_data":{"meaning":"지하경제처럼 통계 자료에 잡히지 않아 국내총생산 계산에서 빠지는 경제활동","detailed_meaning":"비관측경제(NOE; Non-observed Economy)란 국내총생산(GDP)의 추계에 이용되는 기초자료와 행정자료에 누락된 경제활동을 의미한다. GDP는 원칙적으로 합법적이건 불법적이건 모든 경제적 거래에서 발생한 소득을 포함해야 하나 현실적으로 지하경제나 불법생산 등은 반영하기가 쉽지 않다. 비관측경제는 일반적으로 문제영역(problem areas)에 속하는 활동 때문에 발생한다. 대표적인 경우가 흔히 지하경제(underground economy) 나 은닉경제(hidden economy)로 표현되는 경제활동이다. 이는 조세나 사회적 의무의 회피, 근로안전이나 소비자보호 등 법적·행정적 규제에 따른 비용의 회피를 위하여 은밀하게 이루어진다. 이러한 거래는 세무·통계 당국에 축소 보고되기도 하고 현금거래로만 행해져 아예 누락되기도 한다. 또한 마약, 장물 거래, 성매매 등과 같이 생산물의 내용이 불법적인 경우도 거래내역을 포착하기 힘들다. 불법생산(illegal production)은 판매나 소유 자체가 법에 의해 금지되어 있으나 GDP에는 포함되어야 한다는 것이 국제적으로 합의된 원칙이다. 이 밖에도 “통계적 지하(statistical underground)”라고 불리는 소규모기업이나 자영업자 등에 대한 미흡한 기초통계 자료 등에 의해서도 비관측경제가 존재하게 된다.","learning_example":"현금으로만 거래하고 신고하지 않은 경제활동은 공식 통계에서 파악하기 어려워요.","news_example":"지하경제나 비공식 부문처럼 공식 통계에 잡히지 않는 비관측경제(NOE)를 측정하려는 노력이 이어지고 있다.","visuals":null}},{"id":271,"word":"빈일자리율","before_data":{"meaning":"전체 일자리 중 비어 있거나 한 달 안에 채용될 자리의 비율","learning_example":"학습용 가정: 전체 일자리 100개 중 현재 비었거나 곧 채용할 자리가 5개면 빈일자리율은 5%예요."},"after_data":{"meaning":"빈 일자리 수를 현재 근로자 수와 빈 일자리 수의 합으로 나눈 백분율","learning_example":"학습용 가정: 근로자가 95명이고 현재 비어 있거나 1개월 안에 새로 채용될 수 있는 일자리가 5개예요. 빈일자리율은 5 ÷ (95 + 5) × 100 = 5%예요."},"guard_data":{"meaning":"전체 일자리 중 비어 있거나 한 달 안에 채용될 자리의 비율","detailed_meaning":"현재 비어있거나 1개월 안에 새로 채용될 수 있는 일자리 수를 전체 근로자 수와 빈 일자리수의 합으로 나눈 백분율을 의미한다. 우리나라에서는 고용노동부가 매달 발표하고 있다.","learning_example":"학습용 가정: 전체 일자리 100개 중 현재 비었거나 곧 채용할 자리가 5개면 빈일자리율은 5%예요.","news_example":"전체 일자리 가운데 채워지지 않은 일자리 비중을 뜻하는 빈일자리율이 높아 구인난이 이어지고 있다.","visuals":null}},{"id":289,"word":"생산확산지수","before_data":{"meaning":"전월보다 생산이 늘어난 업종이 전체의 몇 %인지로 경기 확산을 보는 지수","detailed_meaning":"광공업생산지수나 서비스업생산지수 등 총량지표로는 파악하기 어려운 전반적인 생산확산의 정도를 측정하는 경제지표이다. 광공업 생산확산지수는 광공업생산 소분류 업종 (2025년 현재 72개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출하고, 서비스업생산확산지수는 서비스업생산 소분류 업종(2025년 현재 85개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출한다. 생산확산지수는 0에서 100까지의 범위 값을 갖는데, 지수가 50 이상이면 전월 대비 증가업종의 수가 감소업종의 수보다 많아 확산도 측면에서 본 생산경기가 확장국면에 있음을 의미한다. 통계청은 2007년 2월부터 제조업부문에 한정하여 생산확산지수를 공표하다가, 2009년 7월부터광공업 및 서비스업 생산확산지수를 공표하고 있다. 증가 업종수 + (보합*업종수×0.5) 생산확산지수 = ×100 전체 업종 수 * 보합: -0.05% < 증감률 < 0.05%","learning_example":"학습용 가정: 10개 업종 중 6개 업종의 생산이 전월보다 늘었다면 생산 증가가 여러 업종으로 퍼진 모습이에요."},"after_data":{"meaning":"전체 업종 중 생산 증가 업종은 1, 보합 업종은 0.5의 비중으로 세어 생산 증가가 얼마나 퍼졌는지 나타내는 지수","detailed_meaning":"광공업생산지수나 서비스업생산지수 등 총량지표로는 파악하기 어려운 전반적인 생산확산의 정도를 측정하는 경제지표이다. 광공업 생산확산지수는 광공업생산 소분류 업종 (2025년 현재 72개) 중 생산이 전월 대비 “증가 업종 수 + 보합 업종 수 × 0.5”를 전체 업종 수로 나눈 백분율로 산출하고, 서비스업생산확산지수는 서비스업생산 소분류 업종(2025년 현재 85개) 중 생산이 전월 대비 “증가 업종 수 + 보합 업종 수 × 0.5”를 전체 업종 수로 나눈 백분율로 산출한다. 생산확산지수는 0에서 100까지의 범위 값을 갖는데, 지수가 50을 초과하면 전월 대비 증가업종의 수가 감소업종의 수보다 많아 확산도 측면에서 본 생산경기가 확장국면에 있음을 의미한다. 통계청은 2007년 2월부터 제조업부문에 한정하여 생산확산지수를 공표하다가, 2009년 7월부터광공업 및 서비스업 생산확산지수를 공표하고 있다. 증가 업종수 + (보합*업종수×0.5) 생산확산지수 = ×100 전체 업종 수 * 보합: -0.05% < 증감률 < 0.05%","learning_example":"학습용 가정: 10개 업종 중 생산 증가가 4개, 보합이 2개, 감소가 4개예요. 생산확산지수는 (4 + 2 × 0.5) ÷ 10 × 100 = 50으로, 증가와 감소 업종 수가 같아요."},"guard_data":{"meaning":"전월보다 생산이 늘어난 업종이 전체의 몇 %인지로 경기 확산을 보는 지수","detailed_meaning":"광공업생산지수나 서비스업생산지수 등 총량지표로는 파악하기 어려운 전반적인 생산확산의 정도를 측정하는 경제지표이다. 광공업 생산확산지수는 광공업생산 소분류 업종 (2025년 현재 72개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출하고, 서비스업생산확산지수는 서비스업생산 소분류 업종(2025년 현재 85개) 중 생산이 전월 대비 “증가 또는 보합인 업종의 수”를 백분비로 산출한다. 생산확산지수는 0에서 100까지의 범위 값을 갖는데, 지수가 50 이상이면 전월 대비 증가업종의 수가 감소업종의 수보다 많아 확산도 측면에서 본 생산경기가 확장국면에 있음을 의미한다. 통계청은 2007년 2월부터 제조업부문에 한정하여 생산확산지수를 공표하다가, 2009년 7월부터광공업 및 서비스업 생산확산지수를 공표하고 있다. 증가 업종수 + (보합*업종수×0.5) 생산확산지수 = ×100 전체 업종 수 * 보합: -0.05% < 증감률 < 0.05%","learning_example":"학습용 가정: 10개 업종 중 6개 업종의 생산이 전월보다 늘었다면 생산 증가가 여러 업종으로 퍼진 모습이에요.","news_example":"생산이 늘어난 업종 수가 줄어든 업종보다 많은지를 보여주는 생산확산지수가 기준선을 웃돌았다.","visuals":null}},{"id":297,"word":"선물환포지션비율 규제","before_data":{"meaning":"은행의 선물환 보유액을 자기자본의 일정 비율 이내로 묶는 규제","learning_example":"은행이 자기자본에 비해 선물환 계약을 너무 많이 쌓지 못하도록 보유 한도를 적용해요."},"after_data":{"meaning":"은행의 선물 외화자산에서 선물 외화부채를 뺀 순포지션을 자기자본에 견줘 제한하는 규제","learning_example":"학습용 가정: 자기자본이 100억 원인 은행의 선물 외화자산이 80억 원, 선물 외화부채가 60억 원이에요. 선물환 순포지션은 20억 원이고 자기자본 대비 비율은 20%로, 계약 총액 140억 원과 달라요."},"guard_data":{"meaning":"은행의 선물환 보유액을 자기자본의 일정 비율 이내로 묶는 규제","detailed_meaning":"선물환포지션비율 규제는 국내은행과 외국은행 지점의 선물환포지션(선물 외화자산에서 선물 외화부채를 뺀 값)을 자기자본의 일정 비율 이내로 제한하는 규제로 2010년 10월부터 시행된 제도이다. 2006년 이후 국내은행 및 외은지점의 선물환 거래가 급증한 것이 단기외채 급증을 가져와 2008년 글로벌 금융위기 당시 외환시장 불안과 자본유출입 변동성 확대의 주된 원인으로 지적되었다. 이에 따라 거시건전성 강화와 외환시장 안정, 단기외채 증가 억제를 목표로 선물환포지션비율 규제 제도가 도입되었다. 도입 당시 국내은행 50%, 외국은행 지점 250%였던 선물환포지션비율 한도는 외환 및 금융시장 상황에 따라 수차례 조정되어 왔으며 2024년 12월 20일부터 각각 75%, 375%로 상향되었는데이는 국내은행들이 외화유동성을 보다 원활하게 확보할 수 있도록 하는 조치였다. 이처럼 선물환포지션비율 규제는 외환건전성 관리의 핵심 정책수단으로 사용됐으며 최근에는 글로벌 환율변동성 확대와 외환수급 불안에 대응하기 위해 한도가 점차 완화되는 추세에 있다.","learning_example":"은행이 자기자본에 비해 선물환 계약을 너무 많이 쌓지 못하도록 보유 한도를 적용해요.","news_example":"금융당국은 은행의 선물환 보유 한도를 자기자본 대비로 묶는 선물환포지션비율 규제를 조정했다.","visuals":null}},{"id":310,"word":"소비자물가지수(CPI)","before_data":{"visuals":[{"item":"0","stat":"901Y009","type":"ecos","unit":"p","cycle":"M","title":"소비자물가지수 최근 5년 (2020년 = 100)","months":60,"caption":"지수가 오를수록 같은 돈으로 살 수 있는 물건이 줄어요. 2020년 물가를 100으로 봤을 때의 값이에요."},{"body":"소비자물가지수는 가계가 주로 사는 상품과 서비스 수백 개의 가격 변화를 기준연도 = 100으로 나타낸 지수예요. 통계청이 작성해요.\n수입품도 포함하고, 집값은 빼고 전월세는 넣어요.\n한국은행 물가안정목표(2%)의 기준이 되는 지표예요.","type":"text","title":"장바구니 물가를 재는 지수"},{"rows":[["소비자물가지수(CPI)","통계청","가계가 사는 상품·서비스","포함"],["생산자물가지수(PPI)","한국은행","국내 생산자가 출하하는 상품·서비스","제외"],["GDP 디플레이터","한국은행","국내에서 생산한 모든 최종 생산물","제외"]],"type":"table","title":"물가지수 세 가지","caption":"CPI는 기준연도 수량을 고정해 계산해서(라스파이레스 방식) 물가 상승을 실제보다 크게 보여 주는 경향이 있어요.","columns":["지표","작성","대상","수입품"]},{"q":"외국에서 수입해 그대로 파는 가전제품 값이 올랐어요. 이 가격 변화가 반영되는 물가지표는?","type":"quiz","answer":0,"options":["소비자물가지수(CPI)","GDP 디플레이터","생산자물가지수(PPI)","실질 GDP"],"explanation":"CPI는 가계가 사는 물건이면 수입품도 포함해요. GDP 디플레이터와 PPI는 국내 생산이 기준이라 수입품을 빼요.","lessonCheck":true},{"q":"소비자물가지수 계산에 들어가지 않는 것은?","type":"quiz","answer":2,"options":["수입 식료품","전세·월세","주택 매매 가격(집값)","외식비"],"explanation":"집은 소비가 아니라 자산 구입으로 보아 집값은 CPI에서 빠져요. 대신 주거 서비스 비용인 전월세는 들어가요."}]},"after_data":{"visuals":[{"item":"0","stat":"901Y009","type":"ecos","unit":"p","cycle":"M","title":"소비자물가지수 최근 5년 (2020년 = 100)","months":60,"caption":"지수가 오를수록 같은 돈으로 살 수 있는 물건이 줄어요. 2020년 물가를 100으로 봤을 때의 값이에요."},{"body":"소비자물가지수는 가계가 주로 사는 상품과 서비스 수백 개의 가격 변화를 기준연도 = 100으로 나타낸 지수예요. 통계청이 작성해요.\n수입품도 포함하고, 집값은 빼고 전월세는 넣어요.\n한국은행 물가안정목표(2%)의 기준이 되는 지표예요.","type":"text","title":"장바구니 물가를 재는 지수"},{"rows":[["소비자물가지수(CPI)","통계청","가계가 사는 상품·서비스","포함"],["생산자물가지수(PPI)","한국은행","국내 생산자가 출하하는 상품·서비스","제외"],["GDP 디플레이터","한국은행","국내에서 생산한 모든 최종 생산물","제외"]],"type":"table","title":"물가지수 세 가지","caption":"CPI는 기준연도 수량을 고정해 계산해서(라스파이레스 방식) 물가 상승을 실제보다 크게 보여 주는 경향이 있어요.","columns":["지표","작성","대상","수입품"]},{"q":"국내 가계가 사는 CPI 조사대상 수입 가전의 소매가격만 올랐어요. 다른 가격은 그대로이고 이 가전은 국내에서 생산하지 않았어요. 직접 반영되는 지표는?","type":"quiz","answer":0,"options":["소비자물가지수(CPI)","GDP 디플레이터","생산자물가지수(PPI)","실질 GDP"],"explanation":"CPI는 국내 가계가 구입하는 조사대상 상품의 소비자가격을 보므로 수입품도 포함해요. GDP 디플레이터와 PPI는 국내 생산을 기준으로 하며, 실질 GDP는 가격 상승 자체를 생산 증가로 세지 않아요.","lessonCheck":true},{"q":"소비자물가지수 계산에 들어가지 않는 것은?","type":"quiz","answer":2,"options":["수입 식료품","전세·월세","주택 매매 가격(집값)","외식비"],"explanation":"집은 소비가 아니라 자산 구입으로 보아 집값은 CPI에서 빠져요. 대신 주거 서비스 비용인 전월세는 들어가요."}]},"guard_data":{"meaning":"가계가 사는 상품·서비스 가격이 얼마나 올랐는지 재는 대표 물가지수","detailed_meaning":"일반 가구가 소비생활을 유지하기 위하여 구입하는 각종 상품과 서비스의 가격변동을 종합적으로 파악하기 위하여 작성되는 물가지표이다. 우리나라의 소비자물가지수는 통계청에서 작성하고 있으며 기준년을 100으로 하여 작성된다. 조사대상 상품 및 서비스의 구성과 가중치도 경제상황에 맞게 주기적으로 조정된다. 2025년 현재는 가계의 총소비지출에 서 구입비중이 큰 458여개의 상품 및 서비스 품목을 대상으로 조사된 소비자 구입가격을 기준으로 하고 있다. 소비자물가지수는 소비자가 일정한 생활수준을 유지하는 데 필요한 소득내지 소비금액의 변동을 나타내기 때문에 소비자의 구매력과 생계비 등의 측정에 사용된다. 또한 소비자물가지수의 상승은 실질임금의 하락을 의미하므로 이를 보전하기 위한 임금인상의 기초자료로 널리 이용되고 있다.","learning_example":"가계가 사는 식료품과 교통 서비스 등 여러 품목의 가격 변화를 모아 소비자물가지수를 계산해요.","news_example":"가계가 사는 상품과 서비스의 가격 변동을 보여주는 소비자물가지수(CPI) 상승률이 둔화됐다.","visuals":[{"item":"0","stat":"901Y009","type":"ecos","unit":"p","cycle":"M","title":"소비자물가지수 최근 5년 (2020년 = 100)","months":60,"caption":"지수가 오를수록 같은 돈으로 살 수 있는 물건이 줄어요. 2020년 물가를 100으로 봤을 때의 값이에요."},{"body":"소비자물가지수는 가계가 주로 사는 상품과 서비스 수백 개의 가격 변화를 기준연도 = 100으로 나타낸 지수예요. 통계청이 작성해요.\n수입품도 포함하고, 집값은 빼고 전월세는 넣어요.\n한국은행 물가안정목표(2%)의 기준이 되는 지표예요.","type":"text","title":"장바구니 물가를 재는 지수"},{"rows":[["소비자물가지수(CPI)","통계청","가계가 사는 상품·서비스","포함"],["생산자물가지수(PPI)","한국은행","국내 생산자가 출하하는 상품·서비스","제외"],["GDP 디플레이터","한국은행","국내에서 생산한 모든 최종 생산물","제외"]],"type":"table","title":"물가지수 세 가지","caption":"CPI는 기준연도 수량을 고정해 계산해서(라스파이레스 방식) 물가 상승을 실제보다 크게 보여 주는 경향이 있어요.","columns":["지표","작성","대상","수입품"]},{"q":"외국에서 수입해 그대로 파는 가전제품 값이 올랐어요. 이 가격 변화가 반영되는 물가지표는?","type":"quiz","answer":0,"options":["소비자물가지수(CPI)","GDP 디플레이터","생산자물가지수(PPI)","실질 GDP"],"explanation":"CPI는 가계가 사는 물건이면 수입품도 포함해요. GDP 디플레이터와 PPI는 국내 생산이 기준이라 수입품을 빼요.","lessonCheck":true},{"q":"소비자물가지수 계산에 들어가지 않는 것은?","type":"quiz","answer":2,"options":["수입 식료품","전세·월세","주택 매매 가격(집값)","외식비"],"explanation":"집은 소비가 아니라 자산 구입으로 보아 집값은 CPI에서 빠져요. 대신 주거 서비스 비용인 전월세는 들어가요."}]}},{"id":317,"word":"수요탄력성","before_data":{"learning_example":"학습용 가정: 가격이 10% 오를 때 구매량이 20% 줄면 수요가 가격 변화에 민감한 편이에요.","visuals":[{"body":"값이 1% 변할 때 사려는 양이 몇 % 변하는지 재는 숫자예요.\n변화량이 아니라 변화율로 재고, 가격과 수요량은 반대로 움직여서 절댓값으로 크기만 봐요.\n1보다 크면 탄력적, 1보다 작으면 비탄력적이에요.","type":"text","title":"수요탄력성 쉽게 설명"},{"rows":[["탄력적 (1 초과)","매출 감소","매출 증가"],["단위 탄력적 (1)","변화 없음","변화 없음"],["비탄력적 (1 미만)","매출 증가","매출 감소"]],"type":"table","title":"탄력성과 매출(총수입)","caption":"매출은 가격 × 판매량이라, 둘 중 어느 쪽이 더 크게 움직이느냐를 탄력성이 정해요.","columns":["구분","값을 올리면","값을 내리면"]},{"body":"대신할 물건이 많을수록, 지출에서 차지하는 몫이 클수록, 필수품보다 사치품일수록 탄력적이에요.\n시간이 길수록, 상품 범위를 좁게 잡을수록(술 전체보다 특정 브랜드 소주) 탄력적이에요.","type":"text","title":"탄력성을 키우는 것들"},{"q":"어떤 과자 값이 10% 오르자 판매량이 25% 줄었어요. 이 과자 수요에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["탄력적이고, 값을 올리면 매출이 줄어요","비탄력적이고, 값을 올리면 매출이 늘어요","단위 탄력적이라 매출이 그대로예요","완전 비탄력적이에요"],"explanation":"탄력성은 25% ÷ 10% = 2.5로 1보다 커요. 판매량이 가격보다 더 크게 줄어서 값을 올리면 매출이 줄어요.","lessonCheck":true},{"q":"쌀처럼 값이 바뀌어도 먹는 양이 크게 안 바뀌는 상품의 수요는?","type":"quiz","answer":0,"options":["비탄력적","탄력적","완전 탄력적","단위 탄력적"],"explanation":"가격이 변해도 수요량이 덜 변하면 비탄력적이에요. 필수품이고 대신할 것이 적을수록 비탄력적이 돼요."},{"rows":[["가격이 10% 오르면","수요가 10%보다 많이 줄어요","수요가 10%보다 적게 줄어요"],["어떤 물건","대신할 게 많은 물건, 사치품","쌀·전기 같은 생활 필수품"]],"type":"table","title":"탄력적 vs 비탄력적 수요","columns":["구분","탄력적 (1보다 큼)","비탄력적 (1보다 작음)"]},{"x":["500원","1,000원","1,500원","2,000원","2,500원"],"type":"line","unit":"개","title":"수요와 공급이 만나는 곳이 가격 (붕어빵 예시)","series":[{"name":"사려는 양(수요)","values":[100,80,60,40,20]},{"name":"팔려는 양(공급)","values":[20,40,60,80,100]}],"caption":"가격이 싸면 사려는 사람은 많고 팔려는 사람은 적어요.\n가격이 비싸면 반대예요.\n\n두 선이 만나는 1,500원에서 사려는 양과 팔려는 양이 같아져요.\n이 가격을 균형가격이라고 해요."},{"rows":[["수요 증가","오름","한파에 패딩 수요 급증"],["수요 감소","내림","유행이 지난 옷"],["공급 감소","오름","태풍으로 배추 수확 감소"],["공급 증가","내림","풍년으로 쌀 생산 증가"]],"type":"table","title":"가격이 오르고 내리는 네 가지 경우","columns":["무슨 일이 생기면","가격","예시"]}]},"after_data":{"learning_example":"학습용 가정: 소득과 대체상품 가격 등은 그대로인데 과자 가격이 1,000원에서 1,100원으로 오르자 수요량이 100개에서 80개로 줄었어요. 최초 값을 기준으로 한 수요의 가격탄력성 절댓값은 20% ÷ 10% = 2예요.","visuals":[{"body":"값이 1% 변할 때 사려는 양이 몇 % 변하는지 재는 숫자예요.\n변화량이 아니라 변화율로 재고, 가격과 수요량은 반대로 움직여서 절댓값으로 크기만 봐요.\n1보다 크면 탄력적, 1보다 작으면 비탄력적이에요.","type":"text","title":"수요탄력성 쉽게 설명"},{"rows":[["탄력적 (1 초과)","매출 감소","매출 증가"],["단위 탄력적 (1)","변화 없음","변화 없음"],["비탄력적 (1 미만)","매출 증가","매출 감소"]],"type":"table","title":"탄력성과 매출(총수입)","caption":"매출은 가격 × 판매량이라, 둘 중 어느 쪽이 더 크게 움직이느냐를 탄력성이 정해요.","columns":["구분","값을 올리면","값을 내리면"]},{"body":"대신할 물건이 많을수록, 지출에서 차지하는 몫이 클수록, 필수품보다 사치품일수록 탄력적이에요.\n시간이 길수록, 상품 범위를 좁게 잡을수록(술 전체보다 특정 브랜드 소주) 탄력적이에요.","type":"text","title":"탄력성을 키우는 것들"},{"q":"소득 등 다른 조건은 그대로인데 과자 가격이 1,000원에서 1,100원으로 오르자 수요량이 100개에서 75개가 됐어요. 최초 값을 기준으로 계산할 때 옳은 설명은?","type":"quiz","answer":0,"options":["탄력적이고, 값을 올리면 매출이 줄어요","비탄력적이고, 값을 올리면 매출이 늘어요","단위 탄력적이라 매출이 그대로예요","완전 비탄력적이에요"],"explanation":"가격은 10% 오르고 수요량은 25% 줄어 탄력성 절댓값은 2.5로 탄력적이에요. 매출은 1,000원 × 100개 = 10만 원에서 1,100원 × 75개 = 8만 2,500원으로 감소해요.","lessonCheck":true},{"q":"쌀처럼 값이 바뀌어도 먹는 양이 크게 안 바뀌는 상품의 수요는?","type":"quiz","answer":0,"options":["비탄력적","탄력적","완전 탄력적","단위 탄력적"],"explanation":"가격이 변해도 수요량이 덜 변하면 비탄력적이에요. 필수품이고 대신할 것이 적을수록 비탄력적이 돼요."},{"rows":[["가격이 10% 오르면","수요가 10%보다 많이 줄어요","수요가 10%보다 적게 줄어요"],["어떤 물건","대신할 게 많은 물건, 사치품","쌀·전기 같은 생활 필수품"]],"type":"table","title":"탄력적 vs 비탄력적 수요","columns":["구분","탄력적 (1보다 큼)","비탄력적 (1보다 작음)"]},{"x":["500원","1,000원","1,500원","2,000원","2,500원"],"type":"line","unit":"개","title":"수요와 공급이 만나는 곳이 가격 (붕어빵 예시)","series":[{"name":"사려는 양(수요)","values":[100,80,60,40,20]},{"name":"팔려는 양(공급)","values":[20,40,60,80,100]}],"caption":"가격이 싸면 사려는 사람은 많고 팔려는 사람은 적어요.\n가격이 비싸면 반대예요.\n\n두 선이 만나는 1,500원에서 사려는 양과 팔려는 양이 같아져요.\n이 가격을 균형가격이라고 해요."},{"rows":[["수요 증가","오름","한파에 패딩 수요 급증"],["수요 감소","내림","유행이 지난 옷"],["공급 감소","오름","태풍으로 배추 수확 감소"],["공급 증가","내림","풍년으로 쌀 생산 증가"]],"type":"table","title":"가격이 오르고 내리는 네 가지 경우","columns":["무슨 일이 생기면","가격","예시"]}]},"guard_data":{"meaning":"가격이 변할 때 수요량이 얼마나 민감하게 반응하는지 나타낸 값","detailed_meaning":"상품의 가격 변화비율에 대한 수요량의 변화비율을 수요의 가격탄력성(price elasticity of demand)이라 한다. 탄력성은 반응의 크기를 분석하는 데 의미가 있다. 충격을 주는 쪽과 반응하는 쪽의 변화율을 비교하여 같은 경우를 단위 탄력적이라고 하고, 반응하는 쪽의 변화율이 더 높으면 탄력적, 작으면 비탄력적이라고 한다. 수요의 가격탄력성의 경우, 한 상품의 가격의 변화비율과 수요량의 변화비율이 동일할 경우 수요의 가격탄력성은 1이 되며, 이 경우 수요가 단위 탄력적이라고 한다. 수요량의 변화비율이 가격의 변화비율보다 작아서 수요의 가격탄력성이 1보다 작으면 수요가 비탄력적이라고 한다. 반면수요량의 변화비율이 가격의 변화비율보다 높아서 수요의 가격탄력성이 1보다 크게 되면수요가 탄력적이라고 한다.","learning_example":"학습용 가정: 가격이 10% 오를 때 구매량이 20% 줄면 수요가 가격 변화에 민감한 편이에요.","news_example":"가격이 바뀔 때 수요량이 얼마나 민감하게 변하는지 보여주는 수요탄력성은 사치재에서 크게 나타난다.","visuals":[{"body":"값이 1% 변할 때 사려는 양이 몇 % 변하는지 재는 숫자예요.\n변화량이 아니라 변화율로 재고, 가격과 수요량은 반대로 움직여서 절댓값으로 크기만 봐요.\n1보다 크면 탄력적, 1보다 작으면 비탄력적이에요.","type":"text","title":"수요탄력성 쉽게 설명"},{"rows":[["탄력적 (1 초과)","매출 감소","매출 증가"],["단위 탄력적 (1)","변화 없음","변화 없음"],["비탄력적 (1 미만)","매출 증가","매출 감소"]],"type":"table","title":"탄력성과 매출(총수입)","caption":"매출은 가격 × 판매량이라, 둘 중 어느 쪽이 더 크게 움직이느냐를 탄력성이 정해요.","columns":["구분","값을 올리면","값을 내리면"]},{"body":"대신할 물건이 많을수록, 지출에서 차지하는 몫이 클수록, 필수품보다 사치품일수록 탄력적이에요.\n시간이 길수록, 상품 범위를 좁게 잡을수록(술 전체보다 특정 브랜드 소주) 탄력적이에요.","type":"text","title":"탄력성을 키우는 것들"},{"q":"어떤 과자 값이 10% 오르자 판매량이 25% 줄었어요. 이 과자 수요에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["탄력적이고, 값을 올리면 매출이 줄어요","비탄력적이고, 값을 올리면 매출이 늘어요","단위 탄력적이라 매출이 그대로예요","완전 비탄력적이에요"],"explanation":"탄력성은 25% ÷ 10% = 2.5로 1보다 커요. 판매량이 가격보다 더 크게 줄어서 값을 올리면 매출이 줄어요.","lessonCheck":true},{"q":"쌀처럼 값이 바뀌어도 먹는 양이 크게 안 바뀌는 상품의 수요는?","type":"quiz","answer":0,"options":["비탄력적","탄력적","완전 탄력적","단위 탄력적"],"explanation":"가격이 변해도 수요량이 덜 변하면 비탄력적이에요. 필수품이고 대신할 것이 적을수록 비탄력적이 돼요."},{"rows":[["가격이 10% 오르면","수요가 10%보다 많이 줄어요","수요가 10%보다 적게 줄어요"],["어떤 물건","대신할 게 많은 물건, 사치품","쌀·전기 같은 생활 필수품"]],"type":"table","title":"탄력적 vs 비탄력적 수요","columns":["구분","탄력적 (1보다 큼)","비탄력적 (1보다 작음)"]},{"x":["500원","1,000원","1,500원","2,000원","2,500원"],"type":"line","unit":"개","title":"수요와 공급이 만나는 곳이 가격 (붕어빵 예시)","series":[{"name":"사려는 양(수요)","values":[100,80,60,40,20]},{"name":"팔려는 양(공급)","values":[20,40,60,80,100]}],"caption":"가격이 싸면 사려는 사람은 많고 팔려는 사람은 적어요.\n가격이 비싸면 반대예요.\n\n두 선이 만나는 1,500원에서 사려는 양과 팔려는 양이 같아져요.\n이 가격을 균형가격이라고 해요."},{"rows":[["수요 증가","오름","한파에 패딩 수요 급증"],["수요 감소","내림","유행이 지난 옷"],["공급 감소","오름","태풍으로 배추 수확 감소"],["공급 증가","내림","풍년으로 쌀 생산 증가"]],"type":"table","title":"가격이 오르고 내리는 네 가지 경우","columns":["무슨 일이 생기면","가격","예시"]}]}},{"id":324,"word":"수확체감의 법칙","before_data":{"meaning":"다른 요소는 그대로 두고 노동만 늘리면 추가 생산량이 점점 줄어든다는 법칙","learning_example":"같은 크기의 공장에 노동자를 계속 더하면 처음에는 생산이 많이 늘어도 한 명을 더할 때 늘어나는 양은 점점 작아져요."},"after_data":{"meaning":"기술과 다른 생산요소를 고정한 채 한 생산요소만 계속 늘리면 어느 단계부터 추가 생산량이 줄어드는 현상","learning_example":"학습용 가정: 주방 설비와 기술이 같은 식당에서 요리사를 1명씩 늘리자 한 시간 요리 수가 10개, 18개, 24개가 됐어요. 추가 생산량은 8개에서 6개로 줄지만 총생산은 여전히 늘어요."},"guard_data":{"meaning":"다른 요소는 그대로 두고 노동만 늘리면 추가 생산량이 점점 줄어든다는 법칙","detailed_meaning":"어떤 생산물을 만드는 데 필요한 자본·노동·토지 등의 생산요소 가운데 자본과 토지는 일정하게 유지하고 노동의 투입량을 증가시킬 경우, 생산물 전체는 증가하지만 추가로 투입되는 노동량 1단위당 생산물의 증가는 차차 감소한다는 법칙이다. 수확체감의 법칙(Law of Diminishing Returns)은 원래 농지에서 작업하는 노동자 수의 증가에 대한 1인당 수확량의 증가와 관련된 것이었으나 이후 모든 산업부문에서 특정 생산요소의 투입량이 고 정된 단기에 발생하는 현상으로 확장되었고 “한계생산력 체감의 법칙”으로 일반화되었다.","learning_example":"같은 크기의 공장에 노동자를 계속 더하면 처음에는 생산이 많이 늘어도 한 명을 더할 때 늘어나는 양은 점점 작아져요.","news_example":"다른 요소는 그대로 두고 노동만 계속 늘리면 추가 생산량이 점점 줄어드는 것이 수확체감의 법칙이다.","visuals":[{"body":"땅이나 공장처럼 당장 늘릴 수 없는 생산요소가 있을 때, 일하는 사람만 계속 늘리면 어느 순간부터 한 명 더해 늘어나는 생산량(한계생산)이 줄어드는 현상이에요.\n논은 그대로인데 사람만 늘면 한 사람이 맡을 땅이 줄어서예요.","type":"text","title":"수확체감의 법칙 쉽게 설명"},{"rows":[["4명","5가마","14가마"],["5명","4가마","18가마"],["6명","3가마","21가마"],["7명","2가마","23가마"],["8명","1가마","24가마"],["9명","0가마","24가마"],["10명","-1가마","23가마"]],"type":"table","title":"논농사로 보는 수확체감","caption":"5번째 사람부터 한계생산이 줄지만, 0보다 크면 총생산은 계속 늘어요.","columns":["일하는 사람","한계생산","총생산"]},{"body":"수확체감은 고정된 요소가 있는 단기에, 노동 하나만 늘릴 때의 이야기예요.\n노동과 자본을 함께 2배로 늘리는 장기 이야기는 규모에 대한 수익이라고 따로 불러요.","type":"text","title":"규모에 대한 수익과 헷갈리지 않기"},{"q":"작은 식당의 주방 크기는 그대로인데 요리사를 계속 늘렸더니, 새 요리사가 더해 늘어나는 요리 수가 점점 줄었어요. 이 현상은?","type":"quiz","answer":0,"options":["수확체감의 법칙","규모의 경제","규모에 대한 수익 체증","범위의 경제"],"explanation":"주방이라는 고정요소가 있는 상태에서 노동만 늘리니 한계생산이 줄었어요. 단기에 나타나는 수확체감이에요.","lessonCheck":true},{"q":"수확체감의 법칙에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["고정된 생산요소가 있는 단기에 나타나요","모든 생산요소를 함께 늘리는 장기에 나타나요","한계생산이 줄면 총생산도 반드시 줄어요","평균생산이 줄어드는 현상을 말해요"],"explanation":"수확체감은 고정요소가 있는 단기에 가변요소만 늘릴 때 한계생산이 줄어드는 현상이에요. 한계생산이 0보다 크면 총생산은 여전히 늘어요."},{"x":["1명","2명","3명","4명","5명","6명"],"type":"line","unit":"kg","title":"같은 밭에 일꾼을 한 명씩 더 넣을 때 수확량 (예시)","series":[{"name":"한 명 더 넣을 때 느는 수확","values":[10,15,11,7,4,2]},{"name":"전체 수확","values":[10,25,36,43,47,49]}],"caption":"땅(고정된 생산요소)은 그대로인데 일꾼만 늘리면, 어느 순간부터 한 명이 더해 주는 수확이 점점 줄어요."}]}},{"id":326,"word":"순안정자금조달비율","before_data":{"meaning":"은행이 1년 이상 안정적인 자금으로 장기 자산을 얼마나 뒷받침하는지 보는 비율","learning_example":"은행이 장기 대출을 늘릴 때 단기 차입만으로 버티지 않고 예금 등 안정적인 자금을 확보해요."},"after_data":{"meaning":"향후 1년을 기준으로 자산 운용에 필요한 안정자금 대비 실제로 확보한 안정자금의 비율","learning_example":"학습용 가정: 은행의 자본·부채에 안정성 가중치를 적용한 가용 안정자금이 110억 원이고 자산에 필요한 안정자금이 100억 원이에요. 순안정자금조달비율은 110 ÷ 100 × 100 = 110%예요."},"guard_data":{"meaning":"은행이 1년 이상 안정적인 자금으로 장기 자산을 얼마나 뒷받침하는지 보는 비율","detailed_meaning":"2008년 글로벌 금융위기 시 신용경색으로 금융시장 기능이 마비되면서 자금조달이나 만 기연장이 어려워짐에 따라 많은 은행들이 만기불일치 등에 따른 유동성 위기를 경험하였고 이는 금융시스템 전체의 유동성 경색을 유발하였다. 이에 따라 바젤위원회(BCBS)는 유동성 위기에 대한 대응 및 금융복원력 강화를 위해 단기 유동성 규제인 유동성커버리지비율과 함께 중장기 유동성 규제인 순안정자금조달비율(NSFR; Net Stable Funding Ratio)을 도입하였다. 순안정자금조달비율은 유동성을 감안한 은행 보유자산대비 안정적 조달자금(자본 및 부채)의 비율이며 은행들은 2018년부터 NSFR 비율을 100% 이상으로 유지하여야 한다. 즉, NSFR은 은행 자금조달 구조의 안정성을 강화하기 위해 장기 운용자산의 일정 부분을 안정적인 부채·자본으로 조달하도록 함으로써 은행들이 단기 도매자금조달에 과도하게 의존하는 행태를 제한하기 위해 도입되었다. NSFR의 산식은 ‘가 용 안정자금 조달금액(∑부채 및 자본항목잔액 × ASF 가중치) / 필요 안정자금 조달금액(∑자산항목잔액 × RSF 가중치) × 100’이다. 분자인 가용 안정자금 조달금액(ASF; Available Stable Funding)은 부채 및 자본 항목 중 향후 1년 이내 이탈 가능성이 낮은 안정적인 자금조달 금액을 의미한다. 분모인 필요 안정자금 조달금액(RSF; Required Stable Funding)은 자산항목 중 향후 1년 이내 현금화되기 어려워 안정적인 자금조달이 요구되는 금액을 말한다.","learning_example":"은행이 장기 대출을 늘릴 때 단기 차입만으로 버티지 않고 예금 등 안정적인 자금을 확보해요.","news_example":"장기 자산을 안정적인 자금으로 조달하는지 보여주는 순안정자금조달비율 규제가 은행에 적용되고 있다.","visuals":[{"q":"은행이 장기 대출을 매우 짧은 차입금에만 의존해 운용해요. 특히 살펴볼 지표는?","type":"quiz","answer":1,"options":["실업률","순안정자금조달비율","소비자물가상승률"],"explanation":"NSFR은 자산 구조에 비해 안정적인 자금조달이 충분한지 살펴요.","lessonCheck":true}]}},{"id":332,"word":"스왑레이트","before_data":{"meaning":"선물환율과 현물환율의 차이를 연율로 나타낸 값(두 나라 금리차와 일치)","learning_example":"오늘 달러를 사고 나중에 되팔기로 할 때 현물환율과 선물환율의 차이를 연율로 계산해요."},"after_data":{"meaning":"선물환율과 현물환율의 차이를 현물환율로 나눈 뒤 연율로 환산한 비율","learning_example":"학습용 가정: 현물환율이 달러당 1,000원이고 1년 뒤 선물환율이 1,020원이면 스왑레이트는 (1,020 - 1,000) ÷ 1,000 × 100 = 2%예요. 실제 시장에서는 자금 수급 등으로 두 통화 금리차와 달라질 수 있어요."},"guard_data":{"meaning":"선물환율과 현물환율의 차이를 연율로 나타낸 값(두 나라 금리차와 일치)","detailed_meaning":"스왑레이트(Swap Rate)는 현물환율 대비 선물환율과 현물환율의 차이(=(선물환율-현물환율)/현물환율)를 연율(%)로 표시한 것으로 이론적으로는 양 통화 간 금리차와 일치 (covered interest rate parity)하게 된다. 스왑레이트는 금융기관의 자금사정을 나타내는 대용지표(proxy)로도 활용된다. 예를 들어 국내 금융기관의 외화자금사정이 악화되면 금융기관은 외화조달의 방안으로 현물환매입/선물환매도(buy/sell) 스왑을 이용한다. 이 경우 현물환매입 증가로 현물환율은 상승하고 선물환매도 증가로 선물환율은 하락하게 되어 스왑레이트가 낮아진다. 반대로 금융기관의 원화자금사정이 악화되면 원화차입을 위한 현물환매도/선물환매입(sell/buy) 스왑 증가로 스왑레이트가 올라간다. 한편 스왑레이 트가 내외금리차를 하회하면 외화차입 후 외환스왑(현물환매도/선물환매입)을 통해 원화를 조달한 다음 원화자산에 투자함으로써 환리스크 없이 이익을 획득할 수 있다. 이에 따라 ‘내외금리차-스왑레이트’를 차익거래 유인으로 해석할 수 있다.","learning_example":"오늘 달러를 사고 나중에 되팔기로 할 때 현물환율과 선물환율의 차이를 연율로 계산해요.","news_example":"선물환율과 현물환율의 차이를 현물환율로 나눈 스왑레이트가 하락해 달러 자금 사정이 빠듯해졌다.","visuals":null}},{"id":336,"word":"스테이블코인","before_data":{"meaning":"달러 등 다른 자산에 가치를 연동해 가격 변동을 최소화한 가상자산","learning_example":"발행사가 토큰 가치를 달러에 연동해 가격 변동을 줄이도록 설계해요."},"after_data":{"meaning":"달러 등 기준 자산에 가치를 연동해 가격 변동을 줄이도록 설계한 가상자산","learning_example":"학습용 가정: 1개당 1달러를 목표로 하는 스테이블코인 100개를 보유했지만 시장가격이 0.95달러가 됐어요. 이때 시장가치는 95달러로, 목표 가격이 실제 가격을 보장하지는 않아요."},"guard_data":{"meaning":"달러 등 다른 자산에 가치를 연동해 가격 변동을 최소화한 가상자산","detailed_meaning":"스테이블코인은 가격변동성이 최소화되도록 설계된 가상자산을 의미한다. 비트코인 등 대부분의 가상자산은 가격 변동성이 커서 실제로는 화폐로서의 수용성이 제한되므로 가 격 변동성을 최소화할 필요성이 대두되었다. 스테이블코인은 가격변동 최소화를 위한 연동대상 자산과 방법에 따라 법정화폐 담보형 및 암호자산 담보형, 알고리즘형 등으로 분류된다. 법정화폐 담보형은 미국 달러화, 유로화 등 기존 화폐를 담보로 제공하고 담보가 치만큼 스테이블코인을 발행하는 방식이다. 암호자산 담보형은 비트코인 등과 같은 주요 암호자산을 담보로 발행하는 방식이다. 알고리즘형은 스테이블코인의 공급량을 자동적으로 조정하는 알고리즘을 내재하여 가치를 안정시키는 방식이다. 스테이블코인은 가상자산을 이용한 지급 및 송금의 효율성 제고, 금융포용성 증가 등의 긍정적 효과가 기대되나 담보자산 가치하락, 알고리즘에 대한 신뢰 부재 등으로 가격변동성이 확대될 가능성이 완전히 사라지지 않을 수 있음에 유의하여야 한다.","learning_example":"발행사가 토큰 가치를 달러에 연동해 가격 변동을 줄이도록 설계해요.","news_example":"달러 같은 법정화폐에 가치를 고정해 가격 변동을 줄인 스테이블코인에 대한 규제 논의가 본격화됐다.","visuals":[{"q":"어떤 코인이 1달러 가치 유지를 목표로 해요. 이용 전 적절한 판단은?","type":"quiz","answer":2,"options":["언제나 법적으로 1달러가 보장된다","가격이 하락할 수 없다","목표와 실제 가격 안정성은 다를 수 있다"],"explanation":"가치 고정 목표가 있어도 준비자산이나 구조에 따라 가격 이탈 위험이 있어요.","lessonCheck":true}]}},{"id":340,"word":"시뇨리지","before_data":{"meaning":"화폐를 찍어 내는 중앙은행이나 국가가 액면가와 제조비용 차이로 얻는 이득","learning_example":"학습용 가정: 액면가 1만 원인 돈 한 장을 만드는 비용이 1천 원이면 두 금액의 차이를 발행 이익의 기초로 봐요."},"after_data":{"meaning":"중앙은행이나 국가가 화폐 발행을 통해 얻는 이익으로, 현대에는 발행으로 취득한 자산의 운용수익에서 화폐 제조비 등을 뺀 것","learning_example":"학습용 가정: 중앙은행이 화폐 발행으로 취득한 채권에서 한 해 이자 300만 원을 얻고 관련 화폐 제조비 20만 원이 들었어요. 다른 비용을 생략하면 이 방식의 시뇨리지는 280만 원이며 지폐 액면가 전체가 수익은 아니에요."},"guard_data":{"meaning":"화폐를 찍어 내는 중앙은행이나 국가가 액면가와 제조비용 차이로 얻는 이득","detailed_meaning":"시뇨리지(Seigniorage)란 화폐에 대한 독점적 발권력을 갖는 중앙은행이나 국가가 화폐발행을 통해 획득하는 이득을 의미한다. 금속화폐 시대에는 절대군주가 금, 은 등을 소재로 화폐를 제조하여 유통하는 과정에서 화폐를 생산비용 보다 높은 액면가치에 유통시킴으로써 시뇨리지(화폐시뇨리지=화폐 액면가-화폐제조비용)가 발생하였다. 한편 명목화폐등장 이후에는 중앙은행이 화폐의 신뢰와 가치를 보장하기 위해 화폐발행액을 부채로 인식하게 되면서 화폐시뇨리지를 수익으로 간주하지 않는 대신 화폐발행을 통해 취득한 유가증권 등의 운용수익에서 화폐제조비를 차감하는 방식으로 시뇨리지를 계상하게 되었다. 전통적으로 시뇨리지는 정부의 재정적자 보전수단으로 인식되어 왔으나 최근에는 중앙은행의 재무적 독립의 중요성이 강조되면서 통화정책 운영에 필요한 재원이라는 인식이 확산되고 있다.","learning_example":"학습용 가정: 액면가 1만 원인 돈 한 장을 만드는 비용이 1천 원이면 두 금액의 차이를 발행 이익의 기초로 봐요.","news_example":"중앙은행이 화폐를 발행해 얻는 이익인 시뇨리지는 화폐 액면가와 제조비용의 차이에서 생긴다.","visuals":null}},{"id":353,"word":"신용창조","before_data":{"learning_example":"은행이 받은 예금 일부를 대출하고 그 돈이 다시 다른 은행에 예금돼 새 대출의 재원이 돼요.","visuals":[{"body":"은행은 예금 중 지급준비금만 남기고 나머지를 대출해요.\n빌린 돈이 다시 다른 은행에 예금되고 또 대출되기를 반복하면서 예금통화가 불어나요.\n현금을 예금하기만 해서는 통화량이 늘지 않고, 다시 대출이 일어나야 늘어나요.","type":"text","title":"같은 돈이 은행을 여러 번 돌아요"},{"rows":[["A","200억","20억","180억 → B"],["B","180억","18억","162억 → C"],["C","162억","16.2억","145.8억 → D"],["끝까지 합계","2,000억","200억","1,800억"]],"type":"table","title":"지급준비율 10%일 때","caption":"예금 총액 = 200억 ÷ 0.1 = 2,000억이에요. 대출된 돈이 모두 다시 예금된다고 가정한 최대치예요.","columns":["단계","예금","지급준비금","대출"]},{"q":"지급준비율이 20%이고 대출된 돈이 모두 다시 예금된다고 해요. 처음 100억 원이 예금되면, 처음 예금을 포함한 예금 총액은 최대 얼마가 될 수 있을까요?","type":"quiz","answer":3,"options":["200억 원","120억 원","2,000억 원","500억 원"],"explanation":"최대 예금 총액은 처음 예금 ÷ 지급준비율이에요. 100억 ÷ 0.2 = 500억 원이에요.","lessonCheck":true},{"q":"신용창조의 크기가 작아지는 경우는?","type":"quiz","answer":3,"options":["은행이 남는 돈을 모두 대출할 때","대출된 돈이 모두 다시 예금될 때","지급준비율이 낮아질 때","사람들이 대출받은 돈을 현금으로 더 많이 들고 있을 때"],"explanation":"대출받은 돈을 현금으로 쥐고 있으면 은행으로 돌아오지 않아 다음 대출이 줄어요. 그만큼 예금통화가 덜 불어나요."}]},"after_data":{"learning_example":"학습용 가정: 은행에 새 지급준비금 100만 원이 공급되고 지급준비율은 20%예요. 현금 유출과 초과지급준비금이 없고 대출금이 모두 재예금되며 충분한 대출 수요가 있다면, 단순 모형에서 이번 공급으로 늘어날 수 있는 예금의 최대 증가액은 100만 원 ÷ 0.2 = 500만 원이에요.","visuals":[{"body":"은행은 예금 중 지급준비금만 남기고 나머지를 대출해요.\n빌린 돈이 다시 다른 은행에 예금되고 또 대출되기를 반복하면서 예금통화가 불어나요.\n현금을 예금하기만 해서는 통화량이 늘지 않고, 다시 대출이 일어나야 늘어나요.","type":"text","title":"같은 돈이 은행을 여러 번 돌아요"},{"rows":[["A","200억","20억","180억 → B"],["B","180억","18억","162억 → C"],["C","162억","16.2억","145.8억 → D"],["끝까지 합계","2,000억","200억","1,800억"]],"type":"table","title":"지급준비율 10%일 때","caption":"예금 총액 = 200억 ÷ 0.1 = 2,000억이에요. 대출된 돈이 모두 다시 예금된다고 가정한 최대치예요.","columns":["단계","예금","지급준비금","대출"]},{"q":"새 지급준비금 100억 원이 은행에 공급되고 지급준비율은 20%예요. 현금 유출·초과지급준비금이 없고 충분한 대출 수요로 대출금이 모두 재예금된다면, 단순 모형에서 이번 공급으로 늘어날 수 있는 예금의 최대 증가액은?","type":"quiz","answer":3,"options":["200억 원","120억 원","2,000억 원","500억 원"],"explanation":"단순 예금승수는 1 ÷ 0.2 = 5이므로 이번 지급준비금 공급으로 늘어날 수 있는 예금의 최대 증가액은 100억 원 × 5 = 500억 원이에요. 실제 증가는 현금 보유와 은행의 대출 여건 등에 따라 달라져요.","lessonCheck":true},{"q":"신용창조의 크기가 작아지는 경우는?","type":"quiz","answer":3,"options":["은행이 남는 돈을 모두 대출할 때","대출된 돈이 모두 다시 예금될 때","지급준비율이 낮아질 때","사람들이 대출받은 돈을 현금으로 더 많이 들고 있을 때"],"explanation":"대출받은 돈을 현금으로 쥐고 있으면 은행으로 돌아오지 않아 다음 대출이 줄어요. 그만큼 예금통화가 덜 불어나요."}]},"guard_data":{"meaning":"은행이 예금과 대출을 반복하며 처음 받은 돈의 몇 배로 통화를 불리는 현상","detailed_meaning":"신용창조(Credit Creation)는 일반적으로 은행이 예금과 대출업무를 반복적으로 취급하는 과정에서 예금통화를 만들어내는 현상을 말한다. 예를 들어 중앙은행이 A은행에 100만큼의 본원통화를 공급하면 A은행은 이중 10(지급준비율 10%, 민간의 화폐보유성향 0% 가정)을 지급준비금으로 남겨두고 나머지 90을 대출로 운용한다. 대출받은 사람이 이를 B은행에 예금을 하면 B은행은 다시 이 가운데 9를 지급준비금으로 남겨두고 나머지 81을 다시 대출하게 된다. 이러한 과정이 무한정 반복되면 결국 예금은 1,000(그러나 대출받는 사람이 전부 예금하기 보다는 이중 일부를 현금으로 보유하게 되는데 그러면 동 현금 부분은 신용창조 사이클에서 누락되므로 실제통화량은 1,000 보다 작아진다) 만큼 늘어난다. 즉, 100이라는 본원통화가 신용창조를 통해 1,000이라는 예금통화가 창출되었다. 본원통화와 통화량 사이의 관계를 통화승수라 하는데 여기서 통화승수는 10이 다(1000÷100). 지급준비율을 변경하면 승수효과를 통해 신용창출효과(통화량)에 영향을 주기 때문에 지급준비제도는 중앙은행의 핵심적인 유동성조절 수단이다. 지급준비율을 인하하면 통화승수가 커지기 때문에 통화량이 늘어나고 반대로 지급준비율을 인상하면 통화승수가 줄어들기 때문에 통화량이 감소한다. 그래서 중앙은행은 통화완화가 필요 한 경우에는 지급준비율 인하를 통해, 통화긴축이 필요한 경우에는 지급준비율 인상을 통해 통화량을 조절하게 된다.","learning_example":"은행이 받은 예금 일부를 대출하고 그 돈이 다시 다른 은행에 예금돼 새 대출의 재원이 돼요.","news_example":"은행이 예금의 일부만 지급준비금으로 남기고 대출을 반복하며 통화량을 늘리는 것을 신용창조라 한다.","visuals":[{"body":"은행은 예금 중 지급준비금만 남기고 나머지를 대출해요.\n빌린 돈이 다시 다른 은행에 예금되고 또 대출되기를 반복하면서 예금통화가 불어나요.\n현금을 예금하기만 해서는 통화량이 늘지 않고, 다시 대출이 일어나야 늘어나요.","type":"text","title":"같은 돈이 은행을 여러 번 돌아요"},{"rows":[["A","200억","20억","180억 → B"],["B","180억","18억","162억 → C"],["C","162억","16.2억","145.8억 → D"],["끝까지 합계","2,000억","200억","1,800억"]],"type":"table","title":"지급준비율 10%일 때","caption":"예금 총액 = 200억 ÷ 0.1 = 2,000억이에요. 대출된 돈이 모두 다시 예금된다고 가정한 최대치예요.","columns":["단계","예금","지급준비금","대출"]},{"q":"지급준비율이 20%이고 대출된 돈이 모두 다시 예금된다고 해요. 처음 100억 원이 예금되면, 처음 예금을 포함한 예금 총액은 최대 얼마가 될 수 있을까요?","type":"quiz","answer":3,"options":["200억 원","120억 원","2,000억 원","500억 원"],"explanation":"최대 예금 총액은 처음 예금 ÷ 지급준비율이에요. 100억 ÷ 0.2 = 500억 원이에요.","lessonCheck":true},{"q":"신용창조의 크기가 작아지는 경우는?","type":"quiz","answer":3,"options":["은행이 남는 돈을 모두 대출할 때","대출된 돈이 모두 다시 예금될 때","지급준비율이 낮아질 때","사람들이 대출받은 돈을 현금으로 더 많이 들고 있을 때"],"explanation":"대출받은 돈을 현금으로 쥐고 있으면 은행으로 돌아오지 않아 다음 대출이 줄어요. 그만큼 예금통화가 덜 불어나요."}]}},{"id":359,"word":"실망실업자","before_data":{"meaning":"일자리를 찾다 지쳐 지난 4주간 구직활동을 포기한 사람(구직단념자)","learning_example":"취업을 원하지만 오랫동안 일자리를 찾지 못한 사람이 최근에는 구직활동을 중단했어요."},"after_data":{"meaning":"취업을 원하고 일할 수 있지만 노동시장 사정으로 최근 4주간 구직하지 않았고 지난 1년 안에 구직 경험이 있는 비경제활동인구","learning_example":"학습용 가정: 6개월 전까지 구직했던 사람이 지금도 취업을 원하고 바로 일할 수 있지만 맞는 일자리가 없을 것 같아 최근 4주간 구직하지 않았어요. 이런 경우 구직단념자에 해당하며 통계상 실업자에는 포함되지 않아요."},"guard_data":{"meaning":"일자리를 찾다 지쳐 지난 4주간 구직활동을 포기한 사람(구직단념자)","detailed_meaning":"구직단념자라고도 하며, 비경제활동인구 중 잠재구직자의 일부분이며 취업 희망과 취업가능성 기준 외에도 노동시장적 사유로 지난 4주간 구직활동을 하지 않는 자 중 지난 1년내 구직 경험이 있는 사람을 의미한다. 여기서 노동시장적 사유라 함은 다음과 같은 사유로 구직활동을 하지 않게 된 경우를 의미한다. ① 전공, 경력, 임금수준, 근로조건 등의 면에서 적당한 일자리가 없을 것 같아서 ② 지난 4주간 이전에 구직하여 보았지만 일자리를 찾을 수 없어서 ③ 교육·기술·경험 부족 등의 면에서 자격이 부족하여 지난 4주간 구직활동을 하지 않은 경우를 의미한다.","learning_example":"취업을 원하지만 오랫동안 일자리를 찾지 못한 사람이 최근에는 구직활동을 중단했어요.","news_example":"일할 뜻은 있지만 일자리를 찾지 못해 구직을 포기한 실망실업자가 늘어 고용 지표가 실제보다 좋아 보였다.","visuals":null}},{"id":392,"word":"예대율","before_data":{"meaning":"예금 대비 대출이 얼마인지의 비율(100% 이하로 규제)","learning_example":"학습용 가정: 은행의 대출금이 90억 원이고 예금이 100억 원이면 예대율은 90%예요."},"after_data":{"meaning":"예금을 기준으로 대출금이 얼마나 되는지 나타내는 비율로, 단순 계산은 대출금 ÷ 예금 × 100","learning_example":"학습용 가정: 같은 범위로 집계한 대출금이 90억 원이고 예금이 100억 원이면 단순 예대율은 90%예요. 실제 규제비율은 적용 기관과 예금·대출의 산정 범위 및 가중치를 따로 확인해야 해요."},"guard_data":{"meaning":"예금 대비 대출이 얼마인지의 비율(100% 이하로 규제)","detailed_meaning":"예대율이란 예금을 대출의 재원으로 보고 원화예수금 가운데 원화대출금이 차지하는 비율을 말한다. 금융당국은 양도성예금증서(CD), 은행채 등 시장성 수신을 기반으로 한 은 행들의 과도한 대출 경쟁을 억제하기 위해 2012년 7월부터 예대율을 100% 이하로 관리하도록 규제하고 있다. 이에 따라 원화예수금 산정시 CD는 원칙적으로 제외된다. 다만, 2020년 이후에는 원화예수금의 최대 1%까지 시장성 CD 발행잔액을 포함하는 것으로 규제가 개편되었다. 한편, 원화대출금 규모 산정 시에는 정책자금대출은 제외되고 기업부문에 자금을 원활하게 공급할 수 있도록 차주별로 상이한 가중치가 적용되는데, 가계대출은 115%, 기업대출(개인사업자대출 제외)은 85%의 가중치가 각각 적용된다.","learning_example":"학습용 가정: 은행의 대출금이 90억 원이고 예금이 100억 원이면 예대율은 90%예요.","news_example":"원화 예수금 대비 원화 대출금의 비율인 예대율 규제로 은행의 과도한 대출 확대를 막는다.","visuals":[{"q":"대출금 90억 원, 예수금 100억 원인 단순 사례에서 예대율은?","type":"quiz","answer":1,"options":["10%","90%","약 111%"],"explanation":"대출금을 예수금으로 나눠 계산해요. 실제 규제에는 별도 산정 범위가 있어요.","lessonCheck":true}]}},{"id":394,"word":"예약자금이체제도","before_data":{"meaning":"미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도","learning_example":"은행 고객이 다음 주 월요일에 임대료가 나가도록 미리 이체 날짜와 금액을 예약해요.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도","type":"quiz","answer":0,"options":["예약자금이체제도","국고대리점","총액결제시스템","자금결제시스템"],"explanation":"예약자금이체제도은/는 미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"실시간 총액결제시스템에서 금융기관이 미리 신청한 자금이체를 정해진 미래 시점에 자동 결제하는 제도","learning_example":"학습용 가정: 은행 A가 은행 B에 오후 2시에 10억 원을 보내도록 한은금융망에 미리 자금이체를 신청했어요. 결제 시점에 시스템이 이를 처리하는 것으로, 개인의 월세 예약송금과는 구분해요.","visuals":[{"q":"은행 A가 한은금융망에서 은행 B로 오후 2시에 자금을 보내도록 미리 신청했어요. 이 신청을 정해진 시점에 처리하는 제도는?","type":"quiz","answer":0,"options":["예약자금이체제도","일중당좌대출제도","증권대금동시결제","외환동시결제제도"],"explanation":"금융기관의 자금이체를 미리 접수해 정해진 미래 시점에 자동 결제하는 예약자금이체제도예요. 일중당좌대출은 결제자금 대출이고, 나머지는 증권·외환의 양쪽 지급을 연계하는 방식이에요.","lessonCheck":true}]},"guard_data":{"meaning":"미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도","detailed_meaning":"실시간 총액결제시스템에서는 금융기관의 자금이체 지급지시가 접수되는 즉시 처리되는 것을 원칙으로 하나, 미래의 특정시점에서 자금결제가 이루어지도록 시스템이 금융기관으로부터 미리 자금이체신청을 받아 두었다가 결제시점이 도래하면 자동으로 결제하도 록 하는 제도를 예약자금이체제도라 한다. 한은금융망에서는 두 가지 종류의 예약자금이 체제도를 운영하고 있다. 하나는 지정시점에 금융기관 간 차액결제가 원활히 이루어질 수있도록 결제자금이 부족한 금융기관이 다른 금융기관으로부터 자금을 차액결제시점에서 수취할 수 있는 지정시점 예약자금이체제도이고, 다른 하나는 금융기관이 지정하는 특정시점에 자금을 이체하는 일반 예약자금이체제도이다.","learning_example":"은행 고객이 다음 주 월요일에 임대료가 나가도록 미리 이체 날짜와 금액을 예약해요.","news_example":"미래 특정 날짜에 자동으로 송금되도록 미리 지시해 두는 예약자금이체제도를 활용하는 기업이 늘었다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도","type":"quiz","answer":0,"options":["예약자금이체제도","국고대리점","총액결제시스템","자금결제시스템"],"explanation":"예약자금이체제도은/는 미래 특정 시점에 자동으로 결제되도록 미리 이체를 예약해 두는 제도 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":408,"word":"외환건전성부담금제도","before_data":{"meaning":"은행의 외화 빚에 부담금을 매겨 과도한 외화 차입을 억제하는 제도","learning_example":"은행이 단기로 빌린 외화가 너무 많이 늘지 않도록 외화 부채에 부담금을 매겨요."},"after_data":{"meaning":"과도한 외화차입과 자금 유출입 변동을 줄이려고 금융기관의 부과대상 비예금성 외화부채에 부담금을 매기는 제도","learning_example":"학습용 가정: 은행의 외화부채가 100억 원이어도 그중 고객 외화예금 60억 원과 외화차입금 40억 원은 구분해요. 전체 100억 원에 일괄 부과하는 것이 아니라 만기 등 요건에 맞는 비예금성 외화부채를 대상으로 부담금을 계산해요."},"guard_data":{"meaning":"은행의 외화 빚에 부담금을 매겨 과도한 외화 차입을 억제하는 제도","detailed_meaning":"동아시아 외환위기, 글로벌 금융위기 등 우리나라가 겪었던 금융위기는 호황기에는 자본이 과도하게 유입되고 불황기에는 급격히 유출되는 자본유출입의 변동성에 주로 기인하였다. 이에 따라 정부와 한국은행은 금융·외환위기의 재발을 방지하기 위하여 과도한 자본유출입의 변동성을 제어하는 한편 우리 경제의 거시건전성을 제고하기 위한 방안으로 외환부문 거시건전성정책 수단을 도입하게 되었는데, 이의 일환으로 2011년 8월에 외환건전성부담금제도를 도입·시행하였다. 외환건전성부담금제도는 과도한 외화차입을 억제하고 외채구조의 장기화를 유도하기 위하여 은행의 비예금성외화부채(=전체외화부채-외화예수금-경과성자금 등)를 대상으로 계약 만기별로 0.02∼0.2%의 부담금을 부과하였으며 적립된 부담금은 외국환평형기금에 귀속되어 위기 시 금융기관에 대한 외화유동성지원에 활용되도록 하고 있다. 2015년 7월 금융업권 간 형평성을 제고하고 부과체계를 단순화하기 위하여 외환건전성부담금의 부과대상 및 부과요율 체계를 중심으로 제도를 개편하였으며, 현재는 만기 1년 이내의 비예금성외화부채에 대해 0.1%의 부담금을 부과 하고 있다.","learning_example":"은행이 단기로 빌린 외화가 너무 많이 늘지 않도록 외화 부채에 부담금을 매겨요.","news_example":"금융회사의 비예금성 외화부채에 부담금을 매겨 단기 외채 급증을 막는 외환건전성부담금제도가 운영되고 있다.","visuals":null}},{"id":409,"word":"외환동시결제(PVP)","before_data":{"meaning":"외환거래에서 두 통화를 동시에 주고받아 결제 위험을 없애는 방식","learning_example":"원화를 지급해야 달러를 받도록 두 통화의 결제를 동시에 처리해 한쪽만 먼저 보내는 위험을 줄여요."},"after_data":{"meaning":"한 통화의 지급과 다른 통화의 수취를 연계해 한쪽만 지급하고 상대 통화를 받지 못할 원금결제위험을 줄이는 방식","learning_example":"학습용 가정: 은행 A가 13억 원을 주고 100만 달러를 받는 거래를 해요. 달러 수취가 보장될 때만 원화 지급이 이뤄지도록 연계하면 원화만 보내고 달러를 못 받는 위험을 줄이지만, 모든 유동성·운영 위험까지 사라지는 것은 아니에요."},"guard_data":{"meaning":"외환거래에서 두 통화를 동시에 주고받아 결제 위험을 없애는 방식","detailed_meaning":"외환동시결제(PVP; Payment versus Payment)는 외환결제과정에서 국가간 결제시간대의 차이로 인하여 발생하는 외환결제리스크를 최소화하기 위하여 외환거래에 따른 수취 통화와 지급통화를 동시에 주고 받는 결제방식으로서 대표적으로 CLS은행이 이러한 방식의 외환결제서비스를 제공하고 있다. 외환동시결제방식은 매수통화의 수취가 보장되는 경우에만 매도통화를 지급하기 때문에 거래당사자 일방이 파산 등의 이유로 매도통화를 지급하지 못했을 경우에는 매입통화의 지급도 일어나지 않아 외환결제리스크를 감축할수 있다.","learning_example":"원화를 지급해야 달러를 받도록 두 통화의 결제를 동시에 처리해 한쪽만 먼저 보내는 위험을 줄여요.","news_example":"두 통화를 동시에 주고받아 한쪽만 지급되는 위험을 없애는 외환동시결제(PVP) 방식의 이용이 늘었다.","visuals":null}},{"id":414,"word":"요소비용","before_data":{"meaning":"시장가격에서 세금을 빼고 보조금을 더한, 생산요소가 실제로 받는 대가","learning_example":"학습용 가정: 물건 가격이 1만 원이고 생산 관련 세금이 1천 원, 보조금이 500원이라면 요소비용은 9,500원이에요."},"after_data":{"meaning":"시장가격에서 생산·수입에 붙는 세금을 빼고 보조금을 더한, 생산요소에 돌아가는 대가","learning_example":"학습용 가정: 시장가격 기준 부가가치가 110억 원이고 생산·수입세가 15억 원, 보조금이 5억 원이면 요소비용 기준은 110−15+5=100억 원이에요."},"guard_data":{"meaning":"시장가격에서 세금을 빼고 보조금을 더한, 생산요소가 실제로 받는 대가","detailed_meaning":"국민소득을 평가하는 데는 두 가지 방법이 있다. 하나는 시장가격에 의한 평가이고 다른하나는 요소비용(Factor Cost)에 의한 평가이다. 시장가격이란 상품이 시장에서 실제로 거래되고 있는 가격을 말하는 것으로서 여기에는 순생산 및 수입세(생산 및 수입세-보조금)가 포함되어 있다. 생산 및 수입세란 부가가치세나 특별소비세 등과 같이 우리가 상품을 살 때 상품가격에 포함되어 있는 세금을 말하며 보조금이란 기업이 상품을 만들 때 정부가 그 상품의 생산을 장려하기 위하여 생산비용 중 일부를 무상으로 제공해 주는 것을 말한다. 요소비용이란 시장가격에서 이와 같은 순생산 및 수입세를 공제한 것으로서 결국 그 상품을 만드는 데 들어간 생산요소에 대한 대가인 피용자보수와 영업잉여의 합계를 말한다. 이와 같이 생산의 요소비용을 측정하는 목적은 주로 투입된 생산요소의 생산성을 정확히 측정하는 데 있다.","learning_example":"학습용 가정: 물건 가격이 1만 원이고 생산 관련 세금이 1천 원, 보조금이 500원이라면 요소비용은 9,500원이에요.","news_example":"시장가격에서 생산세를 빼고 보조금을 더해 생산요소에 돌아간 몫만 보는 기준을 요소비용이라 한다.","visuals":null}},{"id":428,"word":"유동성 함정","before_data":{"meaning":"금리를 아무리 내려도 돈이 돌지 않아 통화정책이 효과를 잃는 상태","learning_example":"금리가 아주 낮아도 사람들이 소비하거나 투자하지 않고 현금을 쥐고 있어 추가 금리 인하의 효과가 약해져요.","visuals":[{"body":"이자율이 아주 낮으면 사람들은 \"이제 오를 일만 남았고 채권값은 내릴 것\"이라고 봐요.\n그래서 채권 대신 돈을 그대로 들고 있어 화폐수요곡선이 수평이 돼요. 화폐수요의 이자율 탄력성이 무한대인 상태예요.\n중앙은행이 돈을 더 풀어도 이자율이 내려가지 않아 투자와 총수요가 늘지 않아요.","type":"text","title":"돈을 풀어도 쌓아 두기만 해요"},{"rows":[["통화정책","거의 없어요","돈을 풀어도 이자율이 더 내려가지 않아요"],["재정정책","커요","정부지출이 늘어도 이자율이 오르지 않아 구축효과가 없어요"]],"type":"table","title":"유동성 함정에서 정책 효과","caption":"금리를 0 가까이 내려도 경기가 잘 살아나지 않는 상황이 대표적인 예로 꼽혀요.","columns":["정책","효과","이유"]},{"q":"금리가 0%에 가까운데 중앙은행이 통화량을 더 늘려도 사람들이 돈을 쌓아 두기만 해서 투자가 늘지 않아요. 이 상황은?","type":"quiz","answer":3,"options":["신용창조","스태그플레이션","구축효과","유동성 함정"],"explanation":"이자율이 바닥이라 더 내려갈 여지가 없고, 풀린 돈은 그대로 보유돼요. 통화정책이 거의 효과를 내지 못하는 유동성 함정이에요.","lessonCheck":true},{"q":"유동성 함정에서 화폐수요곡선의 모양과 이자율 탄력성은?","type":"quiz","answer":1,"options":["우하향, 탄력성 0","수평, 탄력성 무한대","수직, 탄력성 0","우상향, 탄력성 1"],"explanation":"유동성 함정에서는 이자율이 조금도 내려가지 않은 채 돈을 얼마든지 들고 있으려 해요. 그래서 화폐수요곡선이 수평이고 탄력성은 무한대예요."}]},"after_data":{"meaning":"금리가 매우 낮아 사람들이 추가로 풀린 돈을 보유하려 해, 통화 공급 확대가 금리 인하와 소비·투자 증가로 잘 이어지지 않는 상태","learning_example":"학습용 가정: 금리가 이미 매우 낮은 상황에서 중앙은행이 통화를 100억 원 더 공급했지만 사람들이 이를 그대로 보유해 금리와 투자 지출이 거의 변하지 않아요.","visuals":[{"body":"이자율이 아주 낮으면 사람들은 \"이제 오를 일만 남았고 채권값은 내릴 것\"이라고 봐요.\n그래서 채권 대신 돈을 그대로 들고 있어 화폐수요곡선이 수평이 돼요. 화폐수요의 이자율 탄력성이 무한대인 상태예요.\n중앙은행이 돈을 더 풀어도 이자율이 내려가지 않아 투자와 총수요가 늘지 않아요.","type":"text","title":"돈을 풀어도 쌓아 두기만 해요"},{"rows":[["통화정책","거의 없어요","돈을 풀어도 이자율이 더 내려가지 않아요"],["재정정책","커요","정부지출이 늘어도 이자율이 오르지 않아 구축효과가 없어요"]],"type":"table","title":"유동성 함정에서 정책 효과","caption":"금리를 0 가까이 내려도 경기가 잘 살아나지 않는 상황이 대표적인 예로 꼽혀요.","columns":["정책","효과","이유"]},{"q":"금리가 0%에 가까운데 중앙은행이 통화량을 더 늘려도 사람들이 돈을 쌓아 두기만 해서 투자가 늘지 않아요. 이 상황은?","type":"quiz","answer":3,"options":["신용창조","스태그플레이션","구축효과","유동성 함정"],"explanation":"이자율이 바닥이라 더 내려갈 여지가 없고, 풀린 돈은 그대로 보유돼요. 통화정책이 거의 효과를 내지 못하는 유동성 함정이에요.","lessonCheck":true},{"q":"전통적인 유동성 함정 모형에서 가로축은 실질화폐잔액, 세로축은 명목이자율이에요. 아주 낮은 이자율에서 추가 화폐를 얼마든지 보유하려는 구간의 화폐수요곡선과 이자율 탄력성은?","type":"quiz","answer":1,"options":["우하향, 탄력성 0","수평, 탄력성 무한대","수직, 탄력성 0","우상향, 탄력성 1"],"explanation":"이론상의 유동성 함정 구간에서는 이자율이 같은 낮은 수준에 머문 채 화폐수요량이 늘어나므로 곡선이 수평이고 이자율 탄력성은 무한대로 보아요. 이는 축을 반대로 그리거나 실제 모든 금리 구간에 그대로 적용하는 설명이 아니에요."}]},"guard_data":{"meaning":"금리를 아무리 내려도 돈이 돌지 않아 통화정책이 효과를 잃는 상태","detailed_meaning":"유동성 함정(Liquidity Trap)이란 금리 인하를 통한 확장적 통화정책이 투자나 소비 등 실물경제에 영향을 주지 못하는 상태를 말한다. 경제가 침체될 것으로 예상되면 중앙은행은 정책금리를 낮추고 유동성을 공급한다. 그러나 금리를 계속 낮추는데도 경기가 회복되지않고 이 이후에 명목이자율을 더 이상 낮출 수 없어 확장적 통화정책을 통한 경기 진작은 어려워지는데 이를 유동성 함정에 빠졌다고 표현한다.","learning_example":"금리가 아주 낮아도 사람들이 소비하거나 투자하지 않고 현금을 쥐고 있어 추가 금리 인하의 효과가 약해져요.","news_example":"금리를 아무리 낮춰도 돈이 돌지 않고 쌓이기만 하는 유동성 함정에 빠지면 통화정책 효과가 약해진다.","visuals":[{"body":"이자율이 아주 낮으면 사람들은 \"이제 오를 일만 남았고 채권값은 내릴 것\"이라고 봐요.\n그래서 채권 대신 돈을 그대로 들고 있어 화폐수요곡선이 수평이 돼요. 화폐수요의 이자율 탄력성이 무한대인 상태예요.\n중앙은행이 돈을 더 풀어도 이자율이 내려가지 않아 투자와 총수요가 늘지 않아요.","type":"text","title":"돈을 풀어도 쌓아 두기만 해요"},{"rows":[["통화정책","거의 없어요","돈을 풀어도 이자율이 더 내려가지 않아요"],["재정정책","커요","정부지출이 늘어도 이자율이 오르지 않아 구축효과가 없어요"]],"type":"table","title":"유동성 함정에서 정책 효과","caption":"금리를 0 가까이 내려도 경기가 잘 살아나지 않는 상황이 대표적인 예로 꼽혀요.","columns":["정책","효과","이유"]},{"q":"금리가 0%에 가까운데 중앙은행이 통화량을 더 늘려도 사람들이 돈을 쌓아 두기만 해서 투자가 늘지 않아요. 이 상황은?","type":"quiz","answer":3,"options":["신용창조","스태그플레이션","구축효과","유동성 함정"],"explanation":"이자율이 바닥이라 더 내려갈 여지가 없고, 풀린 돈은 그대로 보유돼요. 통화정책이 거의 효과를 내지 못하는 유동성 함정이에요.","lessonCheck":true},{"q":"유동성 함정에서 화폐수요곡선의 모양과 이자율 탄력성은?","type":"quiz","answer":1,"options":["우하향, 탄력성 0","수평, 탄력성 무한대","수직, 탄력성 0","우상향, 탄력성 1"],"explanation":"유동성 함정에서는 이자율이 조금도 내려가지 않은 채 돈을 얼마든지 들고 있으려 해요. 그래서 화폐수요곡선이 수평이고 탄력성은 무한대예요."}]}},{"id":449,"word":"이표채","before_data":{"meaning":"이자 지급일마다 붙어 있는 쿠폰을 떼어 이자를 받는 채권","learning_example":"채권 보유자가 약속된 지급일마다 이자를 받고 만기에 원금을 돌려받아요.","visuals":[{"q":"채권 보유자가 만기 전에도 약정된 날짜마다 이자를 받아요. 가까운 채권 유형은?","type":"quiz","answer":0,"options":["이표채","이자가 전혀 없는 영구 주식","무조건 할인채"],"explanation":"이표채는 약정에 따라 이자를 정기적으로 지급하는 채권이에요.","lessonCheck":true}]},"after_data":{"meaning":"만기까지 약정한 주기마다 이자를 지급하고, 만기에 원금을 갚는 채권","learning_example":"학습용 가정: 액면금액 100만 원, 연 이자율 4%, 매년 이자 지급, 만기 3년인 이표채는 매년 4만 원씩 이자를 주고 3년 말에는 원금 100만 원도 갚아요.","visuals":[{"q":"채권의 액면금액은 100만 원, 만기는 3년이에요. 만기 전에도 매년 약정 이자를 지급하고 만기에는 원금을 갚는 채권은?","type":"quiz","answer":0,"options":["이표채","할인채","복리채"],"explanation":"이표채는 약정한 주기마다 이자를 지급해요. 할인채는 중간 이자 지급 없이 액면보다 낮은 가격에 발행하고, 복리채는 중간에 이자를 주지 않고 만기에 원금과 누적 이자를 함께 지급해요.","lessonCheck":true}]},"guard_data":{"meaning":"이자 지급일마다 붙어 있는 쿠폰을 떼어 이자를 받는 채권","detailed_meaning":"국채·금융채·회사채 등의 채권은 이자지급 방법에 따라 할인채(Discount Bond), 이표채 (Coupon Bond), 복리채(Compound Interest Bond) 등으로 구분되는데 이표채는 채권의 권면에 이표(쿠폰, coupon)가 붙어 있어 이자지급일에 이를 떼어 제시함으로써 이자를 지급받는 채권을 말한다. 통상적으로 만기까지 일정 기간마다 이자를 지급하고 만기에는 원금을 지급하는 가장 일반적인 형태의 채권을 지칭한다. 이표채처럼 일정한 간격을 두고 주기적으로 수취하는 채권이자는 투자자의 입장에서 볼 때는 원래의 채권 투자자금 원본의 회수기간이 일부 앞당겨지는 효과를 얻게 된다. 이처럼 이표의 이자수취 만큼 투자자금 회수기간이 단축되는 효과를 감안하여 채권의 만기를 정밀하게 산출한 것을 듀레이션, 즉 평균만기라고 한다. 금리가 1% 변동할 때 채권의 가격은 듀레이션의 배율만큼 증폭되어 변동하기 때문에 유가증권투자에 있어서 매우 중요한 분석도구이다. 한편 이표채와 대비되는 개념으로 할인채와 복리채가 있다. 할인채는 이자의 지급 없이 만기에 원금을 지급하는 채권으로 액면보다 할인된 가격으로 발행되는데, 쿠폰 없이 발행되기 때문에 무이 표채 또는 제로쿠폰채(zero-coupon bond)라고 한다. 복리채는 이자를 중간에 지급하지않고 만기에 원금과 함께 일시에 지급하는 채권을 말한다.","learning_example":"채권 보유자가 약속된 지급일마다 이자를 받고 만기에 원금을 돌려받아요.","news_example":"정해진 주기마다 이자를 받고 만기에 원금을 돌려받는 이표채가 국고채의 대표적 형태이다.","visuals":[{"q":"채권 보유자가 만기 전에도 약정된 날짜마다 이자를 받아요. 가까운 채권 유형은?","type":"quiz","answer":0,"options":["이표채","이자가 전혀 없는 영구 주식","무조건 할인채"],"explanation":"이표채는 약정에 따라 이자를 정기적으로 지급하는 채권이에요.","lessonCheck":true}]}},{"id":457,"word":"일물일가의 법칙","before_data":{"meaning":"완전경쟁 시장에서는 같은 상품의 가격이 어디서나 같아진다는 법칙","learning_example":"운송비와 거래 제약이 없다면 같은 물건을 싼 시장에서 사서 비싼 시장에 팔 수 있어 가격 차가 줄어요."},"after_data":{"meaning":"거래비용·무역장벽 등이 없고 차익거래가 자유롭다면, 같은 상품의 가격이 같은 통화 기준으로 같아진다는 법칙","learning_example":"학습용 가정: 같은 상품이 두 시장에서 1만 원과 1만 2천 원이고 운송비·세금이 없다면, 싼 곳에서 사서 비싼 곳에 파는 거래가 가격 차이를 줄여요."},"guard_data":{"meaning":"완전경쟁 시장에서는 같은 상품의 가격이 어디서나 같아진다는 법칙","detailed_meaning":"완전경쟁이 이루어질 때 동일한 시기, 동일한 시장에서는 품질이 동일한 상품의 가격이 2 개 이상 형성될 수 없다는 법칙이다. 즉 동일한 상품은 어느 시장에서든지 가격이 같아지게 된다는 것인데 제본스(Jebons, W. S.)와 엣지워스(Edgeworth, F. Y.)는 무차별의 법칙이라고 하였다. 만일 동일한 시기, 동일한 시장에서 동일한 품질의 상품에 대해 2개 이상의 가격이 형성된다면 모든 사람들이 가장 싼 가격으로 사려고 하기 때문에 그보다 비싼가격을 제시한 판매자는 가격을 인하하지 않을 수 없다. 따라서 가격 차이가 없어지게 되며 하나의 상품에는 하나의 가격만 정해지게 된다. 무역에서도 일물일가의 법칙이 적용될수 있는데 어떤 상품의 가격이 국가별로 다를 때 가격이 상대적으로 싼 나라에서 구입하여 가격이 상대적으로 비싼 나라에 파는 이익 추구의 과정이 계속된다면 결국은 모든 나라에서 그 상품의 가격은 일치하게 될 것이다. 그러나 현실 세계에서는 일물일가의 법칙이 성립하기 어려운데, 이는 운송비, 보험료 등의 거래비용뿐만 아니라 관세의 영향도 받기 때문이다.","learning_example":"운송비와 거래 제약이 없다면 같은 물건을 싼 시장에서 사서 비싼 시장에 팔 수 있어 가격 차가 줄어요.","news_example":"같은 상품은 어느 시장에서나 같은 가격에 팔린다는 일물일가의 법칙은 구매력평가설의 바탕이다.","visuals":null}},{"id":458,"word":"일반특혜관세","before_data":{"meaning":"선진국이 개발도상국 수입품에 조건 없이 관세를 깎아 주는 특혜","detailed_meaning":"개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는 관세 상의 특혜대우를 말한다. 여기서 “일반적”이란 의미는 영연방 특혜, 베네룩스 관세동맹 등 기존의 특혜관세제도와는 달리 지리적으로 여러 개 국가에 국한되지 않고 범세계적으로 적용된다는 것을 뜻한다. 현재 일반특혜관세를 공여하는 국가로는 미국, 일본, 캐나다, 호주, 뉴질랜드, EC 등이 있다. 이들 특혜공여국은 특혜 대상품목, 특혜 폭, 원산지 기준 등을 정하고 이러한 제반요건을 충족한 경우에 한하여 특혜관세를 적용하고 있다.","learning_example":"선진국이 개발도상국에서 들어오는 일부 상품의 수입관세를 일반 세율보다 낮춰 줘요."},"after_data":{"meaning":"선진국이 개발도상국의 수출을 돕기 위해, 정해진 대상·품목·원산지 요건을 충족한 수입품의 관세를 낮추거나 면제하는 제도","detailed_meaning":"개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 정해진 대상품목과 원산지 기준 등의 요건을 충족하면 “일반적”으로 무관세 또는 저율의 관세를 부과하는 관세 상의 특혜대우를 말한다. 여기서 “일반적”이란 의미는 영연방 특혜, 베네룩스 관세동맹 등 기존의 특혜관세제도와는 달리 지리적으로 여러 개 국가에 국한되지 않고 범세계적으로 적용된다는 것을 뜻한다. 현재 일반특혜관세를 공여하는 국가로는 미국, 일본, 캐나다, 호주, 뉴질랜드, EC 등이 있다. 이들 특혜공여국은 특혜 대상품목, 특혜 폭, 원산지 기준 등을 정하고 이러한 제반요건을 충족한 경우에 한하여 특혜관세를 적용하고 있다.","learning_example":"학습용 가정: 어떤 나라가 개발도상국산 의류를 특혜 대상으로 정했더라도, 해당 의류가 정해진 원산지 기준을 충족하지 못하면 일반특혜관세를 적용받지 못해요."},"guard_data":{"meaning":"선진국이 개발도상국 수입품에 조건 없이 관세를 깎아 주는 특혜","detailed_meaning":"개발도상국의 수출 확대 및 공업화 촉진을 위하여, 선진국이 개발도상국으로부터 수입되는 농수산물, 공산품 및 반제품에 대하여는 아무런 조건 없이 “일반적”으로 무관세 또는 저율의 관세를 부과하는 관세 상의 특혜대우를 말한다. 여기서 “일반적”이란 의미는 영연방 특혜, 베네룩스 관세동맹 등 기존의 특혜관세제도와는 달리 지리적으로 여러 개 국가에 국한되지 않고 범세계적으로 적용된다는 것을 뜻한다. 현재 일반특혜관세를 공여하는 국가로는 미국, 일본, 캐나다, 호주, 뉴질랜드, EC 등이 있다. 이들 특혜공여국은 특혜 대상품목, 특혜 폭, 원산지 기준 등을 정하고 이러한 제반요건을 충족한 경우에 한하여 특혜관세를 적용하고 있다.","learning_example":"선진국이 개발도상국에서 들어오는 일부 상품의 수입관세를 일반 세율보다 낮춰 줘요.","news_example":"선진국이 개발도상국 상품에 일반 관세보다 낮은 세율을 일방적으로 적용하는 일반특혜관세 혜택이 연장됐다.","visuals":null}},{"id":477,"word":"자연실업률","before_data":{"visuals":[{"rows":[["마찰적 실업","이직·첫 구직 등 일자리를 찾는 과정","일자리 정보망·직업 알선"],["구조적 실업","기술 발달·산업 구조 변화","직업 재교육·훈련"],["경기적 실업","경기 침체로 일자리가 줄어듦","재정·통화정책으로 총수요↑"]],"type":"table","title":"실업의 세 종류와 대책","columns":["종류","원인","대책"]},{"body":"경기적 실업이 없는 완전고용 상태에서도 마찰적·구조적 실업은 남아요. 이때의 실업률이 자연실업률이에요.\n자연실업률일 때의 생산량이 잠재GDP예요.\n총수요 정책으로는 경기적 실업만 줄일 수 있고, 자연실업률을 낮추려면 정보망·재교육 같은 대책이 필요해요.","type":"text","title":"완전고용이어도 실업률은 0%가 아니에요"},{"q":"경기가 완전고용 수준인데도 실업률이 3%예요. 이 3%를 이루는 실업으로 알맞은 것은?","type":"quiz","answer":3,"options":["실업이 아니라 통계 오류","경기적 실업","경기적 실업과 구조적 실업","마찰적 실업과 구조적 실업"],"explanation":"완전고용은 경기적 실업이 없는 상태예요. 그래도 남는 마찰적·구조적 실업의 비율이 자연실업률이에요.","lessonCheck":true},{"q":"자연실업률을 낮추는 데 가장 알맞은 정책은?","type":"quiz","answer":1,"options":["정부지출 확대","구인·구직 정보망 확충과 직업 재교육","통화량 증가","기준금리 인하"],"explanation":"자연실업률은 마찰적·구조적 실업이라 총수요를 늘려서는 줄지 않아요. 일자리 정보를 잘 연결하고 새 산업에 맞게 재교육해야 해요."}]},"after_data":{"visuals":[{"rows":[["마찰적 실업","이직·첫 구직 등 일자리를 찾는 과정","일자리 정보망·직업 알선"],["구조적 실업","기술 발달·산업 구조 변화","직업 재교육·훈련"],["경기적 실업","경기 침체로 일자리가 줄어듦","재정·통화정책으로 총수요↑"]],"type":"table","title":"실업의 세 종류와 대책","columns":["종류","원인","대책"]},{"body":"경기적 실업이 없는 완전고용 상태에서도 마찰적·구조적 실업은 남아요. 이때의 실업률이 자연실업률이에요.\n자연실업률일 때의 생산량이 잠재GDP예요.\n총수요 정책으로는 경기적 실업만 줄일 수 있고, 자연실업률을 낮추려면 정보망·재교육 같은 대책이 필요해요.","type":"text","title":"완전고용이어도 실업률은 0%가 아니에요"},{"q":"경기가 완전고용 수준인데도 실업률이 3%예요. 이 3%를 이루는 실업으로 알맞은 것은?","type":"quiz","answer":3,"options":["실업이 아니라 통계 오류","경기적 실업","경기적 실업과 구조적 실업","마찰적 실업과 구조적 실업"],"explanation":"완전고용은 경기적 실업이 없는 상태예요. 그래도 남는 마찰적·구조적 실업의 비율이 자연실업률이에요.","lessonCheck":true},{"q":"경기적 실업이 아니라 일자리 탐색의 어려움과 기술 불일치로 생기는 실업을 장기적으로 줄이려 해요. 가장 직접적인 정책은?","type":"quiz","answer":1,"options":["정부지출 확대","구인·구직 정보망 확충과 직업 재교육","통화량 증가","기준금리 인하"],"explanation":"구인·구직 정보망은 탐색 과정의 마찰을 줄이고 직업 재교육은 필요한 기술과 보유 기술의 불일치를 줄여요. 지출 확대나 금리 인하는 주로 총수요와 경기적 실업에 작용하므로 이 문제에 대한 직접적인 처방과는 구분해요."}]},"guard_data":{"meaning":"물가를 자극하지 않으면서 유지할 수 있는 가장 낮은 실업률","detailed_meaning":"1968년 프리드먼(M. Friedman)이 처음 제시한 개념으로, 경제의 균형상태에서 상품시장과 노동시장 등의 구조적 요인에 의해 결정되는 실업률을 말한다. 이는 노동시장의 구조적·마찰적 요인에 의해 결정되는 실업률로서 영(0)의 실업률을 의미하는 것이 아니라인플레이션이 안정적으로 유지될 수 있는 가장 낮은 수준의 실업률을 의미한다. 실업률과 인플레이션의 관계는 통화론자와 케인즈학파간 오랜 논쟁거리 중의 하나로, 통화론자인프리드먼은 예상치 못한 인플레이션이 발생하는 경우 일시적으로 실업률이 하락할 수는 있으나 장기적으로는 노동자들이 인플레이션을 인지하게 되어 임금상승을 요구하게 됨으로써 장기적으로 인플레이션만 유발할 뿐 실업률은 자연실업률 수준으로 수렴한다고 주장하였다. 반면 케인즈학파 학자들은 낮은 수준의 실업률을 유지하려는 정책적 노력이 높은 수준의 물가상승률을 초래하는데 그치지 않고 물가상승률을 가속시킬 수 있다는 점을 강조하였다. 이와 관련하여 이들이 제시한 NAIRU(Non-Accelerating Inflation Rate of Unemployment; 비가속적인플레이션실업률)는 인플레이션이 상승하거나 하락하지 않고 안정적으로 유지될 수 있는 실업률 수준을 지칭하는 점에서 사실상 프리드먼의 자연실업률과 같은 개념이다.","learning_example":"일자리를 옮기는 사람 때문에 실업이 일부 남아 있어도 물가가 계속 빨라지지 않는 수준을 살펴봐요.","news_example":"경기 과열이나 침체 없이 노동시장이 균형일 때 존재하는 실업률인 자연실업률이 추정됐다.","visuals":[{"rows":[["마찰적 실업","이직·첫 구직 등 일자리를 찾는 과정","일자리 정보망·직업 알선"],["구조적 실업","기술 발달·산업 구조 변화","직업 재교육·훈련"],["경기적 실업","경기 침체로 일자리가 줄어듦","재정·통화정책으로 총수요↑"]],"type":"table","title":"실업의 세 종류와 대책","columns":["종류","원인","대책"]},{"body":"경기적 실업이 없는 완전고용 상태에서도 마찰적·구조적 실업은 남아요. 이때의 실업률이 자연실업률이에요.\n자연실업률일 때의 생산량이 잠재GDP예요.\n총수요 정책으로는 경기적 실업만 줄일 수 있고, 자연실업률을 낮추려면 정보망·재교육 같은 대책이 필요해요.","type":"text","title":"완전고용이어도 실업률은 0%가 아니에요"},{"q":"경기가 완전고용 수준인데도 실업률이 3%예요. 이 3%를 이루는 실업으로 알맞은 것은?","type":"quiz","answer":3,"options":["실업이 아니라 통계 오류","경기적 실업","경기적 실업과 구조적 실업","마찰적 실업과 구조적 실업"],"explanation":"완전고용은 경기적 실업이 없는 상태예요. 그래도 남는 마찰적·구조적 실업의 비율이 자연실업률이에요.","lessonCheck":true},{"q":"자연실업률을 낮추는 데 가장 알맞은 정책은?","type":"quiz","answer":1,"options":["정부지출 확대","구인·구직 정보망 확충과 직업 재교육","통화량 증가","기준금리 인하"],"explanation":"자연실업률은 마찰적·구조적 실업이라 총수요를 늘려서는 줄지 않아요. 일자리 정보를 잘 연결하고 새 산업에 맞게 재교육해야 해요."}]}},{"id":482,"word":"잠재GDP성장률","before_data":{"meaning":"노동·자본을 최대로 활용했을 때 달성 가능한 경제의 최대 성장률","detailed_meaning":"잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다. 잠재GDP는 일정한 잣대로 추계할 수 없는 추상적인 개념이어서, 추정에 사용되는 원칙이나 통계분석기법 등에 따라 결과가 상이하다는 한계가 있다. 한편 잠재GDP는 성장률도 의미가 있지만 그 수준이 실제GDP보다 얼마나 높은가 또는 낮은가를 살피는 것도 매우 중요하다. 실제GDP 성장률이 잠재GDP성장률을 상회하더라도 그 수준은 잠재GDP를 하회할 수도 있다. 또한 우리나라와 같이 대외의존도가 매우 높은 경우에는 정의에 의한 생산요소의 완전고 용으로 규정하기에는 어려움이 있다. 그럼에도 잠재GDP성장률은 경제의 적정성장목표를 설정하는 데 유용하여 거시경제정책을 수립하고 시행하는 데 있어 널리 활용되고 있다.","learning_example":"노동자 수와 설비가 늘고 기술이 좋아져 물가 압력을 크게 높이지 않고 성장할 수 있는 속도가 빨라져요.","visuals":[{"rows":[["생산성 ↑","↑","투자할 곳이 늘어 돈을 빌리려는 수요가 커져요"],["고령화·인구 감소","↓","성장이 느려지고 노후 대비 저축이 늘어요"],["세계적으로 저축 ↑","↓","빌려주려는 돈이 넘쳐요"],["정부부채 ↑","↑","정부가 돈을 많이 빌려 자금 수요가 커져요"],["안전자산 선호 ↑","↓","위험을 피해 국채로 몰려 안전한 금리가 낮아져요"]],"type":"table","title":"중립금리를 움직이는 힘","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 눈에 보이지 않아 추정만 할 수 있고, 이 힘들이 바뀌면 같은 기준금리라도 긴축인지 완화인지가 달라져요.","columns":["무슨 일이 생기면","중립금리","이유"]},{"q":"현재 GDP가 늘었다는 이유만으로 잠재성장률도 반드시 올랐다고 할 수 있나요?","type":"quiz","answer":1,"options":["네, 물가만 오르면 잠재성장률도 올라요","아니요, 지속 가능한 생산능력을 따로 봐야 해요","네, 두 수치는 항상 같아요"],"explanation":"실제 생산의 단기 반등과 노동·자본·생산성에 따른 장기 능력은 구분해요.","lessonCheck":true}]},"after_data":{"meaning":"물가상승 압력을 지속적으로 높이지 않으면서 유지할 수 있는 실질 국내총생산 수준인 잠재GDP의 증가율","detailed_meaning":"잠재GDP성장률은 노동·자본 등을 정상적으로 활용해 물가상승 압력을 지속적으로 높이지 않으면서 유지할 수 있는 실질GDP 수준인 잠재GDP의 증가율이다. 생산요소를 무리하게 가동한 단기적인 물리적 최대 생산량의 증가율과는 다르다. 잠재GDP는 일정한 잣대로 추계할 수 없는 추상적인 개념이어서, 추정에 사용되는 원칙이나 통계분석기법 등에 따라 결과가 상이하다는 한계가 있다. 한편 잠재GDP는 성장률도 의미가 있지만 그 수준이 실제GDP보다 얼마나 높은가 또는 낮은가를 살피는 것도 매우 중요하다. 실제GDP 성장률이 잠재GDP성장률을 상회하더라도 그 수준은 잠재GDP를 하회할 수도 있다. 또한 우리나라와 같이 대외의존도가 매우 높은 경우에는 정의에 의한 생산요소의 완전고 용으로 규정하기에는 어려움이 있다. 그럼에도 잠재GDP성장률은 경제의 적정성장목표를 설정하는 데 유용하여 거시경제정책을 수립하고 시행하는 데 있어 널리 활용되고 있다.","learning_example":"학습용 가정: 물가상승 압력을 높이지 않고 지속할 수 있는 실질 생산 수준이 1,000조 원에서 1,020조 원으로 늘었다면 잠재GDP성장률은 (1,020−1,000)÷1,000×100=2%예요. 야근으로 한 해 생산을 더 늘린 것만으로 이 비율이 높아지는 것은 아니에요.","visuals":[{"rows":[["생산성 ↑","↑","투자할 곳이 늘어 돈을 빌리려는 수요가 커져요"],["고령화·인구 감소","↓","성장이 느려지고 노후 대비 저축이 늘어요"],["세계적으로 저축 ↑","↓","빌려주려는 돈이 넘쳐요"],["정부부채 ↑","↑","정부가 돈을 많이 빌려 자금 수요가 커져요"],["안전자산 선호 ↑","↓","위험을 피해 국채로 몰려 안전한 금리가 낮아져요"]],"type":"table","title":"중립금리를 움직이는 힘","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 눈에 보이지 않아 추정만 할 수 있고, 이 힘들이 바뀌면 같은 기준금리라도 긴축인지 완화인지가 달라져요.","columns":["무슨 일이 생기면","중립금리","이유"]},{"q":"잠재GDP가 지난해 1,000조 원에서 올해 1,020조 원으로 늘었다고 추정했어요. 잠재GDP성장률과 해석으로 맞는 것은?","type":"quiz","answer":1,"options":["2%이며, 실제 GDP 성장률도 반드시 2%예요","2%이며, 물가상승 압력을 지속적으로 높이지 않고 유지할 수 있는 생산 수준의 증가율이에요","20%이며, 설비를 쉬지 않고 돌린 물리적 최대 생산량의 증가율이에요"],"explanation":"(1,020−1,000)÷1,000×100=2%예요. 잠재GDP는 지속가능성과 물가 조건을 함께 고려해 추정하며, 실제 생산은 경기 상황에 따라 잠재 수준을 웃돌거나 밑돌 수 있어요.","lessonCheck":true}]},"guard_data":{"meaning":"노동·자본을 최대로 활용했을 때 달성 가능한 경제의 최대 성장률","detailed_meaning":"잠재GDP성장률은 노동이나 자본 등의 자원을 최대로 활용하였을 때 유지되는 실질GDP 의 증가율로서 한 나라 경제의 최대성장능력을 의미한다. 잠재GDP는 일정한 잣대로 추계할 수 없는 추상적인 개념이어서, 추정에 사용되는 원칙이나 통계분석기법 등에 따라 결과가 상이하다는 한계가 있다. 한편 잠재GDP는 성장률도 의미가 있지만 그 수준이 실제GDP보다 얼마나 높은가 또는 낮은가를 살피는 것도 매우 중요하다. 실제GDP 성장률이 잠재GDP성장률을 상회하더라도 그 수준은 잠재GDP를 하회할 수도 있다. 또한 우리나라와 같이 대외의존도가 매우 높은 경우에는 정의에 의한 생산요소의 완전고 용으로 규정하기에는 어려움이 있다. 그럼에도 잠재GDP성장률은 경제의 적정성장목표를 설정하는 데 유용하여 거시경제정책을 수립하고 시행하는 데 있어 널리 활용되고 있다.","learning_example":"노동자 수와 설비가 늘고 기술이 좋아져 물가 압력을 크게 높이지 않고 성장할 수 있는 속도가 빨라져요.","news_example":"물가 상승 없이 한 나라가 낼 수 있는 최대 성장 속도인 잠재GDP성장률이 저출생으로 낮아지고 있다.","visuals":[{"rows":[["생산성 ↑","↑","투자할 곳이 늘어 돈을 빌리려는 수요가 커져요"],["고령화·인구 감소","↓","성장이 느려지고 노후 대비 저축이 늘어요"],["세계적으로 저축 ↑","↓","빌려주려는 돈이 넘쳐요"],["정부부채 ↑","↑","정부가 돈을 많이 빌려 자금 수요가 커져요"],["안전자산 선호 ↑","↓","위험을 피해 국채로 몰려 안전한 금리가 낮아져요"]],"type":"table","title":"중립금리를 움직이는 힘","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 눈에 보이지 않아 추정만 할 수 있고, 이 힘들이 바뀌면 같은 기준금리라도 긴축인지 완화인지가 달라져요.","columns":["무슨 일이 생기면","중립금리","이유"]},{"q":"현재 GDP가 늘었다는 이유만으로 잠재성장률도 반드시 올랐다고 할 수 있나요?","type":"quiz","answer":1,"options":["네, 물가만 오르면 잠재성장률도 올라요","아니요, 지속 가능한 생산능력을 따로 봐야 해요","네, 두 수치는 항상 같아요"],"explanation":"실제 생산의 단기 반등과 노동·자본·생산성에 따른 장기 능력은 구분해요.","lessonCheck":true}]}},{"id":494,"word":"전산업생산지수","before_data":{"meaning":"광공업과 서비스업을 합쳐 나라 전체 생산 흐름을 월별로 나타낸 지수","detailed_meaning":"우리나라 경제전체의 모든 산업을 대상으로 재화와 용역에 대한 생산활동의 흐름과 변화를 월별지수로 나타낸 것이다. 모든 재화와 용역의 생산수준을 한 눈에 볼 수 있는 종합지표로 업종별로 생산증감의 방향이 다를 때 전체산업의 방향 파악가능하다. 전산업생산지수는 광공업생산지수와 서비스업생산지수로 구분할 수 있으며, 광공업생산지수는 광업, 제조업, 전기·가스업을 대상으로 일정 기간 중에 이루어진 산업생산활동의 수준을 나 타내는 지표이며 서비스업생산지수는 한국표준분류상의 서비스업에 해당되는 13개 산업의 생산활동을 종합적으로 파악하기 위한 것으로 개별업종의 상대적 중요도인 부가가치기준 가중치를 적용하여 지수화한 것이다. 생산지수는 전체 경기의 흐름과 거의 유사하게움직이는 대표적인 경기동행지표이다. 또한 동 지수들은 GDP 통계의 추계를 위한 기초자료로 사용되며, 생산활동의 수준을 파악할 때 GDP와 함께 핵심적인 지표로 사용되고 있다.","learning_example":"한 달 동안 공장 생산과 서비스업 활동이 어떻게 변했는지 합쳐 전체 생산 흐름을 살펴봐요."},"after_data":{"meaning":"광공업·서비스업·건설업·공공행정 등의 생산활동을 종합해 전체 산업의 생산 흐름을 보여 주는 지수","detailed_meaning":"우리나라 경제전체의 모든 산업을 대상으로 재화와 용역에 대한 생산활동의 흐름과 변화를 월별지수로 나타낸 것이다. 모든 재화와 용역의 생산수준을 한 눈에 볼 수 있는 종합지표로 업종별로 생산증감의 방향이 다를 때 전체산업의 방향 파악가능하다. 전산업생산지수는 광공업·서비스업뿐 아니라 건설업·공공행정 등을 포함해 작성하며, 농림어업은 연간 계열로 작성된다. 이 중  광공업생산지수는 광업, 제조업, 전기·가스업을 대상으로 일정 기간 중에 이루어진 산업생산활동의 수준을 나 타내는 지표이며 서비스업생산지수는 한국표준분류상의 서비스업에 해당되는 13개 산업의 생산활동을 종합적으로 파악하기 위한 것으로 개별업종의 상대적 중요도인 부가가치기준 가중치를 적용하여 지수화한 것이다. 생산지수는 전체 경기의 흐름과 거의 유사하게움직이는 대표적인 경기동행지표이다. 또한 동 지수들은 GDP 통계의 추계를 위한 기초자료로 사용되며, 생산활동의 수준을 파악할 때 GDP와 함께 핵심적인 지표로 사용되고 있다.","learning_example":"학습용 가정: 광공업 생산이 늘더라도 건설업과 서비스업 생산이 줄면 전체 산업의 생산 흐름은 다를 수 있어, 각 산업을 종합한 전산업생산지수를 함께 살펴봐요."},"guard_data":{"meaning":"광공업과 서비스업을 합쳐 나라 전체 생산 흐름을 월별로 나타낸 지수","detailed_meaning":"우리나라 경제전체의 모든 산업을 대상으로 재화와 용역에 대한 생산활동의 흐름과 변화를 월별지수로 나타낸 것이다. 모든 재화와 용역의 생산수준을 한 눈에 볼 수 있는 종합지표로 업종별로 생산증감의 방향이 다를 때 전체산업의 방향 파악가능하다. 전산업생산지수는 광공업생산지수와 서비스업생산지수로 구분할 수 있으며, 광공업생산지수는 광업, 제조업, 전기·가스업을 대상으로 일정 기간 중에 이루어진 산업생산활동의 수준을 나 타내는 지표이며 서비스업생산지수는 한국표준분류상의 서비스업에 해당되는 13개 산업의 생산활동을 종합적으로 파악하기 위한 것으로 개별업종의 상대적 중요도인 부가가치기준 가중치를 적용하여 지수화한 것이다. 생산지수는 전체 경기의 흐름과 거의 유사하게움직이는 대표적인 경기동행지표이다. 또한 동 지수들은 GDP 통계의 추계를 위한 기초자료로 사용되며, 생산활동의 수준을 파악할 때 GDP와 함께 핵심적인 지표로 사용되고 있다.","learning_example":"한 달 동안 공장 생산과 서비스업 활동이 어떻게 변했는지 합쳐 전체 생산 흐름을 살펴봐요.","news_example":"광공업, 서비스업, 건설업 등 모든 산업의 생산 활동을 종합한 전산업생산지수가 감소했다.","visuals":null}},{"id":508,"word":"정규직","before_data":{"meaning":"기간을 정하지 않고 직접 계약해 정년까지 보장되는 고용","detailed_meaning":"정규직은 법적인 개념은 아니지만 기간이 정해져 있지 않은 고용형태로 근로자와 사업주가 직접 근로계약을 체결하고 전일제로 근무하면서 정년까지 보장된다는 의미로 받아들이고 있다. 따라서 회사가 소멸되지 않는 한 원할 때까지 계속 근무가 가능하며 임금, 휴가, 상여금 등의 각종 복지혜택도 받을 수 있다. 반면 비정규직은 근로기간이 정해져 있는 계약직과 일용직, 파견 도급직, 상시 근로를 하지 않는 시간제 근로자 등을 포함하는 개념으로 계약기간이 종료되는 시점이 정해져 있다. 인턴은 일정기간 근무시켜 능력과 성품등을 평가하여 필요시 채용하는 방식이다. 계약직은 일반계약직과 무기계약직으로 구분할 수 있다. 우선 일반계약직은 회사와 근로자가 정해진 한정된 기간에 근로계약을 맺은 것으로 정년이 보장되지 않기 때문에 정규직보다 불안정하고 임금 및 근무환경이 열악하다. 무기계약직은 일반계약직과는 달리 계약기간을 정하지 않은 것이지만 임금 및 복지나 승진 등에 대해서는 일반계약직과 비슷하다. 파견직은 아웃소싱 업체에 고용되어 있으면서 다른 업체로 파견되어 일하는 근로자를 말한다. 파견기간이 2년이 넘게 되면 파견 나 간 다른 업체에서 직접 고용해야 할 의무가 생긴다.","learning_example":"직원이 근로계약의 종료일을 미리 정하지 않고 회사와 직접 고용계약을 맺어요."},"after_data":{"meaning":"보통 근로계약 기간을 정하지 않고 사업주가 직접 고용하는 상시 근로 형태로, 정년까지 고용이 무조건 보장되는 것은 아님","detailed_meaning":"정규직은 법적인 개념은 아니지만 기간이 정해져 있지 않은 고용형태로 근로자와 사업주가 직접 근로계약을 체결하고 전일제로 근무하는 고용형태를 통상 뜻한다. 다만 정년까지 고용이 무조건 보장되는 것은 아니며 정당한 사유와 적법한 절차에 따른 해고 등으로 근로관계가 끝날 수 있다. 일반적으로 임금, 휴가, 상여금 등의 각종 복지혜택도 받을 수 있다. 반면 비정규직은 근로기간이 정해져 있는 계약직과 일용직, 파견 도급직, 상시 근로를 하지 않는 시간제 근로자 등을 포함하는 개념으로 계약기간이 종료되는 시점이 정해져 있다. 인턴은 일정기간 근무시켜 능력과 성품등을 평가하여 필요시 채용하는 방식이다. 계약직은 일반계약직과 무기계약직으로 구분할 수 있다. 우선 일반계약직은 회사와 근로자가 정해진 한정된 기간에 근로계약을 맺은 것으로 정년이 보장되지 않기 때문에 정규직보다 불안정하고 임금 및 근무환경이 열악하다. 무기계약직은 일반계약직과는 달리 계약기간을 정하지 않은 것이지만 임금 및 복지나 승진 등에 대해서는 일반계약직과 비슷하다. 파견직은 아웃소싱 업체에 고용되어 있으면서 다른 업체로 파견되어 일하는 근로자를 말한다. 파견기간이 2년이 넘게 되면 파견 나 간 다른 업체에서 직접 고용해야 할 의무가 생긴다.","learning_example":"학습용 가정: 직원이 회사와 계약 종료일을 정하지 않고 직접 근로계약을 맺었어요. 그렇더라도 정당한 해고 사유와 법정 절차가 충족되면 근로관계가 끝날 수 있어요."},"guard_data":{"meaning":"기간을 정하지 않고 직접 계약해 정년까지 보장되는 고용","detailed_meaning":"정규직은 법적인 개념은 아니지만 기간이 정해져 있지 않은 고용형태로 근로자와 사업주가 직접 근로계약을 체결하고 전일제로 근무하면서 정년까지 보장된다는 의미로 받아들이고 있다. 따라서 회사가 소멸되지 않는 한 원할 때까지 계속 근무가 가능하며 임금, 휴가, 상여금 등의 각종 복지혜택도 받을 수 있다. 반면 비정규직은 근로기간이 정해져 있는 계약직과 일용직, 파견 도급직, 상시 근로를 하지 않는 시간제 근로자 등을 포함하는 개념으로 계약기간이 종료되는 시점이 정해져 있다. 인턴은 일정기간 근무시켜 능력과 성품등을 평가하여 필요시 채용하는 방식이다. 계약직은 일반계약직과 무기계약직으로 구분할 수 있다. 우선 일반계약직은 회사와 근로자가 정해진 한정된 기간에 근로계약을 맺은 것으로 정년이 보장되지 않기 때문에 정규직보다 불안정하고 임금 및 근무환경이 열악하다. 무기계약직은 일반계약직과는 달리 계약기간을 정하지 않은 것이지만 임금 및 복지나 승진 등에 대해서는 일반계약직과 비슷하다. 파견직은 아웃소싱 업체에 고용되어 있으면서 다른 업체로 파견되어 일하는 근로자를 말한다. 파견기간이 2년이 넘게 되면 파견 나 간 다른 업체에서 직접 고용해야 할 의무가 생긴다.","learning_example":"직원이 근로계약의 종료일을 미리 정하지 않고 회사와 직접 고용계약을 맺어요.","news_example":"기간을 정하지 않고 정년까지 고용이 보장되는 정규직 일자리를 원하는 청년 구직자가 여전히 많은 것으로 나타났다.","visuals":null}},{"id":513,"word":"정책시차","before_data":{"visuals":[{"body":"경기 문제를 알아채고 정책을 정해 실행하기까지 걸리는 시간이 내부시차, 실행한 뒤 효과가 나타나기까지 걸리는 시간이 외부시차예요.\n시차가 길면 효과가 나올 때쯤 경기가 이미 바뀌어 오히려 경기 변동을 키울 수도 있어요.","type":"text","title":"정책은 바로 효과가 나지 않아요"},{"rows":[["재정정책","길어요(예산 편성·국회 통과 필요)","짧아요(정부지출이 바로 수요가 돼요)"],["통화정책","짧아요(금융통화위원회가 결정)","길어요(금리가 투자·소비로 이어지기까지 오래 걸려요)"]],"type":"table","title":"재정정책 vs 통화정책","caption":"경기를 미리 읽는 선행지표가 시차를 줄이는 데 도움이 돼요.","columns":["구분","내부시차","외부시차"]},{"q":"정책시차에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["재정정책은 내부시차가, 통화정책은 외부시차가 길다","재정정책은 외부시차가, 통화정책은 내부시차가 길다","두 정책 모두 시차가 없다","자동안정화장치는 내부시차가 가장 길다"],"explanation":"재정정책은 예산과 국회를 거쳐야 해 결정이 느리지만 효과는 빨라요. 통화정책은 결정은 빠르지만 효과가 나타나기까지 오래 걸려요.","lessonCheck":true},{"q":"한국은행이 금리를 내렸지만 기업들이 투자 계획을 바꾸고 실제로 공장을 짓기까지 1년 넘게 걸렸어요. 이 시간은?","type":"quiz","answer":2,"options":["내부시차","구축효과","외부시차","유동성 함정"],"explanation":"정책을 실행한 뒤 실제 경제에 효과가 나타나기까지 걸리는 시간은 외부시차예요. 통화정책은 외부시차가 긴 편이에요."}]},"after_data":{"visuals":[{"body":"경기 문제를 알아채고 정책을 정해 실행하기까지 걸리는 시간이 내부시차, 실행한 뒤 효과가 나타나기까지 걸리는 시간이 외부시차예요.\n시차가 길면 효과가 나올 때쯤 경기가 이미 바뀌어 오히려 경기 변동을 키울 수도 있어요.","type":"text","title":"정책은 바로 효과가 나지 않아요"},{"rows":[["재정정책","길어요(예산 편성·국회 통과 필요)","짧아요(정부지출이 바로 수요가 돼요)"],["통화정책","짧아요(금융통화위원회가 결정)","길어요(금리가 투자·소비로 이어지기까지 오래 걸려요)"]],"type":"table","title":"재정정책 vs 통화정책","caption":"경기를 미리 읽는 선행지표가 시차를 줄이는 데 도움이 돼요.","columns":["구분","내부시차","외부시차"]},{"q":"새로운 예산 편성과 국회 심의가 필요한 재량적 재정정책을 통화정책과 비교할 때, 일반적으로 나타나는 시차의 특징은?","type":"quiz","answer":0,"options":["재정정책은 내부시차가, 통화정책은 외부시차가 상대적으로 길다","재정정책은 외부시차가, 통화정책은 내부시차가 항상 더 길다","두 정책 모두 결정 즉시 경제 전체에 효과가 나타난다","자동안정화장치는 새 예산 심의가 필요해 내부시차가 가장 길다"],"explanation":"새 예산이 필요한 재정정책은 심의·의결 등 내부 절차가 길어질 수 있어요. 통화정책은 결정 후 대출·소비·투자에 영향을 주기까지 외부시차가 있는 편이에요. 다만 재정지출의 종류와 정책 집행 여건에 따라 달라지므로 절대적인 법칙은 아니에요.","lessonCheck":true},{"q":"한국은행이 금리를 내렸지만 기업들이 투자 계획을 바꾸고 실제로 공장을 짓기까지 1년 넘게 걸렸어요. 이 시간은?","type":"quiz","answer":2,"options":["내부시차","구축효과","외부시차","유동성 함정"],"explanation":"정책을 실행한 뒤 실제 경제에 효과가 나타나기까지 걸리는 시간은 외부시차예요. 통화정책은 외부시차가 긴 편이에요."}]},"guard_data":{"meaning":"정책 필요가 생긴 뒤 실행되고 효과가 나타나기까지 걸리는 시간","detailed_meaning":"정책시차(Policy Lag)란 어떤 경제정책을 시행해야 하는 원인이 발생하여 동 정책을 집행하는 데까지 걸리는 시간과 정책이 실제로 집행된 후 정책효과가 나타나는 데 걸리는 시간을 말한다. 전자를 내부시차(inside lag)라 하고 후자를 외부시차(outside lag)라고 한다. 일반적으로 재정정책은 정책이 집행되기까지의 내부시차가 긴 반면, 정책효과가 나타나는 데 걸리는 외부시차는 짧다. 그 이유는 정부지출이나 조세제도를 변경하려면 시간이 걸리는 입법 절차를 거쳐야 하지만, 일단 정책이 집행되고 나면 총수요에 직접적인 영향을 미치기 때문이다. 한편, 통화정책의 경우는 재정정책과는 달리 내부시차는 짧지만, 생산, 물가 등 실물변수에 영향을 미치는 데는 상당한 시간이 걸리는 등 외부시차가 상대적으로 길다. 예컨대 통화정책으로 기준금리가 인하되고 그것이 금융·외환시장을 거쳐 실물부문의 가계 소비나 기업 투자 등으로 파급되기까지는 상당한 시간이 걸릴 수 있다.","learning_example":"경기 침체를 확인하고 예산을 통과시킨 뒤 지출이 실제 일자리에 영향을 주기까지 시간이 걸려요.","news_example":"정책 효과가 나타나기까지 시간이 걸리는 정책시차 때문에 경기 대응은 한발 앞서 이뤄져야 한다는 분석이 나왔다.","visuals":[{"body":"경기 문제를 알아채고 정책을 정해 실행하기까지 걸리는 시간이 내부시차, 실행한 뒤 효과가 나타나기까지 걸리는 시간이 외부시차예요.\n시차가 길면 효과가 나올 때쯤 경기가 이미 바뀌어 오히려 경기 변동을 키울 수도 있어요.","type":"text","title":"정책은 바로 효과가 나지 않아요"},{"rows":[["재정정책","길어요(예산 편성·국회 통과 필요)","짧아요(정부지출이 바로 수요가 돼요)"],["통화정책","짧아요(금융통화위원회가 결정)","길어요(금리가 투자·소비로 이어지기까지 오래 걸려요)"]],"type":"table","title":"재정정책 vs 통화정책","caption":"경기를 미리 읽는 선행지표가 시차를 줄이는 데 도움이 돼요.","columns":["구분","내부시차","외부시차"]},{"q":"정책시차에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["재정정책은 내부시차가, 통화정책은 외부시차가 길다","재정정책은 외부시차가, 통화정책은 내부시차가 길다","두 정책 모두 시차가 없다","자동안정화장치는 내부시차가 가장 길다"],"explanation":"재정정책은 예산과 국회를 거쳐야 해 결정이 느리지만 효과는 빨라요. 통화정책은 결정은 빠르지만 효과가 나타나기까지 오래 걸려요.","lessonCheck":true},{"q":"한국은행이 금리를 내렸지만 기업들이 투자 계획을 바꾸고 실제로 공장을 짓기까지 1년 넘게 걸렸어요. 이 시간은?","type":"quiz","answer":2,"options":["내부시차","구축효과","외부시차","유동성 함정"],"explanation":"정책을 실행한 뒤 실제 경제에 효과가 나타나기까지 걸리는 시간은 외부시차예요. 통화정책은 외부시차가 긴 편이에요."}]}},{"id":519,"word":"조세부담률","before_data":{"meaning":"세금이 국민총소득에서 차지하는 비중","learning_example":"나라 전체가 벌어들인 소득에서 세금으로 낸 몫이 얼마나 되는지 살펴봐요."},"after_data":{"meaning":"일반적으로 국세와 지방세 수입이 명목 국내총생산(GDP)에서 차지하는 비율","learning_example":"학습용 가정: 국세 80조 원, 지방세 20조 원, 명목GDP 500조 원이면 조세부담률은 (80+20)÷500×100=20%예요. 사회보험료는 이 계산에 더하지 않아요."},"guard_data":{"meaning":"세금이 국민총소득에서 차지하는 비중","detailed_meaning":"조세부담률은 국민계정에서 조세수입이 국민총소득(GNI)에서 차지하는 비중으로 정의된다. 이는 국민 전체의 조세부담 정도를 나타내 주는 지표로 조세의 누진 정도, 국가의 조세징수능력 등에 따라 결정된다. 반면, 재정통계의 조세부담률은 국가 및 지방자치단체가 거둬들인 국세 및 지방세 수입이 경상금액기준 국내총생산에서 차지하는 비율로 파악된다. 조세부담률이 높다는 것은 국민들이 벌어들인 소득 중에서 세금으로 납부하는 비중이 높다는 것이다. 조세부담률 = (국세 + 지방세)/경상GDP×100 한편, 국민부담률이란 개념도 있는데 이는 국가가 가입을 의무화하거나 재정에서 지급을 보장하는 각종 공적 사회보험에 대한 보험료 등을 조세수입에 더하여 경상GDP대비 비율을 산출한 것이다. 사회보장기여금은 4대 공적연금인 국민연금, 공무원연금, 사학연금, 군인연금과 고용보험, 산업재해보상보험, 건강보험, 노인장기요양보험 등이다. 국민부담률 = (국세+지방세+사회보장기여금)/경상GDP×100","learning_example":"나라 전체가 벌어들인 소득에서 세금으로 낸 몫이 얼마나 되는지 살펴봐요.","news_example":"국민소득에서 세금이 차지하는 비중인 조세부담률이 오르면서 가계의 세금 부담이 커졌다는 지적이 나왔다.","visuals":null}},{"id":521,"word":"죄수의 딜레마","before_data":{"learning_example":"두 회사가 가격을 함께 낮추면 모두 이익이지만 서로 먼저 이기려 가격을 더 내리다 둘 다 손해를 봐요.","visuals":[{"body":"각자 자기에게 합리적인 선택을 했는데 결과는 모두에게 더 나빠지는 상황이에요.\n공범 둘을 따로 조사하면, 상대가 어떻게 하든 자백하는 쪽이 형량이 가벼워서 둘 다 자백해요.\n둘 다 버텼다면 더 가벼웠을 텐데, 서로 믿지 못해 더 나쁜 결과에 머물러요.","type":"text","title":"죄수의 딜레마 쉽게 설명"},{"rows":[["A 자백","5년, 5년","0년, 9년"],["A 부인","9년, 0년","1년, 1년"]],"type":"table","title":"죄수의 딜레마 보수표(형량)","caption":"칸의 앞 숫자는 A, 뒤 숫자는 B의 형량이에요. 자백이 둘 모두의 우월전략이라 둘 다 자백하는 칸이 균형이에요.","columns":["A의 선택","B 자백","B 부인"]},{"body":"과점 기업들이 함께 값을 높게 유지하기로 짜도, 혼자 몰래 싸게 팔면 더 큰 이윤을 얻어요.\n그래서 배신이 우월전략이 되어 담합은 안에서부터 깨지기 쉬워요. 담합을 먼저 신고하면 처벌을 줄여 주는 리니언시도 이 구조를 이용해요.\n다만 같은 게임이 계속 반복되면 보복할 수 있어 협조가 유지되기도 해요.","type":"text","title":"담합이 깨지는 이유"},{"q":"두 회사 모두 광고비를 줄이면 둘 다 이득인데, 상대가 광고를 할까 봐 둘 다 계속 많은 광고비를 써요. 이 상황을 가장 잘 설명하는 것은?","type":"quiz","answer":0,"options":["죄수의 딜레마","코즈의 정리","가격차별","수확체감의 법칙"],"explanation":"각자에게는 광고하는 쪽이 늘 나은 선택이라 둘 다 광고해요. 그 결과 둘 다 줄였을 때보다 나빠지니 죄수의 딜레마예요.","lessonCheck":true},{"q":"죄수의 딜레마가 보여 주는 것은?","type":"quiz","answer":0,"options":["개인에게 합리적인 선택이 모두에게 최선은 아닐 수 있어요","균형은 항상 모두에게 가장 좋은 결과예요","협조는 언제나 저절로 유지돼요","상대를 믿지 않으면 항상 이득이에요"],"explanation":"각자 우월전략을 골랐는데 둘 다 협조했을 때보다 결과가 나빠요. 개인의 합리성과 모두의 이익이 어긋날 수 있다는 뜻이에요."}]},"after_data":{"learning_example":"학습용 가정: 두 회사가 모두 광고를 줄이면 각 10억 원, 모두 늘리면 각 8억 원의 이익을 얻어요. 한 회사만 늘리면 늘린 회사는 12억 원, 줄인 회사는 6억 원을 얻는다면, 각자는 상대의 선택과 무관하게 광고를 늘리는 편이 유리하지만 둘 다 늘린 결과는 공동 축소보다 나빠져요.","visuals":[{"body":"각자 자기에게 합리적인 선택을 했는데 결과는 모두에게 더 나빠지는 상황이에요.\n공범 둘을 따로 조사하면, 상대가 어떻게 하든 자백하는 쪽이 형량이 가벼워서 둘 다 자백해요.\n둘 다 버텼다면 더 가벼웠을 텐데, 서로 믿지 못해 더 나쁜 결과에 머물러요.","type":"text","title":"죄수의 딜레마 쉽게 설명"},{"rows":[["A 자백","5년, 5년","0년, 9년"],["A 부인","9년, 0년","1년, 1년"]],"type":"table","title":"죄수의 딜레마 보수표(형량)","caption":"칸의 앞 숫자는 A, 뒤 숫자는 B의 형량이에요. 자백이 둘 모두의 우월전략이라 둘 다 자백하는 칸이 균형이에요.","columns":["A의 선택","B 자백","B 부인"]},{"body":"과점 기업들이 함께 값을 높게 유지하기로 짜도, 혼자 몰래 싸게 팔면 더 큰 이윤을 얻어요.\n그래서 배신이 우월전략이 되어 담합은 안에서부터 깨지기 쉬워요. 담합을 먼저 신고하면 처벌을 줄여 주는 리니언시도 이 구조를 이용해요.\n다만 같은 게임이 계속 반복되면 보복할 수 있어 협조가 유지되기도 해요.","type":"text","title":"담합이 깨지는 이유"},{"q":"두 회사가 광고를 모두 줄이면 각각 이익 10억 원, 모두 늘리면 각각 8억 원이에요. 한 회사만 늘리면 늘린 회사는 12억 원, 줄인 회사는 6억 원을 얻어요. 각자 상대의 선택과 무관하게 유리한 전략을 택하면 어떤 상황인가요?","type":"quiz","answer":0,"options":["죄수의 딜레마","코즈의 정리","가격차별","수확체감의 법칙"],"explanation":"상대가 줄이면 광고 확대의 이익 12억 원이 축소의 10억 원보다 커요. 상대가 늘려도 확대의 8억 원이 축소의 6억 원보다 커서 둘 다 확대해요. 하지만 각각 8억 원은 공동 축소 시 10억 원보다 작으므로 죄수의 딜레마예요.","lessonCheck":true},{"q":"죄수의 딜레마가 보여 주는 것은?","type":"quiz","answer":0,"options":["개인에게 합리적인 선택이 모두에게 최선은 아닐 수 있어요","균형은 항상 모두에게 가장 좋은 결과예요","협조는 언제나 저절로 유지돼요","상대를 믿지 않으면 항상 이득이에요"],"explanation":"각자 우월전략을 골랐는데 둘 다 협조했을 때보다 결과가 나빠요. 개인의 합리성과 모두의 이익이 어긋날 수 있다는 뜻이에요."}]},"guard_data":{"meaning":"서로 협력하면 최선인데 각자 이익만 좇다가 둘 다 손해 보는 상황","detailed_meaning":"전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 인해 오히려 두 사람 모두에게 바람직하지 않은 결과를 가져오는 상황을 말한다. 죄수의 딜레마(Prisoners’ Dilemma)는 1950년 미국 프린스턴대 터커(A. Tucker) 교수가 게임 이론을 설명하기 위해 이용한 다음의 예화에서 비롯되었다. 경찰이 두 용의자 Ⅰ, Ⅱ를 격리하여 심문하면서 자백을 이끌어 내려고 다음과 같이 말하였다고 가정한다. ① 한 사람이 자백하고 다른 사람은 입을 다물었다면 자백한 사람은 1단위의 보상, 입을 다문 사람은 2단위의 벌금형이 부과된다. ② 두 사람이 모두 자백하면 각각에게는 1단위의 벌금형이 부과된다. ③ 두 사람이 모두 자백하지 않으면 Ⅰ과 Ⅱ는 혐의가 없다. 이러한 상황에서 두 사람이 직면하는 보상행렬은 아래와 같아지는데, Ⅰ과 Ⅱ는 모두 상대방의 전략과 상관없이 자백하는 전략을 선택하게 되므로 결과적으로 두 사람이 서로를 믿고 자백하지 않는 전략을 취할 때보다 나쁜 결과에 직면하게 된다. 용의자 Ⅱ 구분자백함 자백하지 않음 자백함 (-1, -1) (1, -2) 용의자 Ⅰ자백하지 않음 (-2, 1) (0, 0) 즉 개인적인 수준에서는 합리적인 선택이 구성원 전체로 보아서는 비합리적인 선택이 되는 결과를 가져오는 딜레마를 낳게 되는데, 이 같은 죄수의 딜레마 문제는 광고경쟁, 기업의 환경오염, 국가간 군비경쟁 등 다양한 상황에 적용될 수 있다.","learning_example":"두 회사가 가격을 함께 낮추면 모두 이익이지만 서로 먼저 이기려 가격을 더 내리다 둘 다 손해를 봐요.","news_example":"각 기업이 자기 이익만 좇아 가격을 내리다 모두 손해를 보는 죄수의 딜레마 상황이 벌어졌다는 분석이 나왔다.","visuals":[{"body":"각자 자기에게 합리적인 선택을 했는데 결과는 모두에게 더 나빠지는 상황이에요.\n공범 둘을 따로 조사하면, 상대가 어떻게 하든 자백하는 쪽이 형량이 가벼워서 둘 다 자백해요.\n둘 다 버텼다면 더 가벼웠을 텐데, 서로 믿지 못해 더 나쁜 결과에 머물러요.","type":"text","title":"죄수의 딜레마 쉽게 설명"},{"rows":[["A 자백","5년, 5년","0년, 9년"],["A 부인","9년, 0년","1년, 1년"]],"type":"table","title":"죄수의 딜레마 보수표(형량)","caption":"칸의 앞 숫자는 A, 뒤 숫자는 B의 형량이에요. 자백이 둘 모두의 우월전략이라 둘 다 자백하는 칸이 균형이에요.","columns":["A의 선택","B 자백","B 부인"]},{"body":"과점 기업들이 함께 값을 높게 유지하기로 짜도, 혼자 몰래 싸게 팔면 더 큰 이윤을 얻어요.\n그래서 배신이 우월전략이 되어 담합은 안에서부터 깨지기 쉬워요. 담합을 먼저 신고하면 처벌을 줄여 주는 리니언시도 이 구조를 이용해요.\n다만 같은 게임이 계속 반복되면 보복할 수 있어 협조가 유지되기도 해요.","type":"text","title":"담합이 깨지는 이유"},{"q":"두 회사 모두 광고비를 줄이면 둘 다 이득인데, 상대가 광고를 할까 봐 둘 다 계속 많은 광고비를 써요. 이 상황을 가장 잘 설명하는 것은?","type":"quiz","answer":0,"options":["죄수의 딜레마","코즈의 정리","가격차별","수확체감의 법칙"],"explanation":"각자에게는 광고하는 쪽이 늘 나은 선택이라 둘 다 광고해요. 그 결과 둘 다 줄였을 때보다 나빠지니 죄수의 딜레마예요.","lessonCheck":true},{"q":"죄수의 딜레마가 보여 주는 것은?","type":"quiz","answer":0,"options":["개인에게 합리적인 선택이 모두에게 최선은 아닐 수 있어요","균형은 항상 모두에게 가장 좋은 결과예요","협조는 언제나 저절로 유지돼요","상대를 믿지 않으면 항상 이득이에요"],"explanation":"각자 우월전략을 골랐는데 둘 다 협조했을 때보다 결과가 나빠요. 개인의 합리성과 모두의 이익이 어긋날 수 있다는 뜻이에요."}]}},{"id":541,"word":"증권커스터디서비스","before_data":{"visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 투자자 대신 증권을 보관하고 배당 수령 등 관리 업무를 해 주는 서비스","type":"quiz","answer":0,"options":["증권커스터디서비스","자기띠 카드","익익일결제","현용화폐"],"explanation":"증권커스터디서비스은/는 투자자 대신 증권을 보관하고 배당 수령 등 관리 업무를 해 주는 서비스 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"visuals":[{"q":"연기금이 보유 주식의 보관·권리 기록과 배당금 수령을 금융기관에 맡겼어요. 이 업무에 가장 가까운 것은?","type":"quiz","answer":0,"options":["증권커스터디서비스","기업의 신용등급 평가","투자 판단을 대신하는 일임운용","신규 증권 인수를 통한 자금조달"],"explanation":"커스터디는 증권의 보관과 권리 관리, 배당금·원리금 수령 같은 관리 업무예요. 종목을 골라 운용하는 일임운용이나 신규 증권의 인수와는 역할이 달라요.","lessonCheck":true}]},"guard_data":{"meaning":"투자자 대신 증권을 보관하고 배당 수령 등 관리 업무를 해 주는 서비스","detailed_meaning":"증권커스터디서비스는 유가증권에 투자하는 투자자를 대신하여 해당 증권의 보고 (safekeeping) 및 기록(record keeping), 이전(delivery), 원리금 및 배당금 수령, 통지등 제반 관리서비스를 제공하는 업무를 말한다. 예를 들어, 외국인 투자자가 국내 증권에 투자할 때 시중은행 및 외국계은행 등의 커스터디기관이 실물증권 반출의 어려움이나 법적·행정적 복잡성을 해소해 주는 증권커스터디서비스를 제공하고 있다. 또한 외국 중앙은 행이 국내 채권에 투자할 경우, 커스터디기관인 한국은행을 통해 보호예수, 원리금 수령, 매매대금 결제, 환전, 여유자금 운용 등의 서비스를 이용할 수 있다. 이처럼 증권커스터디서비스는 투자자 자산을 외부 도난, 해킹, 분실 등 위험으로부터 보호하고, 법적·기술적안전성을 제공한다.","learning_example":"해외 투자자가 맡긴 주식을 보관기관이 관리하며 배당금도 대신 받아 전달해요.","news_example":"해외 주식 투자가 늘면서 증권을 대신 보관하고 배당 수령을 관리해 주는 증권커스터디서비스 수요가 커졌다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 투자자 대신 증권을 보관하고 배당 수령 등 관리 업무를 해 주는 서비스","type":"quiz","answer":0,"options":["증권커스터디서비스","자기띠 카드","익익일결제","현용화폐"],"explanation":"증권커스터디서비스은/는 투자자 대신 증권을 보관하고 배당 수령 등 관리 업무를 해 주는 서비스 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":557,"word":"지식재산생산물투자","before_data":{"meaning":"연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자","learning_example":"기업이 새 소프트웨어를 직접 개발하고 앞으로 여러 해 쓸 무형자산으로 투자해요.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자","type":"quiz","answer":0,"options":["지식재산생산물투자","부가가치","IS 곡선","생산확산지수"],"explanation":"지식재산생산물투자은/는 연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"연구개발·소프트웨어·데이터베이스·예술작품 원본 등 생산에 1년 넘게 사용할 지식재산생산물에 대한 투자","learning_example":"학습용 가정: 회사가 생산관리에 3년간 사용할 소프트웨어를 개발해 고정자산으로 인식하면 지식재산생산물투자에 해당해요. 한 달만 쓰는 일반 서비스 이용료와는 달라요.","visuals":[{"q":"기업이 생산 과정에서 3년간 사용할 소프트웨어를 개발해 고정자산으로 인식했어요. 국민계정상 어떤 투자에 가장 가까운가요?","type":"quiz","answer":0,"options":["지식재산생산물투자","건설투자","기계·운송장비에 대한 설비투자","판매를 기다리는 완제품 재고 증가"],"explanation":"소프트웨어는 반복적으로 생산에 사용되는 무형의 지식재산생산물이에요. 건물 같은 건설자산이나 기계·장비, 판매용 재고와 구분돼요.","lessonCheck":true}]},"guard_data":{"meaning":"연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자","detailed_meaning":"지식재산생산물투자는 국민계정 체계(SNA; System of National Accounts)에서 건설투자, 설비투자와 함께 총고정자본형성(=투자)을 구성하는 항목이다. 여기서 지식재산생산물이란 연구, 개발, 조사, 예술작품 창작 등 지적 노력의 결과물로 이루어진 무형자산을 말한다. 이러한 지식재산생산물투자에는 1년 이상 장기간 동안 생산에 사용될 것으로 예상되는 연구개발(R&D), 오락·문학작품 및 예술품 원본, 컴퓨터 소프트웨어 및 데이터베이스, 광물탐사 등이 있다.","learning_example":"기업이 새 소프트웨어를 직접 개발하고 앞으로 여러 해 쓸 무형자산으로 투자해요.","news_example":"연구개발과 소프트웨어 같은 무형자산에 쓰는 지식재산생산물투자가 설비투자보다 빠르게 늘어난 것으로 나타났다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자","type":"quiz","answer":0,"options":["지식재산생산물투자","부가가치","IS 곡선","생산확산지수"],"explanation":"지식재산생산물투자은/는 연구개발·소프트웨어·예술작품 같은 무형자산에 대한 투자 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":568,"word":"차입매수(LBO)","before_data":{"visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 인수할 회사의 자산을 담보로 돈을 빌려 그 회사를 사는 방식","type":"quiz","answer":0,"options":["차입매수(LBO)","평균비용","카르텔","주주환원정책"],"explanation":"차입매수(LBO)은/는 인수할 회사의 자산을 담보로 돈을 빌려 그 회사를 사는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"visuals":[{"q":"인수자가 매수가격 100억 원 중 80억 원을 인수대상 기업의 자산 등을 담보로 빌려 조달하려 해요. 이 구조와 가장 가까운 것은?","type":"quiz","answer":0,"options":["차입매수(LBO)","차입 없이 자기자금만으로 하는 인수","인수 없이 기존 주주에게 하는 현금배당","기업이 신규 주식을 발행해 자금을 조달하는 유상증자"],"explanation":"인수자금의 큰 부분을 차입으로 조달하고 인수대상 기업의 자산 등을 활용하는 구조가 차입매수예요. 예시의 차입 비중은 80÷100×100=80%이며, 이 수치 자체가 법정 기준이라는 뜻은 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"인수할 회사의 자산을 담보로 돈을 빌려 그 회사를 사는 방식","detailed_meaning":"차입매수(LBO; Leveraged Buy out)란 기업을 매수하려는 주체가 인수에 필요한 자금이 충분하지 않은 경우 금융기관 등으로부터 인수대상 기업의 자산을 담보로 인수자금을 차입하여 기업을 매수하는 방식을 말한다. 인수 및 합병이 이루어진 후에는 인수한 기업의 자산을 매각하거나 또는 직접 인수한 기업을 경영하여 발생한 수익으로 차입금을 상환하게 된다. 차입매수는 자기자본 부담 없이도 기업을 매수할 수 있는 것이 가장 큰 장점이다. 그러나 기업 인수후 차입금을 상환하지 못할 신용위험이 커지며, 기업 매수 완료 후자기자본비율이 하락하는 등 재무건전성이 취약해질 가능성도 있고, 자산을 매각하는 과 정에서 대대적인 구조조정도 수반되는 등 많은 약점도 가지고 있다. 그래서 이 제도는 주로 투기펀드들의 고수익 투자방안으로 많이 활용되고 있다.","learning_example":"인수자가 사려는 회사의 자산을 담보로 대출을 받아 그 회사를 매입해요.","news_example":"사모펀드가 인수 대상 회사의 자산을 담보로 돈을 빌려 회사를 사들이는 차입매수(LBO)에 나섰다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 인수할 회사의 자산을 담보로 돈을 빌려 그 회사를 사는 방식","type":"quiz","answer":0,"options":["차입매수(LBO)","평균비용","카르텔","주주환원정책"],"explanation":"차입매수(LBO)은/는 인수할 회사의 자산을 담보로 돈을 빌려 그 회사를 사는 방식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":576,"word":"총고정자본형성","before_data":{"meaning":"기업이 공장·기계 등 고정자산을 새로 사들이거나 지은 금액(설비·건설 투자)","learning_example":"기업이 새 공장을 짓고 오래 쓸 기계를 사는 금액이 총고정자본형성에 반영돼요."},"after_data":{"meaning":"기업·정부 등 생산주체가 생산에 오래 쓰는 유형·무형 고정자산을 취득한 금액에서 처분한 금액을 뺀 투자","learning_example":"학습용 가정: 다른 거래가 없고 국내 기업이 새 기계 10억 원과 생산용 소프트웨어 2억 원을 취득했다면 총고정자본형성은 12억 원이에요. 감가상각 1억 원을 뺀 11억 원은 순고정자본형성이에요."},"guard_data":{"meaning":"기업이 공장·기계 등 고정자산을 새로 사들이거나 지은 금액(설비·건설 투자)","detailed_meaning":"기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한 것이 아니고 미래의 지속적인 수입의 보장 등 장기적인안목에서 이루어진다. 이렇게 장기간에 걸쳐 생산과정에 반복적, 지속적으로 사용되는 유형 또는 무형의 산출물을 고정자산이라 하고, 생산주체에 의한 고정자산의 순취득(취득- 처분)을 총고정자본형성(GFCF; gross fixed capital formation)이라 한다. 총고정자본형성에는 토지나 중고품의 구매는 제외되고 고정자산 취득에 따른 설치비용이나 취득세, 등록세 등의 부대비용은 포함된다.","learning_example":"기업이 새 공장을 짓고 오래 쓸 기계를 사는 금액이 총고정자본형성에 반영돼요.","news_example":"기업들이 공장과 기계에 대한 투자를 늘리면서 총고정자본형성이 증가한 것으로 나타났다.","visuals":null}},{"id":577,"word":"총부채상환비율(DTI)","before_data":{"meaning":"연소득 대비 주택담보대출 연간 원리금 상환액의 비율","learning_example":"학습용 가정: 연소득 5천만 원에 주택대출 원리금을 연 1천만 원 갚으면 단순 계산한 DTI는 20%예요."},"after_data":{"meaning":"연소득에 비해 주택담보대출의 연간 원리금과 기타대출의 연간 이자 상환액이 얼마나 되는지 보는 비율","learning_example":"학습용 가정: 연소득 5,000만 원, 주택담보대출의 연간 원리금 1,000만 원, 기타대출의 연간 이자 200만 원이라면 DTI는 (1,000+200)÷5,000×100=24%예요. 실제 심사에는 대출별 산정 규칙이 적용돼요."},"guard_data":{"meaning":"연소득 대비 주택담보대출 연간 원리금 상환액의 비율","detailed_meaning":"차주의 연간 소득 대비 연간 대출 원리금 상환액의 비율(Debt-To-Income ratio)을 의미한다. 주택담보대출 차주의 원리금상환능력을 감안하여 주택담보대출 한도를 설정하기 위해 도입된 규제 비율이다. 「은행업감독업무시행세칙」에서는 “총부채상환비율 = [(해당 주택담보대출 및 기존 주택담보대출의 연간 원리금 상환액 + 기타부채의 연간이자상환액) / 연소득] × 100” 방식으로 산정하도록 하고 있다. DTI 규제는 담보인정비율(LTV) 규제 강화의 후속조치로 2005년 8월 도입되었으며, 이는 차주의 상환능력과 관계없이 담보가치(주택가격)에 비례하여 주택담보대출 한도가 결정되는 LTV 규제의 문제점을 보완하고자 도입한 것이다. 특히 과도한 가계부채의 증가 억제 및 주택자금 수요 축소 등을 위해 DTI 비율을 특정수준 이내로 제한하기도 한다. 한편, DTI 규제는 LTV 규제와 함 께 대표적인 특정 부문에 대한 거시건전성정책 수단으로서 통화신용정책과 상호 보완적인 관계를 가지고 있다. 예를 들어 저금리 하에서 주택가격 상승세가 확대될 경우 DTI 및LTV 규제를 강화하면 주택담보대출 한도가 축소되어 주택시장 과열을 억제하는 효과를 기대할 수 있다.","learning_example":"학습용 가정: 연소득 5천만 원에 주택대출 원리금을 연 1천만 원 갚으면 단순 계산한 DTI는 20%예요.","news_example":"금융당국은 소득에 비해 주택담보대출 상환 부담이 큰 차주를 막기 위해 총부채상환비율(DTI) 규제를 유지했다.","visuals":null}},{"id":588,"word":"출금이체","before_data":{"meaning":"받을 사람이 은행에 요청해 상대 계좌에서 돈을 빼 오는 이체 방식(자동이체)","learning_example":"고객이 자동이체에 동의해 두면 통신사가 매달 요금을 고객 계좌에서 출금해요."},"after_data":{"meaning":"돈을 받을 사람이 금융기관에 요청해, 사전 동의 등 필요한 요건에 따라 납부자 계좌에서 자기 계좌로 돈을 옮기는 방식","learning_example":"학습용 가정: 회원이 매월 회비 2만 원 출금에 미리 동의했어요. 협회가 금융기관에 출금을 요청하면 회원 계좌에서 2만 원이 빠져 협회 계좌로 입금돼요."},"guard_data":{"meaning":"받을 사람이 은행에 요청해 상대 계좌에서 돈을 빼 오는 이체 방식(자동이체)","detailed_meaning":"출금이체(Debit Transfer)는 수취인이 자신이 거래하는 금융기관에 추심을 의뢰하여(즉, 인출지시) 지급인의 계좌로부터 이체금액을 출금하여 수취인 자신의 계좌에 입금하도록하는 계좌이체방식을 말한다. 대표적인 출금이체방식으로는 수표 추심, 지로시스템의 자동이체, 자금관리서비스(CMS)공동망의 대량자금이체 중 출금이체가 있다. 지로의 자동이체와 CMS의 출금이체는 모두 사전 약정된 수취인의 자금인출지시로 납부자의 예금계좌에서 자금이 인출되어 수납자의 예금계좌로 자동이체된다.","learning_example":"고객이 자동이체에 동의해 두면 통신사가 매달 요금을 고객 계좌에서 출금해요.","news_example":"통신요금과 보험료처럼 받는 쪽이 고객 계좌에서 돈을 빼 가는 출금이체 이용이 꾸준히 늘고 있다.","visuals":null}},{"id":595,"word":"커버드본드(이중상환청구권부 채권)","before_data":{"visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 은행이 주택담보대출 등을 담보로 발행하며 은행 자체 신용까지 함께 책임지는 채권","type":"quiz","answer":0,"options":["커버드본드(이중상환청구권부 채권)","내부자거래","고정금리부채권(SB)","주가지수"],"explanation":"커버드본드(이중상환청구권부 채권)은/는 은행이 주택담보대출 등을 담보로 발행하며 은행 자체 신용까지 함께 책임지는 채권 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"visuals":[{"q":"채권 투자자가 발행 은행에 원리금 상환을 청구할 수 있고, 은행이 파산하면 별도 관리된 담보자산에서도 우선 변제를 받을 수 있어요. 이에 해당하는 채권은?","type":"quiz","answer":0,"options":["커버드본드(이중상환청구권부 채권)","별도 담보가 없는 일반 은행채","이자 지급 없이 할인 발행되는 국채","은행의 손실을 먼저 흡수하는 보통주"],"explanation":"커버드본드는 발행 금융기관에 대한 청구권에 더해 담보자산에 대한 우선변제권을 가져요. 그래서 이중상환청구권부 채권이라고 하며, 두 권리가 있다고 손실 가능성이 완전히 사라지는 것은 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"은행이 주택담보대출 등을 담보로 발행하며 은행 자체 신용까지 함께 책임지는 채권","detailed_meaning":"커버드본드(Covered Bond)란 금융기관이 부동산담보대출 등 자신이 보유한 고정자산을 담보로 발행한 채권을 말하며 우리나라에는 2014년 4월 도입되었다. 대출자산 등을 담보로 하는 것은 자산유동화증권(ABS)이나 주택저당증권(MBS)과 유사하다. 그러나 ABS 나 MBS는 채권 발행시 기초자산(담보자산)을 별도로 설립된 특수목적기구(SPC)에 이전함에 따라 최초로 담보자산을 보유했던 금융기관의 변제의무는 소멸되는 반면, 커버드본드는 투자자가 담보자산에 대해 우선변제권을 보장받는 동시에 채권발행 금융기관에 대해서도 원리금 상환을 청구할 수 있다. 그래서 커버드본드를 이중상환청구권부 채권이라고도 한다. 커버드본드는 이렇게 이중으로 원리금 상환을 보장받기 때문에 일반 채권보다 발행금리가 낮게 형성된다. 일반적으로 은행들은 만기가 짧은 예금으로 자금을 조달하여장기로 자금을 운용할 경우 금리위험에 노출됨에 따라 장기로 자금을 운용하기 어렵다. 그러나 은행이 커버드본드를 발행하면 낮은 고정금리로 장기자금을 조달할 수 있어 주택담보대출과 같은 장기 고정금리대출을 확대할 수 있다. 즉, 커버드본드는 은행들의 안정적인 장기자금 조달을 가능하게 해주는 한편 가계에 대해서는 장기 고정금리 주택담보대출을 해줄 수 있으므로 가계부채의 구조 개선(금리변동위험으로부터 차입자 보호 등)에도 기여할 수 있다.","learning_example":"은행이 주택대출을 담보로 채권을 발행하고 투자자는 담보자산뿐 아니라 은행에도 상환을 청구할 수 있어요.","news_example":"은행은 주택담보대출을 담보로 하고 은행 자체 신용으로도 상환을 책임지는 커버드본드(이중상환청구권부 채권)를 발행했다.","visuals":[{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 은행이 주택담보대출 등을 담보로 발행하며 은행 자체 신용까지 함께 책임지는 채권","type":"quiz","answer":0,"options":["커버드본드(이중상환청구권부 채권)","내부자거래","고정금리부채권(SB)","주가지수"],"explanation":"커버드본드(이중상환청구권부 채권)은/는 은행이 주택담보대출 등을 담보로 발행하며 은행 자체 신용까지 함께 책임지는 채권 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":612,"word":"통화승수","before_data":{"visuals":[{"body":"한국은행이 공급한 본원통화가 신용창조를 거쳐 통화량으로 몇 배 불어났는지를 나타낸 게 통화승수예요.\n현금을 들고 있는 사람이 없다면 최대 통화승수는 1 ÷ 지급준비율이에요. 지급준비율이 10%면 10배예요.\n사람들이 현금을 들고 있으면 은행으로 덜 돌아와서 실제 승수는 그보다 작아요.","type":"text","title":"통화량 = 본원통화 × 통화승수"},{"rows":[["지급준비율","낮아야 해요","대출할 수 있는 돈이 늘어요"],["현금통화비율","낮아야 해요","은행으로 돌아와 다시 대출되는 돈이 늘어요"]],"type":"table","title":"통화승수를 정하는 두 가지","caption":"본원통화는 씨앗 돈, 통화량은 승수만큼 불어난 돈이에요.","columns":["요인","승수가 커지려면","이유"]},{"q":"경제가 불안해지자 사람들이 예금을 빼서 현금으로 들고 있기 시작했어요. 본원통화가 그대로라면 통화승수와 통화량은 어떻게 될까요?","type":"quiz","answer":2,"options":["승수는 늘고 통화량은 줄어든다","둘 다 변하지 않는다","둘 다 줄어든다","둘 다 늘어난다"],"explanation":"현금통화비율이 높아지면 은행으로 돌아와 다시 대출되는 돈이 줄어 통화승수가 작아져요. 본원통화가 같으니 통화량도 줄어요.","lessonCheck":true},{"q":"현금 보유가 없을 때 지급준비율이 5%라면 최대 통화승수는?","type":"quiz","answer":1,"options":["95","20","10","5"],"explanation":"최대 통화승수는 1 ÷ 지급준비율이에요. 1 ÷ 0.05 = 20이에요."}]},"after_data":{"visuals":[{"body":"한국은행이 공급한 본원통화가 신용창조를 거쳐 통화량으로 몇 배 불어났는지를 나타낸 게 통화승수예요.\n현금을 들고 있는 사람이 없다면 최대 통화승수는 1 ÷ 지급준비율이에요. 지급준비율이 10%면 10배예요.\n사람들이 현금을 들고 있으면 은행으로 덜 돌아와서 실제 승수는 그보다 작아요.","type":"text","title":"통화량 = 본원통화 × 통화승수"},{"rows":[["지급준비율","낮아야 해요","대출할 수 있는 돈이 늘어요"],["현금통화비율","낮아야 해요","은행으로 돌아와 다시 대출되는 돈이 늘어요"]],"type":"table","title":"통화승수를 정하는 두 가지","caption":"본원통화는 씨앗 돈, 통화량은 승수만큼 불어난 돈이에요.","columns":["요인","승수가 커지려면","이유"]},{"q":"단순 신용창출 모형에서 지급준비율은 0과 1 사이이며 일정하고, 본원통화도 일정해요. 통화량 중 현금의 비율만 높아지면 통화승수와 통화량은 어떻게 되나요?","type":"quiz","answer":2,"options":["승수는 늘고 통화량은 줄어든다","둘 다 변하지 않는다","둘 다 줄어든다","둘 다 늘어난다"],"explanation":"현금통화비율을 c, 지급준비율을 r이라 하면 승수는 1/[c+(1−c)r]이에요. 0<r<1일 때 c가 커지면 분모가 커져 승수가 작아지고, 본원통화가 일정하므로 통화량도 줄어요. 단순히 예금을 현금으로 바꾸는 순간 통화량이 자동 소멸한다는 뜻은 아니에요.","lessonCheck":true},{"q":"학습용 단순 모형에서 현금 보유와 은행의 초과지급준비금이 없고, 법정 준비금을 제외한 돈은 모두 재대출되어 예금돼요. 지급준비율이 5%라면 최대 통화승수는?","type":"quiz","answer":1,"options":["95","20","10","5"],"explanation":"이 가정에서 최대 통화승수는 1÷0.05=20이에요. 현금 유출이나 초과지급준비금이 있으면 실제 승수는 이 단순 최대치와 달라질 수 있어요."}]},"guard_data":{"meaning":"중앙은행이 푼 본원통화가 몇 배의 통화량으로 불어났는지 나타내는 배수","detailed_meaning":"중앙은행이 공급한 본원통화는 예금은행의 신용창출과정을 통해 이의 수 배에 달하는 통화를 시중에 유통하게 한다. 통화승수(Money Multiplier)는 본원통화 한 단위가 이의 몇 배에 달하는 통화를 창출하였는가를 나타내는 지표로서 통화 총량을 본원통화로 나누어 산출한다. 통화승수는 현금통화 비율과 지급준비율에 의하여 결정되는데 현금통화 비율은 단기적으로는 안정적이라 할 수 있으며 지급준비율은 중앙은행에 의하여 정책적으로 결정된다. M(통화) = RB(본원통화) × k(통화승수), k = 1/{c+(1-c)r} (단 c는 현금통화 비율, r은 지급준비율). 참고로 2025년 3월 말 현재 우리나라의 본원통화 잔액(말잔기준)은 290조원이고, M1, M2, Lf, L의 잔액은 각각 1,308조원, 4,228조원, 5,760조원, 7,250조원으로 통화승수는 각각 4.51배, 14.59배, 19.88배, 25.01배를 기록하고 있다. 한편 동 승수의 장기추세를 보면 우리나라의 경우 대략 2008년 글로벌 금융위기 이후 각 통화승수가 장기적으로 낮아지는 모습을 보이고 있다.","learning_example":"학습용 가정: 본원통화가 100억 원이고 통화량이 500억 원이면 통화승수는 5배예요.","news_example":"은행 대출이 위축되면서 본원통화가 통화량으로 불어나는 배수인 통화승수가 낮아진 것으로 나타났다.","visuals":[{"body":"한국은행이 공급한 본원통화가 신용창조를 거쳐 통화량으로 몇 배 불어났는지를 나타낸 게 통화승수예요.\n현금을 들고 있는 사람이 없다면 최대 통화승수는 1 ÷ 지급준비율이에요. 지급준비율이 10%면 10배예요.\n사람들이 현금을 들고 있으면 은행으로 덜 돌아와서 실제 승수는 그보다 작아요.","type":"text","title":"통화량 = 본원통화 × 통화승수"},{"rows":[["지급준비율","낮아야 해요","대출할 수 있는 돈이 늘어요"],["현금통화비율","낮아야 해요","은행으로 돌아와 다시 대출되는 돈이 늘어요"]],"type":"table","title":"통화승수를 정하는 두 가지","caption":"본원통화는 씨앗 돈, 통화량은 승수만큼 불어난 돈이에요.","columns":["요인","승수가 커지려면","이유"]},{"q":"경제가 불안해지자 사람들이 예금을 빼서 현금으로 들고 있기 시작했어요. 본원통화가 그대로라면 통화승수와 통화량은 어떻게 될까요?","type":"quiz","answer":2,"options":["승수는 늘고 통화량은 줄어든다","둘 다 변하지 않는다","둘 다 줄어든다","둘 다 늘어난다"],"explanation":"현금통화비율이 높아지면 은행으로 돌아와 다시 대출되는 돈이 줄어 통화승수가 작아져요. 본원통화가 같으니 통화량도 줄어요.","lessonCheck":true},{"q":"현금 보유가 없을 때 지급준비율이 5%라면 최대 통화승수는?","type":"quiz","answer":1,"options":["95","20","10","5"],"explanation":"최대 통화승수는 1 ÷ 지급준비율이에요. 1 ÷ 0.05 = 20이에요."}]}},{"id":616,"word":"통화유통속도","before_data":{"meaning":"돈 한 단위가 1년 동안 몇 번 거래에 쓰였는지 나타내는 지표","learning_example":"학습용 가정: 한 해 명목 거래액이 1,000억 원이고 평균 통화량이 200억 원이면 통화유통속도는 5회예요.","visuals":[{"q":"명목 GDP가 500, 통화량이 100이라면 같은 기간 통화유통속도는?","type":"quiz","answer":0,"options":["5","0.2","600"],"explanation":"명목 GDP를 통화량으로 나누어 계산해요.","lessonCheck":true}]},"after_data":{"meaning":"일정 기간의 명목GDP를 같은 기간의 평균 통화량으로 나눠, 돈이 생산·소득을 뒷받침하며 도는 정도를 나타내는 지표","learning_example":"학습용 가정: 1년 명목GDP가 500조 원이고 같은 해 평균 통화량이 100조 원이면 통화유통속도는 500÷100=5예요. 주식·중고품 거래를 포함한 모든 거래 횟수를 직접 센 값은 아니에요.","visuals":[{"q":"1년간 명목GDP가 500조 원, 같은 해 평균 통화량이 100조 원이라면 소득 기준 통화유통속도는?","type":"quiz","answer":0,"options":["5","0.2","600"],"explanation":"명목GDP÷같은 기간 평균 통화량=500÷100=5예요. 돈이 실제로 몇 번 손바뀜했는지 모든 거래를 직접 센 횟수가 아니라 소득과 통화량의 비율이에요.","lessonCheck":true}]},"guard_data":{"meaning":"돈 한 단위가 1년 동안 몇 번 거래에 쓰였는지 나타내는 지표","detailed_meaning":"통화유통속도(Velocity of Circulation of Money)는 통화 한 단위가 일정 기간(통상 1년) 동안 각종 거래를 매개하기 위해 몇 번 유통되었는지를 나타내는 지표를 말한다. 그런데국민경제 전체의 거래규모를 측정할 수는 없으므로 소득이 거래액과 유사하게 변동한다 는 가정하에 연간 국민소득을 통화량으로 나눈 소득유통속도를 사용하는 것이 일반적이다. 통화유통속도는 장기적으로는 생산의 우회도, 경제주체의 거래관습 등 경제 구조적인원인에 의해 결정된다. 반면 단기적으로는 통화보유의 기회비용에 영향을 미치는 시장금리, 예상물가상승률의 변화, 경기 변동 등 거시적 요인과 금융상품 관련 제도변화나 금융혁신 등 금융여건 변화에 따라 변동하기도 한다.","learning_example":"학습용 가정: 한 해 명목 거래액이 1,000억 원이고 평균 통화량이 200억 원이면 통화유통속도는 5회예요.","news_example":"돈이 거래에 쓰이는 횟수를 뜻하는 통화유통속도가 떨어지면서 돈이 잘 돌지 않는다는 지적이 나왔다.","visuals":[{"q":"명목 GDP가 500, 통화량이 100이라면 같은 기간 통화유통속도는?","type":"quiz","answer":0,"options":["5","0.2","600"],"explanation":"명목 GDP를 통화량으로 나누어 계산해요.","lessonCheck":true}]}},{"id":623,"word":"투입계수","before_data":{"meaning":"한 단위를 생산하는 데 다른 산업의 중간재가 얼마나 들어가는지 나타낸 계수","learning_example":"학습용 가정: 빵 1개를 만들 때 밀가루 0.5kg이 필요하면 빵 생산의 밀가루 투입계수는 0.5kg이에요."},"after_data":{"meaning":"한 산업의 생산물 1원어치를 만드는 데 필요한 각 중간재의 투입액을 나타낸 비율","learning_example":"학습용 가정: 빵 생산액이 100만 원이고 밀가루 투입액이 20만 원이면 밀가루 투입계수는 20만 원 ÷ 100만 원 = 0.2예요."},"guard_data":{"meaning":"한 단위를 생산하는 데 다른 산업의 중간재가 얼마나 들어가는지 나타낸 계수","detailed_meaning":"각 산업부문이 재화나 서비스의 생산에 사용하기 위하여 다른 산업으로부터 구매한 원재료, 연료 등 중간재별 투입액을 총투입액으로 나눈 것으로서 각 부문 생산물 1단위 생산에 필요한 중간재들의 단위를 나타낸다. 따라서 어떤 산업부문의 중간재 투입계수들을 모두 합하면 중간투입률이 되며 이와 같은 투입계수는 각 산업부문의 생산활동에서 생산기술구조, 즉 투입과 산출의 함수관계를 나타낸다고 할 수 있다. 한편, 투입계수를 산출함에 있어서는 물량단위에 의한 방법이 이상적이라고 할 수 있으나 모든 생산물의 공통적인 단위가 없으므로 금액에 의한 투입계수를 산출하는 것이 일반적인 방법이다.","learning_example":"학습용 가정: 빵 1개를 만들 때 밀가루 0.5kg이 필요하면 빵 생산의 밀가루 투입계수는 0.5kg이에요.","news_example":"한 단위를 생산하는 데 다른 산업의 중간재가 얼마나 들어가는지 보여주는 투입계수는 산업연관분석의 기초가 된다.","visuals":null}},{"id":638,"word":"피셔효과","before_data":{"meaning":"기대 인플레이션이 오르면 명목금리도 그만큼 오른다는 이론","learning_example":"물가상승 기대가 커지면 돈을 빌려주는 쪽이 요구하는 명목금리도 올라갈 수 있어요.","visuals":[{"body":"실질이자율 5%를 받고 싶은데 물가가 3% 오를 것 같으면 명목이자율은 8%여야 해요.\n그래서 사람들이 예상하는 물가상승률이 오르면 명목이자율도 거의 그만큼 따라 오르는데, 이를 피셔효과라고 해요.\n은행에 붙은 금리는 명목이자율이에요.","type":"text","title":"명목이자율 = 실질이자율 + 예상 인플레이션"},{"rows":[["채권자(돈 빌려준 사람)","채무자(돈 빌린 사람)"],["현금·예금 보유자","실물자산 보유자"],["봉급·연금 생활자","정부(큰 채무자)"]],"type":"table","title":"예상 못한 인플레이션이면","caption":"미리 예상한 인플레이션은 이자율에 반영돼 피해가 작지만, 예상하지 못하면 부가 재분배돼요.","columns":["불리한 쪽","유리한 쪽"]},{"q":"실질이자율은 2%로 그대로인데 사람들이 예상하는 물가상승률이 1%에서 4%로 올랐어요. 피셔효과에 따르면 명목이자율은?","type":"quiz","answer":0,"options":["3%에서 6%로 오른다","4%로 정해진다","2%로 그대로다","1%로 내린다"],"explanation":"명목이자율 = 실질이자율 + 예상 인플레이션이에요. 2 + 1 = 3%에서 2 + 4 = 6%로 올라요.","lessonCheck":true},{"q":"명목이자율이 6%, 예상 물가상승률이 4%라면 실질이자율은?","type":"quiz","answer":1,"options":["-2%","2%","10%","1.5%"],"explanation":"실질이자율 = 명목이자율 - 예상 인플레이션이에요. 6 - 4 = 2%예요."}]},"after_data":{"meaning":"실질금리가 일정할 때 기대 물가상승률이 오르면 명목금리도 그만큼 오른다는 이론","learning_example":"학습용 가정: 실질금리가 2%로 일정하고 기대 물가상승률이 1%에서 4%로 오르면, 합산 근사식에 따른 명목금리는 약 3%에서 약 6%로 올라요.","visuals":[{"body":"실질이자율 5%를 받고 싶은데 물가가 3% 오를 것 같으면 명목이자율은 8%여야 해요.\n그래서 사람들이 예상하는 물가상승률이 오르면 명목이자율도 거의 그만큼 따라 오르는데, 이를 피셔효과라고 해요.\n은행에 붙은 금리는 명목이자율이에요.","type":"text","title":"명목이자율 = 실질이자율 + 예상 인플레이션"},{"rows":[["채권자(돈 빌려준 사람)","채무자(돈 빌린 사람)"],["현금·예금 보유자","실물자산 보유자"],["봉급·연금 생활자","정부(큰 채무자)"]],"type":"table","title":"예상 못한 인플레이션이면","caption":"미리 예상한 인플레이션은 이자율에 반영돼 피해가 작지만, 예상하지 못하면 부가 재분배돼요.","columns":["불리한 쪽","유리한 쪽"]},{"q":"실질이자율은 2%로 일정하고 예상 물가상승률이 1%에서 4%로 올랐어요. 명목금리를 실질금리와 예상 물가상승률의 합으로 근사하면?","type":"quiz","answer":0,"options":["3%에서 6%로 오른다","4%로 정해진다","2%로 그대로다","1%로 내린다"],"explanation":"합산 근사식은 명목금리 ≈ 실질금리 + 예상 물가상승률이에요. 따라서 약 3%(2%+1%)에서 약 6%(2%+4%)로 올라요. 정확한 복리 관계와는 소폭 차이가 날 수 있어요.","lessonCheck":true},{"q":"명목이자율이 6%, 예상 물가상승률이 4%라면 단순 차감으로 근사한 실질이자율은?","type":"quiz","answer":1,"options":["-2%","2%","10%","1.5%"],"explanation":"단순 차감 근사식으로 6% - 4% = 약 2%예요. 정확한 구매력 기준 계산은 1.06 ÷ 1.04 - 1 ≈ 1.92%이므로 여기서는 근사값을 물었어요."}]},"guard_data":{"meaning":"기대 인플레이션이 오르면 명목금리도 그만큼 오른다는 이론","detailed_meaning":"1920년대 미국의 경제학자 어빙 피셔(Irving Fisher)가 발표한 이론으로, 피셔방정식 (Fisher equation)은 명목금리가 실질금리와 기대인플레이션의 합계와 같다고 표현한다. 시중의 명목금리가 상승했다면 그것은 실질금리의 상승이 원인일 수도 있고, 기대인플레이션의 상승이 원인일 수도 있는 것이다. 피셔효과(Fisher effect)가 통화정책에서 나타나는 사례를 살펴보자. 중앙은행이 정책금리를 인상하면 단기적으로 시중의 명목금리가 상승하지만, 중장기적으로는 오히려 명목금리가 하락할 가능성도 있다. 이는 중앙은행이 통화긴축을 실시할 경우 물가안정에 대한 기대감이 높아져 기대인플레이션이 낮아지면명목금리가 하락하게 되기 때문이다. 한편, 국제피셔효과(international Fisher effect)는 자본의 국제적 이동이 자유롭다(즉, 국가 간의 실질금리는 동일하다)는 가정 하에 양국간명목금리의 차이는 양국통화간 기대되는 환율변동과 같아진다는 이론이다. 국제피셔효과 는 피셔방정식과 구매력평가설을 함께 적용하여 설명할 수 있다. 완전한 자본이동성이 성립(양국간 실질금리는 동일)할 경우, 피셔방정식에 의하면 양국간 명목금리 차이는 양국간 기대인플레이션 차이와 같아진다. 여기에 구매력평가설(purchasing power parity) 이 성립한다고 가정하자. 즉, 동일한 물품은 어떤 국가에서도 같은 가격에 구입한다는 일물일가(一物一價)의 법칙이 성립한다고 가정하자. 이 경우 자국의 물가수준은 외국의 물가 수준에 양국간 환율을 곱한 값이 된다. 이 관계를 시간에 대해 미분하여 상대적 변화율을 구하면, 양국간 기대인플레이션의 차이는 양국간 기대되는 환율변동과 같게 된다. 따라서 피셔방정식과 구매력평가설이 동시에 성립한다면, 양국간 명목금리의 차이는 양국간 기대되는 환율변동과 같다.","learning_example":"물가상승 기대가 커지면 돈을 빌려주는 쪽이 요구하는 명목금리도 올라갈 수 있어요.","news_example":"기대 인플레이션이 오르면 명목금리도 따라 오른다는 피셔효과에 따라 채권 금리가 상승했다는 분석이 나왔다.","visuals":[{"body":"실질이자율 5%를 받고 싶은데 물가가 3% 오를 것 같으면 명목이자율은 8%여야 해요.\n그래서 사람들이 예상하는 물가상승률이 오르면 명목이자율도 거의 그만큼 따라 오르는데, 이를 피셔효과라고 해요.\n은행에 붙은 금리는 명목이자율이에요.","type":"text","title":"명목이자율 = 실질이자율 + 예상 인플레이션"},{"rows":[["채권자(돈 빌려준 사람)","채무자(돈 빌린 사람)"],["현금·예금 보유자","실물자산 보유자"],["봉급·연금 생활자","정부(큰 채무자)"]],"type":"table","title":"예상 못한 인플레이션이면","caption":"미리 예상한 인플레이션은 이자율에 반영돼 피해가 작지만, 예상하지 못하면 부가 재분배돼요.","columns":["불리한 쪽","유리한 쪽"]},{"q":"실질이자율은 2%로 그대로인데 사람들이 예상하는 물가상승률이 1%에서 4%로 올랐어요. 피셔효과에 따르면 명목이자율은?","type":"quiz","answer":0,"options":["3%에서 6%로 오른다","4%로 정해진다","2%로 그대로다","1%로 내린다"],"explanation":"명목이자율 = 실질이자율 + 예상 인플레이션이에요. 2 + 1 = 3%에서 2 + 4 = 6%로 올라요.","lessonCheck":true},{"q":"명목이자율이 6%, 예상 물가상승률이 4%라면 실질이자율은?","type":"quiz","answer":1,"options":["-2%","2%","10%","1.5%"],"explanation":"실질이자율 = 명목이자율 - 예상 인플레이션이에요. 6 - 4 = 2%예요."}]}},{"id":642,"word":"필립스곡선","before_data":{"meaning":"실업률이 낮으면 물가상승률이 높아진다는 둘 사이의 반비례 관계 곡선","learning_example":"일자리를 찾기 쉬워 실업률이 낮아질 때 임금과 물가 상승 압력이 커지는 관계를 살펴봐요."},"after_data":{"meaning":"다른 조건이 같을 때 단기적으로 실업률과 물가상승률이 반대 방향으로 움직이는 관계를 나타낸 곡선","learning_example":"학습용 가정: 기대 물가상승률과 공급 여건이 같은 단기 모형에서 총수요가 늘어 실업률이 5%에서 4%로 낮아지는 동안 물가상승률은 2%에서 3%로 높아져요."},"guard_data":{"meaning":"실업률이 낮으면 물가상승률이 높아진다는 둘 사이의 반비례 관계 곡선","detailed_meaning":"뉴질랜드 출신의 영국인 경제학자 필립스(W. Phillips)는 1958년 명목 임금상승률과 실업률이 역의 상관관계를 나타낸다는 것을 처음으로 관찰하였는데, 이러한 임금상승률과 실업률 사이의 반비례 관계를 나타내는 곡선을 필립스 곡선이라 한다. 즉 필립스는 1861 년에서 1957년 사이의 영국의 통계자료를 이용하여 실업률이 낮은 해에는 명목 임금상승률이 높고, 반대로 실업률이 높은 해에는 명목 임금상승률이 낮다는 사실을 발견하였다. 일반적으로 명목 임금상승률과 물가상승률은 비슷한 움직임을 보이기 때문에 물가상승률과 실업률 간의 안정적인 반비례 관계를 나타내는 곡선을 필립스 곡선이라 부른다. 이러한 필립스 곡선은 단순히 경험적 관계로부터 도출되었지만, 완전고용을 이루면(실업률이 낮으면) 물가상승률이 높아지고(물가불안정), 완전고용에서 멀어지면(실업률이 높으면) 물가상승률이 낮아지는(물가안정) 완전고용과 물가안정 사이의 상충관계를 밝힘으로써경제정책 분석에 크게 기여하였다.","learning_example":"일자리를 찾기 쉬워 실업률이 낮아질 때 임금과 물가 상승 압력이 커지는 관계를 살펴봐요.","news_example":"실업률이 낮아지면 물가상승률이 높아진다는 필립스곡선 관계가 약해졌다는 연구 결과가 나왔다.","visuals":[{"body":"단기에는 실업률이 낮을수록 물가상승률이 높고, 실업률이 높을수록 물가상승률이 낮은 관계가 나타나요.\n총수요가 늘면 생산이 늘어 실업은 줄지만 물가는 오르기 때문이에요.\n그래서 물가 안정과 완전고용을 동시에 이루기 어려워요.","type":"text","title":"실업률과 물가상승률의 상충관계"},{"rows":[["단기 필립스곡선","우하향","물가 상승을 감수하면 실업을 줄일 수 있어요"],["장기 필립스곡선","자연실업률에서 수직","기대 물가가 조정되면 실업률은 자연실업률로 돌아가요"]],"type":"table","title":"단기와 장기","caption":"원자재값이 오르는 공급 충격이 오면 실업과 물가가 함께 올라 단기 곡선이 위로 이동해요.","columns":["구분","모양","뜻"]},{"q":"정부가 총수요를 늘려 단기적으로 실업률을 낮췄어요. 단기 필립스곡선에 따르면 함께 나타나기 쉬운 것은?","type":"quiz","answer":1,"options":["자연실업률 하락","물가상승률 상승","물가상승률 하락","잠재GDP 감소"],"explanation":"단기 필립스곡선은 우하향이라 실업률이 내려가면 물가상승률이 올라가요. 실업과 물가 사이의 상충관계예요.","lessonCheck":true},{"q":"장기 필립스곡선의 모양은?","type":"quiz","answer":1,"options":["우하향","자연실업률 수준에서 수직","우상향","수평"],"explanation":"장기에는 사람들의 기대 물가가 실제 물가에 맞춰 조정돼요. 그래서 실업률은 자연실업률로 돌아가고 곡선은 수직이 돼요."}]}},{"id":647,"word":"한시적 근로자","before_data":{"meaning":"계약 기간이 정해져 있는 기간제·계약직 근로자","learning_example":"직원이 회사와 1년 근무하기로 계약하고 기간이 끝나면 재계약 여부를 정해요."},"after_data":{"meaning":"계약 기간을 정해 일하는 사람, 기간을 정하지 않고 계약을 반복 갱신해 계속 일하는 사람, 또는 비자발적 사유로 계속 근무하기 어려운 사람","learning_example":"학습용 가정: 1년 계약으로 일하는 직원과, 계약 기간은 정하지 않았지만 맡은 공사가 끝나면 계속 근무할 수 없는 직원은 모두 한시적 근로자에 해당해요."},"guard_data":{"meaning":"계약 기간이 정해져 있는 기간제·계약직 근로자","detailed_meaning":"근로기간이 정해져 있지 않는 상시 근로자와 달리 근로 기간이 정해져 있는 계약직, 일용직 등을 비정규직 근로자라 한다. 이에는 한시적 근로자, 시간제 근로자 및 비전형근로자가 있다. 한시적 근로자란 근로계약 기간을 정한 근로자(기간제 근로자) 또는 따로 정하지않았으나 계약의 반복 갱신으로 계속 일할 수 있는 근로자와 비자발적 사유로 계속 근무를 기대할 수 없는 근로자(비기간제 근로자)를 말한다. 여기서 기간제 근로자는 일정 기간의 근로계약 기간을 정하여(구두 또는 묵시적 약속이나 계약을 포함하여) 근로를 제공하는 근로자를 말하며 계약 기간의 장·단, 계약 반복 갱신 여부, 계약직·촉탁직·임시직·계절근로자 등 명칭과는 관계가 없다. 시간제 근로자란 직장에서 근무하도록 정해진 소정의 근로 시간이 동일 사업장에서 동일 종류의 업무를 수행하는 근로자의 소정의 근로시간보다 1시간이라도 짧은 근로자로 평소 1주에 36시간미만 일하기로 정해져 있는 경우가 여기에 해당된다. 한편 비전형근로자는 파견근로자, 용역근로자, 가정내 근로자, 일일(단기) 근로자 등을 말한다. 참고로 임시근로자는 임금근로자로서 고용계약 기간이 1개월 이상 1년 미만인 경우, 고용계약 미설정자는 일정한 사업(완료 기간이 1년 미만)의 필요에 의해고용된 경우를 말한다.","learning_example":"직원이 회사와 1년 근무하기로 계약하고 기간이 끝나면 재계약 여부를 정해요.","news_example":"계약 기간이 정해진 한시적 근로자가 늘면서 고용 안정성에 대한 우려가 커지고 있다.","visuals":null}},{"id":650,"word":"합계출산율","before_data":{"meaning":"여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수","learning_example":"학습용 가정: 각 연령대의 출산율을 합산했더니 여성 한 명이 평생 낳을 것으로 예상되는 자녀 수가 평균 1명으로 계산돼요."},"after_data":{"meaning":"현재의 연령별 출산율이 유지된다고 가정할 때 여성 한 명이 가임기간에 낳을 것으로 기대되는 평균 자녀 수","learning_example":"학습용 가정: 15~49세의 각 1세별 출산율이 여성 1명당 모두 0.02명이고 이 수준이 유지되면 합계출산율은 35 × 0.02 = 0.7명이에요."},"guard_data":{"meaning":"여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수","detailed_meaning":"한 여성이 가임기간인 15세에서 49세 사이에 낳을 것으로 기대되는 평균 출생아 수를 측정하는 통계를 말하는데, 실제로는 5년 단위 간격으로 구분한 연령대별 출산율을 계산한 후 이를 합한 개념이기 때문에 합계출산율(Total Fertility Rate)이라고 부른다. 동 지표는 한 국가의 출산력 비교에 유용하게 쓰이고 있으며, 향후 인구는 물론 노동력의 변동을 가 늠하는 데 매우 유용한 지표로 활용되고 있다. 유럽경제위원회(UNECE)는 선진국에서 현재의 인구를 그대로 유지하는 데 필요한 합계출산율이 최소 2.1명이어야 한다고 추산한 바 있다. 우리나라의 합계출산율은 1982년 2.39명을 정점으로 1983년 2.03명으로 낮아진 이후 계속 떨어져 2023년에는 0.72명의 매우 낮은 수준을 기록하였다. 앞으로도 합계출산율 수준이 현 수준보다 크게 높아지지 않는 한 우리나라 인구가 2030년 이후에는 빠르게 감소할 것으로 예상되고 있다.","learning_example":"학습용 가정: 각 연령대의 출산율을 합산했더니 여성 한 명이 평생 낳을 것으로 예상되는 자녀 수가 평균 1명으로 계산돼요.","news_example":"여성 한 명이 평생 낳을 것으로 예상되는 자녀 수인 합계출산율이 낮아지며 인구 감소 우려가 커졌다.","visuals":null}},{"id":694,"word":"GDP디플레이터","before_data":{"meaning":"명목 국내총생산을 실질 국내총생산으로 나눈 가장 종합적인 물가지수","learning_example":"학습용 가정: 명목 GDP가 110이고 실질 GDP가 100이면 GDP디플레이터는 110이에요.","detailed_meaning":"명목GDP를 실질GDP로 나누어 얻어지는 값을 GDP디플레이터라 한다. GDP를 추계할때는 생산자물가지수(PPI)나 소비자물가지수(CPI)뿐만 아니라 수출입물가지수, 임금 등 각종 가격지수가 종합적으로 활용된다. 따라서 GDP디플레이터는 모든 물가요인을 포괄하는 가장 종합적인 물가지수라 할 수 있다. 한편 소비, 투자, 수출, 수입 부문별로 명목 GDP를 동일 부문의 실질GDP로 나누면 개별 부문에서의 물가지수(예를 들면 소비디플레이터, 투자디플레이터 등)를 얻을 수 있다."},"after_data":{"meaning":"명목 국내총생산을 실질 국내총생산으로 나눈 뒤 100을 곱해 구하는, 기준연도 100의 종합 물가지수","learning_example":"학습용 가정: 같은 기간의 명목 GDP가 110조 원, 실질 GDP가 100조 원이면 GDP디플레이터는 110 ÷ 100 × 100 = 110으로 기준연도보다 물가 수준이 10% 높아요.","detailed_meaning":"명목GDP를 실질GDP로 나눈 뒤 100을 곱하여 얻어지는 값(기준연도=100)을 GDP디플레이터라 한다. GDP를 추계할때는 생산자물가지수(PPI)나 소비자물가지수(CPI)뿐만 아니라 수출입물가지수, 임금 등 각종 가격지수가 종합적으로 활용된다. 따라서 GDP디플레이터는 모든 물가요인을 포괄하는 가장 종합적인 물가지수라 할 수 있다. 한편 소비, 투자, 수출, 수입 부문별로 명목 GDP를 동일 부문의 실질GDP로 나눈 뒤 100을 곱하면 개별 부문에서의 물가지수(예를 들면 소비디플레이터, 투자디플레이터 등)를 얻을 수 있다."},"guard_data":{"meaning":"명목 국내총생산을 실질 국내총생산으로 나눈 가장 종합적인 물가지수","detailed_meaning":"명목GDP를 실질GDP로 나누어 얻어지는 값을 GDP디플레이터라 한다. GDP를 추계할때는 생산자물가지수(PPI)나 소비자물가지수(CPI)뿐만 아니라 수출입물가지수, 임금 등 각종 가격지수가 종합적으로 활용된다. 따라서 GDP디플레이터는 모든 물가요인을 포괄하는 가장 종합적인 물가지수라 할 수 있다. 한편 소비, 투자, 수출, 수입 부문별로 명목 GDP를 동일 부문의 실질GDP로 나누면 개별 부문에서의 물가지수(예를 들면 소비디플레이터, 투자디플레이터 등)를 얻을 수 있다.","learning_example":"학습용 가정: 명목 GDP가 110이고 실질 GDP가 100이면 GDP디플레이터는 110이에요.","news_example":"명목 국내총생산을 실질 국내총생산으로 나눈 GDP디플레이터가 하락하며 경제 전반의 물가가 낮아진 것으로 나타났다.","visuals":null}},{"id":709,"word":"P2P대출","before_data":{"meaning":"금융회사 없이 온라인 플랫폼에서 개인끼리 돈을 빌려주고 빌리는 대출","learning_example":"온라인 플랫폼에서 대출을 원하는 사람의 신청을 보고 여러 개인 투자자가 자금을 빌려줘요."},"after_data":{"meaning":"온라인 플랫폼을 통해 투자자의 자금을 모아 개인이나 기업에 빌려주는 대출","learning_example":"학습용 가정: 온라인 대출 플랫폼에서 투자자 10명이 10만 원씩 투자한 총 100만 원을 한 소상공인에게 빌려줘요."},"guard_data":{"meaning":"금융회사 없이 온라인 플랫폼에서 개인끼리 돈을 빌려주고 빌리는 대출","detailed_meaning":"P2P대출(Peer-to-Peer Lending)은 온라인상에서 자금공급자(투자자)와 자금수요자(차입자) 간 전통적인 금융회사의 중개 없이 자금중개가 이뤄지는 금융활동의 하나이다. P2P(peer-to-peer)는 원래 인터넷망을 통해 개인 간에 자신의 음악·동영상·사진 등의 파일을 공유하는 서비스인데 이 개념을 금융에 접목한 것이다. 초기에는 개인 사이의 대출 중개에 집중하였으나 최근에는 기업에 대한 대출 중개 및 다른 금융서비스 제공까지그 업무영역을 확장하고 있다. 이러한 대출 형태는 나라마다 조금씩 차이가 있는데 미국의 경우 P2P대출 중개업자는 온라인으로 대출을 신청한 차입자의 관련 어음(notes)을 산업대부회사(ILC; Industrial Loan Company)로부터 매입하여 투자자에게 제공한다. 증권거래위원회(SEC)가 이 어음을 ‘증권’(securities)으로 해석하여 규제하고, 투자자는 이 증권을 유통시장에서 매도하여 중간에 투자금액을 회수할 수도 있다. 이에 기관투자가까지도 투자자로 참여함에 따라 P2P대출은 시장형 대출(marketplace lending)로도 표현된다. 반면 영국의 경우 소비자신용업이 가능한 P2P대출 중개업자가 투자자들에게서 모금한 자금을 차입자에게 ‘대출금’으로 집행하므로 미국의 ILC같은 여신금융기관은 별도로 없다. 그래서 금융행위감독청(FCA)이 중개업자들의 자본건전성을 규제한다. 우리나라의 경우 대체로 ‘P2P대출정보’중개업자는 자회사인 대부업체로부터 매입한 ‘원리금수취권리’를 투자자에게 매도하고, 대부업체에게서 대출받은 차입자가 원리금을 상환하면, 이 것이 다시 투자자에게 돌아간다. 그래서 대부업관련 법률을 적용받는다. 금융위원회는 투자자·차입자 등을 보호하기 위해 ‘P2P대출 가이드라인’(2017.2.27)을 도입하여 개인당 P2P대출정보 중개업자별 투자한도(1천만원) 설정, P2P업체 자산과 투자자 예치금의 분리 예치, 과장광고 금지 등의 규제를 시행하였으며 최근에는 「온라인투자연계 금융업 및이용자 보호에 관한 법률」이 2025년 8월 27일부터 시행될 예정임에 따라, 기존의 가이드라인도 동 법령과 연계해 일부 개정 및 확대 적용될 예정이다.","learning_example":"온라인 플랫폼에서 대출을 원하는 사람의 신청을 보고 여러 개인 투자자가 자금을 빌려줘요.","news_example":"금융회사를 거치지 않고 온라인 플랫폼에서 개인끼리 돈을 빌려주는 P2P대출에 대한 투자자 보호가 강화됐다.","visuals":null}},{"id":720,"word":"비경제활동인구","before_data":{"meaning":"15세 이상이지만 일할 의사나 능력이 없어 노동시장 밖에 있는 사람","learning_example":"일을 할 수 있는 나이지만 학교에 다니며 일을 하거나 구직할 계획이 없는 학생이 여기에 포함돼요."},"after_data":{"meaning":"15세 이상 조사대상 인구 중 취업자도 실업자도 아닌 사람","learning_example":"학습용 가정: 일을 할 능력과 의사는 있지만 최근 4주 동안 적극적인 구직 활동을 하지 않은 구직단념자는 비경제활동인구로 분류돼요."},"guard_data":{"meaning":"15세 이상이지만 일할 의사나 능력이 없어 노동시장 밖에 있는 사람","detailed_meaning":"만15세 이상 인구 중 일할 수 있는 능력과 취업의사를 동시에 갖춘 사람을 경제활동인구라 한다. 경제활동인구는 현재 취업상태에 있는지에 따라 취업자와 실업자로 구분된다. 취업자란 매월 15일이 포함된 1주일 동안에 수입을 목적으로 1시간 이상 일한 사람과 본인 또는 가족이 운영하는 농장이나 사업체에서 주당 18시간 이상 일한 무급가족종사자를 가리킨다. 그밖에 일정한 직장이나 사업장은 가지고 있으나 일시적인 질병, 일기불순, 휴가, 노동쟁의 등의 사유로 조사기간에 일을 하지 않은 사람도 취업자로 분류된다. 실업자란 적극적으로 일자리를 구해보았으나 일을 하지 못한 사람으로서 즉시 취업이 가능한 사람을 말한다. 한편 15세 이상 인구 중 경제활동인구에 포함되지 않은 사람, 즉 조사대상기간에 취업도 실업도 아닌 상태에 있는 사람은 비경제활동인구로 분류된다. 비경제활동인구에는 집안에서 가사와 육아를 도맡아 하는 전업주부, 학교에 다니는 학생, 일을 할 수없는 연로자와 심신장애자, 구직단념자 등이 포함된다. 경제활동참가율은 15세 이상 인구에 대한 경제활동인구의 비율을 말한다. 경제활동인구(취업자 + 실업자) 경제활동참가율 = ×100 15세 이상 인구","learning_example":"일을 할 수 있는 나이지만 학교에 다니며 일을 하거나 구직할 계획이 없는 학생이 여기에 포함돼요.","news_example":"일할 의사가 없어 노동시장 밖에 있는 비경제활동인구 가운데 그냥 쉬었다는 사람이 늘어났다.","visuals":null}},{"id":731,"word":"실질국내총생산","before_data":{"meaning":"기준연도 가격으로 계산해 물가 변동을 뺀 국내총생산","learning_example":"물건을 더 많이 만들었는지 보려고 올해 생산량을 기준연도 가격으로 환산해 GDP를 계산해요."},"after_data":{"meaning":"물가 변동의 영향을 제거해 생산량 변화를 나타낸 국내총생산","learning_example":"학습용 가정: 생산물 종류와 수량이 그대로이고 모든 가격만 10% 올랐다면 명목 GDP는 10% 늘어도 실질 GDP는 변하지 않아요."},"guard_data":{"meaning":"기준연도 가격으로 계산해 물가 변동을 뺀 국내총생산","detailed_meaning":"명목국내총생산(Nominal GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 그 생산물이 생산된 기간의 가격을 적용하여 계산한 것이다. 명목GDP의 변동분에는 최종생산물의 수량과 가격변동분이 혼재되어 있다. 명목GDP는 경제규모 등의 파악에 이용된다. 반면 실질국내총생산(Real GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 기준년도 의 가격으로 측정한 것이다. 실질GDP는 우리나라를 비롯한 많은 국가에서 UN이 권고한 국제기준인 국민계정체계(SNA; System of National Accounts)에 따라 연쇄가중법에 의 해 추계되고 있다. 연쇄가중법은 기준연도의 가중치를 계속 적용하지 않고 기준연도의 명목금액에 연쇄물량지수를 곱하여 실질GDP를 산출한다. 실질GDP는 경제성장, 경기변동등 전반적인 경제활동의 흐름을 분석하는 데 이용된다. 명목GDP는 특정 시점의 국가간비교, 다른 지표의 기준치(예: 총저축률, GDP대비 경상수지 비율 등)로 활용된다.","learning_example":"물건을 더 많이 만들었는지 보려고 올해 생산량을 기준연도 가격으로 환산해 GDP를 계산해요.","news_example":"물가 변동 효과를 뺀 실질국내총생산이 늘어나며 경제가 실제로 성장한 것으로 나타났다.","visuals":[{"q":"명목 GDP는 10% 늘었지만 생산량은 그대로이고 가격만 10% 올랐어요. 실질 GDP는?","type":"quiz","answer":0,"options":["변하지 않는다","10% 증가한다","10% 감소한다"],"explanation":"실질 GDP는 가격 변화 효과를 제거해 생산량 변화를 측정해요.","lessonCheck":true}]}},{"id":794,"word":"가격차별","before_data":{"meaning":"같은 상품을 사는 사람에 따라 다른 가격을 받는 것","learning_example":"같은 영화관 좌석이라도 성인과 청소년에게 서로 다른 입장료를 받아요.","visuals":[{"body":"같은 물건을 사람이나 사는 양에 따라 다른 값에 파는 거예요. 조조할인, 학생할인, 대용량 할인이 모두 가격차별이에요.\n가능하려면 독점력이 있고, 손님을 나눌 수 있고, 싸게 산 사람이 되팔 수 없어야 해요.","type":"text","title":"가격차별 쉽게 설명"},{"rows":[["1급","손님마다 최대 지불 의사만큼 받음","소비자잉여 0, 생산량은 완전경쟁과 같음"],["2급","많이 살수록 단위당 싸게","묶음·대용량 할인"],["3급","집단마다 다른 가격","가격에 민감한(탄력적인) 집단이 더 쌈"]],"type":"table","title":"가격차별 1·2·3급","caption":"1급은 사중손실이 없어 효율은 높지만, 잉여가 모두 기업에게 가요.","columns":["구분","방식","특징"]},{"q":"영화관이 일반 관객보다 학생에게 더 싸게 표를 팔아요. 그 이유로 가장 알맞은 것은?","type":"quiz","answer":0,"options":["학생 수요가 가격에 더 민감(탄력적)해서","학생에게 상영 비용이 더 적게 들어서","학생이 표를 되팔 수 있어서","일반 관객 수요가 더 탄력적이어서"],"explanation":"3급 가격차별에서는 비싸면 안 사는 탄력적인 집단에 싸게, 비싸도 사는 비탄력적인 집단에 비싸게 받아요.","lessonCheck":true},{"q":"가격차별이 아닌 것은?","type":"quiz","answer":0,"options":["품질과 비용이 다른 두 상품에 다른 값을 받는 것","같은 영화를 아침에 싸게 파는 조조할인","같은 상품을 많이 사면 단위당 싸게 주는 것","같은 상품을 나라마다 다른 값에 파는 것"],"explanation":"가격차별은 같은 물건을 다른 값에 파는 거예요. 품질이나 비용이 다른 물건에 다른 값을 받는 건 가격차별이 아니에요."}]},"after_data":{"meaning":"비용 차이만으로 설명되지 않는 가격 차이를 고객·구매량·판매 시점 등에 따라 두는 판매 방식","learning_example":"학습용 가정: 제공 서비스와 비용이 같은 영화표를 일반 관객에게 1만 원, 학생에게 8천 원에 팔고 표를 되팔 수 없다면 가격차별의 예예요.","visuals":[{"body":"같은 물건을 사람이나 사는 양에 따라 다른 값에 파는 거예요. 조조할인, 학생할인, 대용량 할인이 모두 가격차별이에요.\n가능하려면 독점력이 있고, 손님을 나눌 수 있고, 싸게 산 사람이 되팔 수 없어야 해요.","type":"text","title":"가격차별 쉽게 설명"},{"rows":[["1급","손님마다 최대 지불 의사만큼 받음","소비자잉여 0, 생산량은 완전경쟁과 같음"],["2급","많이 살수록 단위당 싸게","묶음·대용량 할인"],["3급","집단마다 다른 가격","가격에 민감한(탄력적인) 집단이 더 쌈"]],"type":"table","title":"가격차별 1·2·3급","caption":"1급은 사중손실이 없어 효율은 높지만, 잉여가 모두 기업에게 가요.","columns":["구분","방식","특징"]},{"q":"같은 영화를 같은 비용으로 상영하고 표를 되팔 수 없다고 가정해요. 영화관이 집단별 수요의 가격탄력성을 이용해 학생에게 더 싸게 팔아 이윤을 높인다면 그 이유로 가장 알맞은 것은?","type":"quiz","answer":0,"options":["학생 수요가 가격에 더 민감(탄력적)해서","학생에게 상영 비용이 더 적게 들어서","학생이 표를 되팔 수 있어서","일반 관객 수요가 더 탄력적이어서"],"explanation":"다른 조건과 한계비용이 같을 때, 3급 가격차별에서는 가격에 더 민감한 집단에 낮은 가격을 매겨 이윤을 높일 수 있어요. 학생 할인만 보고 실제 탄력성을 단정하는 것은 아니며 이 문제에서는 그런 가격차별 상황을 가정했어요.","lessonCheck":true},{"q":"다음 중 비용 차이만을 반영한 가격 책정으로, 가격차별에 해당하지 않는 것은?","type":"quiz","answer":0,"options":["원가가 2천 원 더 드는 상품에 그 차이만큼만 더 받는 것","비용은 같지만 같은 영화를 아침에 더 싸게 파는 조조할인","단위당 비용은 같지만 같은 상품을 많이 사면 단위당 싸게 파는 것","판매비용은 같지만 같은 상품을 나라마다 다른 값에 파는 것"],"explanation":"첫 보기는 가격 차이가 원가 차이만을 반영하므로 가격차별이 아니에요. 나머지는 비용이 같아도 시간·구매량·시장별로 가격을 달리하는 경우예요. 품질이 다른 상품도 경우에 따라 가격차별에 활용될 수 있어 품질 차이만으로 단정하지 않아요."}]},"guard_data":{"meaning":"같은 상품을 사는 사람에 따라 다른 가격을 받는 것","detailed_meaning":"영화 조조할인, 학생 할인, 비행기 좌석 가격처럼 지불 의사가 다른 고객에게 다른 가격을 매긴다. 기업은 이익을 늘리고, 싼 가격 덕분에 원래 못 사던 사람도 살 수 있게 된다. 되팔기가 어려워야 가능하다.","learning_example":"같은 영화관 좌석이라도 성인과 청소년에게 서로 다른 입장료를 받아요.","news_example":"같은 영화라도 조조 시간대 표를 싸게 파는 것은 대표적인 가격차별 사례로 꼽힌다.","visuals":[{"body":"같은 물건을 사람이나 사는 양에 따라 다른 값에 파는 거예요. 조조할인, 학생할인, 대용량 할인이 모두 가격차별이에요.\n가능하려면 독점력이 있고, 손님을 나눌 수 있고, 싸게 산 사람이 되팔 수 없어야 해요.","type":"text","title":"가격차별 쉽게 설명"},{"rows":[["1급","손님마다 최대 지불 의사만큼 받음","소비자잉여 0, 생산량은 완전경쟁과 같음"],["2급","많이 살수록 단위당 싸게","묶음·대용량 할인"],["3급","집단마다 다른 가격","가격에 민감한(탄력적인) 집단이 더 쌈"]],"type":"table","title":"가격차별 1·2·3급","caption":"1급은 사중손실이 없어 효율은 높지만, 잉여가 모두 기업에게 가요.","columns":["구분","방식","특징"]},{"q":"영화관이 일반 관객보다 학생에게 더 싸게 표를 팔아요. 그 이유로 가장 알맞은 것은?","type":"quiz","answer":0,"options":["학생 수요가 가격에 더 민감(탄력적)해서","학생에게 상영 비용이 더 적게 들어서","학생이 표를 되팔 수 있어서","일반 관객 수요가 더 탄력적이어서"],"explanation":"3급 가격차별에서는 비싸면 안 사는 탄력적인 집단에 싸게, 비싸도 사는 비탄력적인 집단에 비싸게 받아요.","lessonCheck":true},{"q":"가격차별이 아닌 것은?","type":"quiz","answer":0,"options":["품질과 비용이 다른 두 상품에 다른 값을 받는 것","같은 영화를 아침에 싸게 파는 조조할인","같은 상품을 많이 사면 단위당 싸게 주는 것","같은 상품을 나라마다 다른 값에 파는 것"],"explanation":"가격차별은 같은 물건을 다른 값에 파는 거예요. 품질이나 비용이 다른 물건에 다른 값을 받는 건 가격차별이 아니에요."}]}},{"id":797,"word":"사중손실","before_data":{"visuals":[{"body":"가격 규제나 세금 때문에 거래량이 균형보다 줄면서 누구에게도 돌아가지 않고 사라진 잉여예요.\n더 거래됐다면 사는 쪽과 파는 쪽이 얻었을 이득이 없어진 거예요.\n그래프에서는 사라진 삼각형으로 나타나요.","type":"text","title":"사중손실 쉽게 설명"},{"rows":[["거래량","40","20"],["소비자잉여","800","1,000"],["생산자잉여","800","200"],["사회후생","1,600","1,200"]],"type":"table","title":"가격 상한으로 보는 사중손실","caption":"수요 P = 100 - Q, 공급 P = 20 + Q인 시장이에요. 사회후생이 줄어든 400이 사중손실이에요.","columns":["항목","규제 전","상한 40"]},{"body":"세금을 매겨도 거래량이 줄어 사중손실(초과부담)이 생겨요.\n수요나 공급이 탄력적일수록 거래량이 크게 줄어 사중손실도 커져요.\n그래서 효율만 보면 비탄력적인 상품에 매기는 세금이 손실이 적어요.","type":"text","title":"사중손실이 커지는 경우"},{"q":"정부가 어떤 상품에 개당 세금을 매겨 거래량이 줄었어요. 이때 생기는 사중손실에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["줄어든 거래에서 생겼을 잉여가 사라진 거예요","정부가 걷은 세금 전체예요","소비자가 더 낸 금액이에요","생산자가 덜 받은 금액이에요"],"explanation":"세금 수입은 정부에게 옮겨 간 돈이라 사라진 게 아니에요. 거래량이 줄어 아무에게도 돌아가지 않은 잉여가 사중손실이에요.","lessonCheck":true},{"q":"같은 세금을 매길 때 사중손실이 더 커지는 상품은?","type":"quiz","answer":0,"options":["수요가 탄력적인 상품","수요가 완전 비탄력적인 상품","공급이 완전 비탄력적인 상품","대신할 상품이 거의 없는 상품"],"explanation":"탄력적이면 세금에 반응해 거래량이 크게 줄어요. 줄어든 거래가 많을수록 사라지는 잉여도 커요."}]},"after_data":{"visuals":[{"body":"가격 규제나 세금 때문에 거래량이 균형보다 줄면서 누구에게도 돌아가지 않고 사라진 잉여예요.\n더 거래됐다면 사는 쪽과 파는 쪽이 얻었을 이득이 없어진 거예요.\n그래프에서는 사라진 삼각형으로 나타나요.","type":"text","title":"사중손실 쉽게 설명"},{"rows":[["거래량","40","20"],["소비자잉여","800","1,000"],["생산자잉여","800","200"],["사회후생","1,600","1,200"]],"type":"table","title":"가격 상한으로 보는 사중손실","caption":"수요 P = 100 - Q, 공급 P = 20 + Q인 시장이에요. 사회후생이 줄어든 400이 사중손실이에요.","columns":["항목","규제 전","상한 40"]},{"body":"세금을 매겨도 거래량이 줄어 사중손실(초과부담)이 생겨요.\n수요나 공급이 탄력적일수록 거래량이 크게 줄어 사중손실도 커져요.\n그래서 효율만 보면 비탄력적인 상품에 매기는 세금이 손실이 적어요.","type":"text","title":"사중손실이 커지는 경우"},{"q":"외부효과가 없는 완전경쟁시장에서 정부가 상품에 개당 세금을 매겨 거래량이 줄었어요. 이때 생기는 사중손실에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["줄어든 거래에서 생겼을 잉여가 사라진 거예요","정부가 걷은 세금 전체예요","소비자가 더 낸 금액이에요","생산자가 덜 받은 금액이에요"],"explanation":"세금 수입은 정부에게 옮겨 간 돈이라 사라진 게 아니에요. 거래량이 줄어 아무에게도 돌아가지 않은 잉여가 사중손실이에요.","lessonCheck":true},{"q":"외부효과가 없는 경쟁시장에서 수요·공급곡선은 직선이에요. 개당 1,000원의 세금을 새로 부과해 균형 거래량이 세전 100개에서 세후 80개로 줄었다면 사중손실은?","type":"quiz","answer":0,"options":["10,000원","20,000원","80,000원","100,000원"],"explanation":"수요·공급곡선이 직선이면 사중손실은 삼각형 넓이로 계산해요. 1,000원 × (100개 − 80개) ÷ 2 = 10,000원이에요. 세수 1,000원 × 80개 = 80,000원과는 달라요."}]},"guard_data":{"meaning":"독점·세금·가격 규제 때문에 거래가 줄어 누구도 얻지 못하고 사라지는 후생","detailed_meaning":"거래가 일어났다면 소비자와 생산자 모두 이득을 봤을 텐데, 가격이 왜곡되어 그 거래가 사라지면서 없어지는 몫이다. 세금이 클수록, 수요와 공급이 가격에 민감할수록 사중손실이 커진다.","learning_example":"세금 때문에 구매자가 내는 값은 높아지고 판매자가 받는 값은 낮아져 서로 이득이던 거래 일부가 사라져요.","news_example":"과도한 세금으로 거래 자체가 줄면 누구의 이득도 되지 못하고 사라지는 사중손실이 생긴다는 지적이다.","visuals":[{"body":"가격 규제나 세금 때문에 거래량이 균형보다 줄면서 누구에게도 돌아가지 않고 사라진 잉여예요.\n더 거래됐다면 사는 쪽과 파는 쪽이 얻었을 이득이 없어진 거예요.\n그래프에서는 사라진 삼각형으로 나타나요.","type":"text","title":"사중손실 쉽게 설명"},{"rows":[["거래량","40","20"],["소비자잉여","800","1,000"],["생산자잉여","800","200"],["사회후생","1,600","1,200"]],"type":"table","title":"가격 상한으로 보는 사중손실","caption":"수요 P = 100 - Q, 공급 P = 20 + Q인 시장이에요. 사회후생이 줄어든 400이 사중손실이에요.","columns":["항목","규제 전","상한 40"]},{"body":"세금을 매겨도 거래량이 줄어 사중손실(초과부담)이 생겨요.\n수요나 공급이 탄력적일수록 거래량이 크게 줄어 사중손실도 커져요.\n그래서 효율만 보면 비탄력적인 상품에 매기는 세금이 손실이 적어요.","type":"text","title":"사중손실이 커지는 경우"},{"q":"정부가 어떤 상품에 개당 세금을 매겨 거래량이 줄었어요. 이때 생기는 사중손실에 대한 설명으로 옳은 것은?","type":"quiz","answer":0,"options":["줄어든 거래에서 생겼을 잉여가 사라진 거예요","정부가 걷은 세금 전체예요","소비자가 더 낸 금액이에요","생산자가 덜 받은 금액이에요"],"explanation":"세금 수입은 정부에게 옮겨 간 돈이라 사라진 게 아니에요. 거래량이 줄어 아무에게도 돌아가지 않은 잉여가 사중손실이에요.","lessonCheck":true},{"q":"같은 세금을 매길 때 사중손실이 더 커지는 상품은?","type":"quiz","answer":0,"options":["수요가 탄력적인 상품","수요가 완전 비탄력적인 상품","공급이 완전 비탄력적인 상품","대신할 상품이 거의 없는 상품"],"explanation":"탄력적이면 세금에 반응해 거래량이 크게 줄어요. 줄어든 거래가 많을수록 사라지는 잉여도 커요."}]}},{"id":802,"word":"실업률","before_data":{"meaning":"일하고 싶고 일할 수 있는 사람 중 일자리를 찾지 못한 사람의 비율","learning_example":"학습용 가정: 일하거나 적극 구직하는 사람 100명 중 일자리가 없는 사람이 5명이면 실업률은 5%예요."},"after_data":{"meaning":"취업자와 실업자를 합한 경제활동인구 중 실업자가 차지하는 비율","learning_example":"학습용 가정: 취업자 95명과 최근 4주간 적극적으로 구직하고 바로 일할 수 있는 실업자 5명이 있으면 실업률은 5 ÷ (95 + 5) × 100 = 5%예요."},"guard_data":{"meaning":"일하고 싶고 일할 수 있는 사람 중 일자리를 찾지 못한 사람의 비율","detailed_meaning":"실업률은 실업자를 경제활동인구(취업자 + 실업자)로 나눈 값이다. 일할 생각이 없는 학생이나 전업주부는 경제활동인구에 들어가지 않는다. 그래서 구직을 포기한 사람이 늘면 실업률이 오히려 내려갈 수 있어, 고용률과 함께 봐야 한다.","learning_example":"학습용 가정: 일하거나 적극 구직하는 사람 100명 중 일자리가 없는 사람이 5명이면 실업률은 5%예요.","news_example":"일자리를 찾지 못한 구직자가 늘면서 경제활동인구 가운데 실업자 비중을 뜻하는 실업률이 상승했다.","visuals":[{"body":"실업률 = 실업자 ÷ 경제활동인구 × 100, 고용률 = 취업자 ÷ 15세 이상 생산가능인구 × 100이에요.\n실업자는 일하지 않았고, 지난 4주간 적극적으로 일자리를 찾았고, 바로 일할 수 있는 사람이에요.\n주 1시간 이상 돈을 받고 일했다면 아르바이트라도 취업자예요.","type":"text","title":"실업률과 고용률은 분모가 달라요"},{"rows":[["생산가능인구","15세 이상(군인·수감자 등 제외)"],["경제활동인구","취업자 + 실업자"],["비경제활동인구","학생·전업주부·구직 포기자처럼 일하지도 구직하지도 않는 사람"]],"type":"table","title":"인구는 이렇게 나눠요","columns":["구분","누구"]},{"body":"일자리를 못 찾아 구직을 포기한 사람은 실업자가 아니라 비경제활동인구가 돼요.\n그러면 실업자가 줄어 실업률은 내려가지만 취업자는 그대로라 고용률은 변하지 않아요. 그래서 실업률은 고용률과 함께 봐야 해요.","type":"text","title":"구직 포기의 함정"},{"q":"실업자 일부가 구직을 포기해 비경제활동인구가 됐어요. 실업률과 고용률은 어떻게 될까요?","type":"quiz","answer":2,"options":["실업률 그대로, 고용률↑","둘 다 그대로","실업률↓, 고용률 그대로","실업률↑, 고용률↓"],"explanation":"실업자가 경제활동인구에서 빠져 실업률은 내려가요. 하지만 취업자와 생산가능인구는 그대로라 고용률은 변하지 않아요.","lessonCheck":true},{"q":"경제활동인구 200명 중 취업자가 190명, 실업자가 10명이에요. 실업률은?","type":"quiz","answer":0,"options":["5%","95%","10%","약 5.3%"],"explanation":"실업률은 실업자 ÷ 경제활동인구 × 100이에요. 10 ÷ 200 × 100 = 5%예요."}]}},{"id":806,"word":"최고가격제","before_data":{"visuals":[{"body":"정부가 가격이 일정 수준 위로 못 오르게 상한을 정하는 제도예요. 임대료 상한제가 대표적인 예예요.\n상한이 시장가격보다 낮아야 효과가 있어요. 시장가격보다 높게 정하면 원래 가격 그대로라 아무 변화가 없어요.","type":"text","title":"최고가격제 쉽게 설명"},{"rows":[["정하는 것","가격 상한","가격 하한"],["효과가 있는 조건","상한 < 시장가격","하한 > 시장가격"],["생기는 것","초과수요(물건 부족)","초과공급(물건·일손 남음)"],["반드시 감소","생산자잉여, 사회후생","소비자잉여, 사회후생"],["대표 사례","임대료 상한제","최저임금제"]],"type":"table","title":"최고가격제 vs 최저가격제","columns":["구분","최고가격제","최저가격제"]},{"body":"싼값에 사려는 사람은 많은데 팔려는 양은 줄어 물건이 모자라요.\n싸게 산 사람은 이득이지만 못 사는 사람도 생겨서 소비자잉여는 늘 수도, 줄 수도 있어요.\n줄 서기, 암시장, 품질 저하가 생길 수 있어요.","type":"text","title":"최고가격제가 낳는 일"},{"q":"시장 임대료가 월 80만 원인 지역에 정부가 임대료 상한을 60만 원으로 정했어요. 교과서 모형에서 나타날 결과는?","type":"quiz","answer":0,"options":["방을 구하려는 사람이 빌려주려는 방보다 많아져요","빈방이 남아돌아요","임대료가 80만 원 그대로 유지돼요","사회 전체 후생이 늘어나요"],"explanation":"상한이 시장가격보다 낮아 효과가 있어요. 싼값에 빌리려는 사람은 늘고 빌려주려는 방은 줄어 초과수요가 생겨요.","lessonCheck":true},{"q":"최고가격제에서 반드시 줄어드는 것은?","type":"quiz","answer":0,"options":["생산자잉여","소비자잉여","수요량","초과수요"],"explanation":"파는 쪽은 더 싸게, 더 적게 팔게 되어 생산자잉여가 반드시 줄어요. 소비자잉여는 늘 수도 줄 수도 있어요."}]},"after_data":{"visuals":[{"body":"정부가 가격이 일정 수준 위로 못 오르게 상한을 정하는 제도예요. 임대료 상한제가 대표적인 예예요.\n상한이 시장가격보다 낮아야 효과가 있어요. 시장가격보다 높게 정하면 원래 가격 그대로라 아무 변화가 없어요.","type":"text","title":"최고가격제 쉽게 설명"},{"rows":[["정하는 것","가격 상한","가격 하한"],["효과가 있는 조건","상한 < 시장가격","하한 > 시장가격"],["생기는 것","초과수요(물건 부족)","초과공급(물건·일손 남음)"],["반드시 감소","생산자잉여, 사회후생","소비자잉여, 사회후생"],["대표 사례","임대료 상한제","최저임금제"]],"type":"table","title":"최고가격제 vs 최저가격제","columns":["구분","최고가격제","최저가격제"]},{"body":"싼값에 사려는 사람은 많은데 팔려는 양은 줄어 물건이 모자라요.\n싸게 산 사람은 이득이지만 못 사는 사람도 생겨서 소비자잉여는 늘 수도, 줄 수도 있어요.\n줄 서기, 암시장, 품질 저하가 생길 수 있어요.","type":"text","title":"최고가격제가 낳는 일"},{"q":"시장 임대료가 월 80만 원인 지역에 정부가 임대료 상한을 60만 원으로 정했어요. 교과서 모형에서 나타날 결과는?","type":"quiz","answer":0,"options":["방을 구하려는 사람이 빌려주려는 방보다 많아져요","빈방이 남아돌아요","임대료가 80만 원 그대로 유지돼요","사회 전체 후생이 늘어나요"],"explanation":"상한이 시장가격보다 낮아 효과가 있어요. 싼값에 빌리려는 사람은 늘고 빌려주려는 방은 줄어 초과수요가 생겨요.","lessonCheck":true},{"q":"우하향 수요곡선과 우상향 공급곡선을 가진 경쟁시장에서 균형가격보다 낮은 가격상한을 실제로 지켜 거래량이 줄었어요. 암시장은 없다면 규제 전보다 반드시 줄어드는 것은?","type":"quiz","answer":0,"options":["생산자잉여","소비자잉여","수요량","초과수요"],"explanation":"이 조건에서는 판매가격이 낮아지고 공급·거래량도 줄어 생산자잉여가 감소해요. 소비자잉여는 싼 가격의 이득과 거래 감소의 손실에 따라 늘거나 줄 수 있어요. 상한이 균형가격보다 높아 효력이 없다면 생산자잉여가 줄지 않아요."}]},"guard_data":{"meaning":"정부가 물건 값이 일정 수준 이상 오르지 못하게 막는 제도(가격상한제)","detailed_meaning":"임대료 상한, 생필품 가격 통제처럼 소비자를 보호하려고 가격의 위쪽을 묶는다. 시장가격보다 낮게 묶으면 사려는 사람은 많고 팔려는 사람은 줄어 물건이 모자란다. 줄서기, 암시장, 품질 저하 같은 부작용이 생길 수 있다.","learning_example":"정부가 임대료 상한을 정해 집주인이 그 이상 받지 못하게 해요.","news_example":"정부가 생필품 가격이 일정 수준 이상 오르지 못하게 막는 최고가격제를 시행하자 물량 부족이 나타났다.","visuals":[{"body":"정부가 가격이 일정 수준 위로 못 오르게 상한을 정하는 제도예요. 임대료 상한제가 대표적인 예예요.\n상한이 시장가격보다 낮아야 효과가 있어요. 시장가격보다 높게 정하면 원래 가격 그대로라 아무 변화가 없어요.","type":"text","title":"최고가격제 쉽게 설명"},{"rows":[["정하는 것","가격 상한","가격 하한"],["효과가 있는 조건","상한 < 시장가격","하한 > 시장가격"],["생기는 것","초과수요(물건 부족)","초과공급(물건·일손 남음)"],["반드시 감소","생산자잉여, 사회후생","소비자잉여, 사회후생"],["대표 사례","임대료 상한제","최저임금제"]],"type":"table","title":"최고가격제 vs 최저가격제","columns":["구분","최고가격제","최저가격제"]},{"body":"싼값에 사려는 사람은 많은데 팔려는 양은 줄어 물건이 모자라요.\n싸게 산 사람은 이득이지만 못 사는 사람도 생겨서 소비자잉여는 늘 수도, 줄 수도 있어요.\n줄 서기, 암시장, 품질 저하가 생길 수 있어요.","type":"text","title":"최고가격제가 낳는 일"},{"q":"시장 임대료가 월 80만 원인 지역에 정부가 임대료 상한을 60만 원으로 정했어요. 교과서 모형에서 나타날 결과는?","type":"quiz","answer":0,"options":["방을 구하려는 사람이 빌려주려는 방보다 많아져요","빈방이 남아돌아요","임대료가 80만 원 그대로 유지돼요","사회 전체 후생이 늘어나요"],"explanation":"상한이 시장가격보다 낮아 효과가 있어요. 싼값에 빌리려는 사람은 늘고 빌려주려는 방은 줄어 초과수요가 생겨요.","lessonCheck":true},{"q":"최고가격제에서 반드시 줄어드는 것은?","type":"quiz","answer":0,"options":["생산자잉여","소비자잉여","수요량","초과수요"],"explanation":"파는 쪽은 더 싸게, 더 적게 팔게 되어 생산자잉여가 반드시 줄어요. 소비자잉여는 늘 수도 줄 수도 있어요."}]}},{"id":809,"word":"손익분기점","before_data":{"visuals":[{"body":"총수입과 총비용이 같아 이익도 손실도 없는 본전 판매량이에요.\n빵을 3,000원에 팔고 재료비가 1,000원이면 하나 팔 때 2,000원이 남아요. 이걸로 월 임대료 100만 원을 메우려면 500개를 팔아야 해요.","type":"text","title":"손익분기점 쉽게 설명"},{"rows":[["200개","60만 원","120만 원","-60만 원"],["500개","150만 원","150만 원","0"],["800개","240만 원","180만 원","+60만 원"]],"type":"table","title":"본전까지 팔아야 하는 양","caption":"손익분기점 판매량 = 고정비용 ÷ (가격 - 개당 가변비용)","columns":["판매량","총수입","총비용","이윤"]},{"body":"완전경쟁 기업의 그래프에서는 가격이 평균비용의 가장 낮은 점과 같을 때가 손익분기점이에요.\n가격이 그보다 낮아도 평균가변비용보다 높으면 단기에는 계속 만드는 게 손실이 적어요. 평균가변비용 최저점 아래로 내려가면 생산을 멈추는데, 이 점이 조업중단점이에요.","type":"text","title":"손익분기점과 조업중단점"},{"q":"월 고정비용이 200만 원인 가게가 컵 하나를 5,000원에 팔고, 컵 하나의 재료비는 1,000원이에요. 손익분기점 판매량은?","type":"quiz","answer":0,"options":["500개","400개","2,000개","40개"],"explanation":"하나 팔 때 5,000원 - 1,000원 = 4,000원이 남아요. 200만 원 ÷ 4,000원 = 500개를 팔아야 본전이에요.","lessonCheck":true},{"q":"완전경쟁 기업에서 가격이 평균비용 최저점보다 낮지만 평균가변비용 최저점보다는 높아요. 단기에 어떻게 하는 게 유리할까요?","type":"quiz","answer":0,"options":["손실이 나도 생산을 계속해요","바로 생산을 멈춰요","가격을 시장보다 올려 받아요","생산량을 무한히 늘려요"],"explanation":"가변비용을 건지고 남는 돈으로 고정비 일부를 메울 수 있어요. 문을 닫으면 고정비를 전부 잃으니 계속 생산하는 게 손실이 적어요."}]},"after_data":{"visuals":[{"body":"총수입과 총비용이 같아 이익도 손실도 없는 본전 판매량이에요.\n빵을 3,000원에 팔고 재료비가 1,000원이면 하나 팔 때 2,000원이 남아요. 이걸로 월 임대료 100만 원을 메우려면 500개를 팔아야 해요.","type":"text","title":"손익분기점 쉽게 설명"},{"rows":[["200개","60만 원","120만 원","-60만 원"],["500개","150만 원","150만 원","0"],["800개","240만 원","180만 원","+60만 원"]],"type":"table","title":"본전까지 팔아야 하는 양","caption":"손익분기점 판매량 = 고정비용 ÷ (가격 - 개당 가변비용)","columns":["판매량","총수입","총비용","이윤"]},{"body":"완전경쟁 기업의 그래프에서는 가격이 평균비용의 가장 낮은 점과 같을 때가 손익분기점이에요.\n가격이 그보다 낮아도 평균가변비용보다 높으면 단기에는 계속 만드는 게 손실이 적어요. 평균가변비용 최저점 아래로 내려가면 생산을 멈추는데, 이 점이 조업중단점이에요.","type":"text","title":"손익분기점과 조업중단점"},{"q":"월 고정비용이 200만 원인 가게가 컵 하나를 5,000원에 팔고, 컵 하나당 드는 가변비용은 재료비 1,000원뿐이에요. 손익분기점 판매량은?","type":"quiz","answer":0,"options":["500개","400개","2,000개","40개"],"explanation":"컵당 공헌이익은 판매가격 5,000원에서 가변비용 1,000원을 뺀 4,000원이에요. 고정비 200만 원 ÷ 4,000원 = 500개이며, 매출 250만 원과 총비용 200만 원 + 50만 원이 같아요.","lessonCheck":true},{"q":"완전경쟁 기업에서 가격이 평균비용 최저점보다 낮지만 평균가변비용 최저점보다는 높아요. 단기에 어떻게 하는 게 유리할까요?","type":"quiz","answer":0,"options":["손실이 나도 생산을 계속해요","바로 생산을 멈춰요","가격을 시장보다 올려 받아요","생산량을 무한히 늘려요"],"explanation":"가변비용을 건지고 남는 돈으로 고정비 일부를 메울 수 있어요. 문을 닫으면 고정비를 전부 잃으니 계속 생산하는 게 손실이 적어요."}]},"guard_data":{"meaning":"매출과 비용이 같아져 이익도 손해도 없는 지점","detailed_meaning":"가게가 한 달 고정비 300만 원이 들고, 커피 한 잔에 재료비를 빼고 3,000원이 남는다면 1,000잔을 팔아야 본전이다. 이 1,000잔이 손익분기점이다. 이보다 더 팔면 이익, 덜 팔면 손해다.","learning_example":"학습용 가정: 제품을 판 매출과 생산·운영 비용이 모두 1천만 원이면 손익분기점이에요.","news_example":"매출이 비용을 겨우 맞추는 손익분기점을 넘어서면서 신규 사업이 이익을 내기 시작했다.","visuals":[{"body":"총수입과 총비용이 같아 이익도 손실도 없는 본전 판매량이에요.\n빵을 3,000원에 팔고 재료비가 1,000원이면 하나 팔 때 2,000원이 남아요. 이걸로 월 임대료 100만 원을 메우려면 500개를 팔아야 해요.","type":"text","title":"손익분기점 쉽게 설명"},{"rows":[["200개","60만 원","120만 원","-60만 원"],["500개","150만 원","150만 원","0"],["800개","240만 원","180만 원","+60만 원"]],"type":"table","title":"본전까지 팔아야 하는 양","caption":"손익분기점 판매량 = 고정비용 ÷ (가격 - 개당 가변비용)","columns":["판매량","총수입","총비용","이윤"]},{"body":"완전경쟁 기업의 그래프에서는 가격이 평균비용의 가장 낮은 점과 같을 때가 손익분기점이에요.\n가격이 그보다 낮아도 평균가변비용보다 높으면 단기에는 계속 만드는 게 손실이 적어요. 평균가변비용 최저점 아래로 내려가면 생산을 멈추는데, 이 점이 조업중단점이에요.","type":"text","title":"손익분기점과 조업중단점"},{"q":"월 고정비용이 200만 원인 가게가 컵 하나를 5,000원에 팔고, 컵 하나의 재료비는 1,000원이에요. 손익분기점 판매량은?","type":"quiz","answer":0,"options":["500개","400개","2,000개","40개"],"explanation":"하나 팔 때 5,000원 - 1,000원 = 4,000원이 남아요. 200만 원 ÷ 4,000원 = 500개를 팔아야 본전이에요.","lessonCheck":true},{"q":"완전경쟁 기업에서 가격이 평균비용 최저점보다 낮지만 평균가변비용 최저점보다는 높아요. 단기에 어떻게 하는 게 유리할까요?","type":"quiz","answer":0,"options":["손실이 나도 생산을 계속해요","바로 생산을 멈춰요","가격을 시장보다 올려 받아요","생산량을 무한히 늘려요"],"explanation":"가변비용을 건지고 남는 돈으로 고정비 일부를 메울 수 있어요. 문을 닫으면 고정비를 전부 잃으니 계속 생산하는 게 손실이 적어요."}]}},{"id":812,"word":"구성의 오류","before_data":{"meaning":"개인에게 옳은 일이 모두가 하면 전체에는 나쁜 결과가 되는 것","learning_example":"한 사람이 지출을 줄이면 저축이 늘지만 모두 동시에 소비를 줄이면 가게 매출과 경제 전체 소득이 줄 수 있어요."},"after_data":{"meaning":"부분에 성립하는 성질이나 논리가 전체에도 그대로 성립한다고 잘못 추론하는 오류","learning_example":"학습용 가정: 앞사람이 모두 앉아 있을 때 한 명만 일어서면 무대가 잘 보이지만, 모두 일어서도 각자의 시야가 똑같이 좋아지는 것은 아니에요."},"guard_data":{"meaning":"개인에게 옳은 일이 모두가 하면 전체에는 나쁜 결과가 되는 것","detailed_meaning":"공연장에서 한 사람이 일어서면 잘 보이지만, 모두 일어서면 아무도 더 잘 보지 못한다. 경제에서는 불황에 모두가 저축을 늘리면 소비가 줄어 오히려 경기가 더 나빠지는 절약의 역설이 대표적인 예다.","learning_example":"한 사람이 지출을 줄이면 저축이 늘지만 모두 동시에 소비를 줄이면 가게 매출과 경제 전체 소득이 줄 수 있어요.","news_example":"각 개인에게는 옳은 선택이 모두가 따라 하면 전체에 나쁜 결과가 되는 구성의 오류를 경계해야 한다.","visuals":null}},{"id":825,"word":"조세 귀착","before_data":{"learning_example":"가게가 부가가치세를 납부하지만 물건값에 세금이 포함돼 실제로는 소비자가 부담해요.","visuals":[{"body":"세금을 매긴 사람과 실제로 세금을 떠안는 사람은 다를 수 있어요.\n세금을 남에게 넘기는 걸 전가, 넘겨받아 실제로 부담하는 걸 귀착이라고 해요.\n캔디 생산자에게 개당 30원을 매겼는데 값이 10원 올랐다면 소비자가 10원, 생산자가 20원을 부담한 셈이에요.","type":"text","title":"조세 귀착 쉽게 설명"},{"rows":[["소비자 상황","다른 선택지가 많음","다른 선택지가 적음"],["값을 올리면","바로 다른 곳으로 감","그대로 살 수밖에 없음"],["세금 부담","생산자가 더 냄","소비자가 더 냄"]],"type":"table","title":"실제 부담은 탄력성이 정해요","caption":"덜 아쉬운 쪽, 즉 탄력성이 큰 쪽이 세금을 덜 내요.","columns":["구분","수요가 탄력적","수요가 비탄력적"]},{"body":"공급자에게 매기면 공급곡선이 세금만큼 위로, 소비자에게 매기면 수요곡선이 세금만큼 아래로 움직여요.\n가격표만 달라질 뿐, 소비자가 실제로 내는 돈과 생산자가 실제로 받는 돈은 똑같아요.","type":"text","title":"누구에게 매겨도 결과는 같아요"},{"q":"옮겨 갈 비슷한 방이 거의 없고 방을 구하려는 사람이 줄을 서 있는 동네예요. 정부가 집주인에게 임대 소득세를 새로 매기면 세금 부담은?","type":"quiz","answer":0,"options":["세입자가 더 많이 떠안을 가능성이 커요","집주인에게 매겼으니 집주인이 전부 내요","정부가 대신 부담해요","누구도 부담하지 않아요"],"explanation":"세입자 수요가 비탄력적이라 집주인이 월세를 올려도 세입자가 떠나기 어려워요. 탄력성이 작은 쪽이 세금을 더 많이 떠안아요.","lessonCheck":true},{"q":"공급이 완전 비탄력적(수직)인 상품에 세금을 매기면 세금은 누가 부담할까요?","type":"quiz","answer":0,"options":["생산자가 전부","소비자가 전부","반반씩","정부"],"explanation":"공급량이 전혀 변하지 않으니 가격을 올려 넘길 수 없어요. 그래서 생산자가 세금을 전부 떠안아요."}]},"after_data":{"learning_example":"학습용 가정: 세금 전 가격이 1,000원인 상품에 개당 100원의 세금이 붙고 소비자 가격이 1,060원이 됐어요. 판매자는 세금 납부 후 960원을 받아, 소비자가 60원·판매자가 40원을 부담해요.","visuals":[{"body":"세금을 매긴 사람과 실제로 세금을 떠안는 사람은 다를 수 있어요.\n세금을 남에게 넘기는 걸 전가, 넘겨받아 실제로 부담하는 걸 귀착이라고 해요.\n캔디 생산자에게 개당 30원을 매겼는데 값이 10원 올랐다면 소비자가 10원, 생산자가 20원을 부담한 셈이에요.","type":"text","title":"조세 귀착 쉽게 설명"},{"rows":[["소비자 상황","다른 선택지가 많음","다른 선택지가 적음"],["값을 올리면","바로 다른 곳으로 감","그대로 살 수밖에 없음"],["세금 부담","생산자가 더 냄","소비자가 더 냄"]],"type":"table","title":"실제 부담은 탄력성이 정해요","caption":"덜 아쉬운 쪽, 즉 탄력성이 큰 쪽이 세금을 덜 내요.","columns":["구분","수요가 탄력적","수요가 비탄력적"]},{"body":"공급자에게 매기면 공급곡선이 세금만큼 위로, 소비자에게 매기면 수요곡선이 세금만큼 아래로 움직여요.\n가격표만 달라질 뿐, 소비자가 실제로 내는 돈과 생산자가 실제로 받는 돈은 똑같아요.","type":"text","title":"누구에게 매겨도 결과는 같아요"},{"q":"경쟁시장에서 상품 한 개마다 같은 금액의 세금을 판매자에게 부과해요. 수요의 가격탄력성 절댓값이 0.2, 공급의 가격탄력성이 1.0이라면 어느 쪽의 세금 부담이 더 클까요?","type":"quiz","answer":0,"options":["소비자 부담이 더 커요","판매자 부담이 더 커요","양쪽 부담이 같아요","판매자가 납부하므로 소비자 부담은 없어요"],"explanation":"수요가 공급보다 덜 탄력적이어서 소비자가 구매량을 조절해 세금을 피하기 더 어려워요. 따라서 소비자의 가격상승 부담이 판매자의 순수취가격 하락 부담보다 커요. 세금을 납부하는 주체만으로 실제 부담이 정해지지는 않아요.","lessonCheck":true},{"q":"수요곡선은 우하향하고 공급량은 가격과 관계없이 일정한 경쟁시장에 개당 같은 금액의 세금을 부과해요. 세금의 실제 부담은 누구에게 돌아갈까요?","type":"quiz","answer":0,"options":["생산자가 전부","소비자가 전부","반반씩","정부"],"explanation":"공급량이 고정되어 소비자가 지불할 균형가격은 변하지 않아요. 생산자의 세후 수취액만 개당 세금만큼 줄어 생산자가 전액 부담해요. 이는 완전 비탄력적 공급과 우하향 수요를 전제한 결과예요."}]},"guard_data":{"meaning":"세금을 법적으로 누가 내든, 실제 부담이 누구에게 돌아가는지를 따지는 개념","detailed_meaning":"담배세를 판매자가 내도 담뱃값이 오르면 부담 일부는 소비자에게 넘어간다. 가격 변화에 덜 민감한(탄력성이 작은) 쪽이 세금을 더 많이 떠안는다.","learning_example":"가게가 부가가치세를 납부하지만 물건값에 세금이 포함돼 실제로는 소비자가 부담해요.","news_example":"조세 귀착을 따져 보면 세금을 법적으로 판매자가 내더라도 실제 부담은 소비자에게 상당 부분 넘어간다.","visuals":[{"body":"세금을 매긴 사람과 실제로 세금을 떠안는 사람은 다를 수 있어요.\n세금을 남에게 넘기는 걸 전가, 넘겨받아 실제로 부담하는 걸 귀착이라고 해요.\n캔디 생산자에게 개당 30원을 매겼는데 값이 10원 올랐다면 소비자가 10원, 생산자가 20원을 부담한 셈이에요.","type":"text","title":"조세 귀착 쉽게 설명"},{"rows":[["소비자 상황","다른 선택지가 많음","다른 선택지가 적음"],["값을 올리면","바로 다른 곳으로 감","그대로 살 수밖에 없음"],["세금 부담","생산자가 더 냄","소비자가 더 냄"]],"type":"table","title":"실제 부담은 탄력성이 정해요","caption":"덜 아쉬운 쪽, 즉 탄력성이 큰 쪽이 세금을 덜 내요.","columns":["구분","수요가 탄력적","수요가 비탄력적"]},{"body":"공급자에게 매기면 공급곡선이 세금만큼 위로, 소비자에게 매기면 수요곡선이 세금만큼 아래로 움직여요.\n가격표만 달라질 뿐, 소비자가 실제로 내는 돈과 생산자가 실제로 받는 돈은 똑같아요.","type":"text","title":"누구에게 매겨도 결과는 같아요"},{"q":"옮겨 갈 비슷한 방이 거의 없고 방을 구하려는 사람이 줄을 서 있는 동네예요. 정부가 집주인에게 임대 소득세를 새로 매기면 세금 부담은?","type":"quiz","answer":0,"options":["세입자가 더 많이 떠안을 가능성이 커요","집주인에게 매겼으니 집주인이 전부 내요","정부가 대신 부담해요","누구도 부담하지 않아요"],"explanation":"세입자 수요가 비탄력적이라 집주인이 월세를 올려도 세입자가 떠나기 어려워요. 탄력성이 작은 쪽이 세금을 더 많이 떠안아요.","lessonCheck":true},{"q":"공급이 완전 비탄력적(수직)인 상품에 세금을 매기면 세금은 누가 부담할까요?","type":"quiz","answer":0,"options":["생산자가 전부","소비자가 전부","반반씩","정부"],"explanation":"공급량이 전혀 변하지 않으니 가격을 올려 넘길 수 없어요. 그래서 생산자가 세금을 전부 떠안아요."}]}},{"id":826,"word":"합리적 기대 이론","before_data":{"detailed_meaning":"정부가 돈을 풀어 경기를 띄우려 해도, 사람들이 곧 물가가 오를 걸 미리 알고 임금과 가격을 올리면 효과가 사라진다고 본다. 예상된 정책은 효과가 작고, 예상 밖의 정책만 일시적으로 효과가 있다는 결론으로 이어진다.","visuals":[{"body":"사람들은 쓸 수 있는 정보를 모두 써서 미래를 예측해요.\n정부가 돈을 풀 걸 미리 알면 물가가 오를 걸 예상해 임금과 가격을 바로 올려요. 그래서 예상된 정책은 단기에도 생산을 늘리지 못해요.\n루카스·사전트 같은 새고전학파의 주장이고, 가격과 임금이 빠르게 조정된다는 가정이 깔려 있어요.","type":"text","title":"예상된 정책은 효과가 없다"},{"rows":[["미리 예상된 정책","임금·가격에 바로 반영돼 단기에도 효과가 없어요"],["예상하지 못한 정책","잠깐 효과가 있지만 곧 사라져요"]],"type":"table","title":"정책 무력성 명제","columns":["정책","효과"]},{"q":"합리적 기대 이론에 따르면, 중앙은행이 미리 발표한 대로 통화량을 늘릴 때 단기 생산량은?","type":"quiz","answer":2,"options":["크게 줄어든다","물가는 그대로이고 생산만 늘어난다","거의 늘지 않고 물가만 오른다","크게 늘어난다"],"explanation":"사람들이 통화량 증가를 미리 알고 임금과 가격을 올리기 때문에 실질적인 변화가 없어요. 결국 물가만 오르고 생산은 거의 늘지 않아요.","lessonCheck":true},{"q":"합리적 기대 이론에서 일시적으로라도 생산에 영향을 줄 수 있는 정책은?","type":"quiz","answer":3,"options":["매년 같은 규칙대로 하는 정책","이미 임금 계약에 반영된 정책","미리 예고된 정책","사람들이 예상하지 못한 정책"],"explanation":"예상하지 못한 정책은 사람들이 미처 임금과 가격에 반영하지 못해 잠깐 효과를 내요. 하지만 곧 기대가 조정돼 효과가 사라져요."}]},"after_data":{"detailed_meaning":"정부가 돈을 풀어 경기를 띄우려 해도, 사람들이 물가 상승을 미리 예상하고 임금과 가격에 반영하면 효과가 줄 수 있다. 가격·임금의 신축성 등을 가정한 새고전학파 모형에서는 예상된 통화정책은 실질 생산을 늘리지 못하고 예상 밖의 정책만 일시적으로 영향을 줄 수 있다고 본다. 이는 합리적 기대만으로 항상 성립하는 결론은 아니며, 가격·임금이 경직적인 모형에서는 정책 효과가 달라질 수 있다.","visuals":[{"body":"사람들은 쓸 수 있는 정보를 모두 써서 미래를 예측해요.\n정부가 돈을 풀 걸 미리 알면 물가가 오를 걸 예상해 임금과 가격을 바로 올려요. 그래서 예상된 정책은 단기에도 생산을 늘리지 못해요.\n루카스·사전트 같은 새고전학파의 주장이고, 가격과 임금이 빠르게 조정된다는 가정이 깔려 있어요.","type":"text","title":"예상된 정책은 효과가 없다"},{"rows":[["미리 예상된 정책","임금·가격에 바로 반영돼 단기에도 효과가 없어요"],["예상하지 못한 정책","잠깐 효과가 있지만 곧 사라져요"]],"type":"table","title":"정책 무력성 명제","columns":["정책","효과"]},{"q":"합리적 기대와 가격·임금의 신축성을 가정한 새고전학파 모형에서, 충분히 예상되어 임금·가격에 반영된 통화량 확대는 실질 생산량에 어떤 영향을 줄까요?","type":"quiz","answer":2,"options":["지속적으로 감소시켜요","물가는 그대로이고 생산량만 늘려요","지속적으로 늘리지 못해요","지속적으로 증가시켜요"],"explanation":"이 모형에서는 예상된 통화 확대가 임금과 가격에 반영되어 실질 생산량을 지속적으로 늘리지 못해요. 이는 가격·임금이 신축적이라는 추가 가정에 따른 결론으로, 합리적 기대를 가정한 모든 모형의 결론은 아니에요.","lessonCheck":true},{"q":"가격·임금이 신축적이고 합리적 기대를 하는 새고전학파의 정책무력성 모형에서, 일시적 생산 변동을 일으킬 수 있는 통화정책은?","type":"quiz","answer":3,"options":["이미 예상에 반영된 정기 통화 확대","이미 임금과 가격에 반영된 통화 확대","사전에 완전히 예상한 통화 확대","사람들이 예상하지 못한 통화 확대"],"explanation":"이 모형에서는 예상 밖 통화 확대가 실제 물가와 예상 물가의 차이를 만들어 생산에 일시적으로 영향을 줄 수 있어요. 기대가 조정되면 효과는 사라져요. 가격·임금 경직성이 있는 다른 모형에서는 예상된 정책도 실물효과를 낼 수 있어요."}]},"guard_data":{"meaning":"사람들은 쓸 수 있는 정보를 모두 활용해 미래를 예측하고 행동한다는 이론","detailed_meaning":"정부가 돈을 풀어 경기를 띄우려 해도, 사람들이 곧 물가가 오를 걸 미리 알고 임금과 가격을 올리면 효과가 사라진다고 본다. 예상된 정책은 효과가 작고, 예상 밖의 정책만 일시적으로 효과가 있다는 결론으로 이어진다.","learning_example":"투자자들이 공개된 물가 정보와 정책 발표를 함께 보고 앞으로의 금리를 예상해요.","news_example":"합리적 기대 이론에 따르면 사람들이 정책 효과를 미리 예상하고 행동해 예고된 정책은 효과가 약해진다.","visuals":[{"body":"사람들은 쓸 수 있는 정보를 모두 써서 미래를 예측해요.\n정부가 돈을 풀 걸 미리 알면 물가가 오를 걸 예상해 임금과 가격을 바로 올려요. 그래서 예상된 정책은 단기에도 생산을 늘리지 못해요.\n루카스·사전트 같은 새고전학파의 주장이고, 가격과 임금이 빠르게 조정된다는 가정이 깔려 있어요.","type":"text","title":"예상된 정책은 효과가 없다"},{"rows":[["미리 예상된 정책","임금·가격에 바로 반영돼 단기에도 효과가 없어요"],["예상하지 못한 정책","잠깐 효과가 있지만 곧 사라져요"]],"type":"table","title":"정책 무력성 명제","columns":["정책","효과"]},{"q":"합리적 기대 이론에 따르면, 중앙은행이 미리 발표한 대로 통화량을 늘릴 때 단기 생산량은?","type":"quiz","answer":2,"options":["크게 줄어든다","물가는 그대로이고 생산만 늘어난다","거의 늘지 않고 물가만 오른다","크게 늘어난다"],"explanation":"사람들이 통화량 증가를 미리 알고 임금과 가격을 올리기 때문에 실질적인 변화가 없어요. 결국 물가만 오르고 생산은 거의 늘지 않아요.","lessonCheck":true},{"q":"합리적 기대 이론에서 일시적으로라도 생산에 영향을 줄 수 있는 정책은?","type":"quiz","answer":3,"options":["매년 같은 규칙대로 하는 정책","이미 임금 계약에 반영된 정책","미리 예고된 정책","사람들이 예상하지 못한 정책"],"explanation":"예상하지 못한 정책은 사람들이 미처 임금과 가격에 반영하지 못해 잠깐 효과를 내요. 하지만 곧 기대가 조정돼 효과가 사라져요."}]}},{"id":828,"word":"그레샴의 법칙","before_data":{"meaning":"가치가 낮은 돈이 가치가 높은 돈을 시장에서 몰아낸다는 법칙(\"악화가 양화를 구축한다\")","learning_example":"액면이 같은 두 동전 중 금속 가치가 높은 동전은 모아 두고 가치가 낮은 동전만 결제에 써요."},"after_data":{"meaning":"소재 가치가 다른 화폐가 법적으로 같은 액면가로 통용될 때 소재 가치가 높은 화폐는 보관되고 낮은 화폐가 유통되는 현상","learning_example":"학습용 가정: 법적으로 모두 1,000원으로 쓰는 두 동전의 금속 가치가 각각 1,200원과 500원이에요. 사람들은 금속 가치 1,200원인 동전은 보관하고 500원인 동전으로 결제하려 해요."},"guard_data":{"meaning":"가치가 낮은 돈이 가치가 높은 돈을 시장에서 몰아낸다는 법칙(\"악화가 양화를 구축한다\")","detailed_meaning":"금 함량이 다른 두 동전이 같은 값으로 쓰이면, 사람들은 금이 많은 동전은 모아 두고 금이 적은 동전만 쓴다. 결국 시장에는 나쁜 돈만 돈다.","learning_example":"액면이 같은 두 동전 중 금속 가치가 높은 동전은 모아 두고 가치가 낮은 동전만 결제에 써요.","news_example":"가치가 낮은 돈이 좋은 돈을 시장에서 몰아낸다는 그레샴의 법칙이 화폐 역사 곳곳에서 확인된다.","visuals":null}},{"id":851,"word":"완전고용","before_data":{"meaning":"일할 뜻과 능력이 있는 사람은 사실상 모두 일자리를 가진 상태","learning_example":"일자리를 옮기는 동안 잠시 쉬는 사람은 있어도 일하려는 사람 대부분이 일자리를 찾은 상태예요.","visuals":[{"q":"경제가 완전고용 상태여도 구직 중인 사람이 있을 수 있나요?","type":"quiz","answer":2,"options":["아니요, 실업자가 반드시 0명이에요","아니요, 모든 성인이 반드시 일해요","네, 일자리 이동 과정의 실업은 남을 수 있어요"],"explanation":"완전고용은 실업률 0%나 전체 인구 취업을 의미하지 않아요.","lessonCheck":true}]},"after_data":{"meaning":"경기 침체에 따른 실업은 없고 일자리 이동이나 산업구조 변화에 따른 실업만 남아 있는 상태","learning_example":"학습용 가정: 경제활동인구 1,000명 중 취업자가 970명, 이직 중인 실업자가 20명, 기술 불일치로 구직 중인 사람이 10명이고 경기적 실업은 없어요. 실업률이 3%여도 완전고용으로 설명할 수 있어요.","visuals":[{"q":"경기적 실업은 없지만 이직 중인 사람과 새 산업에 필요한 기술을 배우며 구직 중인 사람이 있어요. 완전고용에 관한 설명으로 맞는 것은?","type":"quiz","answer":2,"options":["실업자가 있으므로 반드시 완전고용이 아니에요","구직 중인 사람은 모두 비경제활동인구예요","마찰적·구조적 실업이 남아도 완전고용일 수 있어요"],"explanation":"완전고용은 경기 침체로 인한 실업이 없는 상태를 뜻해요. 이직 과정의 마찰적 실업과 기술 불일치 등의 구조적 실업은 남을 수 있으므로 실업률 0%와 달라요.","lessonCheck":true}]},"guard_data":{"meaning":"일할 뜻과 능력이 있는 사람은 사실상 모두 일자리를 가진 상태","detailed_meaning":"실업률이 0%인 것은 아니다. 이직 중인 사람처럼 늘 있는 실업(자연실업률)만 남은 상태를 완전고용으로 본다.","learning_example":"일자리를 옮기는 동안 잠시 쉬는 사람은 있어도 일하려는 사람 대부분이 일자리를 찾은 상태예요.","news_example":"일할 뜻이 있는 사람 대부분이 일자리를 가진 완전고용에 가까워지면서 임금 상승 압력이 커졌다.","visuals":[{"q":"경제가 완전고용 상태여도 구직 중인 사람이 있을 수 있나요?","type":"quiz","answer":2,"options":["아니요, 실업자가 반드시 0명이에요","아니요, 모든 성인이 반드시 일해요","네, 일자리 이동 과정의 실업은 남을 수 있어요"],"explanation":"완전고용은 실업률 0%나 전체 인구 취업을 의미하지 않아요.","lessonCheck":true}]}},{"id":869,"word":"우선주","before_data":{"meaning":"의결권이 없는 대신 배당을 보통주보다 먼저, 더 많이 받는 주식"},"after_data":{"meaning":"배당이나 잔여재산 분배에서 보통주보다 우선하는 권리를 가지며 구체적 권리는 정관에 따라 달라지는 주식"},"guard_data":{"meaning":"의결권이 없는 대신 배당을 보통주보다 먼저, 더 많이 받는 주식","detailed_meaning":"경영에는 참여하지 않고 배당 수익을 원하는 투자자에게 맞다. 보통 보통주보다 싸게 거래된다.","learning_example":"일부 우선주는 의결권이 제한되는 대신 배당에서 보통주보다 앞선 권리를 줘요.","news_example":"의결권이 없는 대신 배당을 더 받는 우선주가 배당 시즌을 앞두고 보통주보다 강세를 보였다.","visuals":null}},{"id":871,"word":"청산가치","before_data":{"meaning":"회사가 문을 닫고 자산을 모두 팔아 빚을 갚은 뒤 남는 가치","learning_example":"회사가 문을 닫고 건물과 기계를 판 돈에서 빚을 모두 갚은 뒤 남는 금액을 계산해요.","visuals":[{"q":"회사를 정리해 자산을 각각 팔 경우 회수할 수 있는 금액을 추정해요. 평가하는 것은?","type":"quiz","answer":2,"options":["계속 영업할 때의 가치만","주식의 액면가 합계","청산가치"],"explanation":"사업을 계속하는 가치와 달리 자산을 처분하는 상황을 기준으로 해요.","lessonCheck":true}]},"after_data":{"meaning":"회사를 정리하면서 보유 자산을 따로 처분할 때 회수할 수 있다고 평가한 가치","learning_example":"학습용 가정: 회사를 청산할 때 건물을 70억 원, 기계를 30억 원에 팔 수 있고 처분비용은 없어요. 자산의 청산가치는 100억 원이고, 이 돈으로 빚 80억 원을 갚은 뒤 주주에게 남는 20억 원과는 구분해요.","visuals":[{"q":"회사를 청산할 때 자산을 각각 팔아 100억 원을 회수할 수 있고, 처분비용은 없으며 부채는 80억 원이에요. 자산의 청산가치와 채무 상환 후 주주에게 남는 몫은?","type":"quiz","answer":2,"options":["청산가치 20억 원, 주주 몫 100억 원","청산가치 80억 원, 주주 몫 20억 원","청산가치 100억 원, 주주 몫 20억 원"],"explanation":"자산을 처분해 회수할 금액 100억 원이 청산가치예요. 그중 부채 80억 원을 갚으면 주주에게 남는 금액은 100−80=20억 원이에요. 두 가치를 구분해야 해요.","lessonCheck":true}]},"guard_data":{"meaning":"회사가 문을 닫고 자산을 모두 팔아 빚을 갚은 뒤 남는 가치","detailed_meaning":"회사를 계속 운영할 때의 가치(존속가치)보다 청산가치가 크면 문을 닫는 게 낫다고 본다. 기업회생 여부를 판단할 때 쓴다.","learning_example":"회사가 문을 닫고 건물과 기계를 판 돈에서 빚을 모두 갚은 뒤 남는 금액을 계산해요.","news_example":"주가가 회사를 정리하고 빚을 갚은 뒤 남는 청산가치에도 못 미칠 만큼 저평가됐다는 분석이 나왔다.","visuals":[{"q":"회사를 정리해 자산을 각각 팔 경우 회수할 수 있는 금액을 추정해요. 평가하는 것은?","type":"quiz","answer":2,"options":["계속 영업할 때의 가치만","주식의 액면가 합계","청산가치"],"explanation":"사업을 계속하는 가치와 달리 자산을 처분하는 상황을 기준으로 해요.","lessonCheck":true}]}},{"id":903,"word":"내부자거래","before_data":{"meaning":"회사 내부 사람이 공개되지 않은 정보를 이용해 주식을 사고파는 불법 행위"},"after_data":{"meaning":"회사 내부자나 관련 정보를 받은 사람이 공개되지 않은 중요정보를 이용해 주식 등을 거래하는 불공정 행위"},"guard_data":{"meaning":"회사 내부 사람이 공개되지 않은 정보를 이용해 주식을 사고파는 불법 행위","detailed_meaning":"실적 발표나 인수합병 소식을 미리 알고 거래하면 다른 투자자에게 불공정하다. 자본시장법으로 처벌한다.","learning_example":"임원이 아직 공개되지 않은 실적 악화 정보를 알고 자기 회사 주식을 먼저 팔아요.","news_example":"공개되지 않은 실적 정보를 미리 알고 주식을 사고판 임원이 내부자거래 혐의로 수사를 받았다.","visuals":null}},{"id":931,"word":"대체불가토큰(NFT)","before_data":{"meaning":"블록체인으로 디지털 파일에 고유한 소유권을 기록한 토큰","detailed_meaning":"그림, 영상 같은 디지털 작품의 원본과 소유자를 증명한다. 한때 투기 열풍이 불었다가 급격히 식었다."},"after_data":{"meaning":"블록체인에 고유한 식별 정보와 보유·거래 기록을 남기는 서로 대체할 수 없는 토큰","detailed_meaning":"그림, 영상 같은 디지털 작품을 토큰과 연결해 보유·거래 기록을 확인하는 데 쓰이지만, 토큰만으로 작품의 진품 여부나 저작권 소유를 보장하지는 않는다. 저작권의 이전이나 이용허락은 별도 계약 내용을 확인해야 한다. 한때 투기 열풍이 불었다가 급격히 식었다."},"guard_data":{"meaning":"블록체인으로 디지털 파일에 고유한 소유권을 기록한 토큰","detailed_meaning":"그림, 영상 같은 디지털 작품의 원본과 소유자를 증명한다. 한때 투기 열풍이 불었다가 급격히 식었다.","learning_example":"작품의 식별 정보와 소유 기록을 블록체인 토큰에 연결해 거래해요.","news_example":"디지털 그림에 블록체인으로 고유한 소유권을 기록한 대체불가토큰(NFT) 거래가 크게 줄었다.","visuals":null}},{"id":936,"word":"기초연금","before_data":{"meaning":"소득 하위 70% 노인에게 매달 주는 연금"},"after_data":{"meaning":"만 65세 이상 중 소득과 재산을 반영한 소득인정액 등 법정 수급요건을 충족한 사람에게 세금으로 지급하는 연금"},"guard_data":{"meaning":"소득 하위 70% 노인에게 매달 주는 연금","detailed_meaning":"국민연금 가입 여부와 상관없이 세금으로 지급한다. 노인 빈곤을 줄이기 위한 제도다.","learning_example":"소득과 나이 등 수급 조건을 충족한 노인이 매달 기초연금을 받아 생활비에 보태요.","news_example":"소득 하위 노인에게 매달 지급하는 기초연금 수급자가 고령화로 계속 늘어나 재정 부담이 커지고 있다.","visuals":null}},{"id":952,"word":"취업유발계수","before_data":{"meaning":"어떤 산업에서 10억 원어치를 생산할 때 직간접으로 생기는 일자리 수","learning_example":"학습용 가정: 한 산업에서 10억 원어치를 생산할 때 직접 고용과 협력업체 일자리를 합쳐 8명이 생기면 취업유발계수는 8명이에요."},"after_data":{"meaning":"어떤 상품에 최종수요 10억 원이 생길 때 전 산업에서 직간접으로 유발되는 취업자 수","learning_example":"학습용 가정: 한 산업 상품에 최종수요 10억 원이 생겨 해당 산업에서 5명, 연관 산업에서 3명의 취업이 유발된다고 추정해요. 취업유발계수는 5+3=8명/10억 원이에요."},"guard_data":{"meaning":"어떤 산업에서 10억 원어치를 생산할 때 직간접으로 생기는 일자리 수","detailed_meaning":"서비스업은 높고 반도체 같은 장치산업은 낮다. 일자리 정책에서 산업별 효과를 비교할 때 쓴다.","learning_example":"학습용 가정: 한 산업에서 10억 원어치를 생산할 때 직접 고용과 협력업체 일자리를 합쳐 8명이 생기면 취업유발계수는 8명이에요.","news_example":"생산이 늘 때 일자리가 얼마나 생기는지 보여주는 취업유발계수가 서비스업에서 제조업보다 높게 나타났다.","visuals":null}},{"id":1001,"word":"암묵적 비용","before_data":{"learning_example":"학습용 가정: 암묵적 비용을 이해할 때는 \"어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용\"을 먼저 떠올리면 쉬워요. 암묵적 비용은 실제로 돈이 나가지는 않지만 그 일을 하느라 포기한 연봉, 임대 수입, 예금 이자 같은 것이다.","visuals":[{"body":"회사를 그만두고 가게를 열면 월급이 끊겨요.\n통장에서 돈이 나간 건 아니지만 포기한 월급도 비용이에요.\n이렇게 눈에 안 보이는 비용이 암묵적 비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["뜻","실제로 지출한 돈","그 일을 하느라 포기한 것"],["예시","수강료, 재료비, 운영비","받던 연봉, 임대 수입, 예금 이자"],["합치면","경제학적 비용(기회비용)","경제학적 비용(기회비용)"]],"type":"table","title":"명시적 비용 vs 암묵적 비용","columns":["구분","명시적 비용","암묵적 비용"]},{"rows":[["포기한 연봉","2,000만원","암묵적"],["포기한 임대 수입","1,000만원","암묵적"],["운영비","1,500만원","명시적"],["기회비용 합계","4,500만원",""]],"type":"table","title":"제과점 창업 예시","caption":"예상 수입이 4,000만원이면 비용 합계보다 적어 여는 게 손해예요.","columns":["항목","금액","구분"]},{"body":"예금은 원금이 아니라 포기한 이자만 비용으로 넣어요.\n포기한 수입을 빼먹으면 손해 보는 선택도 이득처럼 보여요.","type":"text","title":"왜 중요할까?"},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용","type":"quiz","answer":0,"options":["암묵적 비용","FOMO현상","효용","죄수의 딜레마"],"explanation":"암묵적 비용은/는 어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"learning_example":"학습용 가정: 회사를 계속 다니면 월 300만 원을 받을 사람이 월급을 포기하고 자기 가게에서 일해요. 다른 포기한 수입이 없다면 월 300만 원은 현금 지출이 없는 암묵적 비용이에요.","visuals":[{"body":"회사를 그만두고 가게를 열면 월급이 끊겨요.\n통장에서 돈이 나간 건 아니지만 포기한 월급도 비용이에요.\n이렇게 눈에 안 보이는 비용이 암묵적 비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["뜻","실제로 지출한 돈","그 일을 하느라 포기한 것"],["예시","수강료, 재료비, 운영비","받던 연봉, 임대 수입, 예금 이자"],["합치면","경제학적 비용(기회비용)","경제학적 비용(기회비용)"]],"type":"table","title":"명시적 비용 vs 암묵적 비용","columns":["구분","명시적 비용","암묵적 비용"]},{"rows":[["포기한 연봉","2,000만원","암묵적"],["포기한 임대 수입","1,000만원","암묵적"],["운영비","1,500만원","명시적"],["기회비용 합계","4,500만원",""]],"type":"table","title":"제과점 창업 예시","caption":"예상 수입이 4,000만원이면 비용 합계보다 적어 여는 게 손해예요.","columns":["항목","금액","구분"]},{"body":"예금은 원금이 아니라 포기한 이자만 비용으로 넣어요.\n포기한 수입을 빼먹으면 손해 보는 선택도 이득처럼 보여요.","type":"text","title":"왜 중요할까?"},{"q":"자기 가게에서 일하느라 다른 회사에서 받을 수 있었던 월급 300만 원을 포기했어요. 이 300만 원은 어떤 비용일까요?","type":"quiz","answer":0,"options":["암묵적 비용","직원에게 실제 지급한 임금","재료 구입비","건물주에게 낸 임대료"],"explanation":"가게를 선택하느라 포기한 자기 월급은 현금이 나가지 않아도 기회비용인 암묵적 비용이에요. 직원 임금·재료비·임대료처럼 실제 지급한 비용과 구분해요.","lessonCheck":true}]},"guard_data":{"meaning":"어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용","detailed_meaning":"암묵적 비용은 실제로 돈이 나가지는 않지만 그 일을 하느라 포기한 연봉, 임대 수입, 예금 이자 같은 것이다. 명시적 비용과 더하면 경제학적 비용, 곧 기회비용이 된다. 창업이나 진학처럼 큰 선택을 따질 때 빠뜨리기 쉬운 비용이다.","learning_example":"학습용 가정: 암묵적 비용을 이해할 때는 \"어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용\"을 먼저 떠올리면 쉬워요. 암묵적 비용은 실제로 돈이 나가지는 않지만 그 일을 하느라 포기한 연봉, 임대 수입, 예금 이자 같은 것이다.","news_example":"전문가들은 창업을 고민할 때 포기하는 연봉 같은 암묵적 비용까지 따져봐야 한다고 조언한다.","visuals":[{"body":"회사를 그만두고 가게를 열면 월급이 끊겨요.\n통장에서 돈이 나간 건 아니지만 포기한 월급도 비용이에요.\n이렇게 눈에 안 보이는 비용이 암묵적 비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["뜻","실제로 지출한 돈","그 일을 하느라 포기한 것"],["예시","수강료, 재료비, 운영비","받던 연봉, 임대 수입, 예금 이자"],["합치면","경제학적 비용(기회비용)","경제학적 비용(기회비용)"]],"type":"table","title":"명시적 비용 vs 암묵적 비용","columns":["구분","명시적 비용","암묵적 비용"]},{"rows":[["포기한 연봉","2,000만원","암묵적"],["포기한 임대 수입","1,000만원","암묵적"],["운영비","1,500만원","명시적"],["기회비용 합계","4,500만원",""]],"type":"table","title":"제과점 창업 예시","caption":"예상 수입이 4,000만원이면 비용 합계보다 적어 여는 게 손해예요.","columns":["항목","금액","구분"]},{"body":"예금은 원금이 아니라 포기한 이자만 비용으로 넣어요.\n포기한 수입을 빼먹으면 손해 보는 선택도 이득처럼 보여요.","type":"text","title":"왜 중요할까?"},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용","type":"quiz","answer":0,"options":["암묵적 비용","FOMO현상","효용","죄수의 딜레마"],"explanation":"암묵적 비용은/는 어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":1002,"word":"명시적 비용","before_data":{"learning_example":"학습용 가정: 명시적 비용을 이해할 때는 \"임금, 재료비, 임대료처럼 실제로 돈을 내서 장부에 기록되는 비용\"을 먼저 떠올리면 쉬워요. 명시적 비용은 생산이나 선택을 위해 실제로 지출한 돈으로, 회계학적 비용이라고도 한다."},"after_data":{"learning_example":"학습용 가정: 가게가 한 달 동안 재료비 100만 원, 직원 임금 150만 원, 임대료 50만 원을 지급했고 다른 명시적 비용은 없어요. 이달 명시적 비용은 100+150+50=300만 원이에요."},"guard_data":{"meaning":"임금, 재료비, 임대료처럼 실제로 돈을 내서 장부에 기록되는 비용","detailed_meaning":"명시적 비용은 생산이나 선택을 위해 실제로 지출한 돈으로, 회계학적 비용이라고도 한다. 장부에 찍히는 돈만 보기 때문에 포기한 수입은 들어가지 않는다. 여기에 암묵적 비용을 더해야 경제학에서 말하는 기회비용이 된다.","learning_example":"학습용 가정: 명시적 비용을 이해할 때는 \"임금, 재료비, 임대료처럼 실제로 돈을 내서 장부에 기록되는 비용\"을 먼저 떠올리면 쉬워요. 명시적 비용은 생산이나 선택을 위해 실제로 지출한 돈으로, 회계학적 비용이라고도 한다.","news_example":"기업 장부에 기록되는 명시적 비용만으로는 사업의 실제 수익성을 판단하기 어렵다는 지적이 나온다.","visuals":[{"body":"고시 공부에 수강료와 교재값으로 1천만원을 썼다면\n이 1천만원이 명시적 비용이에요.\n영수증이 남는 돈이라고 생각하면 쉬워요.","type":"text","title":"쉽게 설명"},{"rows":[["명시적 비용","1천만원","수강료·교재값"],["암묵적 비용","2천만원","포기한 연봉"],["경제학적 비용","3천만원","둘의 합"]],"type":"table","title":"고시 공부 예시","caption":"1천만원만 들었다고 생각하기 쉽지만 실제로는 3천만원을 내려놓은 선택이에요.","columns":["구분","금액","내용"]}]}},{"id":1004,"word":"경제학적 이익","before_data":{"learning_example":"학습용 가정: 경제학적 이익을 이해할 때는 \"총수입에서 명시적 비용과 암묵적 비용을 모두 뺀 이익\"을 먼저 떠올리면 쉬워요. 경제학적 이익은 총수입에서 기회비용 전체, 곧 명시적 비용과 암묵적 비용을 뺀 값이다.","visuals":[{"body":"번 돈에서 쓴 돈만 빼면 회계학적 이익이에요.\n포기한 월급까지 빼야 경제학적 이익이에요.\n0보다 크면 그 선택이 다른 선택보다 나아요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["총수입 확인","명시적 비용(낸 돈) 빼기","암묵적 비용(포기한 수입) 빼기","0보다 크면 선택"],"title":"경제학적 이익 구하는 순서","caption":"이미 써서 못 돌려받는 매몰비용은 계산에서 빼요."},{"body":"경제학적 이익이 0이라는 건 망했다는 뜻이 아니에요.\n다른 데서 벌 수 있던 만큼은 번 상태라는 뜻이에요.","type":"text","title":"왜 중요할까?"},{"q":"매출 100만 원, 명시적 비용 60만 원, 포기한 다른 일의 소득 30만 원이에요. 경제학적 이익은?","type":"quiz","answer":1,"options":["70만 원","10만 원","40만 원"],"explanation":"명시적 비용뿐 아니라 암묵적 기회비용 30만 원도 차감해요.","lessonCheck":true}]},"after_data":{"learning_example":"학습용 가정: 가게의 월 총수입이 100만 원, 명시적 비용이 60만 원, 다른 일을 포기한 암묵적 비용이 30만 원이고 추가 비용은 없어요. 경제학적 이익은 100−60−30=10만 원이에요.","visuals":[{"body":"번 돈에서 쓴 돈만 빼면 회계학적 이익이에요.\n포기한 월급까지 빼야 경제학적 이익이에요.\n0보다 크면 그 선택이 다른 선택보다 나아요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["총수입 확인","명시적 비용(낸 돈) 빼기","암묵적 비용(포기한 수입) 빼기","0보다 크면 선택"],"title":"경제학적 이익 구하는 순서","caption":"이미 써서 못 돌려받는 매몰비용은 계산에서 빼요."},{"body":"경제학적 이익이 0이라는 건 망했다는 뜻이 아니에요.\n다른 데서 벌 수 있던 만큼은 번 상태라는 뜻이에요.","type":"text","title":"왜 중요할까?"},{"q":"매출 100만 원, 명시적 비용 60만 원, 포기한 다른 일의 소득 30만 원이에요. 경제학적 이익은?","type":"quiz","answer":1,"options":["70만 원","10만 원","40만 원"],"explanation":"경제학적 이익은 총수입에서 명시적 비용과 암묵적 비용을 모두 빼요. 따라서 100−60−30=10만 원이에요. 40만 원은 암묵적 비용을 빼기 전의 회계학적 이익이에요.","lessonCheck":true}]},"guard_data":{"meaning":"총수입에서 명시적 비용과 암묵적 비용을 모두 뺀 이익","detailed_meaning":"경제학적 이익은 총수입에서 기회비용 전체, 곧 명시적 비용과 암묵적 비용을 뺀 값이다. 이 값이 0보다 커야 다른 선택보다 나은 선택이라고 본다. 포기한 수입까지 빼므로 회계학적 이익보다 항상 작거나 같다.","learning_example":"학습용 가정: 경제학적 이익을 이해할 때는 \"총수입에서 명시적 비용과 암묵적 비용을 모두 뺀 이익\"을 먼저 떠올리면 쉬워요. 경제학적 이익은 총수입에서 기회비용 전체, 곧 명시적 비용과 암묵적 비용을 뺀 값이다.","news_example":"회계상 흑자라도 포기한 기회를 반영한 경제학적 이익은 마이너스일 수 있다는 분석이 나온다.","visuals":[{"body":"번 돈에서 쓴 돈만 빼면 회계학적 이익이에요.\n포기한 월급까지 빼야 경제학적 이익이에요.\n0보다 크면 그 선택이 다른 선택보다 나아요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["총수입 확인","명시적 비용(낸 돈) 빼기","암묵적 비용(포기한 수입) 빼기","0보다 크면 선택"],"title":"경제학적 이익 구하는 순서","caption":"이미 써서 못 돌려받는 매몰비용은 계산에서 빼요."},{"body":"경제학적 이익이 0이라는 건 망했다는 뜻이 아니에요.\n다른 데서 벌 수 있던 만큼은 번 상태라는 뜻이에요.","type":"text","title":"왜 중요할까?"},{"q":"매출 100만 원, 명시적 비용 60만 원, 포기한 다른 일의 소득 30만 원이에요. 경제학적 이익은?","type":"quiz","answer":1,"options":["70만 원","10만 원","40만 원"],"explanation":"명시적 비용뿐 아니라 암묵적 기회비용 30만 원도 차감해요.","lessonCheck":true}]}},{"id":1005,"word":"초과이윤","before_data":{"detailed_meaning":"초과이윤은 가격에서 비용과 정상이윤을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다. 독점처럼 경쟁이 없을 때 생기며, 경쟁이 붙으면 새 기업이 들어와 결국 0이 된다. 초과이윤이 사라져도 정상이윤은 남는다.","learning_example":"학습용 가정: 초과이윤을 이해할 때는 \"가게를 유지할 최소 몫인 정상이윤을 넘어서 더 벌어들이는 이윤\"을 먼저 떠올리면 쉬워요. 초과이윤은 가격에서 비용과 정상이윤을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다."},"after_data":{"detailed_meaning":"초과이윤은 총수입에서 정상이윤을 포함한 경제학적 비용을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다. 독점처럼 경쟁이 제한될 때 유지되기 쉽지만 독점에서만 생기는 것은 아니다. 완전경쟁시장에서는 기업이 자유롭게 진입·퇴출할 수 있다는 등의 가정 아래 장기균형에서 초과이윤이 0이 된다. 초과이윤이 사라져도 정상이윤은 비용에 포함되어 남는다.","learning_example":"학습용 가정: 가게의 월 총수입이 100만 원, 명시적 비용이 70만 원, 정상이윤을 포함한 암묵적 비용이 20만 원이고 다른 비용은 없어요. 초과이윤은 100−70−20=10만 원이에요."},"guard_data":{"meaning":"가게를 유지할 최소 몫인 정상이윤을 넘어서 더 벌어들이는 이윤","detailed_meaning":"초과이윤은 가격에서 비용과 정상이윤을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다. 독점처럼 경쟁이 없을 때 생기며, 경쟁이 붙으면 새 기업이 들어와 결국 0이 된다. 초과이윤이 사라져도 정상이윤은 남는다.","learning_example":"학습용 가정: 초과이윤을 이해할 때는 \"가게를 유지할 최소 몫인 정상이윤을 넘어서 더 벌어들이는 이윤\"을 먼저 떠올리면 쉬워요. 초과이윤은 가격에서 비용과 정상이윤을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다.","news_example":"새 기업들이 잇따라 뛰어들면서 선발 업체가 누리던 초과이윤이 빠르게 줄어들고 있다.","visuals":[{"body":"마을에 빵집이 하나뿐이면 빵을 10만원에 팔 수도 있어요.\n비용과 적정 마진을 넘는 이 바가지 몫이 초과이윤이에요.\n빵집이 늘면 서로 값을 내려 이 몫이 사라져요.","type":"text","title":"쉽게 설명"},{"rows":[["1곳(독점)","10만원","초과이윤이 큼"],["2곳","1만원","가격 경쟁 시작"],["여러 곳","2,000원","초과이윤 0, 정상이윤만 남음"]],"type":"table","title":"빵집 수와 빵 가격","columns":["빵집 수","빵 가격","상황"]},{"body":"\"경쟁하면 초과이윤이 0이 된다\"는 맞는 말이에요.\n\"경쟁하면 정상이윤이 0이 된다\"는 틀린 말이에요.","type":"text","title":"왜 중요할까?"}]}},{"id":1006,"word":"정상이윤","before_data":{"learning_example":"학습용 가정: 정상이윤을 이해할 때는 \"기업이 그 사업을 계속하도록 붙잡아 두는 데 필요한 최소한의 이윤\"을 먼저 떠올리면 쉬워요. 정상이윤은 기업가가 다른 곳에서 벌 수 있었던 몫으로, 경제학에서는 암묵적 비용으로 보고 비용에 넣는다."},"after_data":{"learning_example":"학습용 가정: 점주가 가게 대신 다른 회사에서 일하면 월 300만 원을 벌 수 있고 다른 조건은 같아요. 가게를 계속 운영하게 하는 최소 보상인 월 300만 원을 정상이윤으로 보며 경제학적 비용에 포함해요."},"guard_data":{"meaning":"기업이 그 사업을 계속하도록 붙잡아 두는 데 필요한 최소한의 이윤","detailed_meaning":"정상이윤은 기업가가 다른 곳에서 벌 수 있었던 몫으로, 경제학에서는 암묵적 비용으로 보고 비용에 넣는다. 그래서 경제적 이윤이 0이라는 말은 정상이윤만 남았다는 뜻이다. 완전경쟁에서도 정상이윤은 사라지지 않는다.","learning_example":"학습용 가정: 정상이윤을 이해할 때는 \"기업이 그 사업을 계속하도록 붙잡아 두는 데 필요한 최소한의 이윤\"을 먼저 떠올리면 쉬워요. 정상이윤은 기업가가 다른 곳에서 벌 수 있었던 몫으로, 경제학에서는 암묵적 비용으로 보고 비용에 넣는다.","news_example":"완전경쟁에 가까운 업종일수록 기업들은 정상이윤 수준의 마진에 만족해야 하는 경우가 많다.","visuals":[{"body":"2,000원짜리 빵의 비용이 1,500원이면 500원이 남아요.\n주인이 먹고살 만큼의 이 몫이 정상이윤이에요.\n경쟁이 치열해도 이 몫까지 사라지면 아무도 빵을 안 구워요.","type":"text","title":"쉽게 설명"},{"rows":[["뜻","사업을 계속할 최소 마진","정상이윤을 넘는 몫"],["경쟁 후","남음","0이 됨"],["경제학의 분류","비용(암묵적 비용)에 포함","경제적 이윤"]],"type":"table","title":"정상이윤 vs 초과이윤","columns":["구분","정상이윤","초과이윤"]}]}},{"id":1008,"word":"생산물 시장","before_data":{"meaning":"기업이 만든 재화와 서비스가 가계에 팔리는 시장","detailed_meaning":"생산물 시장은 재화와 서비스가 거래되는 시장으로, 기업이 공급자이고 가계가 수요자다. 생산요소 시장과는 가계와 기업의 역할이 서로 뒤바뀐다. 공급에는 물건뿐 아니라 서비스도 모두 들어간다.","learning_example":"학습용 가정: 생산물 시장을 이해할 때는 \"기업이 만든 재화와 서비스가 가계에 팔리는 시장\"을 먼저 떠올리면 쉬워요. 생산물 시장은 재화와 서비스가 거래되는 시장으로, 기업이 공급자이고 가계가 수요자다."},"after_data":{"meaning":"생산된 재화와 서비스가 거래되는 시장","detailed_meaning":"생산물 시장은 재화와 서비스가 거래되는 시장이다. 가계와 기업만을 보는 기초 모형에서는 기업이 공급자이고 가계가 수요자이며, 생산요소 시장과 가계·기업의 역할이 뒤바뀐다. 실제로는 기업과 정부도 재화·서비스를 구매한다. 공급에는 물건뿐 아니라 서비스도 모두 들어간다.","learning_example":"학습용 가정: 빵집이 만든 빵 100개를 개당 2,000원에 가계와 회사에 팔아요. 빵이라는 생산물을 거래하는 시장의 총거래액은 100×2,000=20만 원이에요."},"guard_data":{"meaning":"기업이 만든 재화와 서비스가 가계에 팔리는 시장","detailed_meaning":"생산물 시장은 재화와 서비스가 거래되는 시장으로, 기업이 공급자이고 가계가 수요자다. 생산요소 시장과는 가계와 기업의 역할이 서로 뒤바뀐다. 공급에는 물건뿐 아니라 서비스도 모두 들어간다.","learning_example":"학습용 가정: 생산물 시장을 이해할 때는 \"기업이 만든 재화와 서비스가 가계에 팔리는 시장\"을 먼저 떠올리면 쉬워요. 생산물 시장은 재화와 서비스가 거래되는 시장으로, 기업이 공급자이고 가계가 수요자다.","news_example":"소비 심리가 위축되면서 생산물 시장의 판매 실적이 부진하다는 진단이 나온다.","visuals":[{"body":"마트에서 우유를 사고 미용실에서 머리를 자르는 곳이에요.\n기업은 팔고 가계는 사요.","type":"text","title":"쉽게 설명"},{"rows":[["가계","수요자(소비)","공급자(노동 제공)"],["기업","공급자(판매)","수요자(고용)"],["거래 대상","재화·서비스","노동·자본·토지"]],"type":"table","title":"두 시장에서 역할 비교","columns":["구분","생산물 시장","생산요소 시장"]}]}},{"id":1034,"word":"완전탄력적","before_data":{"meaning":"가격이 아주 조금만 변해도 수량이 무한히 변하는 극단적인 상태","learning_example":"학습용 가정: 완전탄력적을 이해할 때는 \"가격이 아주 조금만 변해도 수량이 무한히 변하는 극단적인 상태\"을 먼저 떠올리면 쉬워요. 완전탄력적은 탄력성이 무한대인 경우로, 곡선이 가로축과 평행한 수평선이 된다."},"after_data":{"meaning":"일정한 가격에서 수량이 달라질 수 있어 수요곡선이나 공급곡선이 수평선으로 나타나는 이론적 상태","learning_example":"학습용 가정: 완전탄력적인 공급이 개당 1천 원에서 이뤄지는 모형에서 수요가 늘어 거래량이 100개에서 200개로 증가해도 가격은 1천 원으로 같아요."},"guard_data":{"meaning":"가격이 아주 조금만 변해도 수량이 무한히 변하는 극단적인 상태","detailed_meaning":"완전탄력적은 탄력성이 무한대인 경우로, 곡선이 가로축과 평행한 수평선이 된다. 공급이 완전탄력적이면 수요가 늘어도 가격은 그대로고 거래량만 늘어난다. 수요가 완전탄력적이면 공급자에게 매긴 세금을 공급자가 전부 부담한다.","learning_example":"학습용 가정: 완전탄력적을 이해할 때는 \"가격이 아주 조금만 변해도 수량이 무한히 변하는 극단적인 상태\"을 먼저 떠올리면 쉬워요. 완전탄력적은 탄력성이 무한대인 경우로, 곡선이 가로축과 평행한 수평선이 된다.","news_example":"수요가 완전탄력적에 가까운 시장에서는 판매자가 가격을 조금만 올려도 손님을 모두 잃는다.","visuals":[{"body":"정해진 가격에서 원하는 만큼 다 사고팔 수 있는 상태예요.\n값을 조금만 올려도 아무도 안 사요.","type":"text","title":"쉽게 설명"},{"rows":[["완전탄력적(수평선)","그대로","증가"],["완전비탄력적(수직선)","상승","그대로"]],"type":"table","title":"수요가 늘 때 공급이 극단이면","columns":["공급","균형가격","균형거래량"]}]}},{"id":1042,"word":"직각쌍곡선","before_data":{"learning_example":"학습용 가정: 직각쌍곡선을 이해할 때는 \"가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선\"을 먼저 떠올리면 쉬워요. 직각쌍곡선은 P × Q가 항상 일정한 곡선으로, 수요곡선이 이 모양이면 모든 점에서 가격탄력성이 1이다.","visuals":[{"body":"가격 100에 10개, 가격 20에 50개라면 매출이 둘 다 1,000이에요.\n어디서든 곱이 같은 곡선이 직각쌍곡선이에요.","type":"text","title":"쉽게 설명"},{"rows":[["탄력성","점마다 다름(중점만 1)","모든 점에서 1"],["매출","중점에서 최대","어디서나 같음"]],"type":"table","title":"직선 vs 직각쌍곡선","columns":["구분","직선 수요곡선","직각쌍곡선"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선","type":"quiz","answer":0,"options":["직각쌍곡선","반복 게임","도덕적 해이","균형가격"],"explanation":"직각쌍곡선은/는 가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"learning_example":"학습용 가정: 수요곡선이 가격×수요량=10만 원이면 가격 1천 원일 때 100개, 2천 원일 때 50개를 사요. 두 경우 총지출은 10만 원으로 같으며, 이 곡선의 각 점에서 수요의 가격탄력성 절댓값은 1이에요.","visuals":[{"body":"가격 100에 10개, 가격 20에 50개라면 매출이 둘 다 1,000이에요.\n어디서든 곱이 같은 곡선이 직각쌍곡선이에요.","type":"text","title":"쉽게 설명"},{"rows":[["탄력성","점마다 다름(중점만 1)","모든 점에서 1"],["매출","중점에서 최대","어디서나 같음"]],"type":"table","title":"직선 vs 직각쌍곡선","columns":["구분","직선 수요곡선","직각쌍곡선"]},{"q":"수요곡선이 가격×수요량=10만 원인 직각쌍곡선이에요. 가격이 1천 원에서 2천 원으로 오르면 수요량은?","type":"quiz","answer":0,"options":["100개에서 50개로 감소","100개에서 200개로 증가","100개로 유지","100개에서 0개로 감소"],"explanation":"수요량은 10만 원을 가격으로 나눈 값이에요. 100,000÷1,000=100개, 100,000÷2,000=50개이므로 가격과 수요량의 곱이 같게 유지돼요.","lessonCheck":true}]},"guard_data":{"meaning":"가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선","detailed_meaning":"직각쌍곡선은 P × Q가 항상 일정한 곡선으로, 수요곡선이 이 모양이면 모든 점에서 가격탄력성이 1이다. 가격을 내린 만큼 수요량이 같은 비율로 늘어 어느 점에서든 총수입이 같다. 직선 수요곡선이 중점에서만 탄력성 1인 것과 구분된다.","learning_example":"학습용 가정: 직각쌍곡선을 이해할 때는 \"가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선\"을 먼저 떠올리면 쉬워요. 직각쌍곡선은 P × Q가 항상 일정한 곡선으로, 수요곡선이 이 모양이면 모든 점에서 가격탄력성이 1이다.","news_example":"수요곡선이 직각쌍곡선 형태라면 가격을 바꿔도 소비자의 총지출은 일정하게 유지된다.","visuals":[{"body":"가격 100에 10개, 가격 20에 50개라면 매출이 둘 다 1,000이에요.\n어디서든 곱이 같은 곡선이 직각쌍곡선이에요.","type":"text","title":"쉽게 설명"},{"rows":[["탄력성","점마다 다름(중점만 1)","모든 점에서 1"],["매출","중점에서 최대","어디서나 같음"]],"type":"table","title":"직선 vs 직각쌍곡선","columns":["구분","직선 수요곡선","직각쌍곡선"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선","type":"quiz","answer":0,"options":["직각쌍곡선","반복 게임","도덕적 해이","균형가격"],"explanation":"직각쌍곡선은/는 가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":1053,"word":"효용함수","before_data":{"meaning":"상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식","learning_example":"학습용 가정: 효용함수을 이해할 때는 \"상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식\"을 먼저 떠올리면 쉬워요. 효용함수는 소비하는 재화의 양과 효용의 관계를 나타낸 식이다.","visuals":[{"body":"빵 몇 개, 우유 몇 개를 넣으면 만족 점수가 나오는 계산기예요.","type":"text","title":"쉽게 설명"},{"rows":[["U = x × y","골고루 살수록 효용이 커짐","빵과 우유"],["U = x + y","하나를 다른 하나로 똑같이 대체","흑설탕과 백설탕"]],"type":"table","title":"효용함수 모양","columns":["효용함수","뜻","예시"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식","type":"quiz","answer":0,"options":["효용함수","후생경제학","파레토 개선","효용 극대화"],"explanation":"효용함수은/는 상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"meaning":"소비하는 재화의 조합에 대한 선호나 만족을 숫자로 나타내는 함수","learning_example":"학습용 가정: 선호를 U=사과 수×빵 수로 나타내면 사과 2개·빵 3개의 효용값은 6, 사과 1개·빵 4개는 4예요. 서수적 해석에서는 앞 조합을 더 좋아한다는 뜻이지 만족이 1.5배라는 뜻은 아니에요.","visuals":[{"body":"빵 몇 개, 우유 몇 개를 넣으면 만족 점수가 나오는 계산기예요.","type":"text","title":"쉽게 설명"},{"rows":[["U = x × y","골고루 살수록 효용이 커짐","빵과 우유"],["U = x + y","하나를 다른 하나로 똑같이 대체","흑설탕과 백설탕"]],"type":"table","title":"효용함수 모양","columns":["효용함수","뜻","예시"]},{"q":"소비 조합에 숫자를 부여해 선호 순서를 나타내는 식 U(X,Y)는 무엇인가요?","type":"quiz","answer":0,"options":["효용함수","예산선의 식","수요함수","생산함수"],"explanation":"효용함수는 소비 조합과 효용값의 관계를 나타내요. 서수적 효용에서는 숫자의 크기 순서로 선호를 표현하며 만족의 절대량을 측정하는 것은 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식","detailed_meaning":"효용함수는 소비하는 재화의 양과 효용의 관계를 나타낸 식이다. U = x × y처럼 곱하기 꼴이면 골고루 살수록 효용이 커지고, U = x + y처럼 더하기 꼴이면 두 재화를 완전히 바꿔 쓸 수 있다. 정확한 측정보다는 선택의 방향을 설명하는 도구로 쓰인다.","learning_example":"학습용 가정: 효용함수을 이해할 때는 \"상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식\"을 먼저 떠올리면 쉬워요. 효용함수는 소비하는 재화의 양과 효용의 관계를 나타낸 식이다.","news_example":"연구진은 효용함수를 설정해 소비자들이 가격 변화에 어떻게 반응하는지 모의 실험했다.","visuals":[{"body":"빵 몇 개, 우유 몇 개를 넣으면 만족 점수가 나오는 계산기예요.","type":"text","title":"쉽게 설명"},{"rows":[["U = x × y","골고루 살수록 효용이 커짐","빵과 우유"],["U = x + y","하나를 다른 하나로 똑같이 대체","흑설탕과 백설탕"]],"type":"table","title":"효용함수 모양","columns":["효용함수","뜻","예시"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식","type":"quiz","answer":0,"options":["효용함수","후생경제학","파레토 개선","효용 극대화"],"explanation":"효용함수은/는 상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":1060,"word":"예산제약","before_data":{"detailed_meaning":"예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다. 기본 모형에서는 저축을 두지 않아 Px × X + Py × Y = M으로 쓴다. 이 조건을 그래프로 나타낸 것이 예산선이며, 소비자는 그 안에서 효용 극대화를 추구한다.","learning_example":"학습용 가정: 예산제약을 이해할 때는 \"쓸 수 있는 돈이 정해져 있어 소비 선택이 그 범위 안으로 묶이는 조건\"을 먼저 떠올리면 쉬워요. 예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다.","visuals":[{"body":"한 달 용돈이 10만원이면 그 안에서만 살 수 있어요.\n갖고 싶은 건 많아도 돈이 한계를 정해요.","type":"text","title":"쉽게 설명"},{"rows":[["예산선 위","돈을 다 쓴 조합"],["예산선 안쪽","살 수 있지만 돈이 남는 조합"],["예산선 바깥","돈이 모자라 못 사는 조합"]],"type":"table","title":"예산선 기준 위치","columns":["위치","의미"]},{"q":"용돈 1만 원으로 2천 원짜리 음료와 3천 원짜리 빵을 사요. 가능한 조합은?","type":"quiz","answer":2,"options":["음료 3개와 빵 2개","음료 1개와 빵 3개","음료 2개와 빵 2개"],"explanation":"첫 조합만 총액 1만 원으로 예산을 넘지 않아요.","lessonCheck":true}]},"after_data":{"detailed_meaning":"예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다. 가격이 양수이고 차입이 없는 기본 모형의 예산제약은 Px × X + Py × Y ≤ M이며, 가진 예산을 모두 쓰는 경계가 Px × X + Py × Y = M인 예산선이다. 이 예산선과 그 안쪽이 구매 가능한 영역이며, 소비자는 그 안에서 효용 극대화를 추구한다.","learning_example":"학습용 가정: 용돈 1만 원으로 2천 원짜리 음료 2개와 3천 원짜리 빵 2개를 사면 4천 원+6천 원=1만 원으로 예산에 꼭 맞아요. 음료 1개와 빵 2개는 8천 원이므로 역시 예산제약을 충족해요.","visuals":[{"body":"한 달 용돈이 10만원이면 그 안에서만 살 수 있어요.\n갖고 싶은 건 많아도 돈이 한계를 정해요.","type":"text","title":"쉽게 설명"},{"rows":[["예산선 위","돈을 다 쓴 조합"],["예산선 안쪽","살 수 있지만 돈이 남는 조합"],["예산선 바깥","돈이 모자라 못 사는 조합"]],"type":"table","title":"예산선 기준 위치","columns":["위치","의미"]},{"q":"용돈 1만 원으로 2천 원짜리 음료와 3천 원짜리 빵을 사요. 가능한 조합은?","type":"quiz","answer":2,"options":["음료 3개와 빵 2개","음료 1개와 빵 3개","음료 2개와 빵 2개"],"explanation":"세 번째 보기의 음료 2개와 빵 2개는 2,000×2+3,000×2=10,000원으로 예산에 맞아요. 첫 번째는 12,000원, 두 번째는 11,000원이라 예산을 넘어요.","lessonCheck":true}]},"guard_data":{"meaning":"쓸 수 있는 돈이 정해져 있어 소비 선택이 그 범위 안으로 묶이는 조건","detailed_meaning":"예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다. 기본 모형에서는 저축을 두지 않아 Px × X + Py × Y = M으로 쓴다. 이 조건을 그래프로 나타낸 것이 예산선이며, 소비자는 그 안에서 효용 극대화를 추구한다.","learning_example":"학습용 가정: 예산제약을 이해할 때는 \"쓸 수 있는 돈이 정해져 있어 소비 선택이 그 범위 안으로 묶이는 조건\"을 먼저 떠올리면 쉬워요. 예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다.","news_example":"실질소득이 줄면서 가계가 느끼는 예산제약이 커져 외식과 여가 지출부터 줄이고 있다.","visuals":[{"body":"한 달 용돈이 10만원이면 그 안에서만 살 수 있어요.\n갖고 싶은 건 많아도 돈이 한계를 정해요.","type":"text","title":"쉽게 설명"},{"rows":[["예산선 위","돈을 다 쓴 조합"],["예산선 안쪽","살 수 있지만 돈이 남는 조합"],["예산선 바깥","돈이 모자라 못 사는 조합"]],"type":"table","title":"예산선 기준 위치","columns":["위치","의미"]},{"q":"용돈 1만 원으로 2천 원짜리 음료와 3천 원짜리 빵을 사요. 가능한 조합은?","type":"quiz","answer":2,"options":["음료 3개와 빵 2개","음료 1개와 빵 3개","음료 2개와 빵 2개"],"explanation":"첫 조합만 총액 1만 원으로 예산을 넘지 않아요.","lessonCheck":true}]}},{"id":1061,"word":"소비자 균형 조건","before_data":{"meaning":"한계대체율과 상대가격이 같아져야 효용이 가장 커진다는 조건","detailed_meaning":"소비자 균형 조건은 무차별곡선과 예산선이 접하는 점에서 MRS = Px ÷ Py가 성립한다는 것이다. MRS가 상대가격보다 크면 X를 늘리고, 작으면 Y를 늘리는 쪽이 이득이다. MRS = MUx ÷ MUy이므로 이 조건은 한계효용 균등의 법칙과 같은 말이다.","learning_example":"학습용 가정: 소비자 균형 조건을 이해할 때는 \"한계대체율과 상대가격이 같아져야 효용이 가장 커진다는 조건\"을 먼저 떠올리면 쉬워요. 소비자 균형 조건은 무차별곡선과 예산선이 접하는 점에서 MRS = Px ÷ Py가 성립한다는 것이다."},"after_data":{"meaning":"두 재화를 모두 소비하는 매끄러운 내부 최적점에서 한계대체율과 상대가격이 같아지는 조건","detailed_meaning":"선호가 볼록하고 무차별곡선이 매끄러우며 두 재화를 모두 소비하는 내부 최적점에서는 무차별곡선과 예산선이 접하여 MRS = Px ÷ Py가 성립한다. 한 재화만 소비하는 모서리해나 꺾인 무차별곡선의 최적점에는 이 등식이 적용되지 않을 수 있다. MRS가 상대가격보다 크면 X를 늘리고, 작으면 Y를 늘리는 쪽이 이득이다. MRS = MUx ÷ MUy이므로 이 조건은 한계효용 균등의 법칙과 같은 말이다.","learning_example":"학습용 가정: 매끄럽고 원점에 볼록한 무차별곡선에서 사과와 빵을 모두 소비하는 최적점을 찾는다고 해요. 사과 2천 원, 빵 1천 원이면 한계대체율은 빵 2개/사과 1개로 상대가격 2와 같아져요."},"guard_data":{"meaning":"한계대체율과 상대가격이 같아져야 효용이 가장 커진다는 조건","detailed_meaning":"소비자 균형 조건은 무차별곡선과 예산선이 접하는 점에서 MRS = Px ÷ Py가 성립한다는 것이다. MRS가 상대가격보다 크면 X를 늘리고, 작으면 Y를 늘리는 쪽이 이득이다. MRS = MUx ÷ MUy이므로 이 조건은 한계효용 균등의 법칙과 같은 말이다.","learning_example":"학습용 가정: 소비자 균형 조건을 이해할 때는 \"한계대체율과 상대가격이 같아져야 효용이 가장 커진다는 조건\"을 먼저 떠올리면 쉬워요. 소비자 균형 조건은 무차별곡선과 예산선이 접하는 점에서 MRS = Px ÷ Py가 성립한다는 것이다.","news_example":"교과서는 소비자 균형 조건을 통해 가격이 바뀔 때 소비 조합이 어떻게 달라지는지 설명한다.","visuals":[{"body":"내 마음속 교환 비율과 시장의 교환 비율이 같아지는 곳에서\n더 바꿀 이유가 없어져요. 그게 균형이에요.","type":"text","title":"쉽게 설명"},{"rows":[["B(Y가 많음)","MRS > Px ÷ Py","X 늘리고 Y 줄임"],["C(X가 많음)","MRS < Px ÷ Py","Y 늘리고 X 줄임"],["A(접점)","MRS = Px ÷ Py","그대로"]],"type":"table","title":"X재 200원, Y재 100원(상대가격 2)","columns":["점","비교","움직일 방향"]}]}},{"id":1062,"word":"한계효용 균등의 법칙","before_data":{"meaning":"각 재화에 마지막으로 쓴 1원의 만족이 같아질 때 효용이 최대라는 원리","detailed_meaning":"한계효용 균등의 법칙은 MUx ÷ Px = MUy ÷ Py가 성립하도록 돈을 나눠 쓸 때 효용이 가장 커진다는 원리다. 1원당 효용이 큰 재화를 늘리면 한계효용 체감으로 그 값이 줄어들어 결국 두 값이 같아진다. 한계효용 자체가 아니라 가격으로 나눈 1원당 효용을 비교해야 한다.","learning_example":"학습용 가정: 한계효용 균등의 법칙을 이해할 때는 \"각 재화에 마지막으로 쓴 1원의 만족이 같아질 때 효용이 최대라는 원리\"을 먼저 떠올리면 쉬워요. 한계효용 균등의 법칙은 MUx ÷ Px = MUy ÷ Py가 성립하도록 돈을 나눠 쓸 때 효용이 가장 커진다는 원리다."},"after_data":{"meaning":"재화를 나눠서 살 수 있는 내부 최적점에서 각 재화에 마지막으로 쓴 1원당 한계효용이 같아지는 원리","detailed_meaning":"한계효용 균등의 법칙은 재화를 연속적으로 나눠 살 수 있고 두 재화를 모두 소비하는 내부 최적점에서 MUx ÷ Px = MUy ÷ Py가 성립한다는 원리다. 한 재화만 사거나 상품을 정수 단위로만 살 수 있는 경우에는 이 값들이 정확히 같지 않아도 최적일 수 있다. 1원당 효용이 큰 재화를 늘리면 한계효용 체감으로 그 값이 줄어들어 결국 두 값이 같아진다. 한계효용 자체가 아니라 가격으로 나눈 1원당 효용을 비교해야 한다.","learning_example":"학습용 가정: 재화를 나눠 살 수 있는 모형에서 사과의 한계효용이 10, 가격이 2천 원이고 빵의 한계효용이 5, 가격이 1천 원이면 두 재화의 1천 원당 한계효용은 모두 5로 같아요."},"guard_data":{"meaning":"각 재화에 마지막으로 쓴 1원의 만족이 같아질 때 효용이 최대라는 원리","detailed_meaning":"한계효용 균등의 법칙은 MUx ÷ Px = MUy ÷ Py가 성립하도록 돈을 나눠 쓸 때 효용이 가장 커진다는 원리다. 1원당 효용이 큰 재화를 늘리면 한계효용 체감으로 그 값이 줄어들어 결국 두 값이 같아진다. 한계효용 자체가 아니라 가격으로 나눈 1원당 효용을 비교해야 한다.","learning_example":"학습용 가정: 한계효용 균등의 법칙을 이해할 때는 \"각 재화에 마지막으로 쓴 1원의 만족이 같아질 때 효용이 최대라는 원리\"을 먼저 떠올리면 쉬워요. 한계효용 균등의 법칙은 MUx ÷ Px = MUy ÷ Py가 성립하도록 돈을 나눠 쓸 때 효용이 가장 커진다는 원리다.","news_example":"전문가들은 가성비를 따지는 소비 습관이 한계효용 균등의 법칙과 같은 원리라고 설명한다.","visuals":[{"body":"같은 돈이면 더 뿌듯한 쪽에 먼저 써요.\n마지막 1원이 어디에 쓰이든 똑같이 뿌듯해지면 멈춰요.","type":"text","title":"쉽게 설명"},{"rows":[["X재","2","3원","약 0.67"],["Y재","0.5","1원","0.5"]],"type":"table","title":"1원당 효용 비교","caption":"X재의 1원당 효용이 더 크니 X재를 늘리고 Y재를 줄여요.","columns":["재화","한계효용","가격","1원당 효용"]},{"body":"한계효용이 큰 재화를 늘리는 게 아니에요.\n가격으로 나눈 1원당 효용을 비교해야 해요.","type":"text","title":"헷갈리기 쉬운 점"}]}},{"id":1081,"word":"가격수용자","before_data":{"visuals":[{"body":"배추 농가 한 곳이 값을 올리면 다들 옆 농가 배추를 사요.\n값을 내릴 이유도 없으니 시세 그대로 팔 수밖에 없어요.","type":"text","title":"쉽게 설명"},{"rows":[["시장 전체","우하향","값이 내리면 더 사요"],["개별 기업","수평","시장 가격에 얼마든지 팔 수 있어요"]],"type":"table","title":"시장 전체와 개별 기업의 수요곡선","columns":["구분","모양","이유"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 시장에서 정해진 가격을 그대로 받아들이는 경제주체","type":"quiz","answer":0,"options":["가격수용자","오버투어리즘","소비자잉여","신호 발송"],"explanation":"가격수용자은/는 시장에서 정해진 가격을 그대로 받아들이는 경제주체 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]},"after_data":{"visuals":[{"body":"배추 농가 한 곳이 값을 올리면 다들 옆 농가 배추를 사요.\n값을 내릴 이유도 없으니 시세 그대로 팔 수밖에 없어요.","type":"text","title":"쉽게 설명"},{"rows":[["시장 전체","우하향","값이 내리면 더 사요"],["개별 기업","수평","시장 가격에 얼마든지 팔 수 있어요"]],"type":"table","title":"시장 전체와 개별 기업의 수요곡선","columns":["구분","모양","이유"]},{"q":"완전경쟁시장의 작은 기업이 자기 생산량으로 시장가격을 바꾸지 못해 주어진 가격에 판매해요. 이 기업은?","type":"quiz","answer":0,"options":["가격수용자","가격설정자","가격선도기업","독점적 공급자"],"explanation":"자기 거래량으로 시장가격에 영향을 줄 수 없어 주어진 가격을 받아들이는 주체가 가격수용자예요. 가격설정자나 가격선도기업은 가격 결정에 영향력을 행사해요.","lessonCheck":true}]},"guard_data":{"meaning":"시장에서 정해진 가격을 그대로 받아들이는 경제주체","detailed_meaning":"가격수용자는 자기 행동으로 시장 가격을 바꿀 수 없어 주어진 가격을 그대로 받아들이는 기업이나 소비자다. 완전경쟁시장의 개별 기업이 대표적이며, 이 기업이 마주하는 수요곡선은 수평이다. 그래서 가격과 한계수입이 같고, 이윤극대화 조건은 가격 = 한계비용이 된다.","learning_example":"학습용 가정: 가격수용자을 이해할 때는 \"시장에서 정해진 가격을 그대로 받아들이는 경제주체\"을 먼저 떠올리면 쉬워요. 가격수용자는 자기 행동으로 시장 가격을 바꿀 수 없어 주어진 가격을 그대로 받아들이는 기업이나 소비자다.","news_example":"농산물처럼 생산자가 많고 품질이 비슷한 시장에서 개별 농가는 가격수용자로서 시세를 따를 수밖에 없다.","visuals":[{"body":"배추 농가 한 곳이 값을 올리면 다들 옆 농가 배추를 사요.\n값을 내릴 이유도 없으니 시세 그대로 팔 수밖에 없어요.","type":"text","title":"쉽게 설명"},{"rows":[["시장 전체","우하향","값이 내리면 더 사요"],["개별 기업","수평","시장 가격에 얼마든지 팔 수 있어요"]],"type":"table","title":"시장 전체와 개별 기업의 수요곡선","columns":["구분","모양","이유"]},{"q":"다음 설명에 가장 가까운 용어는 무엇일까요? 시장에서 정해진 가격을 그대로 받아들이는 경제주체","type":"quiz","answer":0,"options":["가격수용자","오버투어리즘","소비자잉여","신호 발송"],"explanation":"가격수용자은/는 시장에서 정해진 가격을 그대로 받아들이는 경제주체 이 설명과 연결해 기억하면 쉬워요.","lessonCheck":true}]}},{"id":1083,"word":"이윤극대화 조건","before_data":{"meaning":"한계수입과 한계비용이 같아지는 곳에서 생산량을 정하는 원칙","detailed_meaning":"이윤극대화 조건은 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같아지도록 생산량을 정하는 것이다. 한계수입이 한계비용보다 크면 더 만들고, 작으면 줄이는 것이 이윤을 늘린다. 완전경쟁에서는 가격과 한계수입이 같아 가격 = 한계비용이 되고, 독점은 한계수입이 가격보다 낮다.","learning_example":"학습용 가정: 이윤극대화 조건을 이해할 때는 \"한계수입과 한계비용이 같아지는 곳에서 생산량을 정하는 원칙\"을 먼저 떠올리면 쉬워요. 이윤극대화 조건은 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같아지도록 생산량을 정하는 것이다."},"after_data":{"meaning":"내부 최적 생산량에서 한계수입과 한계비용이 같고 추가 생산의 이윤이 증가에서 감소로 바뀌는 조건","detailed_meaning":"생산량을 연속적으로 조절할 수 있는 내부 최적점에서는 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같다. 다만 이 등식만으로 극대화가 보장되지는 않으며, 생산량을 늘릴 때 한계수입-한계비용이 양수에서 음수로 바뀌는지, 조업중단이나 다른 가능한 생산량보다 이윤이 큰지도 확인해야 한다. 한계수입이 한계비용보다 크면 더 만들고, 작으면 줄이는 것이 이윤을 늘린다. 완전경쟁에서는 가격과 한계수입이 같아 가격 = 한계비용이 되고, 독점은 한계수입이 가격보다 낮다.","learning_example":"학습용 가정: 한계수입이 개당 1만 원으로 일정하고 생산량이 늘수록 한계비용이 8천 원, 1만 원, 1만 2천 원으로 높아진다면, 추가 이윤은 2천 원, 0원, -2천 원으로 바뀌어요. 이산적인 생산에서는 가능한 생산량의 총이윤을 비교해 최대를 골라요."},"guard_data":{"meaning":"한계수입과 한계비용이 같아지는 곳에서 생산량을 정하는 원칙","detailed_meaning":"이윤극대화 조건은 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같아지도록 생산량을 정하는 것이다. 한계수입이 한계비용보다 크면 더 만들고, 작으면 줄이는 것이 이윤을 늘린다. 완전경쟁에서는 가격과 한계수입이 같아 가격 = 한계비용이 되고, 독점은 한계수입이 가격보다 낮다.","learning_example":"학습용 가정: 이윤극대화 조건을 이해할 때는 \"한계수입과 한계비용이 같아지는 곳에서 생산량을 정하는 원칙\"을 먼저 떠올리면 쉬워요. 이윤극대화 조건은 하나 더 팔 때 늘어나는 수입(한계수입)과 하나 더 만들 때 드는 비용(한계비용)이 같아지도록 생산량을 정하는 것이다.","news_example":"기업들은 이윤극대화 조건에 따라 추가 생산의 수입과 비용을 비교해 생산량을 조절한다.","visuals":[{"body":"하나 더 팔아 버는 돈이 하나 더 만드는 비용보다 크면 더 만들어요.\n둘이 같아지는 순간이 이윤이 가장 큰 지점이에요.","type":"text","title":"쉽게 설명"},{"rows":[["7개","70원","400원"],["8개","90원","410원"],["9개","100원","410원"],["10개","130원","380원"]],"type":"table","title":"사탕 하나 100원일 때 생산량 고르기","caption":"한계비용이 가격 100원에 닿는 9개까지 만들면 이윤이 가장 커요.","columns":["생산량","한계비용","이윤"]},{"rows":[["모든 시장","한계수입 = 한계비용"],["완전경쟁","가격 = 한계비용"],["독점","한계수입 = 한계비용, 가격은 수요곡선에서"]],"type":"table","title":"시장별 이윤극대화","columns":["시장","조건"]}]}},{"id":1110,"word":"피구세","before_data":{"meaning":"부정적 외부효과를 일으키는 활동에 외부 비용만큼 매기는 세금","detailed_meaning":"피구세는 오염처럼 제3자에게 피해를 주는 활동에 그 외부 한계비용만큼 세금을 매기는 것이다. 세금으로 사회적 비용을 생산자의 계산 안에 넣어 과다 생산을 사회적 최적 수준으로 줄인다. 이를 외부효과의 내부화라고 하며, 경제학자 피구의 이름을 땄다.","learning_example":"학습용 가정: 피구세을 이해할 때는 \"부정적 외부효과를 일으키는 활동에 외부 비용만큼 매기는 세금\"을 먼저 떠올리면 쉬워요. 피구세는 오염처럼 제3자에게 피해를 주는 활동에 그 외부 한계비용만큼 세금을 매기는 것이다."},"after_data":{"meaning":"부정적 외부효과를 줄이려고 사회적으로 적정한 활동량에서의 한계 외부비용만큼 단위당 부과하는 세금","detailed_meaning":"피구세는 오염처럼 제3자에게 피해를 주는 활동에 대해, 사회적으로 최적인 활동량에서 발생하는 한계 외부비용만큼 단위당 세금을 매기는 것이다. 세금으로 사회적 비용을 생산자의 계산 안에 넣어 과다 생산을 사회적 최적 수준으로 줄인다. 이를 외부효과의 내부화라고 하며, 경제학자 피구의 이름을 땄다.","learning_example":"학습용 가정: 사회적으로 적정한 생산량에서 제품 1개 추가 생산의 외부 피해가 2천 원으로 추정되면 개당 2천 원의 피구세를 부과해 그 피해를 생산자의 비용 계산에 반영해요. 100개 생산 시 세금은 20만 원이에요."},"guard_data":{"meaning":"부정적 외부효과를 일으키는 활동에 외부 비용만큼 매기는 세금","detailed_meaning":"피구세는 오염처럼 제3자에게 피해를 주는 활동에 그 외부 한계비용만큼 세금을 매기는 것이다. 세금으로 사회적 비용을 생산자의 계산 안에 넣어 과다 생산을 사회적 최적 수준으로 줄인다. 이를 외부효과의 내부화라고 하며, 경제학자 피구의 이름을 땄다.","learning_example":"학습용 가정: 피구세을 이해할 때는 \"부정적 외부효과를 일으키는 활동에 외부 비용만큼 매기는 세금\"을 먼저 떠올리면 쉬워요. 피구세는 오염처럼 제3자에게 피해를 주는 활동에 그 외부 한계비용만큼 세금을 매기는 것이다.","news_example":"탄소 배출에 세금을 매기는 탄소세는 대표적인 피구세로 꼽힌다.","visuals":[{"body":"가구 공장이 하나 만들 때 이웃에게 10원어치 피해를 준다면 하나당 10원을 세금으로 내게 해요.\n그러면 공장이 피해까지 계산해서 덜 만들어요.","type":"text","title":"쉽게 설명"},{"rows":[["피구세","외부 한계비용만큼 세금","부정적 외부효과를 줄임"],["보조금","외부 한계편익만큼 지원","긍정적 외부효과를 늘림"],["직접 규제","배출량을 직접 제한","감시 비용이 큼"],["배출권 거래","총량을 정하고 사고팔게 함","시장 원리로 효율적"]],"type":"table","title":"외부효과를 줄이는 방법","columns":["방법","내용","특징"]},{"type":"flow","steps":["외부 비용이 가격에 빠짐","과다 생산","외부 비용만큼 세금 부과","사회적 최적 생산량으로 감소"],"title":"피구세가 작동하는 흐름"}]}},{"id":1121,"word":"국민총생산(GNP)","before_data":{"meaning":"국적을 기준으로 한 나라 국민이 국내외에서 생산한 최종 생산물의 가치","detailed_meaning":"GNP는 장소가 아니라 국적을 기준으로 생산을 세는 지표다. GDP에 국외순수취요소소득(해외에서 받은 요소소득 - 해외로 준 요소소득)을 더해 구한다. 지금은 국민의 소득 수준을 볼 때 교역조건까지 반영한 GNI를 주로 쓴다.","learning_example":"학습용 가정: 국민총생산(GNP)을 이해할 때는 \"국적을 기준으로 한 나라 국민이 국내외에서 생산한 최종 생산물의 가치\"을 먼저 떠올리면 쉬워요. GNP는 장소가 아니라 국적을 기준으로 생산을 세는 지표다."},"after_data":{"meaning":"한 나라 거주자가 국내외 생산활동에 참여해 얻은 소득을 기준으로 집계하는 국민총생산","detailed_meaning":"GNP는 생산 장소만이 아니라 한 나라 거주자가 소유한 생산요소의 국내외 생산활동 대가를 기준으로 집계하며, 여기서 거주자는 법적 국적과 다를 수 있다. GDP에 국외순수취요소소득(해외에서 받은 요소소득 - 해외로 준 요소소득)을 더해 구한다. 지금은 국민의 소득 수준을 볼 때 GNI를 주로 쓰며, 실질 GNI는 교역조건 변화에 따른 실질 무역손익도 반영한다.","learning_example":"학습용 가정: 명목 GDP가 1천억 원이고 거주자가 해외에서 받은 요소소득이 50억 원, 비거주자에게 지급한 요소소득이 30억 원이면 명목 GNP는 1천억+50억-30억=1,020억 원이에요. 거주자는 여권의 국적만으로 구분하지 않아요."},"guard_data":{"meaning":"국적을 기준으로 한 나라 국민이 국내외에서 생산한 최종 생산물의 가치","detailed_meaning":"GNP는 장소가 아니라 국적을 기준으로 생산을 세는 지표다. GDP에 국외순수취요소소득(해외에서 받은 요소소득 - 해외로 준 요소소득)을 더해 구한다. 지금은 국민의 소득 수준을 볼 때 교역조건까지 반영한 GNI를 주로 쓴다.","learning_example":"학습용 가정: 국민총생산(GNP)을 이해할 때는 \"국적을 기준으로 한 나라 국민이 국내외에서 생산한 최종 생산물의 가치\"을 먼저 떠올리면 쉬워요. GNP는 장소가 아니라 국적을 기준으로 생산을 세는 지표다.","news_example":"해외에 진출한 기업과 근로자가 늘면서 국민총생산(GNP)과 GDP의 차이에도 관심이 커지고 있다.","visuals":[{"body":"GDP는 \"우리 땅에서\" 만든 것,\nGNP는 \"우리 국민이\" 만든 것이에요.\n이름에 N(National)이 붙으면 국적 기준이라고 기억해요.","type":"text","title":"쉽게 설명"},{"rows":[["한국인이 미국에서 번 임금","불포함","포함"],["외국인이 한국에서 번 임금","포함","불포함"]],"type":"table","title":"GDP와 GNP에 들어가는 것","caption":"GNP = GDP + 국외순수취요소소득이에요.","columns":["예","GDP (한국)","GNP (한국)"]}]}},{"id":1125,"word":"균형재정승수","before_data":{"meaning":"세금을 걷은 만큼 정부가 그대로 쓸 때 국민소득이 늘어나는 배수, 이론상 1","detailed_meaning":"정부가 세금을 100 걷어 100을 쓰면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다. 정부지출은 전액이 바로 지출이 되지만, 세금은 그중 소비하던 부분만큼만 지출을 줄이기 때문이다. 그래서 정부지출 승수와 조세 승수를 더하면 1이 된다.","learning_example":"학습용 가정: 균형재정승수을 이해할 때는 \"세금을 걷은 만큼 정부가 그대로 쓸 때 국민소득이 늘어나는 배수, 이론상 1\"을 먼저 떠올리면 쉬워요. 정부가 세금을 100 걷어 100을 쓰면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다."},"after_data":{"meaning":"정부지출과 세금을 같은 금액 늘릴 때 국민소득이 늘어나는 배수로, 단순한 폐쇄경제 정액세 모형에서는 1","detailed_meaning":"투자가 고정되고 수입과 구축효과가 없으며 소비함수가 선형인 단순 케인스 모형에서, 정부지출과 정액세를 각각 100 늘리면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다. 정부지출은 전액이 바로 지출이 되지만, 세금은 그중 소비하던 부분만큼만 지출을 줄이기 때문이다. 그래서 이 모형에서는 정부지출 승수와 조세 승수를 더하면 1이 된다. 현실의 재정승수가 언제나 1이라는 뜻은 아니다.","learning_example":"학습용 가정: 폐쇄경제의 단순 케인스 모형에서 투자·물가는 고정되고 구축효과가 없으며 한계소비성향은 0.8이에요. 정부지출과 정액세를 각각 100억 원 늘리면 소득 변화는 (100-0.8×100)÷(1-0.8)=100억 원이에요."},"guard_data":{"meaning":"세금을 걷은 만큼 정부가 그대로 쓸 때 국민소득이 늘어나는 배수, 이론상 1","detailed_meaning":"정부가 세금을 100 걷어 100을 쓰면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다. 정부지출은 전액이 바로 지출이 되지만, 세금은 그중 소비하던 부분만큼만 지출을 줄이기 때문이다. 그래서 정부지출 승수와 조세 승수를 더하면 1이 된다.","learning_example":"학습용 가정: 균형재정승수을 이해할 때는 \"세금을 걷은 만큼 정부가 그대로 쓸 때 국민소득이 늘어나는 배수, 이론상 1\"을 먼저 떠올리면 쉬워요. 정부가 세금을 100 걷어 100을 쓰면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다.","news_example":"세수를 늘려 같은 규모로 지출하더라도 균형재정승수 덕분에 경기에 일부 보탬이 될 수 있다는 분석이 있다.","visuals":[{"body":"세금 100을 걷어 그대로 100을 써도\n경제 전체 소득은 100만큼 늘어나요.\n세금이 줄이는 소비보다 정부가 쓰는 돈이 더 크기 때문이에요.","type":"text","title":"쉽게 설명"},{"rows":[["정부지출 100","+500"],["세금 100","-400 (소비가 80 줄어서)"],["합계","+100"]],"type":"table","title":"한계소비성향 0.8일 때","caption":"늘어난 소득이 정부지출 금액과 같아서 승수가 1이에요.","columns":["항목","소득 변화"]},{"q":"단순 케인스 모형에서 정부지출과 정액세를 같은 금액만큼 늘려요. 투자 고정, 수입과 구축효과가 없다면 균형재정승수는?","type":"quiz","answer":2,"options":["0","-1","1"],"explanation":"이 단순 모형에서는 지출 증가 효과가 증세에 따른 소비 감소보다 커서 늘린 정부지출만큼 국민소득이 증가해요.","lessonCheck":true}]}},{"id":1126,"word":"기본소비","before_data":{"meaning":"소득이 0이어도 살기 위해 꼭 하는 최소한의 소비","learning_example":"학습용 가정: 기본소비을 이해할 때는 \"소득이 0이어도 살기 위해 꼭 하는 최소한의 소비\"을 먼저 떠올리면 쉬워요. 기본소비는 소비함수 C = 기본소비 + 한계소비성향 × 가처분소득에서 소득과 상관없이 정해진 부분이다.","visuals":[{"body":"월급이 끊겨도 밥은 먹고 월세는 내야 해요.\n이렇게 소득과 상관없이 나가는 소비가 기본소비예요.","type":"text","title":"쉽게 설명"},{"rows":[["0","50"],["100","130"],["200","210"]],"type":"table","title":"소비함수 C = 50 + 0.8Y","caption":"50이 기본소비, 0.8이 한계소비성향이에요.","columns":["가처분소득","소비"]},{"q":"현재 소득이 0이어도 저축을 꺼내 최소한의 식비를 써요. 단순 소비함수에서 이 부분은?","type":"quiz","answer":0,"options":["기본소비","유발소비만","기업 투자"],"explanation":"소득과 무관하게 발생하는 소비를 기본소비 또는 독립소비라고 해요.","lessonCheck":true}]},"after_data":{"meaning":"단순 소비함수에서 현재 가처분소득과 관계없이 정해지는 소비 부분","learning_example":"학습용 가정: 월 소비함수가 소비=30만 원+0.8×가처분소득이면 기본소비는 30만 원이에요. 가처분소득이 100만 원일 때 총소비는 110만 원이며, 기본소비가 반드시 생존에 필요한 최소지출과 같은 것은 아니에요.","visuals":[{"body":"월급이 끊겨도 밥은 먹고 월세는 내야 해요.\n이렇게 소득과 상관없이 나가는 소비가 기본소비예요.","type":"text","title":"쉽게 설명"},{"rows":[["0","50"],["100","130"],["200","210"]],"type":"table","title":"소비함수 C = 50 + 0.8Y","caption":"50이 기본소비, 0.8이 한계소비성향이에요.","columns":["가처분소득","소비"]},{"q":"소비함수가 소비=30만 원+0.8×현재 가처분소득이에요. 기본소비에 해당하는 것은?","type":"quiz","answer":0,"options":["30만 원","가처분소득의 80%","총소비 전부"],"explanation":"현재 가처분소득에 따라 변하지 않는 상수항 30만 원이 기본소비예요. 0.8×가처분소득은 소득에 따라 변하는 유발소비이며, 기본소비가 반드시 생계비 최솟값인 것은 아니에요.","lessonCheck":true}]},"guard_data":{"meaning":"소득이 0이어도 살기 위해 꼭 하는 최소한의 소비","detailed_meaning":"기본소비는 소비함수 C = 기본소비 + 한계소비성향 × 가처분소득에서 소득과 상관없이 정해진 부분이다. 소득이 없어도 저축을 헐거나 돈을 빌려 먹고 자는 데 쓰는 지출이 여기에 해당한다. 독립소비라고도 하며 기본소비가 늘면 총지출선 전체가 위로 올라간다.","learning_example":"학습용 가정: 기본소비을 이해할 때는 \"소득이 0이어도 살기 위해 꼭 하는 최소한의 소비\"을 먼저 떠올리면 쉬워요. 기본소비는 소비함수 C = 기본소비 + 한계소비성향 × 가처분소득에서 소득과 상관없이 정해진 부분이다.","news_example":"고물가로 식비와 주거비 같은 기본소비 부담이 커지면서 가계의 저축 여력이 줄고 있다.","visuals":[{"body":"월급이 끊겨도 밥은 먹고 월세는 내야 해요.\n이렇게 소득과 상관없이 나가는 소비가 기본소비예요.","type":"text","title":"쉽게 설명"},{"rows":[["0","50"],["100","130"],["200","210"]],"type":"table","title":"소비함수 C = 50 + 0.8Y","caption":"50이 기본소비, 0.8이 한계소비성향이에요.","columns":["가처분소득","소비"]},{"q":"현재 소득이 0이어도 저축을 꺼내 최소한의 식비를 써요. 단순 소비함수에서 이 부분은?","type":"quiz","answer":0,"options":["기본소비","유발소비만","기업 투자"],"explanation":"소득과 무관하게 발생하는 소비를 기본소비 또는 독립소비라고 해요.","lessonCheck":true}]}},{"id":1203,"word":"자본수지","before_data":{"meaning":"자본이전과 특허권 같은 비생산·비금융자산 거래를 기록한 국제수지 항목","detailed_meaning":"자본수지는 국제수지표에서 채무 면제나 해외 이주비 같은 자본이전과, 특허권·상표권 자체의 매매를 기록한다. 주식·채권 투자나 해외 공장 설립은 자본수지가 아니라 금융계정에 들어간다. 규모가 작아 경상수지와 금융계정에 비해 비중이 낮다.","learning_example":"학습용 가정: 자본수지을 이해할 때는 \"자본이전과 특허권 같은 비생산·비금융자산 거래를 기록한 국제수지 항목\"을 먼저 떠올리면 쉬워요. 자본수지는 국제수지표에서 채무 면제나 해외 이주비 같은 자본이전과, 특허권·상표권 자체의 매매를 기록한다."},"after_data":{"meaning":"거주자와 비거주자 사이의 자본이전과 비생산·비금융자산 거래를 기록하는 국제수지 항목","detailed_meaning":"자본수지는 국제수지표에서 채무 면제 같은 자본이전과 비생산·비금융자산의 거래를 기록한다. 현행 작성기준에서는 이민자의 거주지 변경에 따른 재산반출입을 자본이전 거래로 기록하지 않으며, 특허권 매매는 서비스수지에 포함된다. 상표권 등 거래는 자산의 성격에 따라 분류하므로 특허권과 모두 같은 항목으로 묶어서는 안 된다. 주식·채권 투자나 해외 공장 설립은 자본수지가 아니라 금융계정에 들어간다. 규모가 작아 경상수지와 금융계정에 비해 비중이 낮다.","learning_example":"학습용 가정: 국내 거주자인 채권자가 비거주자의 빚 1억 원을 대가 없이 면제하면 자본이전으로 기록해요. 반면 해외 주식 1억 원을 사는 거래는 금융계정으로 분류하며, 두 거래를 모두 자본수지라고 부르지 않아요."},"guard_data":{"meaning":"자본이전과 특허권 같은 비생산·비금융자산 거래를 기록한 국제수지 항목","detailed_meaning":"자본수지는 국제수지표에서 채무 면제나 해외 이주비 같은 자본이전과, 특허권·상표권 자체의 매매를 기록한다. 주식·채권 투자나 해외 공장 설립은 자본수지가 아니라 금융계정에 들어간다. 규모가 작아 경상수지와 금융계정에 비해 비중이 낮다.","learning_example":"학습용 가정: 자본수지을 이해할 때는 \"자본이전과 특허권 같은 비생산·비금융자산 거래를 기록한 국제수지 항목\"을 먼저 떠올리면 쉬워요. 자본수지는 국제수지표에서 채무 면제나 해외 이주비 같은 자본이전과, 특허권·상표권 자체의 매매를 기록한다.","news_example":"국제수지 통계에서 자본수지는 자본이전 등 비중이 작은 거래를 담는다.","visuals":[{"body":"대가 없이 넘겨주는 자산이나 특허권 자체를 사고판 기록이에요.\n주식이나 채권 투자는 여기가 아니에요.","type":"text","title":"쉽게 설명"},{"rows":[["경상수지","수출입, 여행, 배당·이자, 송금"],["자본수지","채무 면제, 특허권 자체 매매"],["금융계정","해외 공장, 주식·채권, 외환보유액"],["오차 및 누락","통계 차이"]],"type":"table","title":"국제수지표의 큰 틀","columns":["계정","예"]}]}},{"id":1206,"word":"복식부기","before_data":{"meaning":"한 거래를 들어온 쪽과 나간 쪽 두 곳에 같은 금액으로 기록하는 방식","learning_example":"학습용 가정: 복식부기을 이해할 때는 \"한 거래를 들어온 쪽과 나간 쪽 두 곳에 같은 금액으로 기록하는 방식\"을 먼저 떠올리면 쉬워요. 복식부기는 모든 거래를 대변과 차변 두 번 기록해 합계가 늘 일치하도록 하는 기록 원칙이다."},"after_data":{"meaning":"한 거래의 두 측면을 차변과 대변에 같은 금액으로 기록하는 회계 방식","learning_example":"학습용 가정: 기업이 현금 100만 원으로 기계를 사면 자산 중 기계가 100만 원 늘고 현금이 100만 원 줄어요. 차변의 기계 100만 원과 대변의 현금 100만 원을 기록하며, 돈이 들어와야만 차변인 것은 아니에요."},"guard_data":{"meaning":"한 거래를 들어온 쪽과 나간 쪽 두 곳에 같은 금액으로 기록하는 방식","detailed_meaning":"복식부기는 모든 거래를 대변과 차변 두 번 기록해 합계가 늘 일치하도록 하는 기록 원칙이다. 국제수지표도 이 원칙을 따르므로 이론상 전체 합이 항상 0이 된다. 예를 들어 상품을 수출하면 경상수지 수출과 금융계정 자산 증가가 함께 기록된다.","learning_example":"학습용 가정: 복식부기을 이해할 때는 \"한 거래를 들어온 쪽과 나간 쪽 두 곳에 같은 금액으로 기록하는 방식\"을 먼저 떠올리면 쉬워요. 복식부기는 모든 거래를 대변과 차변 두 번 기록해 합계가 늘 일치하도록 하는 기록 원칙이다.","news_example":"국제수지표는 복식부기 원칙에 따라 작성되므로 전체 합이 이론상 0이 된다.","visuals":[{"body":"자동차를 팔면 차는 나가고 달러가 들어오죠.\n두 사건을 함께 적으니 장부가 늘 맞아떨어져요.","type":"text","title":"쉽게 설명"},{"rows":[["자동차 10만 달러 수출","+10 (상품 수출)","+10 (받은 달러)"],["미국 주식 2만 달러 매입","-","+2 주식 / -2 달러"]],"type":"table","title":"한 거래 = 두 번 기록 (예시)","columns":["거래","경상수지","금융계정"]}]}},{"id":1216,"word":"매매가-전세보증금 차이","before_data":{"meaning":"집값에서 보증금을 뺀 금액. 갭투자자가 실제로 마련해야 하는 자기 돈","detailed_meaning":"집값에서 보증금을 뺀 금액. 갭투자자가 실제로 마련해야 하는 자기 돈. 예를 들어 매매가격이 5억 원이고 전세보증금이 4억 5천만 원이면 차이는 5천만 원이에요. 이 차이가 작으면 적은 돈으로 집을 살 수 있어 갭투자가 쉬워 보여요. 하지만 집값이 조금만 내려도 집을 팔아 보증금을 모두 돌려주기 어려워질 수 있어요. 그래서 차이가 작다는 말은 기회이면서 동시에 위험 신호일 수 있어요.","learning_example":"학습용 가정: 매매가 5억 원, 전세보증금 4억 5천만 원이면 차이는 5천만 원이에요. 집값이 4억 4천만 원으로 내려가면 집값이 보증금보다 작아져요."},"after_data":{"meaning":"집의 매매가격에서 전세보증금을 뺀 금액으로, 세금·거래비용·다른 대출을 반영하기 전의 차이","detailed_meaning":"집값에서 보증금을 뺀 금액으로, 세금·중개보수 등 거래비용이나 다른 대출을 반영하기 전의 차이예요. 실제 필요한 자기 돈은 거래비용과 대출 등 자금조달 방식에 따라 달라져요. 예를 들어 매매가격이 5억 원이고 전세보증금이 4억 5천만 원이면 차이는 5천만 원이에요. 이 차이가 작으면 적은 돈으로 집을 살 수 있어 갭투자가 쉬워 보여요. 하지만 집값이 조금만 내려도 집을 팔아 보증금을 모두 돌려주기 어려워질 수 있어요. 그래서 차이가 작다는 말은 기회이면서 동시에 위험 신호일 수 있어요.","learning_example":"학습용 가정: 매매가 5억 원에서 전세보증금 4억 5천만 원을 빼면 차이는 5천만 원이에요. 별도 대출 없이 세금과 거래비용이 합계 500만 원 든다고 가정하면 필요한 자기 돈은 5,500만 원이에요. 집값이 4억 4천만 원으로 내려가면 보증금보다 1천만 원 작아져요."},"guard_data":{"meaning":"집값에서 보증금을 뺀 금액. 갭투자자가 실제로 마련해야 하는 자기 돈","detailed_meaning":"집값에서 보증금을 뺀 금액. 갭투자자가 실제로 마련해야 하는 자기 돈. 예를 들어 매매가격이 5억 원이고 전세보증금이 4억 5천만 원이면 차이는 5천만 원이에요. 이 차이가 작으면 적은 돈으로 집을 살 수 있어 갭투자가 쉬워 보여요. 하지만 집값이 조금만 내려도 집을 팔아 보증금을 모두 돌려주기 어려워질 수 있어요. 그래서 차이가 작다는 말은 기회이면서 동시에 위험 신호일 수 있어요.","learning_example":"학습용 가정: 매매가 5억 원, 전세보증금 4억 5천만 원이면 차이는 5천만 원이에요. 집값이 4억 4천만 원으로 내려가면 집값이 보증금보다 작아져요.","news_example":"매매가-전세보증금 차이가 줄어든 지역에서 갭투자와 보증금 반환 위험이 함께 거론됐다.","visuals":[{"body":"매매가-전세보증금 차이는 집을 살 때 부족한 부분을 뜻해요.\n전세보증금이 4억 5천만 원이고 집값이 5억 원이면, 남는 차이는 5천만 원이에요.\n갭투자자는 이 차이만큼의 자기 돈으로 집을 살 수 있어요.\n하지만 이 차이가 작을수록 집값 하락에는 약해져요.","type":"text","title":"차이는 자기 돈의 크기예요"},{"rows":[["5억 원","3억 원","2억 원","완충 여지가 비교적 큼"],["5억 원","4억 원","1억 원","보증금이 집값에 가까움"],["5억 원","4억 8천만 원","2천만 원","작은 하락에도 위험이 커짐"]],"type":"table","title":"차이가 작아질수록","columns":["매매가격","전세보증금","차이","읽는 법"]},{"q":"매매가 5억 원, 전세보증금 4억 5천만 원인 집의 차이는 얼마일까요?","type":"quiz","answer":0,"options":["5천만 원","5억 원","4억 5천만 원","9억 5천만 원"],"explanation":"매매가격에서 전세보증금을 빼면 5억 원 - 4억 5천만 원 = 5천만 원이에요.","lessonCheck":true}]}},{"id":1217,"word":"갭투자","before_data":{"visuals":[{"body":"갭투자의 갭은 매매가격과 전세보증금 사이의 차이를 뜻해요.\n자기 돈을 적게 넣을 수 있어 집값 상승기에는 수익률이 커질 수 있어요.\n하지만 보증금은 세입자에게 돌려줘야 하는 돈이에요.\n집값이 내려가거나 새 세입자를 못 구하면 반환 부담이 커져요.","type":"text","title":"갭투자는 보증금을 끼고 사는 구조예요"},{"rows":[["전세가율 높음","자기 돈이 적게 듦","가격 하락에 취약"],["집값 상승","수익률이 커짐","상승을 전제로 하면 위험을 놓침"],["다음 세입자 필요","보증금 반환 자금 마련","전세 수요가 약하면 막힐 수 있음"]],"type":"table","title":"좋아 보이는 점과 위험","columns":["상황","좋아 보이는 점","위험"]},{"q":"갭투자에서 특히 조심해야 할 위험은?","type":"quiz","answer":0,"options":["계약 종료 때 보증금을 돌려줄 돈이 부족해질 위험","집값이 오르면 세입자에게 차익을 나눠줘야 하는 위험","전세보증금이 자동으로 월세가 되는 위험","매매가격이 항상 0원이 되는 위험"],"explanation":"갭투자는 보증금을 끼고 집을 사는 구조라서, 계약 종료 때 반환 자금을 마련하지 못하면 문제가 커져요.","lessonCheck":true}]},"after_data":{"visuals":[{"body":"갭투자의 갭은 매매가격과 전세보증금 사이의 차이를 뜻해요.\n자기 돈을 적게 넣을 수 있어 집값 상승기에는 수익률이 커질 수 있어요.\n하지만 보증금은 세입자에게 돌려줘야 하는 돈이에요.\n집값이 내려가거나 새 세입자를 못 구하면 반환 부담이 커져요.","type":"text","title":"갭투자는 보증금을 끼고 사는 구조예요"},{"rows":[["전세가율 높음","자기 돈이 적게 듦","가격 하락에 취약"],["집값 상승","수익률이 커짐","상승을 전제로 하면 위험을 놓침"],["다음 세입자 필요","보증금 반환 자금 마련","전세 수요가 약하면 막힐 수 있음"]],"type":"table","title":"좋아 보이는 점과 위험","columns":["상황","좋아 보이는 점","위험"]},{"q":"집값 5억 원, 기존 전세보증금 4억 5천만 원인 집을 갭투자해요. 거래비용과 다른 대출은 제외할 때, 집값이 4억 원으로 내려가 그 가격에 팔면 어떤 문제가 생기나요?","type":"quiz","answer":0,"options":["매각대금만으로 보증금을 돌려주기에 5천만 원이 부족하다","집값이 내린 만큼 보증금도 자동으로 5천만 원 줄어든다","처음 낸 차액 5천만 원만 돌려주면 된다","집을 팔면 보증금 반환 의무가 자동으로 없어져도 된다"],"explanation":"4억 5천만 원의 보증금에 비해 매각대금은 4억 원이므로 5천만 원이 부족해요. 집값 하락이 약정 보증금을 자동으로 줄이지는 않으며, 반환 책임을 따로 준비해야 해요.","lessonCheck":true}]},"guard_data":{"meaning":"전세보증금을 끼고 적은 자기 돈으로 집을 사지만, 보증금 반환 책임도 지는 투자","detailed_meaning":"전세보증금을 끼고 적은 자기 돈으로 집을 사지만, 보증금 반환 책임도 지는 투자. 집값 5억 원짜리 집에 전세보증금 4억 5천만 원이 들어 있으면, 투자자는 5천만 원 차이로 집을 살 수 있어요. 집값이 오르면 자기 돈 대비 수익률이 커질 수 있어요. 반대로 집값이 떨어지거나 다음 세입자를 구하지 못하면 계약 종료 때 돌려줄 보증금이 부족해질 수 있어요. 갭투자는 수익 가능성과 반환 위험이 같이 커지는 구조예요.","learning_example":"학습용 가정: 5억 원 집에 4억 5천만 원 전세가 있으면 투자자는 5천만 원으로 집을 사는 것처럼 보여요. 하지만 세입자가 나갈 때 4억 5천만 원을 돌려줘야 하는 책임도 함께 가져와요.","news_example":"전세가율이 높은 지역에서 갭투자가 늘자 보증금 반환 리스크를 우려하는 목소리가 나왔다.","visuals":[{"body":"갭투자의 갭은 매매가격과 전세보증금 사이의 차이를 뜻해요.\n자기 돈을 적게 넣을 수 있어 집값 상승기에는 수익률이 커질 수 있어요.\n하지만 보증금은 세입자에게 돌려줘야 하는 돈이에요.\n집값이 내려가거나 새 세입자를 못 구하면 반환 부담이 커져요.","type":"text","title":"갭투자는 보증금을 끼고 사는 구조예요"},{"rows":[["전세가율 높음","자기 돈이 적게 듦","가격 하락에 취약"],["집값 상승","수익률이 커짐","상승을 전제로 하면 위험을 놓침"],["다음 세입자 필요","보증금 반환 자금 마련","전세 수요가 약하면 막힐 수 있음"]],"type":"table","title":"좋아 보이는 점과 위험","columns":["상황","좋아 보이는 점","위험"]},{"q":"갭투자에서 특히 조심해야 할 위험은?","type":"quiz","answer":0,"options":["계약 종료 때 보증금을 돌려줄 돈이 부족해질 위험","집값이 오르면 세입자에게 차익을 나눠줘야 하는 위험","전세보증금이 자동으로 월세가 되는 위험","매매가격이 항상 0원이 되는 위험"],"explanation":"갭투자는 보증금을 끼고 집을 사는 구조라서, 계약 종료 때 반환 자금을 마련하지 못하면 문제가 커져요.","lessonCheck":true}]}},{"id":1218,"word":"깡통전세","before_data":{"meaning":"집값이나 경매 회수액이 보증금보다 낮아 보증금 회수가 어려울 수 있는 상태","detailed_meaning":"집값이나 경매 회수액이 보증금보다 낮아 보증금 회수가 어려울 수 있는 상태. 깡통전세는 법률 용어라기보다 시장에서 위험을 설명할 때 쓰는 말이에요. 집 시세가 2억 5천만 원인데 보증금이 2억 7천만 원이면, 집을 팔아도 보증금 전부를 마련하기 어려울 수 있어요. 여기에 선순위 근저당, 세금 체납, 낮은 경매 낙찰가가 겹치면 임차인의 회수 위험은 더 커져요. 다만 깡통전세처럼 보인다고 해서 곧바로 사기죄가 되는 것은 아니고, 사기 여부는 별도 요건을 봐요.","learning_example":"학습용 가정: 집 시세가 2억 5천만 원인데 전세보증금이 2억 7천만 원이면, 집을 팔아도 보증금이 2천만 원 부족할 수 있어요.","visuals":[{"body":"깡통전세는 집을 처분해도 보증금을 다 돌려주기 어려운 상태를 말해요.\n핵심은 집값보다 보증금 부담이 더 커졌는지예요.\n경매에서는 실제 낙찰가가 시세보다 낮을 수도 있어요.\n그래서 전세가율, 선순위 권리, 세금, 보증 가입 가능성을 함께 확인해야 해요.","type":"text","title":"깡통전세는 회수 위험을 말해요"},{"type":"flow","steps":["전세보증금이 집값에 가까운 계약","집값 하락 또는 낮은 경매 낙찰가","매각 대금이 보증금보다 부족","임차인이 보증금을 전부 회수하지 못할 위험"],"title":"깡통전세가 되는 흐름"},{"q":"깡통전세 설명으로 가장 알맞은 것은?","type":"quiz","answer":0,"options":["집을 팔아도 보증금 반환이 어려울 수 있는 상태","전세보증금이 항상 0원인 계약","월세가 없는 모든 전세계약","집주인이 반드시 사기죄로 처벌되는 상태"],"explanation":"깡통전세는 보증금 회수 위험을 설명하는 말이에요. 사기죄 여부는 계약 당시 속임과 고의 등을 따로 봐요.","lessonCheck":true}]},"after_data":{"meaning":"보증금과 선순위채권을 합한 금액이 집값이나 경·공매 매각대금을 넘어 보증금 회수가 어려울 수 있는 상태","detailed_meaning":"보증금과 선순위 근저당권·조세채권 등 선순위채권을 합한 금액이 집값이나 경·공매 매각대금을 초과해 보증금 회수가 어려울 수 있는 상태. 깡통전세는 법률 용어라기보다 시장에서 위험을 설명할 때 쓰는 말이에요. 집 시세가 2억 5천만 원인데 보증금이 2억 7천만 원이면, 집을 팔아도 보증금 전부를 마련하기 어려울 수 있어요. 여기에 선순위 근저당, 세금 체납, 낮은 경매 낙찰가가 겹치면 임차인의 회수 위험은 더 커져요. 다만 깡통전세처럼 보인다고 해서 곧바로 사기죄가 되는 것은 아니고, 사기 여부는 별도 요건을 봐요.","learning_example":"학습용 가정: 집값이 3억 원이고 내 보증금은 2억 원이어도 먼저 배당받을 채권이 1억 5천만 원이면 합계가 3억 5천만 원으로 집값을 5천만 원 넘어요. 매각대금이 3억 원이고 다른 비용이 없다고 가정하면 내 보증금에 배당될 돈은 1억 5천만 원뿐이에요.","visuals":[{"body":"깡통전세는 집을 처분해도 보증금을 다 돌려주기 어려운 상태를 말해요.\n핵심은 집값보다 보증금 부담이 더 커졌는지예요.\n경매에서는 실제 낙찰가가 시세보다 낮을 수도 있어요.\n그래서 전세가율, 선순위 권리, 세금, 보증 가입 가능성을 함께 확인해야 해요.","type":"text","title":"깡통전세는 회수 위험을 말해요"},{"type":"flow","steps":["전세보증금이 집값에 가까운 계약","집값 하락 또는 낮은 경매 낙찰가","매각 대금이 보증금보다 부족","임차인이 보증금을 전부 회수하지 못할 위험"],"title":"깡통전세가 되는 흐름"},{"q":"집이 3억 원에 팔리고 먼저 배당받을 채권이 1억 5천만 원, 내 보증금이 2억 원이에요. 다른 비용과 채권이 없다면 회수 위험은?","type":"quiz","answer":0,"options":["내 보증금 중 5천만 원이 부족할 수 있다","집값이 보증금보다 커서 2억 원 전액을 받을 수 있다","선순위채권은 보증금 뒤에 배당된다","깡통전세이므로 사기죄가 자동으로 성립한다"],"explanation":"3억 원에서 선순위채권 1억 5천만 원을 먼저 빼면 1억 5천만 원이 남아 보증금 2억 원보다 5천만 원 부족해요. 집값과 보증금만 비교해서는 안 되며 사기죄는 별도로 판단해요.","lessonCheck":true}]},"guard_data":{"meaning":"집값이나 경매 회수액이 보증금보다 낮아 보증금 회수가 어려울 수 있는 상태","detailed_meaning":"집값이나 경매 회수액이 보증금보다 낮아 보증금 회수가 어려울 수 있는 상태. 깡통전세는 법률 용어라기보다 시장에서 위험을 설명할 때 쓰는 말이에요. 집 시세가 2억 5천만 원인데 보증금이 2억 7천만 원이면, 집을 팔아도 보증금 전부를 마련하기 어려울 수 있어요. 여기에 선순위 근저당, 세금 체납, 낮은 경매 낙찰가가 겹치면 임차인의 회수 위험은 더 커져요. 다만 깡통전세처럼 보인다고 해서 곧바로 사기죄가 되는 것은 아니고, 사기 여부는 별도 요건을 봐요.","learning_example":"학습용 가정: 집 시세가 2억 5천만 원인데 전세보증금이 2억 7천만 원이면, 집을 팔아도 보증금이 2천만 원 부족할 수 있어요.","news_example":"전세가율이 높은 빌라를 중심으로 깡통전세와 보증금 미반환 우려가 다시 제기됐다.","visuals":[{"body":"깡통전세는 집을 처분해도 보증금을 다 돌려주기 어려운 상태를 말해요.\n핵심은 집값보다 보증금 부담이 더 커졌는지예요.\n경매에서는 실제 낙찰가가 시세보다 낮을 수도 있어요.\n그래서 전세가율, 선순위 권리, 세금, 보증 가입 가능성을 함께 확인해야 해요.","type":"text","title":"깡통전세는 회수 위험을 말해요"},{"type":"flow","steps":["전세보증금이 집값에 가까운 계약","집값 하락 또는 낮은 경매 낙찰가","매각 대금이 보증금보다 부족","임차인이 보증금을 전부 회수하지 못할 위험"],"title":"깡통전세가 되는 흐름"},{"q":"깡통전세 설명으로 가장 알맞은 것은?","type":"quiz","answer":0,"options":["집을 팔아도 보증금 반환이 어려울 수 있는 상태","전세보증금이 항상 0원인 계약","월세가 없는 모든 전세계약","집주인이 반드시 사기죄로 처벌되는 상태"],"explanation":"깡통전세는 보증금 회수 위험을 설명하는 말이에요. 사기죄 여부는 계약 당시 속임과 고의 등을 따로 봐요.","lessonCheck":true}]}},{"id":1221,"word":"임차인","before_data":{"visuals":[{"body":"임차인은 집을 빌려 쓰는 사람이에요.\n전세에서는 큰 보증금을 맡기고 집을 사용해요.\n계약이 끝나면 집을 돌려주고 보증금 반환을 청구해요.\n보증금 보호를 위해 전입신고, 확정일자, 반환보증 같은 장치를 확인해요.","type":"text","title":"임차인은 세입자예요"},{"rows":[["권리","집을 사용할 권리","계약 기간 동안 거주"],["권리","보증금 반환 청구","계약 종료 후 보증금 청구"],["의무","계약에 맞게 사용","무단 훼손 금지"],["보호 장치","요건을 갖춰 보증금 보호","전입신고와 확정일자"]],"type":"table","title":"임차인의 권리와 의무","columns":["구분","쉽게 말하면","전세 예시"]},{"q":"임차인이 보증금 회수 가능성을 높이기 위해 확인할 수 있는 것은?","type":"quiz","answer":0,"options":["전입신고와 확정일자 등 대항력-우선변제 요건","집주인의 주식 수익률","근처 편의점 매출","아파트 브랜드 로고"],"explanation":"주택 인도와 주민등록, 확정일자 등은 임차인의 대항력과 우선변제권을 이해할 때 핵심이에요.","lessonCheck":true}]},"after_data":{"visuals":[{"body":"임차인은 집을 빌려 쓰는 사람이에요.\n전세에서는 큰 보증금을 맡기고 집을 사용해요.\n계약이 끝나면 집을 돌려주고 보증금 반환을 청구해요.\n보증금 보호를 위해 전입신고, 확정일자, 반환보증 같은 장치를 확인해요.","type":"text","title":"임차인은 세입자예요"},{"rows":[["권리","집을 사용할 권리","계약 기간 동안 거주"],["권리","보증금 반환 청구","계약 종료 후 보증금 청구"],["의무","계약에 맞게 사용","무단 훼손 금지"],["보호 장치","요건을 갖춰 보증금 보호","전입신고와 확정일자"]],"type":"table","title":"임차인의 권리와 의무","columns":["구분","쉽게 말하면","전세 예시"]},{"q":"주택 임차인이 일반적인 대항력과 확정일자에 따른 우선변제권 요건을 준비할 때 확인할 조합은?","type":"quiz","answer":0,"options":["주택 인도·주민등록과 임대차계약서의 확정일자","계약서에 서명하고 보증금만 송금하기","확정일자만 받고 주택 인도와 주민등록은 생략하기","전입신고만 하고 확정일자는 받지 않기"],"explanation":"주택 인도와 주민등록은 대항요건이며, 확정일자에 따른 우선변제권에는 대항요건과 임대차계약서의 확정일자가 필요해요. 계약이나 송금만으로 이 요건들이 모두 갖춰지지는 않아요.","lessonCheck":true}]},"guard_data":{"meaning":"집을 빌려 쓰는 사람. 보증금을 맡기고 주택을 사용하는 쪽","detailed_meaning":"집을 빌려 쓰는 사람. 보증금을 맡기고 주택을 사용하는 쪽. 임차인은 세입자라고 생각하면 쉬워요. 계약 기간 동안 집을 사용할 권리가 있고, 계약이 끝나면 보증금 반환을 청구할 수 있어요. 대신 차임을 내야 하는 계약이면 차임을 지급하고, 집을 계약에 맞게 사용하며, 계약 종료 때 집을 반환해야 해요. 주택 인도와 주민등록, 확정일자 같은 요건을 갖추면 대항력과 우선변제권을 이해하는 데 도움이 돼요.","learning_example":"학습용 가정: 세입자는 이사해서 전입신고를 하고 확정일자를 받으면, 보증금 보호와 관련한 중요한 요건을 갖추는 데 도움이 돼요.","news_example":"임차인이 전입신고와 확정일자를 마친 뒤 보증금 회수 가능성을 점검하고 있다.","visuals":[{"body":"임차인은 집을 빌려 쓰는 사람이에요.\n전세에서는 큰 보증금을 맡기고 집을 사용해요.\n계약이 끝나면 집을 돌려주고 보증금 반환을 청구해요.\n보증금 보호를 위해 전입신고, 확정일자, 반환보증 같은 장치를 확인해요.","type":"text","title":"임차인은 세입자예요"},{"rows":[["권리","집을 사용할 권리","계약 기간 동안 거주"],["권리","보증금 반환 청구","계약 종료 후 보증금 청구"],["의무","계약에 맞게 사용","무단 훼손 금지"],["보호 장치","요건을 갖춰 보증금 보호","전입신고와 확정일자"]],"type":"table","title":"임차인의 권리와 의무","columns":["구분","쉽게 말하면","전세 예시"]},{"q":"임차인이 보증금 회수 가능성을 높이기 위해 확인할 수 있는 것은?","type":"quiz","answer":0,"options":["전입신고와 확정일자 등 대항력-우선변제 요건","집주인의 주식 수익률","근처 편의점 매출","아파트 브랜드 로고"],"explanation":"주택 인도와 주민등록, 확정일자 등은 임차인의 대항력과 우선변제권을 이해할 때 핵심이에요.","lessonCheck":true}]}},{"id":1224,"word":"우선변제권","before_data":{"learning_example":"학습용 가정: 세입자가 전입신고와 확정일자를 갖췄다면, 경매 대금에서 후순위 권리자보다 보증금을 먼저 받을 수 있는지 검토할 수 있어요.","visuals":[{"body":"우선변제권은 돈을 받을 차례를 앞당겨 주는 권리예요.\n집이 경매로 넘어가면 여러 사람이 돈을 받아가려 해요.\n이때 대항요건과 확정일자를 갖춘 임차인은 후순위 권리자보다 먼저 받을 수 있어요.\n하지만 선순위 근저당이 있으면 그 권리보다 앞서지는 못할 수 있어요.","type":"text","title":"우선변제권은 순서의 문제예요"},{"q":"우선변제권을 이해할 때 함께 봐야 하는 것은?","type":"quiz","answer":0,"options":["확정일자와 선순위 권리","집의 인테리어 색상","가전제품 브랜드","관리비 고지서 디자인"],"explanation":"우선변제권은 확정일자와 권리 순서가 중요해요. 선순위 권리가 있으면 보증금 회수 순서에 영향을 줄 수 있어요.","lessonCheck":true}]},"after_data":{"learning_example":"학습용 가정: 주택 인도·주민등록·확정일자를 갖춘 임차인의 보증금이 1억 원이고, 배당받을 수 있는 매각대금 2억 원에서 그보다 앞선 채권 1억 5천만 원을 먼저 갚는다고 해요. 다른 비용·권리가 없으면 남은 5천만 원만 받을 수 있어 우선변제권이 전액 반환을 보장하지는 않아요.","visuals":[{"body":"우선변제권은 돈을 받을 차례를 앞당겨 주는 권리예요.\n집이 경매로 넘어가면 여러 사람이 돈을 받아가려 해요.\n이때 대항요건과 확정일자를 갖춘 임차인은 후순위 권리자보다 먼저 받을 수 있어요.\n하지만 선순위 근저당이 있으면 그 권리보다 앞서지는 못할 수 있어요.","type":"text","title":"우선변제권은 순서의 문제예요"},{"q":"일반적인 확정일자에 따른 우선변제권 설명으로 맞는 것은?","type":"quiz","answer":0,"options":["대항요건과 확정일자를 갖춰도 선순위 권리와 배당대금에 따라 전액 회수하지 못할 수 있다","확정일자만 받으면 입주와 주민등록은 필요 없다","확정일자가 있으면 모든 선순위 담보권보다 먼저 받는다","확정일자는 보증기관의 자동 지급 약정이다"],"explanation":"확정일자에 따른 우선변제권에는 대항요건과 확정일자가 필요해요. 후순위 권리자보다 우선하지만 선순위 권리와 배당대금 부족 때문에 보증금 전액을 받지 못할 수 있어요.","lessonCheck":true}]},"guard_data":{"meaning":"경매나 공매 때 다른 후순위 채권자보다 먼저 보증금을 받을 수 있는 권리","detailed_meaning":"경매나 공매 때 다른 후순위 채권자보다 먼저 보증금을 받을 수 있는 권리. 임차인이 대항요건을 갖추고 확정일자를 받으면 우선변제권을 이해할 수 있어요. 집이 경매로 넘어가면 여러 채권자가 돈을 받아가려 하는데, 우선변제권은 일정한 순서에서 보증금을 먼저 받을 수 있게 해 주는 장치예요. 그러나 모든 사람보다 항상 먼저 받는다는 뜻은 아니고, 선순위 권리가 있으면 그보다 뒤로 밀릴 수 있어요. 그래서 확정일자와 선순위 권리 확인을 함께 봐야 해요.","learning_example":"학습용 가정: 세입자가 전입신고와 확정일자를 갖췄다면, 경매 대금에서 후순위 권리자보다 보증금을 먼저 받을 수 있는지 검토할 수 있어요.","news_example":"전세 주택이 경매로 넘어가자 임차인의 우선변제권과 선순위 권리 여부가 쟁점이 됐다.","visuals":[{"body":"우선변제권은 돈을 받을 차례를 앞당겨 주는 권리예요.\n집이 경매로 넘어가면 여러 사람이 돈을 받아가려 해요.\n이때 대항요건과 확정일자를 갖춘 임차인은 후순위 권리자보다 먼저 받을 수 있어요.\n하지만 선순위 근저당이 있으면 그 권리보다 앞서지는 못할 수 있어요.","type":"text","title":"우선변제권은 순서의 문제예요"},{"q":"우선변제권을 이해할 때 함께 봐야 하는 것은?","type":"quiz","answer":0,"options":["확정일자와 선순위 권리","집의 인테리어 색상","가전제품 브랜드","관리비 고지서 디자인"],"explanation":"우선변제권은 확정일자와 권리 순서가 중요해요. 선순위 권리가 있으면 보증금 회수 순서에 영향을 줄 수 있어요.","lessonCheck":true}]}},{"id":1233,"word":"경매","before_data":{"visuals":[{"body":"경매는 빚 문제 등이 있을 때 재산을 팔아 돈을 나누는 절차예요.\n전세에서는 집이 경매로 넘어가면 보증금 회수가 문제될 수 있어요.\n매각대금이 충분하지 않으면 앞순위 권리자가 먼저 받아가요.\n그래서 전세 위험을 볼 때 경매 낙찰가와 권리 순서를 함께 봐요.","type":"text","title":"경매는 팔아서 나누는 절차예요"},{"q":"전세 위험에서 경매가 중요한 이유는?","type":"quiz","answer":0,"options":["매각대금에서 권리 순서대로 돈을 받기 때문","집값이 항상 오르기 때문","보증금이 자동으로 늘기 때문","계약서가 필요 없어지기 때문"],"explanation":"경매에서는 매각대금이 권리 순서에 따라 배분돼요. 선순위 권리가 크면 보증금 회수에 영향을 줄 수 있어요.","lessonCheck":true}]},"after_data":{"visuals":[{"body":"경매는 빚 문제 등이 있을 때 재산을 팔아 돈을 나누는 절차예요.\n전세에서는 집이 경매로 넘어가면 보증금 회수가 문제될 수 있어요.\n매각대금이 충분하지 않으면 앞순위 권리자가 먼저 받아가요.\n그래서 전세 위험을 볼 때 경매 낙찰가와 권리 순서를 함께 봐요.","type":"text","title":"경매는 팔아서 나누는 절차예요"},{"q":"경매 매각대금이 4억 원이고 내 보증금보다 먼저 배당할 채권이 3억 원, 내 보증금이 1억 5천만 원이에요. 다른 비용·채권은 없고 내가 적법하게 배당받는다면 최대 회수액은?","type":"quiz","answer":0,"options":["1억 원","1억 5천만 원","3억 원","4억 원"],"explanation":"4억 원에서 선순위채권 3억 원을 먼저 빼면 1억 원이 남아요. 내 보증금 1억 5천만 원보다 적으므로 이 매각대금에서는 최대 1억 원을 받을 수 있고 5천만 원이 부족해요.","lessonCheck":true}]},"guard_data":{"meaning":"빚을 갚지 못한 재산 등을 법원 절차로 팔아 돈을 나누는 절차","detailed_meaning":"빚을 갚지 못한 재산 등을 법원 절차로 팔아 돈을 나누는 절차. 전세에서 경매가 중요한 이유는 집이 경매로 넘어가면 매각대금에서 여러 권리자가 순서대로 돈을 받아가기 때문이에요. 낙찰가는 시세보다 낮을 수 있고, 선순위 권리가 크면 임차인이 받을 돈이 줄어들 수 있어요. 우선변제권은 이 경매 절차에서 보증금을 받을 순서와 관련돼요. 그래서 깡통전세 위험을 볼 때는 집값뿐 아니라 경매에서 실제로 얼마가 회수될지도 생각해야 해요.","learning_example":"학습용 가정: 집 시세가 5억 원이어도 경매에서 4억 원에 팔리고 선순위 권리가 3억 원이면, 남은 돈으로 내 보증금을 다 받기 어려울 수 있어요.","news_example":"전세 주택이 경매로 넘어가면서 임차인의 보증금 회수 가능성이 쟁점이 됐다.","visuals":[{"body":"경매는 빚 문제 등이 있을 때 재산을 팔아 돈을 나누는 절차예요.\n전세에서는 집이 경매로 넘어가면 보증금 회수가 문제될 수 있어요.\n매각대금이 충분하지 않으면 앞순위 권리자가 먼저 받아가요.\n그래서 전세 위험을 볼 때 경매 낙찰가와 권리 순서를 함께 봐요.","type":"text","title":"경매는 팔아서 나누는 절차예요"},{"q":"전세 위험에서 경매가 중요한 이유는?","type":"quiz","answer":0,"options":["매각대금에서 권리 순서대로 돈을 받기 때문","집값이 항상 오르기 때문","보증금이 자동으로 늘기 때문","계약서가 필요 없어지기 때문"],"explanation":"경매에서는 매각대금이 권리 순서에 따라 배분돼요. 선순위 권리가 크면 보증금 회수에 영향을 줄 수 있어요.","lessonCheck":true}]}}]$content_revision_payload$::jsonb) AS x(id integer, word text, before_data jsonb, after_data jsonb, guard_data jsonb) ORDER BY id LOOP
    SELECT to_jsonb(w) INTO current_row FROM public.words w WHERE w.id=p.id FOR UPDATE;
    IF NOT FOUND OR current_row->>'word' IS DISTINCT FROM p.word THEN RAISE EXCEPTION '단어 식별 불일치: %',p.id; END IF;
    IF NOT EXISTS (SELECT 1 FROM jsonb_each(p.after_data) e WHERE current_row->e.key IS DISTINCT FROM e.value) THEN skipped := skipped+1; CONTINUE; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(p.guard_data) e WHERE current_row->e.key IS DISTINCT FROM e.value) THEN RAISE EXCEPTION '검토 이후 내용이 변경됨: %',p.id; END IF;
    UPDATE public.words SET
      meaning=CASE WHEN p.after_data ? 'meaning' THEN p.after_data->>'meaning' ELSE meaning END,
      detailed_meaning=CASE WHEN p.after_data ? 'detailed_meaning' THEN p.after_data->>'detailed_meaning' ELSE detailed_meaning END,
      learning_example=CASE WHEN p.after_data ? 'learning_example' THEN p.after_data->>'learning_example' ELSE learning_example END,
      news_example=CASE WHEN p.after_data ? 'news_example' THEN p.after_data->>'news_example' ELSE news_example END,
      visuals=CASE WHEN p.after_data ? 'visuals' THEN p.after_data->'visuals' ELSE visuals END
    WHERE id=p.id;
    changed:=changed+1;
  END LOOP;
  RAISE NOTICE '수정 %, 이미 동일 %',changed,skipped;
END;
